// ═════════════ أوامر الواجهة بلا كود مضمَّن (سياسة أمان المحتوى) ═════════════
// لا يُكتب onclick ولا أخواته في أي وسم: سياسة الأمان تمنع تشغيل أي كود داخل الصفحة.
// العنصر يحمل الأمر في:  data-on-click="اسم_دالة"  ومعاملاتها في  data-on-click-args="${qa([...])}"
//   أو  data-on-click="#رقم"  لدالة في السجل QH أدناه (لما هو أكثر من استدعاء واحد)،
//   أو قائمة خطوات JSON من qon('click', رمز) حين يُبنى الأمر في الكود (روابط القائمة وغيرها).
// الأحداث المدعومة: click change input keydown mousedown submit focus blur.
// معاملات خاصة: QA.t = العنصر نفسه (this)، QA.e = الحدث (event)، QA.v = this.value، QA.c = this.checked.
// الاسم يجب أن يكون دالة عامة في هذا الملف (function أو window.اسم)، لا دالة من المتصفح.
const QA = Object.freeze({ t:{$:'t'}, e:{$:'e'}, v:{$:'v'}, c:{$:'c'} });
function qs(v){ return v==null ? '' : String(v); }
function qa(args){ return escH(JSON.stringify(args)); }
function qh(name, ...args){ return [[name, args]]; }
function qhs(...toks){ const out = []; toks.forEach(t=>{ if(Array.isArray(t)) out.push(...t); }); return out; }
function qon(type, tok){ return (Array.isArray(tok) && tok.length) ? ` data-on-${type}="${escH(JSON.stringify(tok))}"` : ''; }
function qset(el, type, tok){ if(el && Array.isArray(tok)) el.setAttribute('data-on-'+type, JSON.stringify(tok)); }
function qsig(el, type){ const v = el && el.getAttribute && el.getAttribute('data-on-'+type); return v ? v + '|' + (el.getAttribute('data-on-'+type+'-args')||'') : ''; }
function QJS(){ throw new Error('QJS: علامة تُحوَّل عند البناء، لا تُستدعى'); }
function qArg(a, el, ev){
  if(a && typeof a==='object' && !Array.isArray(a) && typeof a.$==='string' && Object.keys(a).length===1){
    if(a.$==='t') return el; if(a.$==='e') return ev;
    if(a.$==='v') return el ? el.value : undefined; if(a.$==='c') return el ? el.checked : undefined;
  }
  return a;
}
const _qNative = /\{\s*\[native code\]\s*\}\s*$/;
function qCall(name, args, el, ev){
  const real = (Array.isArray(args) ? args : []).map(a=>qArg(a, el, ev));
  if(typeof name==='string' && name[0]==='#'){
    const f = QH[name.slice(1)];
    if(typeof f!=='function'){ console.warn('أمر غير مسجَّل:', name); return; }
    return f.call(el, ev, ...real);
  }
  const f = (typeof name==='string' && /^[A-Za-z_$][\w$]*$/.test(name)) ? window[name] : null;
  if(typeof f!=='function' || _qNative.test(Function.prototype.toString.call(f))){ console.warn('أمر غير مسموح:', name); return; }
  return f.apply(null, real);
}
function qrun(tok, el, ev){
  let r;
  if(!Array.isArray(tok)) return;
  for(const step of tok){
    if(!Array.isArray(step)) continue;
    r = qCall(step[0], step[1], el, ev);
  }
  return r;
}
(function(){
  const fire = (el, type, ev)=>{
    const v = el.getAttribute('data-on-'+type); if(!v) return;
    let tok;
    if(v[0]==='['){ try{ tok = JSON.parse(v); }catch(e){ return; } }
    else {
      let args = []; const a = el.getAttribute('data-on-'+type+'-args');
      if(a){ try{ args = JSON.parse(a); }catch(e){ args = []; } }
      tok = [[v, args]];
    }
    try{ if(qrun(tok, el, ev) === false) ev.preventDefault(); }
    catch(e){ if(typeof window.reportError==='function') window.reportError(e); else console.error(e); }
  };
  // يُسجَّل قبل أي مستمع آخر على المستند، فيعمل الأمر قبل مستمعات «النقر خارج القائمة» كما كان onclick
  ['click','change','input','keydown','mousedown','submit'].forEach(type=>{
    document.addEventListener(type, ev=>{
      const path = ev.composedPath ? ev.composedPath() : [];
      for(const el of path){
        if(el===document || el===window) break;
        if(el && el.nodeType===1 && el.hasAttribute('data-on-'+type)){
          fire(el, type, ev);
          if(ev.cancelBubble){ ev.stopImmediatePropagation(); break; }
        }
      }
    });
  });
  ['focus','blur'].forEach(type=>document.addEventListener(type, ev=>{
    const el = ev.target; if(el && el.nodeType===1 && el.hasAttribute && el.hasAttribute('data-on-'+type)) fire(el, type, ev);
  }, true));
})();
