// شريط تقدّم أعلى الصفحة يظهر أثناء أي اتصال بقاعدة البيانات (بعد 250 مللي ثانية، ولا يظهر للتحديث الخلفي الصامت)
let _netInFlight = 0, _netTimer = null, _netHideTimer = null, _netShownAt = 0;
function netStart(){
  _netInFlight++;
  if(_netInFlight===1){
    clearTimeout(_netTimer); clearTimeout(_netHideTimer);
    _netTimer = setTimeout(()=>{ const b=document.getElementById('netBar'); if(b){ b.classList.add('on'); _netShownAt = Date.now(); } }, 120);
  }
}
function netEnd(){
  _netInFlight = Math.max(0, _netInFlight-1);
  if(_netInFlight!==0) return;
  clearTimeout(_netTimer);
  const b = document.getElementById('netBar');
  if(!b || !b.classList.contains('on')) return;
  const wait = Math.max(0, 600 - (Date.now() - _netShownAt));
  _netHideTimer = setTimeout(()=>{ if(_netInFlight===0) b.classList.remove('on'); }, wait);
}
// عدّاد الكتابات: التحديث التلقائي يُهمَل إن تزامن مع حفظ، لأن بياناته قد تكون أقدم من الحفظ نفسه
// (كان يعيد الطلب على الشاشة لحالته السابقة فيضغط المستخدم مرة ثانية ويتكرر السجل)
window._wSeq = 0; window._wInFlight = 0;
const READ_RPCS = ['/rpc/qy_log_event','/rpc/qy_users_private','/rpc/qy_people_names','/rpc/qy_my_company_names','/rpc/qy_budget_figures','/rpc/resolve_login_email','/rpc/qy_login_suspended','/rpc/verify_request'];
function trackedFetch(...args){
  const silent = window._netSilent;
  if(!silent) netStart();
  let url = '', method = 'GET';
  try{ const a0 = args[0]; url = String((a0 && a0.url) || a0 || ''); method = String((args[1] && args[1].method) || (a0 && a0.method) || 'GET').toUpperCase(); }catch(e){}
  const isWrite = url.includes('/rest/v1/') && method!=='GET' && method!=='HEAD' && !READ_RPCS.some(p=>url.includes(p));
  if(isWrite){ window._wSeq++; window._wInFlight++; }
  return fetch(...args).then(r=>{ window._dbLastOk = !!r && (r.ok || r.status<500); return r; }, e=>{ window._dbLastOk = false; throw e; })
    .finally(()=>{ if(isWrite){ window._wInFlight = Math.max(0, window._wInFlight-1); window._wSeq++; } if(!silent) netEnd(); });
}
const db = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {global:{fetch: trackedFetch}});
// الجلسة مشتركة بين تبويبات المتصفح: لو دخل أحد بحساب آخر في تبويب، صارت كل التبويبات تكتب بذاك الحساب
// بينما واجهتها تعرض المستخدم القديم. نكتشف الاختلاف ونُعيد التحميل بدل أن تُرفض العمليات بأخطاء غامضة.
let _qyAuthWatchBusy = false;
try{
  db.auth.onAuthStateChange((ev, sess)=>{
    try{
      if(_qyAuthWatchBusy || typeof state==='undefined' || !state.user || state.impersonatingFromAdmin || state._loggingOut) return;
      if(ev!=='SIGNED_IN' && ev!=='SIGNED_OUT' && ev!=='USER_UPDATED') return;
      const mine = (state.users||[]).find(u=>u.id===state.user.id);
      const myAuth = mine && mine.authId;
      if(!myAuth) return;
      const now = sess && sess.user ? sess.user.id : null;
      if(now !== myAuth){
        _qyAuthWatchBusy = true;
        alert(now ? 'تم تسجيل الدخول بحساب آخر في تبويب آخر من المتصفح. ستُعاد تحميل هذه الصفحة لتطابق الحساب الحالي.' : 'تم تسجيل الخروج من تبويب آخر. ستُعاد تحميل الصفحة.');
        location.reload();
      }
    }catch(e){}
  });
}catch(e){}

