const ASSISTANT_WEBHOOK = 'https://vmi3593541.contaboserver.net/webhook/qayam-assistant';
// توكن يمنع الاستعمال العابر فقط (ظاهر في الصفحة)، ويجب أن يطابق TOKEN في عقدة «تحقق وتنقية» داخل n8n
const ASSISTANT_TOKEN   = '7bcfd76f64572cc6b1f17708d0b1344b';
const ASSISTANT_SRC     = 'https://cdn.jsdelivr.net/npm/@n8n/chat@1.36.4/dist/chat.bundle.es.js';
const ASSISTANT_CSS     = 'https://cdn.jsdelivr.net/npm/@n8n/chat@1.36.4/dist/style.css';
// من يرى الفقاعة. تُوسَّع بإضافة 'accountant' و'cfo' وغيرهما بعد التجربة.
// null = كل المستخدمين المسجّلين. للتقييد: ['admin','accountant','cfo']
const ASSISTANT_ROLES   = null;

// يضع زرّ الإغلاق (الذي فيه سهم) يسار الترويسة والعنوان يمينها، دون الاعتماد
// على أسماء class المكتبة: يستثني فقاعة التبديل وصندوق الكتابة وزر الإرسال.
function placeAssistantClose(){
  const root = document.getElementById('qyamAssistant');
  if(!root) return;
  root.querySelectorAll('button').forEach(btn=>{
    if(!btn.querySelector('svg')) return;
    if(btn.closest('[class*="toggle"],[class*="input"],[class*="footer"],[class*="message"]')) return;
    const p = btn.parentElement;
    if(!p || p === root || p.dataset.qyFixed === '1') return;
    p.dataset.qyFixed = '1';
    p.style.direction = 'ltr';
    p.style.flexDirection = 'row';
    p.style.justifyContent = 'space-between';
    btn.style.order = '-1';
    btn.style.margin = '0';
    const h = p.querySelector('h1,h2,h3');
    if(h){ h.style.order='1'; h.style.direction='rtl'; h.style.textAlign='right'; h.style.flex='1 1 auto'; }
  });
}

let assistantMounted = false;
let assistantChat = null;
// مسودة الشات: ما يكتبه المستخدم ولم يرسله يُحفظ باسمه في هذا المتصفح، فيعود له بعد الخروج والدخول
function astDraftKey(){ return 'qy_chat_draft_' + ((state.user||{}).id||''); }
function astDraftRestore(){
  const ta = document.querySelector('#qyamAssistant textarea'); if(!ta || ta.dataset.qyDraft) return;
  ta.dataset.qyDraft = '1';
  let v = ''; try{ v = localStorage.getItem(astDraftKey()) || ''; }catch(e){}
  if(v && !ta.value){ ta.value = v; ta.dispatchEvent(new Event('input', {bubbles:true})); }
}
document.addEventListener('input', e=>{ const t = e.target; if(!t || t.tagName!=='TEXTAREA' || !t.closest('#qyamAssistant') || !state.user) return; try{ if(t.value) localStorage.setItem(astDraftKey(), t.value); else localStorage.removeItem(astDraftKey()); }catch(x){} }, true);
document.addEventListener('keydown', e=>{ const t = e.target; if(t && t.tagName==='TEXTAREA' && t.closest('#qyamAssistant') && e.key==='Enter' && !e.shiftKey){ try{ localStorage.removeItem(astDraftKey()); }catch(x){} } }, true);
document.addEventListener('click', e=>{ const b = e.target.closest && e.target.closest('#qyamAssistant button'); if(b && b.closest('[class*="input"],[class*="footer"]')){ try{ localStorage.removeItem(astDraftKey()); }catch(x){} } }, true);
// تبديل المستخدم (دخول بالنيابة / عودة / خروج): تُمحى محادثة المساعد وجلستها حتى لا تظهر لغير صاحبها
function assistantReset(){
  try{ Object.keys(localStorage).filter(k=>k.indexOf('n8n-chat')>=0).forEach(k=>localStorage.removeItem(k)); }catch(e){}
  try{ Object.keys(sessionStorage).filter(k=>k.indexOf('n8n-chat')>=0).forEach(k=>sessionStorage.removeItem(k)); }catch(e){}
  try{ if(assistantChat && assistantChat.unmount) assistantChat.unmount(); }catch(e){}
  assistantChat = null;
  // عقدة جديدة بدل القديمة: تسقط معها المراقبات والمستمعات فلا تتكرر عند إعادة التركيب
  const root = document.getElementById('qyamAssistant'); if(root && root.parentNode){ const fresh = root.cloneNode(false); fresh.innerHTML=''; root.parentNode.replaceChild(fresh, root); }
  assistantMounted = false;
}
function canSeeAssistant(){ return !!state.user && (!ASSISTANT_ROLES || ASSISTANT_ROLES.includes(state.user.role)); }

async function mountAssistant(){
  if(assistantMounted || !canSeeAssistant() || !ASSISTANT_WEBHOOK) return;
  assistantMounted = true;                     // قبل الانتظار، لئلا يُركَّب مرتين
  try{
    if(!document.getElementById('n8nChatCss')){
      const l = document.createElement('link');
      l.id='n8nChatCss'; l.rel='stylesheet'; l.href=ASSISTANT_CSS;
      document.head.appendChild(l);
    }
    const { createChat } = await import(ASSISTANT_SRC);
    const co = (state.companies||[]).find(c=>c.id===state.currentCompanyId) || {};
    assistantChat = createChat({
      webhookUrl: ASSISTANT_WEBHOOK,
      webhookConfig: { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-qayam-token': ASSISTANT_TOKEN } },
      target: '#qyamAssistant',
      mode: 'window',
      loadPreviousSession: true,
      showWelcomeScreen: false,
      // هوية السائل تُرسل مع كل رسالة: يسجّلها المسار اليوم،
      // ويقيّد بها بحثه في القاعدة حين يأتي دور أسئلة البيانات.
      metadata: {
        app: 'qyam-sarf',
        userId: state.user.id,
        userName: state.user.name,
        phone: ((state.users||[]).find(u=>u.id===state.user.id)||{}).phone || state.user.phone || '',
        role: state.user.role,
        companyId: state.currentCompanyId || '',
        companyName: co.nameAr || ''
      },
      initialMessages: [
        'مرحباً 👋',
        'أنا مساعد النظام الذكي. اسألني عن أي خطوة لا تعرف كيف تتمّها.',
        'لإرسال ملاحظة أو اقتراح عن النظام، ابدأ رسالتك بكلمة «ملاحظة» وسأسجّلها لمدير النظام.'
      ],
      i18n: { en: {
        title: 'مساعد النظام الذكي',
        subtitle: 'اسأل عن أي شيء في النظام.',
        footer: '',
        getStarted: 'محادثة جديدة',
        inputPlaceholder: 'اكتب سؤالك…',
        closeButtonTooltip: 'إغلاق'
      }}
    });
    // الواجهة تُبنى بعد التركيب وتُعاد عند الفتح والإغلاق: نعيد الضبط عند كل تغيير
    const rootEl = document.getElementById('qyamAssistant');
    if(rootEl){
      placeAssistantClose(); astDraftRestore();
      new MutationObserver(()=>{ placeAssistantClose(); astDraftRestore(); }).observe(rootEl, { childList:true, subtree:true });
      // ملحوظة في الشات: حين يؤكد المساعد تسجيلها (بعد رسالة أرسلها المستخدم الآن) يُبلَّغ مدير النظام بإشعار جهاز
      let noteArm = 0;
      rootEl.addEventListener('keydown', e=>{ if(e.key==='Enter' && !e.shiftKey) noteArm = Date.now(); }, true);
      rootEl.addEventListener('click', e=>{ if(e.target.closest && e.target.closest('button')) noteArm = Date.now(); }, true);
      new MutationObserver(muts=>{
        if(!noteArm || Date.now()-noteArm > 90000) return;
        for(const m of muts){ for(const n of m.addedNodes){
          const t = (n.textContent||'');
          if(t.indexOf('تم تسجيل ملاحظتك')>-1){ noteArm = 0; try{ db.rpc('qy_push_note'); }catch(e){} return; }
        } }
      }).observe(rootEl, { childList:true, subtree:true });
    }
  }catch(e){
    assistantMounted = false;                  // تعذّر التحميل: تُعاد المحاولة لاحقاً
    console.error('تعذّر تحميل المساعد:', e);
  }
}

// ===================== الشريط الجانبي الدائم (خريطة الموقع) =====================
state.navPeek = false; state.navDrawer = false;
function navPref(){ try{ return localStorage.getItem('qayam_nav_pref'); }catch(e){ return null; } }
function navEffectiveMode(){
  const w = window.innerWidth;
  if(w < 700) return state.navDrawer ? 'drawer' : 'hidden';
  if(state.navPeek) return 'open';
  const pref = navPref();
  if(pref==='open' || pref==='collapsed') return pref;
  return w > 1150 ? 'open' : 'collapsed';
}
function toggleNav(){
  const cur = navEffectiveMode();
  try{ localStorage.setItem('qayam_nav_pref', cur==='open' ? 'collapsed' : 'open'); }catch(e){}
  state.navPeek = false; renderAppNav();
}
function openNavDrawer(){ state.navDrawer = true; renderAppNav(); renderMobileTabs(); }
function closeNavDrawer(){ state.navDrawer = false; renderAppNav(); renderMobileTabs(); }
function navPeekOpen(){ state.navPeek = true; renderAppNav(); }
// كل نقرة تنقّل تُنهي أي فتح مؤقت أو قائمة الجوال
// ينفّذ أمر واجهة (قائمة خطوات) كأنه نقرة، بلا نص برمجي
function qyRunJs(tok){ qrun(tok, document.body, new Event('click')); }
function navClick(tok){ return qhs([["#3",[]]], tok); }
// ───────── مجموعات التنقل: صف علوي للمجموعة وصف سفلي لما تحتها ─────────
function injectGroupNav(){
  const app = document.getElementById('app'); if(!app || !state.user) return;
  app.querySelectorAll(':scope > .adm-nav2[data-gn]').forEach(e=>e.remove());
  if(app.querySelector(':scope > .adm-nav2')) return;            // صفحات لها رأسها الخاص (لوحة التحكم: صفّان كما هي)
  const v = state.view;
  // خارج لوحة التحكم: صف تبويبات واحد بلون واحد (صفحات القسم وأجزاء الصفحة معاً)،
  // وتحته صف ثابت لسطر التعريف بالصفحة. لا يختفيان في أي صفحة.
  const mk = darkHtml=>{
    const nav = document.createElement('div'); nav.className='adm-nav2 no-print'; nav.dataset.gn='1';
    nav.innerHTML = `<div class="adm-tabs2">${darkHtml}</div><div id="secTabs"></div>`;
    app.insertBefore(nav, app.firstChild);
  };
  const t2 = (label, on, attrs, count)=>`<button type="button" class="adm-t2${on?' active':''}" ${attrs||''}>${escH(label)}${count?` <span class="tab-count">${count}</span>`:''}</button>`;
  // صف أجزاء خاص بالصفحة (الإيرادات، القيود الدورية...): يصعد إلى الصف الواحد، وما بقي (مرشّحات داخل المحتوى) يصير أزراراً متجاورة لا صفاً فاتحاً
  const solos = [...app.querySelectorAll(':scope > .adm-subs-solo')];
  const toSeg = el=>{
    el.classList.remove('adm-subs','adm-subs-solo'); el.classList.add('seg','page-seg');
    el.querySelectorAll('.adm-sub').forEach(b=>{ const on = b.classList.contains('active'); b.classList.remove('adm-sub','active'); b.classList.add('seg-btn'); if(on) b.classList.add('on'); });
  };
  const partsHtml = el=>[...el.querySelectorAll('.adm-sub')].map(b=>{
    const c = b.cloneNode(true); c.classList.remove('adm-sub'); c.classList.add('adm-t2'); c.removeAttribute('style'); return c.outerHTML; }).join('');
  // حسابي: أجزاؤه (البطاقات) هي تبويبات الصف
  if(v==='account'){
    const cards = [...app.children].filter(e=>e.classList && e.classList.contains('card') && !e.closest('.modal-overlay'));
    if(cards.length>=2){
      const lab = c=>{ const h=c.querySelector('h2'); let t=h?h.textContent.trim():'قسم'; if(/^عرض صفحات/.test(t)) t='عرض الصفحات'; return t; };
      const cur = Math.min(cards.length-1, Math.max(0, Number(state.accountSec||0)));
      cards.forEach((c,i)=>{ c.dataset.accsec = i; c.hidden = (i!==cur); });
      mk(cards.map((c,i)=>t2(lab(c), i===cur, `data-accsec-tab="${i}" data-on-click="setAccountSec" data-on-click-args="${qa([(i)])}"`)).join(''));
    } else mk(t2('حسابي', true, 'data-on-click="#10"'));
    solos.forEach(toSeg);
    return;
  }
  const sec = navSections().find(x=>!x.admin && x.pages.some(pg=>pg.views.includes(v)));
  if(!sec){
    // صفحة خارج الأقسام (فحص المسارات، طلبات شركات سابقة بلا طلبات...): الصف باسمها، فلا تختلف عن غيرها
    const h = app.querySelector(':scope > h1'); const t = h ? h.textContent.replace(/\s+/g,' ').trim() : '';
    if(t && v!=='login') mk(t2(t, true, 'tabindex="-1"'));
    solos.forEach(toSeg);
    return;
  }
  const isOn = pg => (pg.on!==undefined) ? pg.on : pg.views.includes(v);
  if(sec.pages.length===1 && solos.length){
    // قسم من صفحة واحدة لها أجزاء: الأجزاء هي الصف
    mk(partsHtml(solos[0])); solos[0].remove(); solos.slice(1).forEach(toSeg);
    return;
  }
  mk(sec.pages.map(pg=>t2(pg.label, isOn(pg), qon('click', navClick(pg.js)), pg.count)).join(''));
  solos.forEach(toSeg);
}
// الصف الفاتح بلا أجزاء: يحمل سطر التعريف بالصفحة (أو ملاحظتها، كملاحظة المعاينة) بدل أن يبقى فارغاً أو يختفي
function viewNote(){
  const v = state.view;
  if(v==='detail'){
    const r = state.requests.find(x=>x.id===state.activeReqId);
    return r ? `الطلب <bdi>${escH(r.number||'قيد المراجعة')}</bdi>: تفاصيله ومراحل اعتماده. «معاينة الطلب» تعرضه كما سيُطبع.` : 'تفاصيل الطلب ومراحل اعتماده.';
  }
  if(v==='newRequest') return state.editingReqId ? 'عدّل بيانات الطلب ثم اضغط «حفظ التعديلات».' : '';
  if(v==='newRequestChoice') return 'ابدأ طلباً جديداً فارغاً أو انسخ طلباً سابقاً.';
  if(v==='duplicateList') return 'اختر الطلب الذي تريد نسخه طلباً جديداً.';
  if(v==='oldRequests') return 'طلباتك في شركات لم تعد مرتبطاً بها، للمتابعة فقط.';
  if(v==='custodyList') return 'العهد التي في عهدتك أو طلبتها لغيرك، وحالة كل منها. اضغط أي عهدة لفتح صفحتها.';
  if(v==='custody') return 'حياة العهدة من طلبها إلى إقفالها، وأرصدتها. مسار اعتماد طلبها بأسماء المعتمدين في صفحة الطلب: «عرض الطلب».';
  if(v==='newCustody') return (state.custodyDraft && state.custodyDraft.reqId) ? 'عدّل بيانات العهدة ثم اضغط «حفظ التعديلات».' : 'اختر صاحب العهدة والبند والمبلغ والغرض، ثم اضغط «إرسال للاعتماد». يعتمدها من حدّدته الشركة لمسار العهدة، ثم المالية.';
  if(v==='dashboard') return state.dashStatusFilter==='mypending' ? 'الطلبات التي تنتظر قرارك الآن. اضغط أي طلب لفتحه واتخاذ قرارك.' : 'كل طلبات الصرف التي تخصك وحالة كل منها. اضغط أي طلب لفتحه.';
  if(v==='monitor') return 'ما يحدث في الشركة الآن: من ينتظر قراره، وما في يد المالية، وآخر الحركات.';
  if(v==='securityLog') return 'تنبيهات الحماية وأخطاء الواجهة ومحاولات الدخول، وما روجع منها.';
  return '';
}
function fillSecNote(){
  const host = document.getElementById('secTabs'), app = document.getElementById('app');
  if(!host || !app || host.children.length) return;           // فيه أجزاء الصفحة أو ملاحظتها
  // سطر التعريف هو أول ما بعد الصفّين (يُتخطّى العنوان المنقول للشريط العلوي وزر الرجوع)، لا أي ملاحظة في وسط الصفحة
  const nv = host.closest('.adm-nav2');
  let e = nv ? nv.nextElementSibling : null;
  while(e && (e.tagName==='H1' || e.classList.contains('adm-head') || e.classList.contains('back-link') || e.classList.contains('print-header') || e.classList.contains('page-seg') || (e.tagName!=='P' && getComputedStyle(e).display==='none'))) e = e.nextElementSibling;
  const p = (e && e.tagName==='P' && e.classList.contains('sub')) ? e : null;
  const note = document.createElement('div'); note.className = 'sec-note';
  if(p){ while(p.firstChild) note.appendChild(p.firstChild); p.remove(); note.dataset.moved = '1'; }
  else {
    const vn = viewNote();
    // صفحة الطلب الجديد: بلا سطر تعريف، فيرتفع النموذج
    if(!vn && state.view==='newRequest'){ host.classList.add('sec-hide'); return; }
    note.innerHTML = vn || '&nbsp;';
  }
  host.classList.remove('sec-hide');
  host.appendChild(note);
}
function setAccountSec(i){
  state.accountSec = i;
  document.querySelectorAll('#app > .card[data-accsec]').forEach(c=>{ c.hidden = (Number(c.dataset.accsec)!==i); });
  document.querySelectorAll('[data-accsec-tab]').forEach(b=>b.classList.toggle('active', Number(b.dataset.accsecTab)===i));
  window.scrollTo(0,0);
}
// مجموعات الشريط الجانبي القابلة للفتح والإغلاق: المعاملات المالية | لوحة التحكم | المساعدة
function inFinArea(){
  const v = state.view;
  if(['dashboard','detail','newRequest','newRequestChoice','duplicateList','printPreview','revenues','recurring','handovers','oldRequests','monitor','budgetReport','cancelledArchive','custodyList','newCustody','custody','clients','catalog','centerBooks','centerBook','gwImport'].includes(v)) return true;
  return !inAdminArea() && ['ledger','analytics'].includes(v);
}
function inHelpArea(){ return ['guide','sitemap'].includes(state.view); }
function navGroupOf(){ return inAdminArea() ? 'admin' : inFinArea() ? 'fin' : inHelpArea() ? 'help' : null; }
function navGroupPref(){ try{ return JSON.parse(localStorage.getItem('qayam_nav_groups')||'{}') || {}; }catch(e){ return {}; } }
function navGroupSet(k, v){ const p = navGroupPref(); p[k] = !!v; try{ localStorage.setItem('qayam_nav_groups', JSON.stringify(p)); }catch(e){} }
function navGroupIsOpen(k){
  if(k==='admin') return inAdminArea();
  const p = navGroupPref();
  return (k in p) ? !!p[k] : (k==='fin');          // المالية مفتوحة لأول زيارة، والمساعدة مطوية
}
function navGroupToggle(k){ navGroupSet(k, !navGroupIsOpen(k)); renderAppNav(); }
// المساعد: بند الشريط والتبويب مفتاح (يفتح ثم يغلق). ويُغلق تلقائياً إذا لم يُكتب فيه شيء
// عند الانتقال لصفحة أخرى أو بعد دقيقتين من الخمول. وإذا بدأت محادثة فلا يُغلق من تلقائه.
const ASSISTANT_IDLE_MS = 120000;
let _astActivity = Date.now();
function assistantParts(){
  const root = document.getElementById('qyamAssistant'); if(!root) return {};
  const tgl = root.querySelector('[class*="chat-window-toggle"]');
  const win = root.querySelector('[class*="chat-window"]:not([class*="wrapper"]):not([class*="toggle"])');
  return {root, tgl, win, open: !!(win && win.getBoundingClientRect().height > 60)};
}
function assistantUsed(){
  const {root} = assistantParts(); if(!root) return false;
  const ta = root.querySelector('textarea');
  return !!root.querySelector('[class*="from-user"]') || !!(ta && ta.value.trim());
}
function assistantAutoClose(){
  const p = assistantParts();
  if(p.open && p.tgl && !assistantUsed()) p.tgl.click();
}
async function openAssistant(){
  if(!canSeeAssistant()) return;
  try{ if(!assistantMounted) await mountAssistant(); }catch(e){}
  let p = assistantParts();
  for(let i=0;i<30 && !p.tgl;i++){ await new Promise(r=>setTimeout(r,100)); p = assistantParts(); }
  if(!p.tgl){ showToast('المساعد غير متاح الآن، حاول بعد قليل'); return; }
  _astActivity = Date.now();
  p.tgl.click();                                   // يفتح إن كان مغلقاً ويغلق إن كان مفتوحاً
}
['input','keydown','click','pointerdown'].forEach(ev=>document.addEventListener(ev, e=>{
  if(e.target && e.target.closest && e.target.closest('#qyamAssistant')) _astActivity = Date.now();
}, true));
setInterval(()=>{ if(Date.now()-_astActivity > ASSISTANT_IDLE_MS) assistantAutoClose(); }, 10000);
// ═════ أقسام الموقع ═════
// الشريط الجانبي يعرض الأقسام فقط، والصف العلوي يعرض صفحات القسم المفتوح فقط: لا تظهر صفحة في المكانين.
// كل قسم: {key, ico, label, count, pages:[{label, views, js, on?, count?}]}. لوحة التحكم لها رأسها الخاص.
function navSections(){
  const u = state.user; if(!u) return [];
  const v = state.view, out = [];
  const pend = (typeof getMyPendingRequests==='function') ? getMyPendingRequests().length : 0;
  const nOld = (typeof oldCoReqList==='function') ? oldCoReqList().length : 0;
    // «بانتظار قراري» لم يعد تبويباً: هو زر «بانتظار قرارك» في فلتر صفحة الطلبات، ورقمه على القسم وعلى زر «الطلبات» في الهاتف
  const req = [{label:'كل الطلبات', views:['dashboard','detail','duplicateList','printPreview'], js:[["navGoRequests",[]]]}];
  req.push({label:'طلب صرف جديد', views:['newRequest','newRequestChoice'], js:[["#5",[]]]});
  if(nOld) req.push({label:'طلباتي في شركات أخرى', count:nOld, views:['oldRequests'], js:[["openOldRequests",[]]]});
  // الإسناد صار تبويباً في «طلبات الصرف» (كان قسماً مستقلاً في الشريط الجانبي)
  const hoN = canSeeHandovers() && typeof hoMyPendingToMeCount==='function' ? hoMyPendingToMeCount() : 0;
  if(canSeeHandovers()) req.push({label:'إسناد المعاملات', count:hoN, views:['handovers'], js:[["openHandovers",[]]]});
  out.push({key:'req', ico:'clip', label:'طلبات الصرف', count:pend + hoN, pages:req});
  if(state.custodyReady && pageLevel('custody')!=='none'){
    const kN = custodyTasksMine(state.currentCompanyId).length;
    const finU = ['accountant','cfo','admin'].includes(state.user.role), cidn = state.currentCompanyId;
    const LIVEK = ['open','returned','close_requested','acct_review','pending_sign','awaiting_receipt'].concat(state.user.role==='admin' ? ['requested'] : []);
    const nOpenK = (state.custodies||[]).filter(k=>k.companyId===cidn && LIVEK.includes(k.status)).length, nClosedK = (state.custodies||[]).filter(k=>k.companyId===cidn && k.status==='closed').length;
    const ft = state.cusFinTab;
    const cpages = [
      {label:'عهدي', count:kN, views:['custodyList','custody'], on:(v==='custodyList' && !ft) || v==='custody', js:[["openCustodyList",[]]]},
      {label:'عهدة جديدة', views:['newCustody'], js:[["openNewCustody",[]]]}
    ];
    if(finU){
      cpages.push({label:'عهد الشركة المفتوحة', count:nOpenK, views:[], on: v==='custodyList' && ft==='open', js:[["cusFinTab",["open"]]]});
      cpages.push({label:'عهد الشركة المقفلة', count:nClosedK, views:[], on: v==='custodyList' && ft==='closed', js:[["cusFinTab",["closed"]]]});
      const nBalK = (state.custodyBalances||[]).filter(b=>b.companyId===cidn && b.status==='open').length;
      cpages.push({label:'المبالغ المعلّقة', count:nBalK, views:[], on: v==='custodyList' && ft==='bal', js:[["cusFinTab",["bal"]]]});
    }
    if(!finU && state.user && (state.companies.find(c=>c.id===cidn)||{}).custodyAlertUserId===state.user.id) cpages.push({label:'عهد متجاوزة', views:[], on: v==='custodyList' && ft==='over', js:[["cusFinTab",["over"]]]});
    out.push({key:'cus', ico:'case', label:'العهد', count:kN, pages:cpages});
  }
  if(canSeeRevenues()) out.push({key:'rev', ico:'cash', label:'الإيرادات', pages:[{label:'الإيرادات', views:['revenues'], js:[["openRevenues",[0]]]}]});
  if(canSeeCenterBook() || canSeeGwImport()){
    const pg = [];
    if(canSeeCenterBooks()) pg.push({label:'لوحة المراكز', views:['centerBooks'], js:[["openCenterBooks",[]]]});
    if(canSeeCenterBook()) pg.push({label:'دفتر المركز', views:['centerBook'], js:[["openCenterBook",[]]]});
    if(canSeeGwImport()) pg.push({label:'استيراد البوابة', views:['gwImport'], js:[["openGwImport",[]]]});
    out.push({key:'cbk', ico:'building', label:'المراكز', pages:pg});
  }
  if(canSeeCatalog()) out.push({key:'prj', ico:'layers', label:'المشاريع', pages:[{label:'خدمات الشركة', views:['catalog'], js:[["openCatalog",[]]]}]});
  if(canSeeClients()) out.push({key:'cli', ico:'me', label:'العملاء', pages:[{label:'العملاء', views:['clients'], js:[["openClients",[]]]}]});
  if(canSeeRecurring()) out.push({key:'rec', ico:'repeat', label:'القيود الدورية', count:recDueCount(), pages:[{label:'القيود الدورية', views:['recurring'], js:[["openRecurring",[0]]]}]});
  const rep = [];
  if(canSeeMonitor()) rep.push({label:'لوحة المتابعة', views:['monitor'], js:[["openMonitor",[]]]});
  if(pageLevel('ledger')!=='none') rep.push({label:'دفتر الحركات', views:['ledger'], js:[["#6",[]]]});
  if(pageLevel('analytics')!=='none'){
    if(canSeeExec()){
      const at = state.analyticsTab || 'exec';
      rep.push({label:'اللوحة التنفيذية', views:['analytics'], on: v==='analytics' && at==='exec', js:[["openAnalyticsTab",["exec"]]]});
      rep.push({label:'التفاصيل المالية', views:['analytics'], on: v==='analytics' && at==='details', js:[["openAnalyticsTab",["details"]]]});
    } else rep.push({label:'التحليلات المالية', views:['analytics'], js:[["#7",[]]]});
  }
  if(pageLevel('budgetReport')!=='none') rep.push({label:'تقرير الميزانية', views:['budgetReport'], js:[["openBudgetReport",[]]]});
  if(pageLevel('cancelled')!=='none') rep.push({label:'أرشيف الملغاة', views:['cancelledArchive'], js:[["openCancelledArchive",[]]]});
  if(rep.length) out.push({key:'rep', ico:'chart', label:'المتابعة والتقارير', pages:rep});
  if(u.role==='admin') out.push({key:'admin', ico:'sliders', label:'لوحة التحكم', admin:true, pages:[]});
  else out.push({key:'account', ico:'account', label:'حسابي', pages:[{label:'حسابي', views:['account'], js:[["#10",[]]]}]});
  const help = [{label:'دليل المستخدم', views:['guide'], js:[["#8",[]]]}, {label:'خريطة الموقع', views:['sitemap'], js:[["#9",[]]]}];
  if(canSeeAssistant() && ASSISTANT_WEBHOOK) help.push({label:'مساعد النظام الذكي', views:[], js:[["openAssistant",[]]]});
  out.push({key:'help', ico:'help', label:'المساعدة', pages:help});
  out.forEach(sec=>{ sec.active = sec.admin ? inAdminArea() : sec.pages.some(pg=>pg.views.includes(v)); });
  return out;
}
function navGoRequests(){ state.view = 'dashboard'; render(); window.scrollTo(0,0); }
function navMyPending(){ state.dashStatusFilter = 'mypending'; state.view = 'dashboard'; render(); window.scrollTo(0,0); }
function navTopItems(){
  return navSections().map(sec => sec.admin
    ? {key:'admin', ico:sec.ico, label:sec.label, group:'admin', active:sec.active}
    : {key:sec.key, ico:sec.ico, label:sec.label, count:sec.count, active:sec.active, js:sec.pages[0].js, pages:sec.pages});
}
// صندوق العمل يبقى بمنتصف الصفحة تماماً ما دام عرضه ≥ 840 بكسل، وإلا يُزاح بالقدر الأدنى اللازم كي لا يتداخل مع الشريط
// (يُحسب بعد رسم المحتوى لأن ظهور شريط التمرير يغيّر العرض المتاح)
function navApplyPadding(navW){
  if(navW===undefined){ const m=(document.getElementById('appNav')||{}).dataset; navW = m ? ({open:240,collapsed:64}[m.mode]||0) : 0; }
  // فجوة ثابتة بجانب الشريط الداكن: بلا هذه كان الصندوق يلتصق به تماماً
  const RAIL_GAP = 16;
  // قاعدة واحدة لكل الصفحات: احجز عرض الشريط وفجوته، ولا تعكس شيئاً على اليسار.
  // الصندوق يبدأ بعد الشريط، والفائض كله يذهب يساراً.
  let pl = 0, pr = navW ? (navW + RAIL_GAP) : 0;
  document.documentElement.style.setProperty('--nav-pl', pl+'px');
  document.documentElement.style.setProperty('--nav-pr', pr+'px');
}
function renderAppNav(){
  try{ renderAppNavInner(); } finally { if(state.user){ try{ applyPageWidth(); }catch(e){} } }
}
function renderAppNavInner(){
  const nav = document.getElementById('appNav'); if(!nav) return;
  const show = !!state.user && state.view!=='login';
  document.body.classList.toggle('has-nav', show);
  if(!show){ nav.setAttribute('data-mode','hidden'); nav.innerHTML=''; document.documentElement.style.setProperty('--nav-w','0px'); document.documentElement.style.setProperty('--nav-pl','0px'); document.documentElement.style.setProperty('--nav-pr','0px'); document.body.classList.remove('nav-drawer-open'); return; }
  const mode = navEffectiveMode();
  nav.setAttribute('data-mode', mode);
  document.body.classList.toggle('nav-drawer-open', mode==='drawer');
  const navW = mode==='open' ? 240 : mode==='collapsed' ? 64 : 0;
  document.documentElement.style.setProperty('--nav-w', navW+'px');
  navApplyPadding(navW);
  const tb = document.querySelector('.topbar');
  document.documentElement.style.setProperty('--topbar-h', (tb ? Math.ceil(tb.getBoundingClientRect().height) : 64)+'px');
  { const g = navGroupOf(); if(g && g!=='admin' && g!==state._navLastG) navGroupSet(g, true); state._navLastG = g; }
  const collapsed = mode==='collapsed';
  const itemHtml = it=>{
    if(it.head) return collapsed ? '<div class="nav-sep"></div>' : `<div class="nav-headlabel">${escH(it.head)}</div>`;
    if(it.group==='admin'){
      const open = inAdminArea() && !collapsed;
      // الشريط الجانبي: البنود العامة الخمسة فقط — تبويباتها تظهر داخل الصفحة
      const curG = inAdminArea() ? activeAdminGroup() : null;
      const sub = ADMIN_NAV.map(g=>
        `<div class="admin-nav-item${curG && curG.gkey===g.gkey ? ' active':''}" data-nav-item data-nav-label="${escH(g.cat)}" ${qon('click', navClick([["openAdminGroup",[(''+(g.gkey))]]]))}>${escH(g.cat)}${g.gkey==='seclog' && state.secUnread ? `<span class="nav-count">${state.secUnread}</span>` : ''}</div>`
      ).join('');
      const headJs = collapsed ? [["navPeekOpen",[]]] : navClick([["#11",[]]]);
      return `<div class="nav-group">
        <div class="nav-item${it.active?' active':''}" title="${escH(it.label)}" ${qon('click', headJs)}><span class="nav-ico">${qiOr(it.ico)}</span><span class="nav-label">${escH(it.label)}</span>${!open && state.secUnread ? `<span class="nav-count">${state.secUnread}</span>` : ''}<span class="nav-caret">${open?'▲':'▼'}</span></div>
        ${open ? `<div class="nav-sub">${sub}</div>` : ''}
      </div>`;
    }
    if(it.group){
      const open = navGroupIsOpen(it.group) && !collapsed;
      const sub = it.subs.map(x=>
        `<div class="admin-nav-item${x.active?' active':''}" data-nav-item data-nav-label="${escH(x.label)}" ${qon('click', navClick(x.js))}>${escH(x.label)}${x.count?`<span class="nav-count">${x.count}</span>`:''}</div>`
      ).join('');
      const headJs = collapsed ? [["navPeekOpen",[]]] : [["navGroupToggle",[(''+(it.group))]]];
      const totalCount = open ? 0 : it.subs.reduce((n,x)=>n+(x.count||0),0);
      return `<div class="nav-group">
        <div class="nav-item${it.active?' active':''}" title="${escH(it.label)}" ${qon('click', headJs)}><span class="nav-ico">${qiOr(it.ico)}</span><span class="nav-label">${escH(it.label)}</span>${totalCount?`<span class="nav-count">${totalCount}</span>`:''}<span class="nav-caret">${open?'▲':'▼'}</span></div>
        ${open ? `<div class="nav-sub">${sub}</div>` : ''}
      </div>`;
    }
    return `<div class="nav-item${it.active?' active':''}" title="${escH(it.label)}" ${qon('click', navClick(it.js))}><span class="nav-ico">${qiOr(it.ico)}</span><span class="nav-label">${escH(it.label)}</span>${it.count?`<span class="nav-count">${it.count}</span>`:''}</div>`;
  };
  nav.innerHTML = `
    <div class="nav-head"><button type="button" class="nav-toggle" ${qon('click', mode==='drawer'?[["closeNavDrawer",[]]]:[["toggleNav",[]]])} title="${mode==='drawer'?'إغلاق':'طيّ/فتح القائمة'}">${mode==='drawer'?'✕':'☰'}</button><span class="nav-title">القائمة</span></div>
    <nav class="nav-list">${navTopItems().map(itemHtml).join('')}</nav>
    <div class="nav-foot"><div class="nav-user${state.view==='account'?' on':''}" role="button" tabindex="0" title="حسابي — ${escH(state.user.name)} · ${escH(findRole(state.user.role).name)}" ${qon('click', navClick([["#10",[]]]))} data-on-keydown="#35"><div class="nav-avatar">${avSrc(state.user.id) ? `<img src="${escH(avSrc(state.user.id))}" alt="">` : escH((state.user.name||'?').trim().charAt(0))}</div><div class="nav-uinfo"><div class="nav-uname">${escH(state.user.name)}</div><div class="nav-urole">${escH(findRole(state.user.role).name)}</div></div></div><button type="button" class="nav-logout" title="تسجيل الخروج" aria-label="تسجيل الخروج" ${qon('click', navClick([["logout",[]]]))}><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/></svg><span>خروج</span></button></div>${mode==='drawer' ? `<div class="nav-ver">${escH(appVersionText())}${isOwner() ? ` · ≈ ${appWorkTotal()} ساعة عمل` : ''}</div>` : ''}`;
}
let _navResizeT=null;
window.addEventListener('resize', ()=>{ clearTimeout(_navResizeT); _navResizeT=setTimeout(()=>{ if(state.navDrawer && window.innerWidth>=700) state.navDrawer=false; renderAppNav(); },80); });

// ===================== البحث الموحّد: أقسام الموقع + الطلبات =====================
function searchSectionIndex(){
  const out = [];
  navSections().forEach(sec=>{
    if(sec.admin) return;
    sec.pages.forEach(pg=>out.push({label:pg.label, sub:sec.label, js:pg.js}));
  });
  if(canSeeRevenues() && pageAtLeast('revenues','full')) out.push({label:'إيراد جديد', sub:'الإيرادات', js:[["openRevenues",[1]]]});
  if(state.user && state.user.role==='admin'){
    ADMIN_NAV.forEach(g=>g.items.forEach(i=>out.push({label:i.head||i.label, sub:'لوحة التحكم — '+g.cat, js:adminNavAction(i)})));
  }
  return out;
}
function searchRequestMatches(v){
  return state.requests.filter(r=>r.companyId===state.currentCompanyId && (
    (r.number||'').toLowerCase().includes(v) || (r.reason||'').toLowerCase().includes(v) ||
    r.beneficiaries.some(b=>(b.name||'').toLowerCase().includes(v)))).slice(0,6);
}
function updateSearchDrop(){
  const box = document.getElementById('searchDrop'); const inp = document.getElementById('searchInput');
  if(!box || !inp) return;
  document.querySelectorAll('.search-results').forEach(e=>e.remove());
  state.searchResults = null;
  const v = inp.value.trim().toLowerCase();
  if(!v){ box.innerHTML=''; box.style.display='none'; return; }
  const secs = searchSectionIndex().filter(x=>x.label.toLowerCase().includes(v)).slice(0,6);
  const reqs = searchRequestMatches(v);
  state._searchSecs = secs;
  let html = '';
  if(secs.length) html += `<div class="sd-group">الصفحات والأقسام</div>` + secs.map((x,i)=>`<div class="sd-item" data-on-mousedown="#36" data-on-mousedown-args="${qa([(i)])}"><span>${escH(x.label)}</span><span class="sd-sub">${escH(x.sub)}</span></div>`).join('');
  if(reqs.length) html += `<div class="sd-group">الطلبات</div>` + reqs.map(r=>`<div class="sd-item" data-on-mousedown="#37" data-on-mousedown-args="${qa([(''+(r.id))])}"><span style="font-weight:700;">${escH(r.number)}</span><span class="sd-sub">${escH(r.reason||'')}</span></div>`).join('');
  if(!html) html = `<div class="sd-item" style="color:var(--muted);">لا نتائج مطابقة</div>`;
  box.innerHTML = html; box.style.display='block';
}
function toggleSearch(force){
  const f = document.getElementById('searchFloat'); if(!f) return;
  const open = force===undefined ? !f.classList.contains('open') : !!force;
  f.classList.toggle('open', open);
  if(open){ const i = document.getElementById('searchInput'); if(i){ i.focus(); i.select(); } updateSearchDrop(); }
  else hideSearchDrop();
}
document.addEventListener('mousedown', function(e){
  const f = document.getElementById('searchFloat');
  if(f && f.classList.contains('open') && !e.target.closest('#searchFloat') && !e.target.closest('#searchBtn')) toggleSearch(false);
});
document.addEventListener('keydown', function(e){
  if(!state.user) return;
  const f = document.getElementById('searchFloat');
  if(e.key==='Escape' && f && f.classList.contains('open')) toggleSearch(false);
  else if((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='k'){ e.preventDefault(); toggleSearch(true); }
  else if((e.ctrlKey||e.metaKey) && !e.altKey && e.code==='KeyF'){
    // Ctrl+F يفتح بحث النظام؛ وإن كان مفتوحاً أصلاً فالضغطة الثانية تُترك للمتصفح ليبحث داخل نص الصفحة
    if(f && f.classList.contains('open')) return;
    e.preventDefault(); toggleSearch(true);
  }
  else if(e.code==='KeyF' && !e.ctrlKey && !e.metaKey && !e.altKey){
    // مفتاح F وحده (يعمل أيضاً مع لوحة المفاتيح العربية لأنه نفس المفتاح الفعلي) يفتح البحث، بشرط ألا تكون تكتب في حقل
    const t = e.target, tag = (t && t.tagName) || '';
    if(tag==='INPUT' || tag==='TEXTAREA' || tag==='SELECT' || (t && t.isContentEditable)) return;
    e.preventDefault(); toggleSearch(true);
  }
});
function hideSearchDrop(){ const b=document.getElementById('searchDrop'); if(b){ b.style.display='none'; } }
function runSearchSection(i){
  const x = (state._searchSecs||[])[i]; if(!x) return;
  const inp = document.getElementById('searchInput'); if(inp) inp.value='';
  hideSearchDrop(); toggleSearch(false);
  qyRunJs(navClick(x.js));
  window.scrollTo(0,0);
}

function toggleImpMin(v){ try{ localStorage.setItem('qayam_imp_min', v?'1':'0'); }catch(e){} renderTopbar(); }
// أيقونة الطباعة بالشريط العلوي: في الطلب تفتح معاينته وتطبع، وفي غيره تطبع الصفحة الحالية
async function topPrint(){
  if(state.view==='detail' && state.activeReqId){ await openPrintPreview(state.activeReqId); setTimeout(()=>window.print(), 500); return; }
  if(state.view==='orgTree' && typeof printOrgTree==='function'){ printOrgTree(); return; }   // الشجرة لها تجهيز خاص (A4 صفحة واحدة)
  window.print();
}
function renderTopbar(){
  const el = document.getElementById('topbarRight');
  if(!state.user){
    el.innerHTML='';
    const st0 = document.getElementById('impStrip'); if(st0){ st0.style.display='none'; st0.innerHTML=''; }   // لا يبقى شريط «العودة للأدمن» بعد الخروج
    return;
  }
  const bn = computeNotifications();
  const bellBtn = `<button type="button" class="bell-btn" data-on-click="toggleBell" data-on-click-args="${qa([QA.e])}" title="الإشعارات" aria-label="الإشعارات"><svg class="tb-svg" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/></svg><span class="bell-badge${bn.badge?' on':''}" id="bellBadge">${bn.badge>99?'99+':bn.badge}</span></button>`;
  const companySwitcher = (state.myCompanyIds && state.myCompanyIds.length>1)
    ? `<select class="tb-company" data-on-change="switchCompany" data-on-change-args="${qa([QA.v])}" style="border-radius:6px;padding:8px 10px;font-size:var(--fs-label);border:1px solid #2E4356;background:#2E4356;color:#fff;">
        ${state.myCompanyIds.map(id=>{ const c = state.companies.find(x=>x.id===id); const n = id===state.currentCompanyId ? 0 : getMyPendingRequests(id).length; return `<option value="${escH(id)}" ${id===state.currentCompanyId?'selected':''}>${escH(c?c.nameAr:id)}${n ? ' ('+n+' بانتظارك)' : ''}</option>`; }).join('')}
      </select>`
    : '';
  const impersonateSwitcher = (state.user.role==='admin' && !state.impersonatingFromAdmin)
    ? `<select class="tb-impersonate" data-on-change="#38" style="border-radius:6px;padding:8px 10px;font-size:var(--fs-label);border:1px solid #2E4356;background:#2E4356;color:#fff;max-width:180px;">
        <option value="">👁 عرض كمستخدم...</option>
        ${state.users.filter(u=>u.role!=='admin').map(u=>`<option value="${u.id}">${escH(u.name)} — ${escH(findRole(u.role).name)}</option>`).join('')}
      </select>`
    : '';
  const searchResultsHtml = (state.searchResults && state.searchResults.length>0) ? `
    <div class="search-results">
      ${state.searchResults.map(r=>`
        <div class="search-result-item" data-on-click="openSearchResult" data-on-click-args="${qa([(''+(r.id))])}">
          <span style="font-weight:700;">${escH(r.number)}</span>
          <span style="color:var(--muted);font-size:var(--fs-hint);">${escH(r.reason||'')}</span>
        </div>
      `).join('')}
    </div>` : '';
  const strip = document.getElementById('impStrip');
  if(strip){
    if(state.impersonatingFromAdmin){
      const min = (()=>{ try{ return localStorage.getItem('qayam_imp_min')==='1'; }catch(e){ return false; } })();
      strip.style.display='flex';
      strip.innerHTML = min
        ? `<button type="button" class="imp-dot" data-on-click="toggleImpMin" data-on-click-args="${qa([false])}" title="تتصفح الآن كـ ${escH(state.user.name)} — اضغط للتوسيع">👁</button>`
        : `<div class="imp-pill"><span>👁 تتصفح الآن كـ <b>${escH(state.user.name)}</b> · ${escH(findRole(state.user.role).name)}</span><button type="button" data-on-click="returnToAdmin">العودة لحسابي</button><button type="button" class="imp-min" data-on-click="toggleImpMin" data-on-click-args="${qa([true])}" title="تصغير">—</button></div>`;
    } else { strip.style.display='none'; strip.innerHTML=''; }
  }
  el.innerHTML = `
    <div class="tb-tools">
      ${companySwitcher}
      ${impersonateSwitcher}
      ${bellBtn}
      <button type="button" class="tb-icon" id="printBtn" data-on-click="topPrint" title="${state.view==='detail'||state.view==='printPreview' ? 'طباعة الطلب / حفظ PDF' : state.view==='orgTree' ? 'طباعة الشجرة كاملة' : 'طباعة هذه الصفحة'}" aria-label="طباعة"><svg class="tb-svg" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 9V3h12v6"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="7" rx="1"/></svg></button>
      <button type="button" class="tb-icon" id="searchBtn" data-on-click="toggleSearch" title="بحث عن صفحة أو طلب (F أو Ctrl+F)" aria-label="بحث"><svg class="tb-svg" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/></svg></button>
      <button type="button" class="tb-icon" data-on-click="refreshNow" data-on-click-args="${qa([true])}" title="تحديث بيانات الطلبات" aria-label="تحديث"><svg class="tb-svg" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8"/><path d="M21 3v5h-5"/><path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16"/><path d="M8 16H3v5"/></svg></button>
    </div>
    <div class="search-float" id="searchFloat">
      <div class="search-box">
        <input id="searchInput" type="search" class="qy-search" placeholder="ابحث عن صفحة أو طلب (رقم، عنوان، مستفيد)" data-on-input="updateSearchDrop" data-on-focus="updateSearchDrop" data-on-blur="#39" data-on-keydown="#40">
        <button data-on-click="doSearch">بحث</button>
      </div>
      <div class="search-drop" id="searchDrop" style="display:none;"></div>
      ${searchResultsHtml}
    </div>`;
}

function openAccount(){
  state.view='account';
  render();
}

function openAnalytics(){
  state.view='analytics';
  render();
}

function openAdmin(){
  state.view='admin';
  render();
}

function impersonateUser(userId){
  const target = state.users.find(u=>u.id===userId);
  if(!target) return;
  assistantReset(); state.dashOwner='all';
  state.impersonatingFromAdmin = state.user.id; state._impSeenAt = 0;
  state.user = {id: target.id, role: target.role, name: target.name};
  setupCompanyAccess(target);
  state.cx.balances = []; state.cx.centerId = null; state.cx.itemId = ''; loadCxLight();
  state.view = 'dashboard';
  showToast('تتصفح الآن كـ: ' + target.name + ' (' + findRole(target.role).name + ')', 'success');
  render();
}

function returnToAdmin(){
  const admin = state.users.find(u=>u.id===state.impersonatingFromAdmin);
  if(!admin) return;
  assistantReset(); state.dashOwner='all';
  state.user = {id: admin.id, role: admin.role, name: admin.name};
  setupCompanyAccess(admin);
  state.cx.balances = []; state.cx.centerId = null; state.cx.itemId = ''; loadCxLight();
  state.impersonatingFromAdmin = null;
  state.view = 'admin';
  render();
}

function doSearch(){
  const v = document.getElementById('searchInput').value.trim().toLowerCase();
  if(!v){ return; }
  const matches = state.requests.filter(r=>
    r.companyId===state.currentCompanyId && (
      r.number.toLowerCase().includes(v) ||
      (r.reason||'').toLowerCase().includes(v) ||
      r.beneficiaries.some(b=>(b.name||'').toLowerCase().includes(v))
    )
  );
  if(matches.length===0){
    const secs = searchSectionIndex().filter(x=>x.label.toLowerCase().includes(v));
    if(secs.length){ state._searchSecs = secs; runSearchSection(0); return; }
    showToast('لم يتم العثور على طلب أو صفحة تطابق هذا البحث','error');
    state.searchResults = null;
  } else if(matches.length===1){
    state.searchResults = null;
    state.activeReqId = matches[0].id;
    state.view='detail';
  } else {
    state.searchResults = matches;
  }
  render();
}
function openSearchResult(reqId){
  state.searchResults = null;
  state.activeReqId = reqId;
  state.view='detail';
  render();
}

async function logout(){ state._loggingOut = true; assistantReset(); state.dashOwner='all'; try{ if(state.user) qyLog('logout','خروج',''); await db.auth.signOut(); }catch(e){} clearSession(); state.user=null; state._loggingOut=false; state.impersonatingFromAdmin=null; state.bellOpen=false; state.navPeek=false; state.navDrawer=false; state.view='login'; state._navStack=[]; state._navPrev=null; const st0=document.getElementById('impStrip'); if(st0){ st0.style.display='none'; st0.innerHTML=''; } render(); }

// ───────── إغلاق الدخول تلقائياً عند عدم النشاط ─────────
// 30 دقيقة بلا نقر أو كتابة أو تمرير؛ تنبيه قبل الإغلاق بدقيقة؛ وآخر نشاط مشترك بين كل التبويبات.
const IDLE_DEFAULT_MIN = 30, IDLE_MIN_MIN = 5, IDLE_DEFAULT_CAP = 60, IDLE_WARN_MS = 60*1000;
// السقف: أطول مهلة يسمح بها المدير لكل دور (التخزين: app_settings.idle_caps) — وإن لم يُحدَّد فالسقف الافتراضي 60 دقيقة
function idleCaps(){ try{ return JSON.parse((state.appSettings && state.appSettings.idle_caps) || '{}') || {}; }catch(e){ return {}; } }
function idleCapFor(role){
  const c = idleCaps(); let v = Number(c[role]); if(!(v>0)) v = Number(c.default); if(!(v>0)) v = IDLE_DEFAULT_CAP;
  return Math.max(IDLE_MIN_MIN, v);
}
function idleLimitMin(){
  const cap = idleCapFor(state.user ? state.user.role : '');
  const mine = Number(state.myIdleMin) > 0 ? Number(state.myIdleMin) : IDLE_DEFAULT_MIN;
  return Math.min(Math.max(mine, IDLE_MIN_MIN), cap);
}
async function loadMyIdle(){
  if(!state.user) return;
  state.myIdleMin = null;
  try{
    const r = await db.from('users').select('idle_minutes').eq('id', state.user.id).maybeSingle();
    if(!r.error && r.data && r.data.idle_minutes) state.myIdleMin = r.data.idle_minutes;
  }catch(e){}
}
const IDLE_KEY = 'qayam_last_act', IDLE_OUT_KEY = 'qayam_idle_logout';
let _idleLocal = Date.now(), _idleWrite = 0;
function idleLastAct(){ let t = _idleLocal; try{ t = Math.max(t, Number(localStorage.getItem(IDLE_KEY))||0); }catch(e){} return t; }
function idleMark(){
  const n = Date.now(); _idleLocal = n;
  if(n - _idleWrite > 5000){ _idleWrite = n; try{ localStorage.setItem(IDLE_KEY, String(n)); }catch(e){} }
  const w = document.getElementById('idleWarn'); if(w && w.dataset.keep!=='1') w.remove();
}
['pointerdown','keydown','touchstart','scroll','input'].forEach(ev=>document.addEventListener(ev, idleMark, {capture:true, passive:true}));
function idleStay(){ _idleWrite = 0; idleMark(); const w = document.getElementById('idleWarn'); if(w) w.remove(); }
async function idleLogout(){
  const w = document.getElementById('idleWarn'); if(w) w.remove();
  try{ saveDraftToStorage(); }catch(e){}
  try{ localStorage.setItem(IDLE_OUT_KEY, String(Date.now())); }catch(e){}
  await logout();
  showToast('أُغلق دخولك تلقائياً لعدم النشاط. سجّل الدخول من جديد.');
}
window.addEventListener('storage', e=>{ if(e.key===IDLE_OUT_KEY && state.user && state.view!=='login'){ try{ saveDraftToStorage(); }catch(x){} logout(); } });
setInterval(()=>{
  if(!state.user || state.view==='login') return;
  if(state._idleFor !== state.user.id){ state._idleFor = state.user.id; loadMyIdle(); }
  const LIM = idleLimitMin()*60000;
  const idle = Date.now() - idleLastAct();
  if(idle >= LIM){ idleLogout(); return; }
  if(idle >= LIM - Math.min(IDLE_WARN_MS, LIM/2)){
    let w = document.getElementById('idleWarn');
    const left = Math.max(1, Math.ceil((LIM - idle)/1000));
    if(!w){
      w = document.createElement('div'); w.id='idleWarn'; w.className='no-print'; w.dataset.keep='1';
      w.style.cssText='position:fixed;inset:0;z-index:100000;background:rgba(15,25,35,.55);display:flex;align-items:center;justify-content:center;padding:16px;direction:rtl;';
      w.innerHTML = '<div role="alertdialog" aria-modal="true" style="background:#fff;border-radius:14px;padding:22px 24px;max-width:380px;width:100%;text-align:right;box-shadow:0 10px 40px rgba(0,0,0,.3);"><h2 style="margin:0 0 8px;font-size:var(--fs-h2);">هل ما زلت هنا؟</h2><p style="margin:0 0 16px;line-height:1.7;">سيُغلق دخولك بعد <b id="idleLeft"></b> ثانية لعدم النشاط، حمايةً لبياناتك.</p><button type="button" class="btn btn-primary btn-md" data-on-click="idleStay" title="يبقيك داخل النظام">ابقَ متصلاً</button></div>';
      document.body.appendChild(w);
    }
    const sp = document.getElementById('idleLeft'); if(sp) sp.textContent = left;
  }
}, 1000);

// يحوّل ما يكتبه المستخدم إلى بريد المصادقة: رقم هاتف ← <الرقم>@qyam.local ، وبريد ← كما هو
const AUTH_EMAIL_DOMAIN = '@qyam.local';
function loginIdToEmail(id){
  const v = String(id||'').trim().toLowerCase();
  return v.includes('@') ? v : v + AUTH_EMAIL_DOMAIN;
}

// الخادم يترجم ما يكتبه المستخدم إلى بريد المصادقة، فيقبل رقمه الحالي
// وأي رقم قديم ما زال صالحاً. يُرجع بريداً دائماً فلا يكشف من هو مسجَّل.
// وإن لم تكن الدالة منشورة بعد، نعود للاشتقاق المحلي كما كان.
async function resolveLoginEmail(idInput){
  const local = loginIdToEmail(idInput);
  try{
    const { data, error } = await db.rpc('resolve_login_email', { p_login: String(idInput||'').trim() });
    if(error || !data) return local;
    return String(data);
  }catch(e){ return local; }
}

// الأرقام القديمة التي ما زالت تصلح للدخول — لمدير النظام وحده،
// وقد لا يكون الجدول منشوراً بعد، فالفشل يُتجاهَل بصمت.
async function loadLoginAliases(){
  if(!state.loginAliases) state.loginAliases = [];
  if(!state.user || state.user.role !== 'admin') return;
  try{
    const { data, error } = await db.from('login_aliases').select('*');
    if(error) return;
    state.loginAliases = (data||[]).map(a=>({phone:a.phone, userId:a.user_id}));
  }catch(e){ /* الجدول غير موجود بعد */ }
}

async function removeLoginAlias(phone){
  if(!confirm('إلغاء صلاحية الرقم ' + phone + ' للدخول؟\n\nلن يستطيع صاحبه الدخول به بعدها، ويبقى رقمه الحالي وحده.')) return;
  const { error } = await db.rpc('admin_remove_login_alias', { p_phone: phone });
  if(error){ showToast('تعذّر الإلغاء: ' + (error.message||''), 'error'); return; }
  state.loginAliases = (state.loginAliases||[]).filter(a=>a.phone!==phone);
  showToast('أُلغيت صلاحية الرقم ' + phone, 'success');
  render();
}

async function attemptLogin(){
  const idInput = document.getElementById('loginPhone').value.trim();
  const pass    = document.getElementById('loginPassword').value;
  if(!idInput || !pass){ showToast('أدخل رقم الهاتف وكلمة المرور','error'); return; }

  const btn = document.querySelector('#loginPassword')?.closest('.card')?.querySelector('.btn-primary');
  if(btn){ btn.disabled = true; btn.textContent = 'جارٍ الدخول…'; }

  try{
    const loginEmail = await resolveLoginEmail(idInput);
    const { data, error } = await db.auth.signInWithPassword({
      email: loginEmail, password: pass
    });
    if(error || !data?.user){
      let suspendedAcc = !!(error && (error.code==='user_banned' || /banned/i.test(error.message||'')));
      if(!suspendedAcc && error){ try{ const sr = await db.rpc('qy_login_suspended', {p_email: loginEmail}); suspendedAcc = sr && sr.data===true; }catch(e){} }
      // الحساب الموقوف ليس «دخولاً فاشلاً»: يُسجَّل بنوعه حتى لا يختلط بمحاولات كلمة المرور الخاطئة
      if(suspendedAcc) qyLog('login_suspended', 'محاولة دخول بحساب موقوف', '', idInput);
      else qyLog('login_failed', (error && error.message) || 'بيانات غير صحيحة', '', idInput);
      if(suspendedAcc){
        qyBodyModal(`<div class="modal-box" style="max-width:min(94vw,460px);text-align:center;"><h2 style="margin-top:0;color:#b42318;"><span style="font-size:.7em;">⛔</span> حسابك موقوف <span style="font-size:.7em;">⛔</span></h2><p style="line-height:1.9;"><b style="font-size:var(--fs-h2);">🤍 شكراً لك 🤍</b><br>على ما قدّمته للشركة خلال فترة عملك معنا.<br>سنسعد بعودتك في أي وقت، وللعودة تواصل مع الإدارة لإعادة تفعيل حسابك.</p><div class="actions-row" style="justify-content:center;"><button class="btn btn-primary btn-md" data-on-click="qyBodyModalClose" data-on-click-args="${qa(["banned"])}">حسناً</button></div></div>`, 'banned');
        return;
      }
      showToast('رقم الهاتف أو كلمة المرور غير صحيحة','error');
      return;
    }
    // لا بيانات في الذاكرة قبل هذه اللحظة — تُحمَّل الآن بهوية المستخدم
    if(btn) btn.textContent = 'جارٍ تحميل البيانات…';
    await loadAllAfterAuth();
    await finishLogin(data.user.id);
    if(state.user){ qyLog('login_ok', 'دخول', ''); if(state.user.role==='admin') loadSecUnread(); }
  }catch(e){
    qyLog('login_failed', 'تعذّر الاتصال: ' + ((e && e.message)||''), '', idInput);
    showToast('تعذّر الاتصال بالخادم — حاول مجدداً','error');
  }finally{
    if(btn){ btn.disabled = false; btn.textContent = 'دخول'; }
  }
}

// يُستدعى بعد نجاح المصادقة: يربط حساب Auth بصف المستخدم ويكمل الدخول
async function finishLogin(authUid){
  let user = state.users.find(u => u.authId === authUid);
  if(!user){
    // الصفوف قد تكون قديمة في الذاكرة — أعِد تحميلها مرة واحدة
    await reloadUsers();
    user = state.users.find(u => u.authId === authUid);
  }
  if(!user){
    await db.auth.signOut();
    // فشل قراءة المستخدمين نفسها ليس «حساباً غير مرتبط»: تظهر الرسالة الصحيحة للتشخيص
    if(state._usersErr){ qyLog('login_failed','تعذّر تحميل المستخدمين: '+state._usersErr,''); showToast('تعذّر تحميل بيانات المستخدمين من الخادم — أبلغ الدعم الفني ('+state._usersErr+')','error'); return; }
    showToast('الحساب غير مرتبط بمستخدم في النظام — راجع مدير النظام','error');
    return;
  }
  if(user.isSuspended){
    qyLog('login_suspended', 'محاولة دخول بحساب موقوف', '', user.phone||'');
    await db.auth.signOut();
    showToast('هذا الحساب موقوف — راجع مدير النظام','error');
    return;
  }
  state.user = {id:user.id, role:user.role, name:user.name};
  setupCompanyAccess(user);
  loadLoginAliases();
  const remember = document.getElementById('rememberMeCheck')?.checked;
  saveSession(user.id, remember);
  state.view = user.role==='admin' ? 'admin' : 'dashboard';
  render();
  maybeAutoOpenBell();
}

// آخر شركة عمل فيها المستخدم — تُحفظ لكل مستخدم على حدة في هذا المتصفح،
// فيفتح النظام حيث تركه لا حيث سُجِّل. وإن لم يوجد محفوظ، أو لم يعد
// مسموحاً له بها، رجع إلى شركته المسجَّلة كما كان.
function lastCompanyKey(userId){ return 'qayam_last_company_' + userId; }
function loadLastCompany(userId){
  try{ return localStorage.getItem(lastCompanyKey(userId)); }catch(e){ return null; }
}
function saveLastCompany(userId, companyId){
  try{ if(userId && companyId) localStorage.setItem(lastCompanyKey(userId), companyId); }catch(e){}
}
function pickStartCompany(user){
  const allowed = state.myCompanyIds || [];
  const last = loadLastCompany(user.id);
  if(last && allowed.includes(last)) return last;
  if(user.companyId && allowed.includes(user.companyId)) return user.companyId;
  return allowed[0] || null;
}

function setupCompanyAccess(user){
  if(user.role==='admin'){
    state.myCompanyIds = state.companies.map(c=>c.id);
    state.currentCompanyId = pickStartCompany(user);
    return;
  }
  const full = state.users.find(u=>u.id===user.id) || user;
  const extra = full.isGeneral ? state.companies.map(c=>c.id) : (state.userCompanyLinks||[]).filter(l=>l.userId===user.id).map(l=>l.companyId);
  const ids = new Set(extra);
  if(user.companyId) ids.add(user.companyId);
  state.myCompanyIds = Array.from(ids);
  state.currentCompanyId = pickStartCompany(user);
}

function switchCompany(companyId){
  state.currentCompanyId = companyId;
  if(state.user) saveLastCompany(state.user.id, companyId);
  showToast('تم التبديل إلى: ' + (state.companies.find(c=>c.id===companyId)?.nameAr||''), 'success');
  state.budgetSums = null; loadBudgetSums().then(()=>{ if(state.budgetSums) render(); });
  render();
}

function newDraft(){
  if(newReqBlocked()) return;
  const saved = loadDraftFromStorage();
  if(saved && saved.draft){
    state.editingReqId = saved.editingReqId || null;
    state.draft = saved.draft;
    state.view='newRequest';
    showToast('تم استرجاع مسودة طلب سابقة لم تُرسل — راجعها ثم أرسل، أو ابدأ من جديد', 'success');
    render();
    return;
  }
  state.editingReqId = null;
  state.draft = {
    reason:'', detailedReason:'', number: null, isRecurring:false,
    beneficiaries:[{name:'', nameEn:'', iban:'', civilId:'', statement:'', notes:'', amount:'', deduction:'', deductionNote:'', extra:'', extraNote:'', idFileName:'', idFileData:'', bankFileName:'', bankFileData:'', isNew:true}]
  };
  state.view='newRequest';
  render();
}
function discardDraftAndStartFresh(){
  clearDraftStorage();
  state.editingReqId = null;
  state.draft = {
    reason:'', detailedReason:'', number: null, isRecurring:false,
    beneficiaries:[{name:'', nameEn:'', iban:'', civilId:'', statement:'', notes:'', amount:'', deduction:'', deductionNote:'', extra:'', extraNote:'', idFileName:'', idFileData:'', bankFileName:'', bankFileData:'', isNew:true}]
  };
  render();
}

// من مُنع «طلب جديد»: رسالة واضحة بدل إخفاء الزر أو تحويل صامت
function newReqBlocked(){
  if(pageLevel('newreq')!=='none') return false;
  openNewRequestChoice();
  return true;
}
// صلاحية «تعديل طلباتي» مستقلة عن «طلب صرف جديد»: من مُنع التعديل تظهر له رسالة ويبقى في صفحته
function canEditMyRequests(companyId){
  const u = state.user; if(!u) return false;
  if(u.role==='admin') return true;
  const co = companyId || state.currentCompanyId || u.companyId;
  return PAGE_LEVEL_RANK[pageLevelFor(u.role, 'editreq', co)] >= PAGE_LEVEL_RANK.edit;
}
function editReqBlocked(req){
  if(canEditMyRequests(req && req.companyId)) return false;
  qyBodyModal(`<div class="modal-box" style="max-width:min(94vw,440px);text-align:center;">
      <h2 style="margin-top:0;">تعديل الطلب</h2>
      <p style="line-height:1.9;">ليست لديك صلاحية «تعديل طلباتي» في هذه الشركة.<br>تستطيع رؤية طلبك ومتابعته، أما تعديله فيحتاج هذه الصلاحية من مدير النظام.</p>
      <div class="actions-row" style="justify-content:center;"><button class="btn btn-primary btn-md" data-on-click="qyBodyModalClose" data-on-click-args="${qa(["noedit"])}">حسناً</button></div></div>`, 'noedit');
  return true;
}
function openNewRequestChoice(){
  // الزر يبقى ظاهراً للجميع (إخفاؤه يُربك)؛ من مُنع تظهر له رسالة واضحة بدل أن يبحث عنه
  if(pageLevel('newreq')==='none'){
    qyBodyModal(`<div class="modal-box" style="max-width:min(94vw,440px);text-align:center;">
      <h2 style="margin-top:0;">طلب صرف جديد</h2>
      <p style="line-height:1.9;">ليست لديك صلاحية إنشاء طلب صرف في هذه الشركة.<br>إن كنت تحتاجها فراجع مدير النظام.</p>
      <div class="actions-row" style="justify-content:center;"><button class="btn btn-primary btn-md" data-on-click="qyBodyModalClose" data-on-click-args="${qa(["nonew"])}">حسناً</button></div></div>`, 'nonew');
    return;
  }
  state.view='newRequestChoice';
  render();
}

function openDuplicateList(mode){
  state.duplicateListMode = mode;
  state.view='duplicateList';
  render();
}

function duplicateFromRequest(id){
  if(newReqBlocked()) return;
  const req = state.requests.find(r=>r.id===id);
  if(!req) return;
  state.editingReqId = null;
  state.draft = {
    reason: req.reason, detailedReason: req.detailedReason||'', salutationText: req.salutationText||'', referenceText: req.referenceText||'', number: null, isRecurring: !!req.isRecurring,
    beneficiaries: req.beneficiaries.map(b=>({
      name:b.name, nameEn:b.nameEn, iban:b.iban, civilId:b.civilId, statement:b.statement, notes:b.notes,
      amount:b.amount, deduction:b.deduction, deductionNote:b.deductionNote, extra:b.extra||0, extraNote:b.extraNote,
      idFileName:'', idFileData:'', bankFileName:'', bankFileData:'', isNew:false
    }))
  };
  state.view='newRequest';
  showToast('تم تعبئة الطلب — راجع البيانات قبل الإرسال', 'success');
  render();
}

function renderNewRequestChoice(app){
  app.innerHTML = `
    <h1>طلب صرف جديد</h1>
    <p class="sub">اختر طريقة إنشاء الطلب</p>
    <div class="role-grid">
      <div class="role-card" data-on-click="newDraft">
        <b>إنشاء من الصفر</b>
        <span>تعبئة كل البيانات يدوياً من البداية</span>
      </div>
      <div class="role-card" data-on-click="openDuplicateList" data-on-click-args="${qa(["recurring"])}">
        <b>من الطلبات المتكررة</b>
        <span>قائمة مختصرة بالطلبات المعلّمة كمتكررة (رواتب، عهد...)</span>
      </div>
      <div class="role-card" data-on-click="openDuplicateList" data-on-click-args="${qa(["all"])}">
        <b>من كل الطلبات المصروفة سابقاً</b>
        <span>اختيار أي طلب سابق تم صرفه كنقطة بداية</span>
      </div>
    </div>
  `;
}

function renderDuplicateList(app){
  const mode = state.duplicateListMode;
  let list = state.requests.filter(r=>r.status==='completed' && r.createdById===state.user.id && r.requestType!=='custody');
  if(mode==='recurring') list = list.filter(r=>r.isRecurring);
  list = list.slice().reverse();

  app.innerHTML = `
    <h1>${mode==='recurring' ? 'الطلبات المتكررة' : 'كل الطلبات المصروفة'}</h1>
    <p class="sub">اختر طلباً لتعبئة نموذج جديد بنفس بياناته</p>
    ${list.length===0 ? `<div class="empty">لا توجد طلبات ${mode==='recurring' ? 'متكررة معلّمة' : 'مصروفة'} بعد</div>` : list.map(r=>`
      <div class="list-item" data-on-click="duplicateFromRequest" data-on-click-args="${qa([(''+(r.id))])}">
        <div class="li-main">
          <b>${escH(r.reason)} — ${escH(r.number)}</b>
          <span>${escH(r.beneficiaries.map(b=>b.name).join('، '))} · ${fmtKWDHtml(r.totalAmount)} د.ك</span>
        </div>
        ${r.isRecurring ? `<span class="badge badge-approved">متكرر</span>` : ''}
      </div>
    `).join('')}
  `;
}

function editRequest(id){
  const req = state.requests.find(r=>r.id===id);
  if(!req || !isEditable(req)) return;
  if(editReqBlocked(req)) return;
  if(req.requestType==='custody'){ openCustodyEdit(req); return; }
  state.editingReqId = id;
  // البند و«هل يتكرر» كانا يسقطان من المسودّة، فيفتح النموذج بلا البند المحفوظ
  state.draft = {
    reason: req.reason, detailedReason: req.detailedReason||'', salutationText: req.salutationText||'', referenceText: req.referenceText||'', number: req.number, requestNotes: req.requestNotes||'',
    budgetItemId: req.budgetItemId || UNSPECIFIED_BUDGET,
    isRecurring: !!req.isRecurring,
    beneficiaries: req.beneficiaries.map(b=>({...b, idFileName:'', idFileData:'', bankFileName:'', bankFileData:''}))
  };
  state.view='newRequest';
  render();
}

async function pushHistory(req, entry){
  const result = await db.from('request_history').insert({request_id:req.id, step:entry.step, actor:entry.actor, user_id:entry.userId, action:entry.action, note:entry.note, time:entry.time, signature_override: entry.signatureOverride||null});
  if(!(await dbCheck(result, 'حفظ سجل الإجراء'))) return false;
  req.history.push(entry);
  return true;
}
async function setRequestStatus(req, newStatus){
  // التغيير مشروط بأن تكون الحالة على الخادم كما يراها المستخدم: ضغطة من شاشة قديمة تُرفض بلا تكرار
  const result = await db.from('requests').update({status:newStatus}).eq('id', req.id).eq('status', req.status).select('id');
  if(!(await dbCheck(result, 'تحديث حالة الطلب'))) return false;
  // تحديث لم يطابق أي صف (حالة تغيّرت أو صلاحية) يُعد فشلاً، لا نجاحاً صامتاً
  if(!result.data || !result.data.length){
    showToast('حالة الطلب تغيّرت قبل حفظ إجرائك (من جهاز أو مستخدم آخر). عُرضت الحالة الحالية.','error');
    try{ await refreshRequests(); }catch(e){}
    return false;
  }
  req.status = newStatus;
  return true;
}

function deleteRequestCfo(id){
  const req = state.requests.find(r=>r.id===id);
  if(!req) return;
  requestDeleteConfirm(`إبطال الطلب رقم ${escH(req.number)}؟ سيبقى محفوظاً بالأرشيف ويمكن استرجاعه لاحقاً.`, 'cancel_request', id);
}
function deleteRequest(id){
  const req = state.requests.find(r=>r.id===id);
  if(!req || !isEditable(req)) return;
  requestDeleteConfirm(`إبطال الطلب رقم ${escH(req.number)}؟ سيبقى محفوظاً بالأرشيف ويمكن استرجاعه لاحقاً.`, 'cancel_request', id);
}
async function executeCancelRequest(id){
  const updates = {is_cancelled:true, cancelled_at:new Date().toISOString(), cancelled_by_id: state.user.id};
  const result = await db.from('requests').update(updates).eq('id', id);
  if(!(await dbCheck(result, 'إبطال الطلب'))) return;
  const req = state.requests.find(r=>r.id===id);
  if(req){ req.isCancelled = true; req.cancelledAt = updates.cancelled_at; req.cancelledById = state.user.id;
    await pushHistory(req, {step:req.status, actor:state.user.name, userId:state.user.id, action:'إبطال الطلب', note:'', time:fmtDate()}); }
  state.view='dashboard';
  showToast('تم إبطال الطلب ونقله للأرشيف', 'success');
  render();
}
async function restoreRequest(id){
  const req = state.requests.find(r=>r.id===id);
  if(!req) return;
  const updates = {is_cancelled:false, cancelled_at:null, cancelled_by_id:null};
  const result = await db.from('requests').update(updates).eq('id', id);
  if(!(await dbCheck(result, 'استرجاع الطلب'))) return;
  req.isCancelled = false; req.cancelledAt = null; req.cancelledById = null;
  await pushHistory(req, {step:req.status, actor:state.user.name, userId:state.user.id, action:'استرجاع الطلب', note:'', time:fmtDate()});
  showToast('تم استرجاع الطلب', 'success');
  render();
}
async function executeDeleteRequest(id){
  // السطور التابعة (المستفيدون، السجل، خطوات الاعتماد) تُحذف تلقائياً بـ CASCADE.
  // سجل تجاوز الميزانية لا يرتبط بمفتاح أجنبي، فنحذفه صراحةً لئلا يبقى يتيماً.
  try{ await db.from('budget_overrun_log').delete().eq('request_id', id); }catch(e){}
  const delResult = await db.from('requests').delete().eq('id', id);
  if(!(await dbCheck(delResult, 'حذف الطلب'))) return;
  state.requests = state.requests.filter(r=>r.id!==id);
  if(state.view!=='cancelledArchive') state.view='dashboard';   // الحذف من الأرشيف يبقيك فيه
  if(state.activeReqId===id) state.activeReqId = null;
  showToast('تم حذف الطلب نهائياً', 'success');
  render();
}

// حذف نهائي من أرشيف الملغاة — لمدير النظام وحده، ولا تراجع عنه
function deleteRequestPermanently(id){
  if(state.user.role!=='admin'){ showToast('الحذف النهائي من صلاحية مدير النظام وحده', 'error'); return; }
  const req = state.requests.find(r=>r.id===id);
  if(!req) return;
  requestDeleteConfirm(
    `حذف الطلب <b>${req.number || '(بلا رقم)'}</b> نهائياً؟<br>يُمحى هو ومستفيدوه وسجله من قاعدة البيانات، ولا يمكن استرجاعه.`,
    'request', id);
}

function isEditable(req){
  if(req.status==='pending_decision') return true;
  if(OLD_DECISION_STATUSES.includes(req.status)) return true;
  if(req.status==='rejected') return true;
  return false;
}

function syncDraftFromDOM(){
  const reasonEl = document.getElementById('reasonInput');
  if(reasonEl) state.draft.reason = reasonEl.value;
  const detailedEl = document.getElementById('detailedReasonInput');
  if(detailedEl) state.draft.detailedReason = detailedEl.value;
  const notesEl = document.getElementById('requestNotesInput');
  if(notesEl) state.draft.requestNotes = notesEl.value;
  const rtEl = document.getElementById('cxRoute');
  if(rtEl){ state.draft.amountRoute = rtEl.value; const rcEl = document.getElementById('cxRouteCenter'); state.draft.routeCenterId = rcEl ? (rcEl.value||null) : null; }
  const recEl = document.getElementById('recurringCheck');
  if(recEl) state.draft.isRecurring = recEl.checked;
  const biEl = document.getElementById('budgetItemSelect');
  if(biEl) state.draft.budgetItemId = biEl.value || null;
  document.querySelectorAll('.beneficiary-block').forEach((b,i)=>{
    const item = state.draft.beneficiaries[i];
    if(!item) return;
    item.name = b.querySelector('.b-name').value;
    item.nameEn = b.querySelector('.b-nameEn').value;
    item.iban = b.querySelector('.b-iban').value;
    const civilIdEl = b.querySelector('.b-civilId');
    if(civilIdEl) item.civilId = civilIdEl.value;
    item.statement = b.querySelector('.b-statement').value;
    item.notes = b.querySelector('.b-notes').value;
    item.amount = b.querySelector('.b-amount').value;
    const dedEl = b.querySelector('.b-deduction');
    const dedNoteEl = b.querySelector('.b-deductionNote');
    if(dedEl) item.deduction = dedEl.value;
    if(dedNoteEl) item.deductionNote = dedNoteEl.value;
    const extraEl = b.querySelector('.b-extra');
    const extraNoteEl = b.querySelector('.b-extraNote');
    if(extraEl) item.extra = extraEl.value;
    if(extraNoteEl) item.extraNote = extraNoteEl.value;
  });
}

function isKnownBeneficiary(name){
  return state.beneficiaries.some(x=>x.name===name && x.companyId===state.currentCompanyId);
}

// حساب رصيد بند الميزانية محلياً
async function logBudgetOverrun(requestId, budgetItemId, stage, requestedAmount, availableBalance){
  try {
    await sb.from('budget_overrun_log').insert({
      request_id: requestId,
      budget_item_id: budgetItemId,
      stage,
      actor_id: state.user?.id || null,
      actor_name: state.user?.name || null,
      requested_amount: requestedAmount,
      available_balance: availableBalance
    });
  } catch(e){ console.warn('logBudgetOverrun error', e); }
}

// ═══ دفتر الحركات ═════════════════════════════════════════════════════
// سطر لكل حركة مالية، لا يُعدَّل ولا يُحذف (حارس في قاعدة البيانات نفسها).
// التصحيح يكون بقيد عاكس يشير إلى الأصل عبر reversesId.
// رسائل القاعدة التقنية → عربية مفهومة
function friendlyLedgerError(msg){
  msg = String(msg||'');
  if(/transactions_reverses_once_idx|duplicate key/.test(msg)) return 'هذه الحركة عُكست من قبل (ربما بيد مستخدم آخر قبل لحظات). حدّثت الدفتر لك.';
  const known = ['عُكست من قبل','عليها استرداد قائم','يتجاوز المبلغ الأصلي','معكوسة، فلا استرداد','لا يُسترد من حركة','حركة عاكسة','اتجاه الاسترداد'];
  for(const k of known){ if(msg.indexOf(k)>-1) return msg; }
  return 'تعذّر تسجيل الحركة في الدفتر: ' + msg;
}
function mapTransactionRow(t){
  return {
    id:t.id, companyId:t.company_id, centerId:t.center_id||null, date:t.tx_date,
    direction:t.direction, amount:Number(t.amount)||0, budgetItemId:t.budget_item_id||null,
    beneficiary:t.beneficiary||'', description:t.description||'',
    sourceType:t.source_type, sourceId:t.source_id||null, reversesId:t.reverses_id||null, refundOfId:t.refund_of_id||null,
    note:t.note||'', createdById:t.created_by_id||null, createdBy:t.created_by||'', createdAt:t.created_at
  };
}

async function postTransaction(tx){
  const row = {
    company_id:    tx.companyId || state.currentCompanyId,
    center_id:     tx.centerId || null,
    tx_date:       tx.date || new Date().toISOString().slice(0,10),
    direction:     tx.direction,
    amount:        Number(tx.amount),
    budget_item_id: tx.budgetItemId || null,
    beneficiary:   tx.beneficiary || null,
    description:   tx.description,
    source_type:   tx.sourceType,
    source_id:     tx.sourceId || null,
    reverses_id:   tx.reversesId || null,
    note:          tx.note || null,
    created_by_id: state.user ? state.user.id : null,
    created_by:    state.user ? state.user.name : null
  };
  if(tx.refundOfId) row.refund_of_id = tx.refundOfId;
  const {data, error} = await db.from('transactions').insert(row).select().single();
  if(error){
    console.error('تسجيل الحركة', error);
    showToast(friendlyLedgerError(error.message), 'error');
    return null;
  }
  state.transactions = state.transactions || [];
  state.transactions.unshift(mapTransactionRow(data));
  return data;
}

// هل لهذا المستند حركة مسجَّلة أصلاً؟ يمنع ازدواج القيد لو تكرّر الاستدعاء
function hasTransactionFor(sourceType, sourceId){
  return (state.transactions||[]).some(t=>t.sourceType===sourceType && t.sourceId===sourceId && !t.reversesId);
}

// ═══ أرقام البند الأربعة ══════════════════════════════════════════════
// رقم واحد لا يجيب عن سؤالين مختلفين، فنفصل:
//   المصروف فعلاً — خرج من الصندوق. مصدره الدفتر لا حالة الطلب.
//   المرتبط       — اكتمل قراره ولم يُدفع بعد. وعدٌ قاطع.
//   قيد الطلب     — ما زال في سلسلة القرار. احتمال قد يُرفض فيعود.
// والمتاح = الإيراد − ربح الشركة − الثلاثة. ولأن شيئاً من هذا لا يُخزَّن،
// فرفض طلبٍ أو إلغاؤه يُعيد مبلغه إلى المتاح تلقائياً بلا «فكّ حجز» يدوي.
function isFinanceUser(){ return !!state.user && ['accountant','cfo','admin'].includes(state.user.role); }
async function loadBudgetSums(){
  if(!state.user || isFinanceUser() || !state.currentCompanyId) return;
  try{
    const r = await db.rpc('qy_budget_figures', {p_company: state.currentCompanyId});
    if(r.error || !r.data) return;
    const m = {}; r.data.forEach(x=>{ m[x.budget_item_id] = {committed:Number(x.committed)||0, pending:Number(x.pending)||0, extra:Number(x.reserved_extra)||0}; });
    state.budgetSums = m;
  }catch(e){}
}
const CUSTODY_LIVE_RESERVE = ['awaiting_receipt','open','returned','close_requested','acct_review','pending_sign'];
const COMMITTED_STATUSES = ['pending_transfer_request','pending_transfer_approval',
                            'pending_disbursement','pending_accountant','pending_cfo'];
function isPendingDecisionStatus(s){ return s==='pending_decision' || OLD_DECISION_STATUSES.includes(s); }

function computeBudgetItemFigures(itemId){
  const item = (state.budgetItems||[]).find(b=>b.id===itemId);
  if(!item) return null;

  const totalRev = (state.budgetRevenues||[])
    .filter(r=>r.budget_item_id===itemId)
    .reduce((s,r)=>s+(Number(r.amount)||0),0);

  let profit = 0;
  if(item.profit_mode==='percent')     profit = totalRev*(item.profit_percent||0)/100;
  else if(item.profit_mode==='fixed')  profit = Math.min(totalRev, item.profit_fixed||0);
  else if(item.profit_mode==='both')   profit = totalRev*(item.profit_percent||0)/100 + (item.profit_fixed||0);

  // المصروف فعلاً: مجموع الخروج ناقص ما عُكس منه بقيد عاكس
  const txs = (state.transactions||[]).filter(t=>t.budgetItemId===itemId);
  // سطر عاكس ليس صرفاً: استُثني من الطرفين، وإلا عُدّ عكسُ الإيراد مصروفاً
  const out      = txs.filter(t=>t.direction==='out' && !t.reversesId).reduce((s,t)=>s+t.amount,0);
  const reversed = txs.filter(t=>t.direction==='in' && t.reversesId).reduce((s,t)=>s+t.amount,0);
  const spent    = out - reversed;

  const live = (state.requests||[]).filter(r=>r.budgetItemId===itemId && !r.isCancelled && r.status!=='rejected');
  let committed = live.filter(r=>COMMITTED_STATUSES.includes(r.status))
                        .reduce((s,r)=>s+(Number(r.totalAmount)||0),0);
  let pending   = live.filter(r=>isPendingDecisionStatus(r.status))
                        .reduce((s,r)=>s+(Number(r.totalAmount)||0),0);
  // غير المالية لا يرى كل طلبات الشركة؛ المجاميع تأتيه من الخادم (أرقام فقط) فلا يظهر له متاح أكبر من الحقيقي
  const srv = !isFinanceUser() && state.budgetSums ? state.budgetSums[itemId] : null;
  if(!isFinanceUser() && state.budgetSums){ committed = Math.max(committed, srv ? srv.committed : 0); pending = Math.max(pending, srv ? srv.pending : 0); }
  // محجوز العهد: المبلغ المصروف للعهدة المفتوحة محجوز حتى إقفالها (ضمن المصروف في الدفتر)، ويُحجز فوقه المرحَّل والصرف الزائد فور تسجيله
  let reservedCustody = 0, reservedExtra = 0;
  if(isFinanceUser()){
    (state.custodies||[]).filter(k=>k.budgetItemId===itemId && CUSTODY_LIVE_RESERVE.includes(k.status)).forEach(k=>{
      const sm = custodySums(k);
      reservedCustody += Number(k.amount)||0;
      reservedExtra += (Number(k.carriedIn)||0) + Math.max(0, -sm.B);
    });
  } else if(srv){ reservedExtra = srv.extra||0; }
  reservedExtra = Math.round(reservedExtra*1000)/1000;
  committed += reservedExtra;      // المرحَّل والصرف الزائد يُحجزان من رصيد البند كالمرتبط

  return { revenue: totalRev, profit, spent, committed, pending, reservedCustody, reservedExtra,
           available: totalRev - profit - spent - committed - pending };
}

// المتاح وحده — للنداءات القديمة التي تنتظر رقماً واحداً
function computeBudgetItemBalance(itemId){
  const f = computeBudgetItemFigures(itemId);
  return f ? f.available : null;
}

// المتاح لو استبعدنا طلباً بعينه من الحساب.
// يلزم عند اعتماد طلب: هو نفسه داخل «قيد الطلب»، فمقارنة مبلغه بالمتاح
// تخصمه مرتين وتُطلق تحذيراً كاذباً على بند رصيده كافٍ تماماً.
function computeBudgetItemBalanceExcluding(itemId, reqId){
  const f = computeBudgetItemFigures(itemId);
  if(!f) return null;
  const r = (state.requests||[]).find(x=>x.id===reqId);
  const own = (r && r.budgetItemId===itemId && !r.isCancelled && r.status!=='rejected'
               && (isPendingDecisionStatus(r.status) || COMMITTED_STATUSES.includes(r.status)))
            ? (Number(r.totalAmount)||0) : 0;
  return f.available + own;
}

// جمع IDs كل الفروع (بأي عمق) لبند معين
function getDescendantIds(itemId, allItems){
  const children = allItems.filter(b=>b.parent_id===itemId);
  return children.reduce((acc,c)=>[...acc, c.id, ...getDescendantIds(c.id, allItems)], []);
}

// حساب الرصيد المجمّع للبند + كل فروعه
function computeBudgetItemBalanceTotal(itemId){
  const allItems = state.budgetItems||[];
  const ids = [itemId, ...getDescendantIds(itemId, allItems)];
  let total = 0;
  let hasAny = false;
  for(const id of ids){
    const b = computeBudgetItemBalance(id);
    if(b !== null){ total += b; hasAny = true; }
  }
  return hasAny ? total : null;
}

// بيانات مجمّعة لبند شاملة الفروع — بالأرقام الأربعة المفصولة
function computeBudgetItemStats(itemId, includeChildren){
  const allItems = state.budgetItems||[];
  const ids = includeChildren ? [itemId, ...getDescendantIds(itemId, allItems)] : [itemId];
  let rev=0, profit=0, spent=0, committed=0, pending=0;
  for(const id of ids){
    const f = computeBudgetItemFigures(id);
    if(!f) continue;
    rev+=f.revenue; profit+=f.profit; spent+=f.spent; committed+=f.committed; pending+=f.pending;
  }
  return { rev, profit, spent, committed, pending,
           bal: rev-profit-spent-committed-pending,   // المتاح لطلب جديد
           net: rev-profit };
}

function onBudgetItemSelectChange(){
  syncDraftFromDOM();
  showBudgetBalance();
}
// سطر الرصيد تحت «بند الميزانية»: القائمة تحمل اسم البند فقط، والرصيد هنا بلونه
function showBudgetBalance(){
  const sel = document.getElementById('budgetItemSelect');
  const box = document.getElementById('budgetItemBalanceBox');
  if(!sel||!box) return;
  const itemId = sel.value;

  // «بند غير محدد»: تحذير صريح بأن الطلب ناقص ولن يُصرف قبل إسناده لبند حقيقي
  if(itemId === UNSPECIFIED_BUDGET){
    box.style.cssText = 'display:block;margin-top:-2px;padding:8px 11px;border-radius:8px;font-size:var(--fs-hint);'
      + 'line-height:1.75;background:rgba(245,158,11,.1);color:#8a5a00;border:1px solid var(--amber);';
    box.innerHTML = '<b style="font-size:var(--fs-label);">⚠️ الطلب لن يكتمل بهذا الاختيار</b><br>'
      + 'سيمضي في سلسلة الاعتماد، لكن <b>الصرف سيتوقف</b> حتى يُفتح بند مناسب '
      + 'أو يُغيَّر إلى بند موجود. والمحاسب هو من يُسنده قبل إتمام الصرف.';
    return;
  }

  if(!itemId){ box.style.display='none'; return; }
  const bal = computeBudgetItemBalance(itemId);
  if(bal==null){ box.style.display='none'; return; }
  const color = bal>50 ? 'var(--green)' : bal>0 ? 'var(--amber)' : 'var(--red)';
  const bg = bal>50 ? 'rgba(34,197,94,.08)' : bal>0 ? 'rgba(245,158,11,.08)' : 'rgba(239,68,68,.08)';
  box.style.cssText = `display:block;margin-top:-2px;padding:6px 10px;border-radius:8px;font-size:var(--fs-hint);font-weight:600;background:${bg};color:${color};border:1px solid ${color};`;
  const f = computeBudgetItemFigures(itemId);
  const bits = [];
  if(f){
    if(f.spent>0)     bits.push(`مصروف فعلاً ${fmtKWD(f.spent,{noUnit:true})}`);
    if(f.committed>0) bits.push(`مرتبط ${fmtKWD(f.committed,{noUnit:true})}`);
    if(f.reservedCustody>0 || f.reservedExtra>0) bits.push(`محجوز في العهد المفتوحة ${fmtKWD(f.reservedCustody+f.reservedExtra,{noUnit:true})}`);
    if(f.pending>0)   bits.push(`قيد الطلب ${fmtKWD(f.pending,{noUnit:true})}`);
  }
  box.innerHTML = `الرصيد المتاح لطلب جديد: ${fmtKWD(bal)}`
    + (bits.length ? `<div style="font-size:var(--fs-xs);opacity:.85;margin-top:2px;font-weight:600;">من إيراد ${fmtKWD(f.revenue,{noUnit:true})} — ${bits.join(' · ')}</div>` : '');
}

// مستفيد مكرر في الطلب نفسه (بالاسم أو الآيبان): تنبيه وإطار برتقالي، دون منع — قد يتكرر ببيان مختلف
function nrDupMark(){
  const blocks = [...document.querySelectorAll('.beneficiary-block')];
  const norm = v => String(v||'').replace(/\s+/g,' ').trim().toLowerCase();
  const info = blocks.map(b=>({n:norm((b.querySelector('.b-name')||{}).value), i:norm((b.querySelector('.b-iban')||{}).value).replace(/ /g,'')}));
  let any = false;
  blocks.forEach((b,k)=>{
    const me = info[k];
    const others = info.map((x,j)=>j).filter(j=>j!==k && ((me.n && info[j].n===me.n) || (me.i && me.i.length>8 && info[j].i===me.i)));
    const inp = b.querySelector('.b-name'), h = b.querySelector('.nr-dup-h');
    const dup = others.length>0; if(dup) any = true;
    if(inp){ inp.classList.toggle('nr-dup', dup); }
    if(h){ h.style.display = dup ? '' : 'none';
      h.textContent = dup ? `⚠ هذا المستفيد مكرر في الطلب (المستفيد رقم ${others.map(j=>j+1).join(' و')}). تأكد أن البيان مختلف وأن التكرار مقصود.` : ''; }
  });
  return any;
}
document.addEventListener('input', ev=>{ const t = ev.target; if(t && t.matches && t.matches('.beneficiary-block .b-name, .beneficiary-block .b-iban')) nrDupMark(); });
function onBeneficiaryNameChange(index, value){
  syncDraftFromDOM();
  const item = state.draft.beneficiaries[index];
  if(!item) return;
  const known = state.beneficiaries.find(x=>x.name===value);
  if(known){
    item.nameEn = known.nameEn || item.nameEn;
    item.iban = known.iban || item.iban;
    item.civilId = known.civilId || item.civilId;
  }
  render();
  if(nrDupMark() && (value||'').trim()) showToast('تنبيه: هذا المستفيد مضاف أكثر من مرة في الطلب','warning');
}

function toggleAttachmentUpdate(index){
  state.draft.beneficiaries[index]._showUpload = true;
  render();
}

function handleAttachment(index, kind, input){
  const file = input.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = function(e){
    syncDraftFromDOM();
    const item = state.draft.beneficiaries[index];
    if(!item) return;
    if(kind==='id'){ item.idFileName = file.name; item.idFileData = e.target.result; }
    else { item.bankFileName = file.name; item.bankFileData = e.target.result; }
    render();
  };
  reader.readAsDataURL(file);
}

function updateTotalPreview(){
  let total = 0;
  let maxBeneAmount = 0;
  const me = state.users.find(u=>u.id===state.user.id);
  const center = me ? state.centers.find(c=>c.id===me.centerId) : null;

  document.querySelectorAll('.beneficiary-block').forEach(b=>{
    const amountEl = b.querySelector('.b-amount');
    const amount = parseFloat(amountEl.value) || 0;
    const dedEl = b.querySelector('.b-deduction');
    const deduction = dedEl ? (parseFloat(dedEl.value) || 0) : 0;
    const extraEl = b.querySelector('.b-extra');
    const extra = extraEl ? (parseFloat(extraEl.value) || 0) : 0;
    const net = Math.max(amount - deduction + extra, 0);
    const netEl = b.querySelector('.b-net');
    if(netEl) netEl.innerHTML = `الصافي: <b>${fmtKWDHtml(net)}</b> د.ك`;
    total += net;
    if(net > maxBeneAmount) maxBeneAmount = net;
    const overMax = center && center.maxBeneficiaryAmount!=null && net > center.maxBeneficiaryAmount;
    amountEl.style.borderColor = overMax ? 'var(--red)' : '';
    amountEl.style.borderWidth = overMax ? '2px' : '';
    amountEl.style.background = overMax ? 'var(--red-bg)' : '';
  });
  document.getElementById('totalPreview').innerHTML = fmtKWDHtml(total) + ' د.ك';
  const wordsEl = document.getElementById('totalPreviewWords');
  if(wordsEl) wordsEl.textContent = total>0 ? amountToArabicWords(total) : '';
  const stickyEl = document.getElementById('stickyTotalPreview');
  if(stickyEl) stickyEl.innerHTML = fmtKWDHtml(total) + ' د.ك';

  const isFastTrackEligible = center && center.minThreshold!=null && total>0 && total <= center.minThreshold;
  const totalPreviewEl = document.getElementById('totalPreview');
  if(totalPreviewEl){
    totalPreviewEl.style.color = isFastTrackEligible ? 'var(--green)' : '';
  }

  const warnEl = document.getElementById('amountLimitWarning');
  let hasWarning = false;
  if(warnEl){
    const warnings = [];
    if(center && center.maxRequestAmount!=null && total > center.maxRequestAmount){
      warnings.push(`إجمالي الطلب (${fmtKWD(total,{noUnit:true})} د.ك) يتجاوز الحد الأعلى المحدد لمركزك (${fmtKWD(center.maxRequestAmount,{noUnit:true})} د.ك)`);
    }
    if(center && center.maxBeneficiaryAmount!=null && maxBeneAmount > center.maxBeneficiaryAmount){
      warnings.push(`مبلغ أحد المستفيدين (${fmtKWD(maxBeneAmount,{noUnit:true})} د.ك) يتجاوز الحد الأعلى المسموح لكل مستفيد (${fmtKWD(center.maxBeneficiaryAmount,{noUnit:true})} د.ك)`);
    }
    hasWarning = warnings.length>0;
    warnEl.innerHTML = hasWarning ? `⚠️ ${warnings.join(' — ')}` : '';
    warnEl.style.display = hasWarning ? 'block' : 'none';
  }
  const badge = document.getElementById('amountLimitBadge');
  if(badge) badge.style.display = hasWarning ? 'inline-flex' : 'none';
}
function scrollToAmountWarning(){
  const el = document.getElementById('amountLimitWarning');
  if(el) el.scrollIntoView({behavior:'smooth', block:'center'});
}

function toggleCalcBox(i, type){
  const box = document.getElementById('calcBox-'+type+'-'+i);
  if(!box) return;
  document.querySelectorAll('.nr-calc-pop').forEach(x=>{ if(x!==box) x.style.display='none'; });
  box.style.display = box.style.display==='none' ? 'block' : 'none';
  if(box.style.display==='block'){
    const f = box.querySelector('input'); if(f) f.focus({preventScroll:true});
    qyAutoBox(box, box.previousElementSibling, ()=>{ box.style.display='none'; });
    // لا يختفي خلف الشريط السفلي
    requestAnimationFrame(()=>{ const r = box.getBoundingClientRect(), bar = document.querySelector('.sticky-submit-bar'); const lim = bar ? bar.getBoundingClientRect().top - 8 : innerHeight - 8; if(r.bottom > lim) window.scrollBy({top: r.bottom - lim, behavior:'smooth'}); });
  }
}

// ── أي صندوق يفتحه زر: يُغلق تلقائياً عند الضغط خارجه ما دام لم يُستخدم ──
// «لم يُستخدم» = حقوله كما كانت لحظة فتحه (من كتب ثم مسح ما كتب كأنه لم يستخدمه). من كتب فيه يبقى مفتوحاً.
const _qyBoxes = new Set();
function qySnap(b){ return [...b.querySelectorAll('input:not([type=hidden]),select,textarea')].map(x=>(x.type==='checkbox'||x.type==='radio') ? (x.checked?'1':'0') : String(x.value||'').trim()).join('\u0001'); }
function qyAutoBox(box, opener, close){ if(!box) return; box._qyInit = qySnap(box); box._qyOpener = opener || null; box._qyClose = close; _qyBoxes.add(box); }
document.addEventListener('pointerdown', ev=>{
  const t = ev.target;
  _qyBoxes.forEach(b=>{
    if(!b.isConnected || b.hidden || getComputedStyle(b).display==='none'){ _qyBoxes.delete(b); return; }
    if(b.contains(t) || (b._qyOpener && b._qyOpener.isConnected && b._qyOpener.contains(t))) return;
    if(qySnap(b)===b._qyInit){ _qyBoxes.delete(b); try{ b._qyClose(); }catch(e){} }
  });
}, true);
function applyDeductionCalc(i){
  const blocks = document.querySelectorAll('.beneficiary-block');
  const block = blocks[i];
  if(!block) return;
  const amount = parseFloat(block.querySelector('.b-amount').value) || 0;
  const days = parseFloat(document.getElementById('calcDeductionDays-'+i).value) || 0;
  const result = (amount / 26) * days;
  block.querySelector('.b-deduction').value = result.toFixed(3);
  toggleCalcBox(i, 'deduction');
  updateTotalPreview();
}

function applyExtraCalc(i){
  const blocks = document.querySelectorAll('.beneficiary-block');
  const block = blocks[i];
  if(!block) return;
  const amount = parseFloat(block.querySelector('.b-amount').value) || 0;
  const hours = parseFloat(document.getElementById('calcExtraHours-'+i).value) || 0;
  const multiplier = parseFloat(document.getElementById('calcExtraType-'+i).value) || 1.25;
  const result = (amount / 26 / 8) * hours * multiplier;
  block.querySelector('.b-extra').value = result.toFixed(3);
  toggleCalcBox(i, 'extra');
  updateTotalPreview();
}

