function nrAdjOpen(i, type){
  syncDraftFromDOM();
  const b = state.draft.beneficiaries[i]; if(!b) return;
  nrAdjClose();
  const isDed = type==='deduction';
  const val = isDed ? b.deduction : b.extra, note = isDed ? b.deductionNote : b.extraNote;
  const base = Number(b.amount)||0;
  const ov = document.createElement('div');
  ov.className = 'modal-overlay nr-adj-ov'; ov.id = 'nrAdjModal';
  ov.dataset.i = i; ov.dataset.t = type;
  ov.innerHTML = `
    <div class="modal-box nr-adj-box" role="dialog">
      <h2 style="margin:0 0 4px;">${isDed ? 'خصم' : 'إضافي'}${(b.name||'').trim() ? ' — '+escH(b.name.trim()) : ''}</h2>
      <p class="sub" style="margin:0 0 12px;">المبلغ الأساسي: <b>${fmtKWDHtml(base)}</b> د.ك</p>
      <label>${isDed ? 'مبلغ الخصم' : 'مبلغ الإضافي'} (د.ك)</label>
      <div class="field-with-calc"><input id="nrAdjAmt" class="nr-adj-${isDed ? 'ded' : 'ext'}" type="number" inputmode="decimal" value="${escH(String(val||''))}" placeholder="0.000"><button type="button" class="calc-in" data-on-click="nrAdjCalcToggle">احسب</button></div>
      <div id="nrAdjCalc" class="calc-box" style="display:none;">
        ${isDed ? `<label>عدد أيام الغياب</label><input id="nrAdjQty" type="number" inputmode="decimal" placeholder="مثال: 3">
          <p class="file-hint">الحساب: (المبلغ ÷ 26) × عدد الأيام</p>`
        : `<label>عدد ساعات الإضافي</label><input id="nrAdjQty" type="number" inputmode="decimal" placeholder="مثال: 5">
          <label>نوع اليوم</label><select id="nrAdjKind"><option value="1.25">يوم عمل (×1.25)</option><option value="1.5">يوم عطلة (×1.5)</option></select>
          <p class="file-hint">الحساب: (المبلغ ÷ 26 ÷ 8) × عدد الساعات × المعامل</p>`}
        <button type="button" class="btn btn-primary btn-sm" data-on-click="nrAdjCalcApply">تطبيق</button>
      </div>
      <label style="margin-top:10px;">${isDed ? 'سبب الخصم' : 'سبب الإضافي'}</label>
      <input id="nrAdjNote" type="text" value="${escH(note||'')}" placeholder="${isDed ? 'مثال: غياب يومين' : 'مثال: ساعات إضافية'}">
      <div class="nr-adj-acts">
        <button type="button" class="btn btn-primary btn-md" data-on-click="nrAdjSave">حفظ</button>
        <button type="button" class="btn btn-ghost btn-md" data-on-click="nrAdjClose">إلغاء</button>
        ${(Number(val)||0)>0 ? `<button type="button" class="btn btn-ghost btn-md nr-adj-del" data-on-click="nrAdjClear">حذف ${isDed ? 'الخصم' : 'الإضافي'}</button>` : ''}
      </div>
    </div>`;
  document.body.appendChild(ov);
  qyAutoBox(ov.querySelector('.nr-adj-box'), null, nrAdjClose);
  setTimeout(()=>{ const a = document.getElementById('nrAdjAmt'); if(a) a.focus({preventScroll:true}); }, 30);
}
function nrAdjClose(){ const m = document.getElementById('nrAdjModal'); if(m) m.remove(); }
function nrAdjCalcToggle(){ const c = document.getElementById('nrAdjCalc'); if(c) c.style.display = c.style.display==='none' ? 'block' : 'none'; }
function nrAdjCalcApply(){
  const m = document.getElementById('nrAdjModal'); if(!m) return;
  const b = state.draft.beneficiaries[+m.dataset.i]; if(!b) return;
  const base = Number(b.amount)||0, q = parseFloat((document.getElementById('nrAdjQty')||{}).value)||0;
  if(!base){ showToast('اكتب مبلغ المستفيد أولاً ليُحسب منه','error'); return; }
  const r = m.dataset.t==='deduction' ? (base/26)*q : (base/26/8)*q*(parseFloat((document.getElementById('nrAdjKind')||{}).value)||1.25);
  document.getElementById('nrAdjAmt').value = r.toFixed(3);
  nrAdjCalcToggle();
}
function nrAdjSave(clear){
  const m = document.getElementById('nrAdjModal'); if(!m) return;
  const b = state.draft.beneficiaries[+m.dataset.i]; if(!b){ nrAdjClose(); return; }
  const v = clear===true ? '' : String(document.getElementById('nrAdjAmt').value||'').trim();
  const n = clear===true ? '' : String(document.getElementById('nrAdjNote').value||'').trim();
  if(v && !(parseFloat(v)>=0)){ showToast('المبلغ غير صحيح','error'); return; }
  if(m.dataset.t==='deduction'){ b.deduction = v; b.deductionNote = n; } else { b.extra = v; b.extraNote = n; }
  nrAdjClose(); render(); saveDraftToStorage();
}
function nrAdjClear(){ nrAdjSave(true); }
function removeBeneficiaryRow(i){
  syncDraftFromDOM();
  state.draft.beneficiaries.splice(i,1);
  render();
}

async function submitDraft(){
  if(state.editingReqId){
    const er = state.requests.find(r=>r.id===state.editingReqId);
    if(!canEditMyRequests(er && er.companyId)){ editReqBlocked(er); return; }
  } else if(!pageAtLeast('newreq','edit')){ showToast('ليست لديك صلاحية إرسال طلب صرف (قراءة فقط)','error'); return; }
  if(state.submittingDraft) return;
  state.submittingDraft = true;
  const btns = Array.from(document.querySelectorAll('.submit-draft-trigger'));
  const originalLabel = btns.length ? btns[0].textContent : '';
  btns.forEach(b=>{ b.disabled = true; b.textContent = 'جارٍ الإرسال...'; });
  try{
    await submitDraftInner();
  } finally {
    state.submittingDraft = false;
    const btns2 = Array.from(document.querySelectorAll('.submit-draft-trigger'));
    btns2.forEach(b=>{ b.disabled = false; b.textContent = originalLabel || 'إرسال للاعتماد'; });
  }
}

function checkLimitExceeded(centerId, total, beneficiaries){
  const center = state.centers.find(c=>c.id===centerId);
  if(!center) return false;
  if(center.maxRequestAmount!=null && total > center.maxRequestAmount) return true;
  if(center.maxBeneficiaryAmount!=null){
    const anyBeneOver = (beneficiaries||[]).some(b=>{
      const net = Math.max((Number(b.amount)||0) - (Number(b.deduction)||0) + (Number(b.extra)||0), 0);
      return net > center.maxBeneficiaryAmount;
    });
    if(anyBeneOver) return true;
  }
  return false;
}
function buildApprovalChain(creatorUser){
  const roleToLabel = {dept_manager:'pending_manager', senior_manager:'pending_senior', executive_manager:'pending_executive'};
  const order = ['pending_manager','pending_senior','pending_executive'];
  const chain = [];
  const usedLabels = new Set();
  const visited = new Set();
  let current = creatorUser;
  let hops = 0;
  while(current && current.managerId && hops < 10){
    if(visited.has(current.managerId)) break; // حماية من حلقات دائرية بالخطأ
    visited.add(current.managerId);
    hops++;
    const mgr = state.users.find(u=>u.id===current.managerId);
    if(!mgr) break;
    const label = roleToLabel[mgr.role];
    if(label && !usedLabels.has(label)){
      chain.push({roleLabel: label, approverId: mgr.id});
      usedLabels.add(label);
    }
    if(mgr.role==='executive_manager') break; // أعلى مستوى بالمسار الديناميكي، نتوقف هنا (المحاسب والمدير المالي أدوار ثابتة منفصلة)
    current = mgr;
  }
  chain.sort((a,b)=>order.indexOf(a.roleLabel)-order.indexOf(b.roleLabel));
  return chain;
}
async function submitDraftInner(){
  syncDraftFromDOM();
  const d = state.draft;
  const reasonInput = d.reason.trim();
  const detailedReasonInput = (d.detailedReason||'').trim();
  if(!reasonInput){ fieldErr('#reasonInput', 'الرجاء إدخال عنوان الطلب'); return; }
  // «بند غير محدد» يُخزَّن NULL ويمرّ — الصرف هو ما يتوقف لاحقاً لا الإرسال
  const staffReq = isCenterStaff();
  if(staffReq && !state.editingReqId && !cxReqUnits().some(x=>x.u.id===d.centerUnitId)){ showToast('لا يمكن إنشاء طلب الآن: مركزك أو بندك غير مفتوح للطلبات','error'); return; }
  const rawBudget = staffReq ? UNSPECIFIED_BUDGET : (d.budgetItemId || '');
  if(!rawBudget){ fieldErr('#budgetItemSelect', 'الرجاء اختيار بند الميزانية، أو «بند غير محدد» إن لم يناسبك أيٌّ منها'); return; }
  const budgetItemId = (rawBudget === UNSPECIFIED_BUDGET) ? null : rawBudget;
  const beneficiaries = [];
  let hasInvalidAmount = false;
  let missingStatement = false;
  let badDeduction = false;
  // أول مستفيد فيه الخطأ، ليذهب المؤشر إلى حقله
  const benBlock = i => document.querySelectorAll('#beneficiaryList .beneficiary-block')[i] || document;
  let badAmtAt = -1, badDedAt = -1, badDedCls = '.b-deduction', noStmtAt = -1;
  d.beneficiaries.forEach((b, bi)=>{
    const name = (b.name||'').trim();
    if(!name) return;
    // الدينار بثلاث خانات (فلس): يُقرَّب كل مبلغ حتى لا تتراكم كسور الحساب العشري في المجاميع
    const r3 = v => Math.round(v*1000)/1000;
    const amount = r3(parseFloat(b.amount));
    const deduction = r3(parseFloat(b.deduction) || 0);
    const extra = r3(parseFloat(b.extra) || 0);
    if(isNaN(amount) || amount<=0){ hasInvalidAmount = true; if(badAmtAt<0) badAmtAt = bi; }
    if(deduction < 0 || deduction > amount || extra < 0){ badDeduction = true; if(badDedAt<0){ badDedAt = bi; badDedCls = (extra < 0 && !(deduction < 0 || deduction > amount)) ? '.b-extra' : '.b-deduction'; } }
    if(!(b.statement||'').trim()){ missingStatement = true; if(noStmtAt<0) noStmtAt = bi; }
    beneficiaries.push({
      name, nameEn:(b.nameEn||'').trim(), iban:(b.iban||'').trim(), civilId:(b.civilId||'').trim(),
      statement:(b.statement||'').trim(), notes:(b.notes||'').trim(),
      amount: isNaN(amount)?0:amount,
      deduction: deduction, deductionNote: (b.deductionNote||'').trim(),
      extra: extra, extraNote: (b.extraNote||'').trim(),
      _idFileName: b.idFileName||'', _idFileData: b.idFileData||'',
      _bankFileName: b.bankFileName||'', _bankFileData: b.bankFileData||''
    });
  });
  if(beneficiaries.length===0){ fieldErr(document.querySelector('#beneficiaryList .b-name'), 'الرجاء إدخال بيانات مستفيد واحد على الأقل'); return; }
  if(hasInvalidAmount){ fieldErr(benBlock(badAmtAt).querySelector('.b-amount'), 'الرجاء إدخال مبلغ صحيح لكل مستفيد (المستفيد رقم '+(badAmtAt+1)+')'); return; }
  if(badDeduction){ fieldErr(benBlock(badDedAt).querySelector(badDedCls), 'قيمة الخصم أو الإضافي غير صحيحة (لا سالب، والخصم لا يتجاوز المبلغ) — المستفيد رقم '+(badDedAt+1)); return; }
  if(missingStatement){ fieldErr(benBlock(noStmtAt).querySelector('.b-statement'), 'حقل البيان إلزامي لكل مستفيد (المستفيد رقم '+(noStmtAt+1)+')'); return; }

  // المستفيد المسجّل: غير المالية لا يغيّر آيبانه أو رقمه المدني؛ المختلف يُحفظ لهذا الطلب فقط مع ملحوظة وتنبيه للمالية
  const normIban = v => String(v||'').replace(/\s+/g,'').toUpperCase();
  const tail4 = v => { const t = normIban(v); return t ? t.slice(-4) : '—'; };
  const finUser = isFinanceUser();
  const identityDiffs = [];
  beneficiaries.forEach(b=>{
    const m = state.beneficiaries.find(x=>x.name===b.name && x.companyId===state.currentCompanyId);
    if(!m || !m.id || finUser) return;
    const ibanDiff = !!(b.iban && m.iban && normIban(b.iban)!==normIban(m.iban));
    const civDiff = !!(b.civilId && m.civilId && b.civilId.trim()!==String(m.civilId).trim());
    if(ibanDiff || civDiff) identityDiffs.push({name:b.name, ibanDiff, civDiff, reg:tail4(m.iban), used:tail4(b.iban)});
  });
  const autoLines = identityDiffs.map(x=>'• المستفيد «'+x.name+'»: '
    + [x.ibanDiff ? 'آيبان يختلف عن المسجّل (المسجّل ينتهي بـ '+x.reg+'، والمستخدم هنا ينتهي بـ '+x.used+')' : '', x.civDiff ? 'رقم مدني يختلف عن المسجّل' : ''].filter(Boolean).join(' و')
    + ' — محفوظ لهذا الطلب فقط');
  let requestNotes = (d.requestNotes||'').trim();
  autoLines.forEach(l=>{ if(!requestNotes.includes(l)) requestNotes = (requestNotes ? requestNotes+'\n' : '') + l; });
  if(!reviewSkipped()){
    const tPrev = Math.round(beneficiaries.reduce((s,b)=>s + Math.max(b.amount - b.deduction + (b.extra||0), 0), 0)*1000)/1000;
    const biObj = budgetItemId ? (state.budgetItems||[]).find(x=>x.id===budgetItemId) : null;
    const ans = await reviewBeforeSend({total:tPrev, count:beneficiaries.length, item: biObj ? biObj.name : 'غير محدد', notes:requestNotes, diffs:identityDiffs.length});
    if(!ans) return;
    requestNotes = ans.notes;
  }
  d.requestNotes = requestNotes;

  for(const b of beneficiaries){
    let master = state.beneficiaries.find(x=>x.name===b.name && x.companyId===state.currentCompanyId);
    if(master && master.id && !finUser){
      // مسجّل من قبل: يُكمَّل الناقص فقط (لا يُستبدل آيبان أو رقم مدني موجود)
      const upd = {};
      if(b.nameEn && !master.nameEn){ upd.name_en = b.nameEn; master.nameEn = b.nameEn; }
      if(b.iban && !master.iban){ upd.iban = b.iban; master.iban = b.iban; }
      if(b.civilId && !master.civilId){ upd.national_id = b.civilId; master.civilId = b.civilId; }
      if(b._idFileData){ upd.id_file_data = b._idFileData; master.idFileName = b._idFileName; master.idFileData = b._idFileData; }
      if(b._bankFileData){ upd.bank_file_data = b._bankFileData; master.bankFileName = b._bankFileName; master.bankFileData = b._bankFileData; }
      delete b._idFileName; delete b._idFileData; delete b._bankFileName; delete b._bankFileData;
      if(Object.keys(upd).length) await dbCheck(await db.from('beneficiaries_master').update(upd).eq('id', master.id), 'حفظ بيانات المستفيد');
      const draftB0 = (d.beneficiaries||[]).find(x=>(x.name||'').trim()===b.name);
      if(draftB0 && (draftB0._pend||[]).length) await attFlushPending(draftB0, master);
      continue;
    }
    if(!master){
      master = {name:b.name, nameEn:b.nameEn, iban:b.iban, civilId:b.civilId, idFileName:'', idFileData:'', bankFileName:'', bankFileData:'', companyId: state.currentCompanyId};
      state.beneficiaries.push(master);
    }
    const payload = {name:b.name, name_en:b.nameEn, iban:b.iban, national_id:b.civilId, company_id: state.currentCompanyId};
    if(b._idFileData){ master.idFileName = b._idFileName; master.idFileData = b._idFileData; payload.id_file_data = b._idFileData; }
    if(b._bankFileData){ master.bankFileName = b._bankFileName; master.bankFileData = b._bankFileData; payload.bank_file_data = b._bankFileData; }
    if(b.nameEn) master.nameEn = b.nameEn;
    if(b.iban) master.iban = b.iban;
    if(b.civilId) master.civilId = b.civilId;
    delete b._idFileName; delete b._idFileData; delete b._bankFileName; delete b._bankFileData;
    const upRes = await db.from('beneficiaries_master').upsert(payload, {onConflict:'company_id,name'}).select('id').maybeSingle();
    await dbCheck(upRes, 'حفظ بيانات المستفيد');
    if(upRes && upRes.data && upRes.data.id) master.id = upRes.data.id;
    const draftB = (d.beneficiaries||[]).find(x=>(x.name||'').trim()===b.name);
    if(draftB && (draftB._pend||[]).length) await attFlushPending(draftB, master);
  }
  if(state.editingReqId && ATT_REQ_QUEUE.length) await attFlushReqQueue(state.editingReqId);

  const total = Math.round(beneficiaries.reduce((s,b)=>s + Math.max(b.amount - b.deduction + (b.extra||0), 0), 0)*1000)/1000;
  const beneRows = beneficiaries.map(b=>({name:b.name, name_en:b.nameEn, iban:b.iban, national_id:b.civilId, statement:b.statement, notes:b.notes, amount:b.amount, deduction:b.deduction, deduction_note:b.deductionNote, extra:b.extra||0, extra_note:b.extraNote}));

  if(state.editingReqId){
    await applyRequestEdit({reqId: state.editingReqId, reasonInput, detailedReasonInput, budgetItemId, beneficiaries, beneRows, total, requestNotes, identityDiffs, isRecurring: !!d.isRecurring, salutationText: d.salutationText||'', referenceText: d.referenceText||''});
    return;
  }

  await createNewRequest({reasonInput, detailedReasonInput, budgetItemId, beneficiaries, beneRows, total, requestNotes, identityDiffs, isRecurring: !!d.isRecurring, salutationText: d.salutationText||'', referenceText: d.referenceText||''});
}

// إنشاء الطلب في القاعدة (مسار الاعتماد والمستفيدون والسجل ونافذة المراجعة) — مشترك بين طلب الصرف وطلب العهدة
async function createNewRequest(o){
  const {reasonInput, detailedReasonInput, budgetItemId, beneficiaries, beneRows, total, requestNotes, identityDiffs} = o;
  const isCustody = o.requestType==='custody';
  const creatorUser = state.users.find(u=>u.id===state.user.id);
  const {steps: rawChain, error: chainError} = buildDecisionChain(creatorUser, state.currentCompanyId);
  // العهدة: مسارها يبنيه الخادم من صاحب العهدة وإعداد الشركة (لا من منشئها)، فلا يُحكم عليه هنا
  if(chainError && !isCustody){
    showToast('تعذّر بناء مسار اعتماد الطلب: '+chainError+'. راجع مدير النظام لتصحيح الهيكل التنظيمي.', 'error');
    return false;
  }
  let chain = rawChain;
  let isFastTracked = false;
  const creatorCenter = creatorUser ? state.centers.find(c=>c.id===creatorUser.centerId) : null;
  if(creatorCenter && creatorCenter.minThreshold!=null && total <= creatorCenter.minThreshold && chain.length>0){
    // تخطٍّ للمبالغ الصغيرة: نحذف من مسار القرار أي معتمِد دوره الوظيفي من الأدوار المسموح تخطّيها لهذا المركز
    const skipRoles = new Set();
    if(creatorCenter.skipDeptManager) skipRoles.add('dept_manager');
    if(creatorCenter.skipSeniorManager) skipRoles.add('senior_manager');
    if(creatorCenter.skipExecutiveManager) skipRoles.add('executive_manager');
    if(skipRoles.size){
      let filtered = chain.filter(s=>{ const u=state.users.find(x=>x.id===s.approverId); return !u || !skipRoles.has(u.role); });
      if(filtered.length !== chain.length){ isFastTracked = true; if(!filtered.length) filtered = [keepOneApprover(creatorCenter, chain)]; chain = filtered; }
    }
  }
  const roleLabelFor = ()=>'pending_decision';
  chain = chain.map(s=>({roleLabel: roleLabelFor(), approverId: s.approverId}));
  if(isCustody){ isFastTracked = false; }
  // كل طلب يبدأ «قيد القرار»، والخادم يبني مساره: لمن في أعلى السلسلة يُسجَّل إنشاؤه اعتماداً له وينتقل الطلب للمالية
  const initialStatus = 'pending_decision';
  // طلب بلا معتمدين لا يُرسل إلا لمن فُعّل له الانتقال المباشر، أو إن كان التخطي بسبب حد المبلغ الصغير للمركز
  if(!isCustody && chain.length===0 && !isFastTracked && !(creatorUser && creatorUser.directToTransfer)){
    showToast('لا يوجد معتمِد لطلبك، فلا يمكن إرساله بلا اعتماد. حدّد مديراً في حسابك أو اطلب من مدير النظام تفعيل «الانتقال المباشر إلى التحويل».', 'error');
    return false;
  }
  // تحذير تجاوز الرصيد عند الإرسال
  if(budgetItemId){
    const submitBal = computeBudgetItemBalance(budgetItemId);
    if(submitBal != null && total > submitBal){
      const bi = (state.budgetItems||[]).find(b=>b.id===budgetItemId);
      const biName = bi ? bi.name : '';
      const f = computeBudgetItemFigures(budgetItemId) || {revenue:0,profit:0,spent:0,committed:0,pending:0};
      const line = (lbl,v)=> v>0 ? `\n  ${lbl}: ${v.toFixed(3)}` : '';
      const confirmed = confirm(
        `⚠️ تجاوز رصيد الميزانية\n\n`
      + `البند: ${biName}\n`
      + `المبلغ المطلوب: ${total.toFixed(3)} د.ك\n`
      + `المتاح: ${submitBal.toFixed(3)} د.ك\n\n`
      + `وأين ذهب الرصيد:`
      + line('الإيراد', f.revenue)
      + line('− ربح الشركة', f.profit)
      + line('− مصروف فعلاً', f.spent)
      + line('− مرتبط (اعتُمد ولم يُدفع)', f.committed)
      + line('− قيد الطلب (قد يُرفض فيعود)', f.pending)
      + `\n\nالطلب سيُرسل ويُسجَّل التجاوز. هل تريد الاستمرار؟`);
      if(!confirmed) return false;
      // سيُسجَّل التجاوز بعد حفظ الطلب (بعد معرفة الـ id)
      state._pendingOverrunLog = { budgetItemId, stage:'submit', requestedAmount: total, availableBalance: submitBal };
    }
  }

  const dates = getDocDates();
  const numTpl = reqNumberTemplate();
  const winMin = reviewWindowMinutes();
  const req = {
    id: 'r'+Date.now(),
    number: null,                       // يُمنح عند انتهاء نافذة المراجعة
    numberPrefix: numTpl.prefix,
    numberSuffix: numTpl.suffix,
    reviewUntil: new Date(Date.now() + winMin*60000).toISOString(),
    reason: reasonInput,
    detailedReason: detailedReasonInput,
    salutationText: o.salutationText||'',
    referenceText: o.referenceText||'',
    totalAmount: total,
    beneficiaries,
    status: initialStatus,
    createdBy: state.user.name,
    createdById: state.user.id,
    origin: 'center',
    centerId: (isCenterStaff() && state.draft && state.draft.centerUnitId) ? state.draft.centerUnitId : (creatorUser ? creatorUser.centerId : null),
    dateGreg: dates.greg,
    dateHijri: dates.hijri,
    createdAtRaw: new Date().toISOString(),
    isRecurring: !!o.isRecurring,
    fastTracked: isFastTracked,
    limitExceeded: checkLimitExceeded(creatorUser ? creatorUser.centerId : null, total, beneficiaries),
    companyId: state.currentCompanyId,
    budgetItemId: budgetItemId,
    history: [{step:'created', actor: state.user.name, userId: state.user.id, action:'إنشاء الطلب', note:'', time: fmtDate()}],
    approvalSteps: []
  };
  const reqInsert = await db.from('requests').insert({
    id:req.id, number:req.number, reason:req.reason, detailed_reason:req.detailedReason||null, salutation_text:req.salutationText||null, reference_text:req.referenceText||null, total_amount:req.totalAmount, status:req.status,
    origin:req.origin, center_id:req.centerId, company_id:req.companyId, created_by:req.createdBy, created_by_id:req.createdById,
    date_greg:req.dateGreg, date_hijri:req.dateHijri, is_recurring:req.isRecurring, fast_tracked:req.fastTracked, limit_exceeded:req.limitExceeded,
    budget_item_id: budgetItemId,
    number_prefix: req.numberPrefix, number_suffix: req.numberSuffix, review_until: req.reviewUntil,
    request_notes: requestNotes || null,
    ...(cxRouteInsert()),
    ...(isCustody ? {request_type:'custody'} : {})
  });
  if(!(await dbCheck(reqInsert, 'إنشاء الطلب'))) return false;
  if(isCustody) req.requestType = 'custody';
  // سجل الإنشاء أولاً، فيأتي قبل «اعتمد بإنشائه الطلب» إن سجّله الخادم
  const h0 = req.history[0];
  await dbCheck(await db.from('request_history').insert({request_id:req.id, step:h0.step, actor:h0.actor, user_id:h0.userId, action:h0.action, note:h0.note, time:h0.time}), 'حفظ سجل الإنشاء');
  // العهدة: صفّها يُكتب فور الطلب، فيرفض الخادم مبكراً من بلغ الحد الأقصى، ويُحذف الطلب معه
  if(o.afterInsert && !(await o.afterInsert(req))){ await db.from('requests').delete().eq('id', req.id); return false; }
  // مسار الاعتماد يبنيه الخادم من الهيكل التنظيمي (qy_set_chain)؛ المتصفح لا يضيف خطوات المسار
  if(initialStatus==='pending_decision'){
    const chainRes = await db.rpc('qy_set_chain', {p_req: req.id, p_reset: false});
    if(!(await dbCheck(chainRes, 'بناء مسار الاعتماد'))){ await db.from('requests').delete().eq('id', req.id); return false; }
    req.approvalSteps = (chainRes.data||[]).map(mapStepRow);
    // المنشئ في أعلى السلسلة: سجّل الخادم إنشاءه اعتماداً له ونقل الطلب إلى المحاسب
    if(isSelfApproved(req)){ req.status = 'pending_transfer_request'; noteSelfApproval(req); }
    else if(!req.approvalSteps.length){
      await db.from('requests').delete().eq('id', req.id);
      showToast('تعذّر بناء مسار الاعتماد في الخادم — حدّث الصفحة وحاول مرة أخرى، أو راجع مدير النظام', 'error');
      return false;
    }
  }
  const beneInsert = await db.from('request_beneficiaries').insert(beneRows.map(r=>({...r, request_id:req.id})));
  if(beneInsert.error){
    console.error('إضافة المستفيدين', beneInsert.error);
    const e = beneInsert.error;
    let msg = 'فشل حفظ بيانات المستفيدين: ' + e.message;
    if(e.details) msg += ' | ' + e.details;
    if(e.hint) msg += ' | ' + e.hint;
    showToast(msg, 'error');
    await db.from('requests').delete().eq('id', req.id);
    return false;
  }
  req.requestNotes = requestNotes;
  if(identityDiffs.length) await pushHistory(req, {step:req.status, actor:state.user.name, userId:state.user.id, action:'تنبيه آيبان', note:identityDiffs.map(x=>x.name).join('، ')+' — يختلف عن المسجّل، محفوظ لهذا الطلب فقط', time:fmtDate()});
  loadBudgetSums();
  // رقم التحقق يولّده الخادم عند الإنشاء؛ نقرؤه الآن حتى يظهر على السند دون الحاجة لتحديث الصفحة
  try{ const vc = await db.from('requests').select('verify_code').eq('id', req.id).maybeSingle(); req.verifyCode = (vc && vc.data && vc.data.verify_code) || ''; }catch(e){ req.verifyCode = ''; }
  state.requests.push(req);
  if(ATT_REQ_QUEUE.length) await attFlushReqQueue(req.id);
  if(!isCustody) clearDraftStorage();
  // تسجيل تجاوز الرصيد إن وُجد
  if(state._pendingOverrunLog){
    const ol = state._pendingOverrunLog;
    logBudgetOverrun(req.id, ol.budgetItemId, ol.stage, ol.requestedAmount, ol.availableBalance);
    state._pendingOverrunLog = null;
  }
  if(winMin <= 0){
    await finalizeRequestNow(req, {silent:true});
    showToast((isCustody ? 'تم إرسال طلب العهدة — رقمه ' : 'تم إرسال الطلب بنجاح — رقمه ') + (req.number||''), 'success');
  }else{
    showToast(`${isCustody ? 'تم حفظ طلب العهدة' : 'تم حفظ الطلب'} — أمامك ${winMin} ${winMin===1?'دقيقة':'دقائق'} لمراجعته قبل الإرسال النهائي. `
            + 'لم يأخذ رقماً بعد ولم يصل المعتمدين، ويمكنك تعديله أو حذفه.', 'success');
    startReviewTicker();
  }
  state.view = o.afterView || 'dashboard';
  state.activeReqId = req.id;
  render();
  return true;
}

// حفظ تعديل طلب قائم (مستفيدون جدد ثم بيانات الطلب ثم حذف القدامى) — مشترك بين طلب الصرف وطلب العهدة
async function applyRequestEdit(o){
  const {reasonInput, detailedReasonInput, budgetItemId, beneficiaries, beneRows, total, requestNotes, identityDiffs} = o;
  const req = state.requests.find(r=>r.id===o.reqId);
  if(!req) return false;
  const newStatus = statusForSteps(req.approvalSteps);
  const newLimitExceeded = checkLimitExceeded(req.centerId, total, beneficiaries);
  // ما الذي تغيّر فعلاً؟ يُحسب قبل تعديل الطلب، ليُكتب في السجلّ بدل «تعديل الطلب» المجرّدة
  const wasRecurring = !!req.isRecurring, nowRecurring = !!o.isRecurring;
  const chg = [];
  if((req.budgetItemId||null) !== budgetItemId){
    const bn = budgetItemId ? ((state.budgetItems||[]).find(b=>b.id===budgetItemId)||{}).name : null;
    chg.push('البند: ' + (bn ? bn : 'غير محدد'));
  }
  if(req.reason !== reasonInput) chg.push('العنوان');
  if(Math.abs((Number(req.totalAmount)||0) - total) > 0.0005) chg.push('المبلغ: من ' + fmtKWDPlain(Number(req.totalAmount)||0) + ' إلى ' + fmtKWDPlain(total));
  if(wasRecurring !== nowRecurring) chg.push(nowRecurring ? 'صار متكرراً' : 'لم يعد متكرراً');
  const histEntry = {step: req.status, actor: state.user.name, userId: state.user.id, action:'تعديل الطلب', note: chg.join(' · '), time: fmtDate()};
  // الترتيب يحمي من نصف تعديل: المستفيدون الجدد أولاً، ثم بيانات الطلب، ثم حذف القدامى.
  // إن فشلت خطوة يُتراجع عمّا قبلها فيبقى الطلب كما كان تماماً.
  const {data: oldRows} = await db.from('request_beneficiaries').select('id').eq('request_id', req.id);
  const oldIds = (oldRows||[]).map(r=>r.id);
  const insertResult = await db.from('request_beneficiaries').insert(beneRows.map(r=>({...r, request_id:req.id}))).select('id');
  if(insertResult.error){
    console.error('إضافة المستفيدين الجدد', insertResult.error);
    showToast('فشل حفظ المستفيدين الجدد: ' + arDbMessage(insertResult.error) + ' — أُلغي التعديل، والطلب كما كان.', 'error');
    return false;
  }
  const newIds = (insertResult.data||[]).map(r=>r.id);
  // budget_item_id وis_recurring كانا ناقصَين من هذه الجملة، فكان الاختيار يضيع بلا أثر
  const upd = await db.from('requests').update({reason:reasonInput, detailed_reason:detailedReasonInput||null, salutation_text:o.salutationText||null, reference_text:o.referenceText||null, total_amount:total, status:newStatus, limit_exceeded:newLimitExceeded, budget_item_id:budgetItemId, is_recurring:nowRecurring, request_notes:requestNotes||null}).eq('id', req.id).select('id');
  if(!(await dbCheck(upd, 'تحديث بيانات الطلب')) || !upd.data || !upd.data.length){
    if(newIds.length) await db.from('request_beneficiaries').delete().in('id', newIds);
    if(!upd.error) showToast('تعذّر حفظ التعديل: الطلب لم يعد قابلاً للتعديل. حدّث الصفحة.','error');
    return false;
  }
  req.limitExceeded = newLimitExceeded;
  req.budgetItemId = budgetItemId;
  req.isRecurring = nowRecurring;
  if((req.approvalSteps||[]).length){
    await dbCheck(await db.from('request_approval_steps').update({status:'pending', acted_at:null}).eq('request_id', req.id), 'إعادة ضبط مسار الاعتماد');
    req.approvalSteps.forEach(s=>{ s.status='pending'; s.actedAt=null; });
  }
  if(oldIds.length>0){
    await dbCheck(await db.from('request_beneficiaries').delete().in('id', oldIds), 'حذف المستفيدين القدامى بعد التحديث');
  }
  await dbCheck(await db.from('request_history').insert({request_id:req.id, step:histEntry.step, actor:histEntry.actor, user_id:histEntry.userId, action:histEntry.action, note:histEntry.note, time:histEntry.time}), 'حفظ سجل التعديل');
  req.reason = reasonInput;
  req.detailedReason = detailedReasonInput;
  req.salutationText = o.salutationText||'';
  req.referenceText = o.referenceText||'';
  req.requestNotes = requestNotes;
  if(identityDiffs.length) await pushHistory(req, {step:req.status, actor:state.user.name, userId:state.user.id, action:'تنبيه آيبان', note:identityDiffs.map(x=>x.name).join('، ')+' — يختلف عن المسجّل، محفوظ لهذا الطلب فقط', time:fmtDate()});
  req.beneficiaries = beneficiaries;
  req.totalAmount = total;
  req.status = newStatus;
  req.history.push(histEntry);
  if(o.afterUpdate) await o.afterUpdate(req);
  state.editingReqId = null;
  state.view = o.afterView || 'dashboard';
  state.activeReqId = req.id;
  render();
  return true;
}

// ═══ أفعال نافذة المراجعة ═════════════════════════════════════════════
// منح الرقم: يستدعي دالة محمية في القاعدة تزيد العدّاد ذرّياً وتعيد الرقم.
// صاحب الطلب وحده يستطيع ذلك، والمهمة الدورية (كل دقيقة) هي شبكة الأمان
// لمن أغلق المتصفح قبل انتهاء المدة.
async function finalizeRequestNow(req, opts){
  opts = opts || {};
  if(!req || req.number) return true;
  const {data, error} = await db.rpc('finalize_request', {p_id: req.id});
  if(error){
    if(!opts.silent) showToast('تعذّر منح الرقم: ' + error.message, 'error');
    return false;
  }
  req.number = data;
  req.reviewUntil = new Date().toISOString();
  if(!opts.silent) showToast('تم إرسال الطلب نهائياً — رقمه ' + data, 'success');
  return true;
}

async function sendRequestFinal(id){
  const req = state.requests.find(r=>r.id===id);
  if(!req || req.number) return;
  if(!confirm('إرسال الطلب نهائياً الآن؟\n\nسيأخذ رقمه ويصل المعتمدين، ولن يمكنك حذفه بعدها.')) return;
  if(await finalizeRequestNow(req)) render();
}

async function deleteRequestInReview(id){
  const req = state.requests.find(r=>r.id===id);
  if(!req || req.number) return;
  if(!confirm('حذف الطلب؟\n\nلم يأخذ رقماً ولم يره أحد، فسيُحذف تماماً ولن يظهر في أرشيف الملغاة.')) return;
  const delResult = await db.from('requests').delete().eq('id', id);
  if(!(await dbCheck(delResult, 'حذف الطلب'))) return;
  state.requests = state.requests.filter(r=>r.id!==id);
  state.view = 'dashboard';
  state.activeReqId = null;
  showToast('تم حذف الطلب', 'success');
  render();
}

// عدّاد حيّ: يُحدّث الشاشة كل ثانية، ويمنح الرقم فور انتهاء المدة
let _reviewTicker = null;
function myRequestsUnderReview(){
  if(!state.user) return [];
  return state.requests.filter(r=>isUnderReview(r) && r.createdById===state.user.id && r.companyId===state.currentCompanyId);
}
// العدّاد يُحدّث نصّ الثواني وحده في مكانه، ولا يُعيد رسم الصفحة.
// وإعادة الرسم كل ثانية كانت تهدم أي قائمة منسدلة مفتوحة وأي حقل
// قيد الكتابة — فالرسم الكامل لا يقع إلا حين يتغيّر شيء فعلاً:
// عند انتهاء مدة طلب ومنحه رقمه.
function startReviewTicker(){
  if(_reviewTicker || !myRequestsUnderReview().length) return;
  _reviewTicker = setInterval(async ()=>{
    const mine = myRequestsUnderReview();
    if(!mine.length){ clearInterval(_reviewTicker); _reviewTicker = null; return; }

    const due = mine.filter(r=>reviewSecondsLeft(r)<=0);
    if(due.length){
      for(const r of due){ await finalizeRequestNow(r, {silent:true}); }
      render();                       // تغيّرت الحالة فعلاً: الطلب أخذ رقمه
      return;
    }
    // لا شيء انتهى: تحديث جرّاحي للنص وحده
    document.querySelectorAll('[data-countdown]').forEach(el=>{
      const r = mine.find(x=>x.id === el.getAttribute('data-countdown'));
      if(r) el.textContent = fmtCountdown(reviewSecondsLeft(r));
    });
  }, 1000);
}

async function rebuildChainIfUntouched(req){
  if(!req || req.isCancelled) return false;
  if(req.requestType==='custody') return false;   // مسار العهدة يبنيه الخادم من صاحب العهدة وإعداد الشركة، لا يحسبه المتصفح
  // يُعاد البناء من متصفح صاحب الطلب أو مدير النظام فقط: غيرهما قد لا يرى كل المستخدمين فيحسب مساراً ناقصاً،
  // والخادم يمنعه من الكتابة أصلاً فيبقى الطلب بلا خطوات
  if(!state.user || !(state.user.role==='admin' || state.user.id===req.createdById)) return false;
  const isNewEngine = req.status==='pending_decision';
  const isOldEngine = OLD_DECISION_STATUSES.includes(req.status);
  if(!isNewEngine && !isOldEngine) return false;
  const noApprovalsYet = (req.approvalSteps||[]).every(s=>s.status==='pending');
  if(!noApprovalsYet) return false;
  const creator = state.users.find(u=>u.id===req.createdById);
  if(!creator) return false;
  let freshChain, freshStatus;
  if(isNewEngine){
    const {steps, error} = buildDecisionChain(creator, req.companyId);
    if(error) return false; // حلقة دائرية بالهيكل — لا نلمس الطلب، يبقى كما هو حتى يُصلَح الهيكل
    // حماية: مسار جديد فارغ لطلب له خطوات اعتماد = اختلال مؤقت (مدير أُزيل أثناء تعديل مستخدم مثلاً)، لا إلغاء لمعتمديه وقفز إلى المحاسب
    if(steps.length===0 && (req.approvalSteps||[]).length>0) return false;
    freshChain = applyFastTrack(creator, req.totalAmount, steps).chain.map(s=>({roleLabel:'pending_decision', approverId:s.approverId}));
    freshStatus = freshChain.length ? 'pending_decision' : 'pending_transfer_request';
  } else {
    freshChain = buildApprovalChain(creator);
    freshStatus = freshChain.length ? freshChain[0].roleLabel : null;
  }
  // البصمة تعتمد على ترتيب المعتمدين فقط (لا اسم الخطوة، لأن خطوات القرار الجديدة تتشارك نفس الاسم)
  const currentChainSig = (req.approvalSteps||[]).map(s=>s.approverId).join(',');
  const freshChainSig = freshChain.map(s=>s.approverId).join(',');
  if((isOldEngine && freshChain.length===0) || currentChainSig===freshChainSig) return false;
  if(!isNewEngine) return false;   // طلبات المحرك القديم تحتفظ بخطواتها؛ لا إعادة بناء تلقائية لها
  const rr = await db.rpc('qy_set_chain', {p_req: req.id, p_reset: false});
  if(rr.error) return false;
  req.approvalSteps = (rr.data||[]).map(mapStepRow); noteSelfApproval(req);
  const newStatus = statusForSteps(req.approvalSteps);
  const nmOf = id => (state.users.find(u=>u.id===id)||{}).name || id;
  const prevSig = currentChainSig ? currentChainSig.split(',').map(nmOf).join(' ← ') : 'لا أحد';
  const nextSig = req.approvalSteps.length ? req.approvalSteps.map(x=>nmOf(x.approverId)).join(' ← ') : 'لا أحد';
  if(newStatus && newStatus !== req.status){
    const stR = await db.from('requests').update({status:newStatus}).eq('id', req.id).select('id');
    if(!stR.error && stR.data && stR.data.length) req.status = newStatus;
  }
  // سجل واضح بكل تغيير تلقائي: من أي مسار إلى أي مسار ولماذا (بعد تعديل الهيكل قبل أي اعتماد)
  try{ await pushHistory(req, {step:req.status, actor:'النظام', userId:(state.user||{}).id||null, action:'تحديث تلقائي لمسار الاعتماد',
    note:'تغيّر الهيكل التنظيمي قبل أي اعتماد. السابق: '+prevSig+' — الجديد: '+nextSig, time: fmtDate()}); }catch(e){}
  return true;
}
async function syncAllUntouchedRequestPaths(){
  const candidates = state.requests.filter(r=>!r.isCancelled && (r.status==='pending_decision' || OLD_DECISION_STATUSES.includes(r.status)));
  for(const req of candidates){
    await rebuildChainIfUntouched(req);
  }
}
async function openRequest(id){
  const req = state.requests.find(r=>r.id===id);
  if(req && req.companyId===state.currentCompanyId){ await rebuildChainIfUntouched(req); }   // طلب شركة سابقة لا يُعاد بناء مساره من هنا
  state.activeReqId = id;
  state.view='detail';
  render();
}

function canActOn(req){
  if(isUnderReview(req)) return false;   // لم يأخذ رقماً بعد: خارج سلسلة الاعتماد مؤقتاً
  if(req.status==='completed' || req.status==='rejected') return false;
  if(req.status==='pending_decision'){
    return !!myDecisionStep(req, state.user.id);
  }
  if(req.status==='pending_transfer_approval'){
    const target = cfoApprovalTarget(req);
    if(target.mode==='normal' || target.mode==='delegate_user'){
      const full = state.users.find(u=>u.id===state.user.id);
      const asCfo = state.user.role==='cfo' && (!full || userHasCompany(full, req.companyId));
      return asCfo || (target.mode==='delegate_user' && !!target.userId && target.userId===state.user.id);   // المالي يبقى قادراً أثناء التفويض
    }
    return !!target.userId && target.userId===state.user.id;
  }
  if(TAIL_FLOW.includes(req.status)){
    const full = state.users.find(u=>u.id===state.user.id);
    if(full && !userHasCompany(full, req.companyId)) return false;   // محاسب شركة لا ينفّذ طلبات شركة أخرى
    return state.user.role===STATUS_ROLE_MAP[req.status];
  }
  // ===== توافق مع طلبات تجريبية متبقية من النظام القديم (قبل تفعيل محرك المسار الجديد) =====
  const requiredRole = STATUS_ROLE_MAP[req.status];
  if(!requiredRole) return false;
  if(requiredRole==='accountant' || requiredRole==='cfo'){
    return state.user.role===requiredRole;
  }
  // dept_manager / senior_manager / executive_manager: مطلوب شخص محدد حسب سلسلة manager_id
  const step = (req.approvalSteps||[]).find(s=>s.roleLabel===req.status);
  return !!step && step.approverId===state.user.id;
}

async function approve(req){
  // تحذير تجاوز رصيد الميزانية عند الاعتماد
  if(req.budgetItemId && req.status==='pending_decision'){
    // المتاح بعد استبعاد هذا الطلب نفسه، وإلا خُصم مرتين وجاء التحذير كاذباً
    const approveBal = computeBudgetItemBalanceExcluding(req.budgetItemId, req.id);
    if(approveBal != null && (Number(req.totalAmount)||0) > approveBal){
      const bi = (state.budgetItems||[]).find(b=>b.id===req.budgetItemId);
      const biName = bi ? bi.name : '';
      const f = computeBudgetItemFigures(req.budgetItemId) || {spent:0,committed:0,pending:0};
      const other = Math.max(0, f.pending - (Number(req.totalAmount)||0));
      const confirmed = confirm(
        `⚠️ تنبيه: رصيد البند غير كافٍ\n\n`
      + `البند: ${biName}\n`
      + `مبلغ الطلب: ${(Number(req.totalAmount)||0).toFixed(3)} د.ك\n`
      + `المتاح قبل هذا الطلب: ${approveBal.toFixed(3)} د.ك\n\n`
      + `وما استهلك الرصيد:\n`
      + `  مصروف فعلاً: ${f.spent.toFixed(3)}\n`
      + `  مرتبط: ${f.committed.toFixed(3)}\n`
      + `  طلبات أخرى قيد القرار: ${other.toFixed(3)}\n\n`
      + `الاعتماد لن يُمنع، وسيُسجَّل التجاوز باسمك. هل تريد الاستمرار؟`);
      if(!confirmed) return;
      logBudgetOverrun(req.id, req.budgetItemId, 'approve', Number(req.totalAmount)||0, approveBal);
    }
  }

  const me = state.users.find(u=>u.id===state.user.id);
  const needsSignature = ['dept_manager','senior_manager','executive_manager','cfo'].includes(state.user.role);
  const canManualSign = ['dept_manager','senior_manager','executive_manager','cfo','accountant'].includes(state.user.role);
  if(needsSignature && me && (!me.signatureData || !me.stampData)){
    state.returnTo = req.id;
    state.view = 'account';
    render();
    return;
  }
  if(req.status==='pending_transfer_request' && isUnspecifiedBudget(req.budgetItemId) && !isCenterReq(req)){
    fieldErr(document.getElementById('assignBudgetSel'), 'حدّد بند الميزانية أولاً من بطاقة «بند غير محدد» أعلى الطلب، ثم سجّل التحويل');
    return false;
  }
  if(state.user.role==='accountant' && req.status==='pending_transfer_request'){
    const center = req.centerId ? state.centers.find(c=>c.id===req.centerId) : null;
    const requireTransferRef = !center || center.requireBankTransferRef!==false;
    if(requireTransferRef){
      state.transferFormReqId = req.id;
      render();
      return;
    }
  }
  if(canManualSign && me && me.signatureMode==='manual'){
    state.manualSignReqId = req.id;
    render();
    return;
  }
  await finalizeApprove(req, null);
}

async function finalizeApprove(req, signatureOverride){
  const label = 'اعتماد';
  let delegationNote = (req.status==='pending_transfer_approval' && state.user.role!=='cfo') ? 'بالتفويض عن المدير المالي' : '';
  if(req.status==='pending_decision'){ const _st = myDecisionStep(req, state.user.id); if(_st && _st.approverId!==state.user.id) delegationNote = 'بالإنابة عن '+hoUserName(_st.approverId); }
  const histEntry = {step:req.status, actor: state.user.name, userId: state.user.id, action: label, note:delegationNote, time: fmtDate(), signatureOverride: signatureOverride||''};
  // في مرحلة القرار يُسجَّل الاعتماد بعد نجاح اعتماد الخطوة نفسها، لا قبله
  // خارج مرحلة القرار يُكتب السجل بعد نجاح تغيير الحالة، فلا يتكرر إن كانت الشاشة قديمة
  const postHist = [];
  if(req.status!=='pending_decision') postHist.push(histEntry);
  let newStatus;
  if(req.status==='pending_decision'){
    const group = currentDecisionGroup(req);
    const step = group.find(s=>s.approverId===state.user.id) || myDecisionStep(req, state.user.id);
    const nowIso = new Date().toISOString();
    if(!step){ showToast('لا توجد خطوة اعتماد بانتظارك في هذا الطلب. حدّث الصفحة.','error'); return; }
    if(step){
      const stR = await db.from('request_approval_steps').update({status:'approved', acted_at:nowIso}).eq('id', step.id).eq('status','pending').select('id');
      if(!(await dbCheck(stR, 'اعتماد خطوتك'))) return;
      if(!stR.data || !stR.data.length){ showToast('تعذّر اعتماد خطوتك: لم تعد بانتظارك (ربما حسمها غيرك). حدّث الصفحة.','error'); return; }
      if(!(await pushHistory(req, histEntry))) return;
      step.status='approved'; step.actedAt=nowIso;
      // بقية معتمدي نفس الخطوة (الأصلي أو المحال إليه): تُغلق لأن الأسبق حسم
      for(const o of group){
        if(o===step || o.status!=='pending') continue;
        await dbCheck(await db.from('request_approval_steps').update({status:'skipped', acted_at:nowIso, note:'أُغلقت لاعتماد '+state.user.name}).eq('id', o.id), 'إغلاق خطوة موازية');
        o.status='skipped'; o.actedAt=nowIso;
      }
      // لو هذا المعتمِد نفسه وارد بخطوة لاحقة بنفس الطلب فلا نسأله مرة ثانية
      for(const o of (req.approvalSteps||[])){
        if(o.status==='pending' && o.approverId===state.user.id && o.sequenceOrder>step.sequenceOrder){
          await dbCheck(await db.from('request_approval_steps').update({status:'skipped', acted_at:nowIso, note:'اعتُمدت ضمن خطوة سابقة'}).eq('id', o.id), 'تخطي خطوة مكررة');
          o.status='skipped'; o.actedAt=nowIso;
        }
      }
      // إحالة يدوية: اعتماد ثم إضافة خطوة للمدير الأعلى مباشرة بعد هذه الخطوة
      const esc = state.pendingEscalate; state.pendingEscalate = null;
      if(esc && esc.reqId===req.id && esc.targetId){
        for(const o of (req.approvalSteps||[]).filter(x=>x.sequenceOrder>step.sequenceOrder).sort((a,b)=>b.sequenceOrder-a.sequenceOrder)){
          await dbCheck(await db.from('request_approval_steps').update({sequence_order:o.sequenceOrder+1}).eq('id', o.id), 'ترتيب خطوات الإحالة');
          o.sequenceOrder += 1;
        }
        const row = {id:'as_'+req.id+'_m'+Date.now(), request_id:req.id, approver_id:esc.targetId, sequence_order:step.sequenceOrder+1, role_label:'pending_decision', status:'pending', kind:'primary', escalated_from:state.user.id};
        const ins = await db.from('request_approval_steps').insert(row);
        if(await dbCheck(ins, 'إضافة خطوة الإحالة')){
          req.approvalSteps.push({id:row.id, approverId:row.approver_id, sequenceOrder:row.sequence_order, roleLabel:row.role_label, status:'pending', actedAt:null, note:'', kind:'primary', escalatedFrom:state.user.id, activatedAt:null});
          req.approvalSteps.sort((a,b)=>a.sequenceOrder-b.sequenceOrder);
          const tName = (state.users.find(u=>u.id===esc.targetId)||{}).name||'';
          await pushHistory(req, {step:'pending_decision', actor:state.user.name, userId:state.user.id, action:'إحالة للمدير الأعلى', note:'أحال الاعتماد إلى '+tName, time: fmtDate()});
        }
      }
    }
    // الخطوة التالية تبدأ مهلتها الآن
    const nextGroup = currentDecisionGroup(req);
    if(nextGroup.length){
      const nowIso2 = new Date().toISOString();
      for(const o of nextGroup){
        await dbCheck(await db.from('request_approval_steps').update({activated_at:nowIso2}).eq('id', o.id), 'بدء مهلة الخطوة التالية');
        o.activatedAt = nowIso2;
      }
    }
    newStatus = nextGroup.length ? 'pending_decision' : 'pending_transfer_request';
  } else if(req.status==='pending_transfer_request'){
    const company = state.companies.find(c=>c.id===req.companyId);
    if(company && company.cfoDelegationMode==='skip'){
      postHist.push({step:'pending_transfer_approval', actor:'النظام', userId:null, action:'تخطٍّ تلقائي', note:'المدير المالي لا يستخدم النظام (حسب إعدادات الشركة)', time: fmtDate()});
      newStatus = 'pending_disbursement';
    } else {
      newStatus = 'pending_transfer_approval';
    }
  } else if(req.status==='pending_transfer_approval'){
    newStatus = 'pending_disbursement';
  } else {
    // توافق مع النظام القديم (طلبات تجريبية متبقية بأدوار ثابتة)
    const step = (req.approvalSteps||[]).find(s=>s.roleLabel===req.status);
    if(step){
      await db.from('request_approval_steps').update({status:'approved', acted_at:new Date().toISOString()}).eq('id', step.id);
      step.status='approved'; step.actedAt=new Date().toISOString();
    }
    const tailOrder = ['pending_accountant','pending_cfo','completed'];
    const i = tailOrder.indexOf(req.status);
    newStatus = i>=0 ? tailOrder[i+1] : 'pending_transfer_request';
  }
  if(!(await setRequestStatus(req, newStatus))){ render(); return; }
  for(const he of postHist){ await pushHistory(req, he); }
  showToast('تم اعتماد الطلب', 'success');
  render();
  if(newStatus==='pending_decision') paperAfterApprove(req);
}
// ===================== الاعتماد الورقي =====================
// معتمِد لا يستخدم النظام: يوقّع على الورقة، ويسجّل اعتماده أو رفضه أحد مسجِّليه (حتى ثلاثة) بإرفاق الورقة الموقعة
function isPaperApprover(uid){ const u = userById(uid); return !!(u && u.paperApproval && (u.paperProxyIds||[]).length); }
// طلب فيه اعتماد ورقي: مرحلة حالية لمعتمِد ورقي، أو مرحلة سُجّلت ورقياً
function reqPaperInfo(r){
  const steps = r.approvalSteps||[];
  const done = steps.filter(s=>s.method==='paper' && ['approved','rejected'].includes(s.status));
  const now = r.status==='pending_decision' ? currentDecisionGroup(r).find(s=>isPaperApprover(s.approverId)) : null;
  if(!done.length && !now) return null;
  return {waiting: !!now, names: [...new Set((now ? [now] : []).concat(done).map(s=>(userById(s.approverId)||{}).name||''))].filter(Boolean)};
}
function reqPaperBadge(r){
  const p = reqPaperInfo(r); if(!p) return '';
  return `<span class="badge paper-badge" title="${escH((p.waiting ? 'بانتظار اعتماد ورقي: ' : 'فيه اعتماد ورقي: ') + p.names.join('، '))}">📄 ${p.waiting ? 'بانتظار اعتماد ورقي' : 'معتمد ورقياً'}</span>`;
}
function paperProxiesOf(uid){ const u = userById(uid); return u && u.paperApproval ? (u.paperProxyIds||[]).map(userById).filter(Boolean) : []; }
// خطوة القرار الحالية التي أنا مسجِّلها الورقي
function paperStepForMe(req){
  if(!req || !state.user || req.status!=='pending_decision' || isUnderReview(req) || req.isCancelled) return null;
  const me = state.user.id;
  return currentDecisionGroup(req).find(s=>{ const u = userById(s.approverId); return u && u.paperApproval && (u.paperProxyIds||[]).includes(me); }) || null;
}
// الخطوة الحالية لمعتمِد ورقي (لأي ناظر): لعرض التنبيه
function paperStepNow(req){
  if(!req || req.status!=='pending_decision') return null;
  const me = state.user && state.user.id;
  // لا يظهر لصاحب القرار نفسه (يعتمد بنفسه) ولا لمسجِّليه (عندهم «بانتظارك الآن»)
  return currentDecisionGroup(req).find(s=>isPaperApprover(s.approverId) && s.approverId!==me && !paperProxiesOf(s.approverId).some(u=>u.id===me)) || null;
}
function waLink(phone){ const d = String(phone||'').replace(/\D/g,''); if(!d) return ''; return 'https://wa.me/' + (d.length===8 ? '965'+d : d.replace(/^00/,'')); }
// صندوق التنبيه: من يعتمد ورقياً، وزر الطباعة والتواصل مع المسجِّلين
function paperNoticeHtml(req, step, compact){
  const ap = userById(step.approverId) || {}, px = paperProxiesOf(step.approverId);
  const names = px.map(u=>u.name).join(' أو ');
  return `<div class="note-box paper-note no-print">
    <b>📄 المرحلة ${compact ? 'الحالية' : 'التالية'}: ${escH(ap.name||'')} يعتمد ورقياً.</b>
    <div>اطبع الطلب وأرسله له ليوقّعه، أو بلّغ ${escH(names)} — ${px.length>1 ? 'فهم مخوّلون' : 'فهو مخوّل'} بتسجيل اعتماده في النظام.</div>
    <div class="paper-note-acts">
      <button type="button" class="btn btn-ghost btn-sm" data-on-click="openPrintPreview" data-on-click-args="${qa([(''+req.id)])}">طباعة الطلب</button>
      ${px.map(u=>{ const l = waLink(u.phone); return l ? `<a class="btn btn-ghost btn-sm" href="${escH(l)}" target="_blank" rel="noopener">واتساب ${escH(u.name)}</a>` : ''; }).join('')}
    </div>
  </div>`;
}
// بعد اعتمادي: إن كانت المرحلة التالية ورقية يظهر التنبيه في صندوق عائم
function paperAfterApprove(req){
  const st = paperStepNow(req); if(!st) return;
  const ov = document.createElement('div'); ov.className = 'modal-overlay'; ov.id = 'paperNextModal';
  ov.innerHTML = `<div class="modal-box" style="max-width:480px;"><h2 style="margin:0 0 8px;">تم الاعتماد</h2>${paperNoticeHtml(req, st, false)}
    <div class="actions-row"><button type="button" class="btn btn-primary btn-md" data-on-click="paperNextClose">تم</button></div></div>`;
  document.body.appendChild(ov);
}
function paperNextClose(){ const m = document.getElementById('paperNextModal'); if(m) m.remove(); }

// ---- صندوق التسجيل ----
function paperRecordOpen(reqId, action){
  const req = state.requests.find(r=>r.id===reqId); if(!req) return;
  const st = paperStepForMe(req); if(!st){ showToast('لا توجد مرحلة بانتظار تسجيلك. حدّث الصفحة.','error'); return; }
  const ap = userById(st.approverId) || {}, rej = action==='reject';
  paperRecordClose();
  const t = new Date(), today = t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');
  const ov = document.createElement('div'); ov.className = 'modal-overlay'; ov.id = 'paperRecModal';
  ov.dataset.req = reqId; ov.dataset.step = st.id; ov.dataset.act = rej ? 'reject' : 'approve';
  ov.innerHTML = `<div class="modal-box paper-rec-box" role="dialog">
      <h2 style="margin:0 0 4px;">${rej ? 'تسجيل رفض ورقي' : 'تسجيل اعتماد ورقي'}</h2>
      <p class="sub" style="margin:0 0 10px;">عن <b>${escH(ap.name||'')}</b> — الطلب ${escH(req.number||'')}</p>
      <label>الورقة الموقعة (صورة أو PDF) *</label>
      <label class="btn btn-ghost btn-sm file-btn" style="width:100%;">اختيار الملف<input id="paperFile" type="file" accept="image/*,application/pdf" hidden data-on-change="paperFilePicked"></label>
      <div id="paperFileName" class="file-hint"></div>
      <label>تاريخ التوقيع *</label>
      <input id="paperDate" type="date" max="${today}" value="${today}">
      <label>${rej ? 'سبب الرفض *' : 'ملاحظة (اختياري)'}</label>
      <textarea id="paperNote" rows="2" placeholder="${rej ? 'كما كتبه على الورقة' : ''}"></textarea>
      <div class="nr-adj-acts">
        <button type="button" class="btn ${rej ? 'btn-reject' : 'btn-approve'} btn-md" id="paperSaveBtn" data-on-click="paperRecordSave">${rej ? 'تسجيل الرفض' : 'تسجيل الاعتماد'}</button>
        <button type="button" class="btn btn-ghost btn-md" data-on-click="paperRecordClose">إلغاء</button>
      </div>
    </div>`;
  document.body.appendChild(ov);
  qyAutoBox(ov.querySelector('.paper-rec-box'), null, paperRecordClose);
}
function paperRecordClose(){ const m = document.getElementById('paperRecModal'); if(m) m.remove(); }
function paperFilePicked(input){ if(!input || !input.files) input = document.getElementById('paperFile'); const f = input && input.files && input.files[0]; const n = document.getElementById('paperFileName'); if(n) n.textContent = f ? '📎 ' + f.name : ''; }
async function paperRecordSave(){
  const m = document.getElementById('paperRecModal'); if(!m) return;
  const req = state.requests.find(r=>r.id===m.dataset.req); if(!req) return;
  const step = (req.approvalSteps||[]).find(s=>s.id===m.dataset.step); if(!step) return;
  const rej = m.dataset.act==='reject';
  const fi = document.getElementById('paperFile'), f = fi && fi.files && fi.files[0];
  const date = (document.getElementById('paperDate')||{}).value || '';
  const note = ((document.getElementById('paperNote')||{}).value || '').trim();
  if(!f){ showToast('أرفق صورة الورقة الموقعة','error'); return; }
  if(!/^image\//.test(f.type) && f.type!=='application/pdf'){ showToast('الملف يجب أن يكون صورة أو PDF','error'); return; }
  if(f.size > 15*1024*1024){ showToast('الملف أكبر من 15 ميجابايت','error'); return; }
  if(!date){ showToast('اكتب تاريخ التوقيع','error'); return; }
  const t = new Date(), today = t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');
  if(date > today){ showToast('تاريخ التوقيع لا يكون في المستقبل','error'); return; }
  if(rej && !note){ showToast('اكتب سبب الرفض','error'); return; }
  const btn = document.getElementById('paperSaveBtn'); if(btn){ btn.disabled = true; btn.textContent = 'جارٍ الحفظ…'; }
  try{
    const ext = f.type==='application/pdf' ? 'pdf' : ((f.type.split('/')[1]||'jpg').replace('jpeg','jpg'));
    const path = req.companyId + '/paper/' + req.id + '/' + (crypto.randomUUID ? crypto.randomUUID() : Date.now()+'-'+Math.random().toString(36).slice(2)) + '.' + ext;
    const up = await db.storage.from('attachments').upload(path, f, {contentType: f.type, upsert:false});
    if(up.error) throw new Error(up.error.message);
    paperRecordClose();
    await finalizePaper(req, step, rej, path, date, note);
  }catch(e){
    showToast('تعذّر رفع الورقة: ' + e.message, 'error');
    if(btn){ btn.disabled = false; btn.textContent = rej ? 'تسجيل الرفض' : 'تسجيل الاعتماد'; }
  }
}
async function finalizePaper(req, step, rej, path, date, note){
  const ap = userById(step.approverId) || {}, nowIso = new Date().toISOString(), me = state.user.id;
  const dmy = date.split('-').reverse().join('-');
  const upd = {status: rej ? 'rejected' : 'approved', acted_at: nowIso, method:'paper', paper_path:path, paper_signed_at:date, recorded_by:me};
  if(rej) upd.note = note;
  const r = await db.from('request_approval_steps').update(upd).eq('id', step.id).eq('status','pending').select('id');
  // رُفض التسجيل: الورقة المرفوعة لا تبقى معلّقة في التخزين
  const dropFile = ()=>{ db.storage.from('attachments').remove([path]).catch(()=>{}); };
  if(!(await dbCheck(r, rej ? 'تسجيل الرفض الورقي' : 'تسجيل الاعتماد الورقي'))){ dropFile(); render(); return; }
  if(!r.data || !r.data.length){ dropFile(); showToast('المرحلة لم تعد بانتظار التسجيل (ربما حسمها غيرك أو أُلغي الاعتماد الورقي). حدّث الصفحة.','error'); render(); return; }
  Object.assign(step, {status:upd.status, actedAt:nowIso, method:'paper', paperPath:path, paperSignedAt:date, recordedBy:me});
  const group = currentDecisionGroup(req).concat([]);
  for(const o of (req.approvalSteps||[]).filter(x=>x!==step && x.status==='pending' && x.sequenceOrder===step.sequenceOrder)){
    await dbCheck(await db.from('request_approval_steps').update({status:'skipped', acted_at:nowIso, note:(rej?'أُغلقت لرفض ورقي عن ':'أُغلقت لاعتماد ورقي عن ')+(ap.name||'')}).eq('id', o.id), 'إغلاق خطوة موازية');
    o.status='skipped'; o.actedAt=nowIso;
  }
  if(rej){
    if(!(await setRequestStatus(req, 'rejected'))){ render(); return; }
    await pushHistory(req, {step:'pending_decision', actor:state.user.name, userId:me, action:'رفض الطلب', note:'(رفض ورقي عن '+(ap.name||'')+' — وقّعه بتاريخ '+dmy+') '+note, time:fmtDate()});
    showToast('سُجّل الرفض الورقي','success'); render(); return;
  }
  await pushHistory(req, {step:'pending_decision', actor:state.user.name, userId:me, action:'اعتماد ورقي', note:'عن '+(ap.name||'')+' — وقّعه بتاريخ '+dmy+(note ? ' — '+note : ''), time:fmtDate()});
  // المعتمِد الورقي نفسه في خطوة لاحقة بالطلب: لا يُسأل مرتين
  for(const o of (req.approvalSteps||[])){
    if(o.status==='pending' && o.approverId===step.approverId && o.sequenceOrder>step.sequenceOrder){
      await dbCheck(await db.from('request_approval_steps').update({status:'skipped', acted_at:nowIso, note:'اعتُمدت ضمن خطوة سابقة'}).eq('id', o.id), 'تخطي خطوة مكررة');
      o.status='skipped'; o.actedAt=nowIso;
    }
  }
  const nextGroup = currentDecisionGroup(req);
  for(const o of nextGroup){ await dbCheck(await db.from('request_approval_steps').update({activated_at:nowIso}).eq('id', o.id), 'بدء مهلة الخطوة التالية'); o.activatedAt = nowIso; }
  if(!(await setRequestStatus(req, nextGroup.length ? 'pending_decision' : 'pending_transfer_request'))){ render(); return; }
  showToast('سُجّل الاعتماد الورقي','success');
  render();
  paperAfterApprove(req);
}
// عرض الورقة الموقعة
async function paperView(reqId, stepId){
  const req = state.requests.find(r=>r.id===reqId); const st = req && (req.approvalSteps||[]).find(s=>s.id===stepId);
  if(!st || !st.paperPath) return;
  const sg = await db.storage.from('attachments').createSignedUrl(st.paperPath, 300);
  if(sg.error || !sg.data){ showToast('تعذّر فتح الورقة: ' + ((sg.error&&sg.error.message)||''), 'error'); return; }
  window.open(sg.data.signedUrl, '_blank', 'noopener');
}

// ---- الإعداد: في «حسابي» ولمدير النظام في تعديل المستخدم ----
// المسجِّل: من نفس شركة صاحب الحساب، أو مستخدم عام في المؤسسة
function paperCandidates(u){
  const cos = u.isGeneral ? state.companies.map(c=>c.id) : [u.companyId, ...(state.userCompanyLinks||[]).filter(l=>l.userId===u.id).map(l=>l.companyId)].filter(Boolean);
  return state.users.filter(x=>x.id!==u.id && !x.isSuspended && (x.isGeneral || u.isGeneral || cos.some(c=>userHasCompany(x, c))))
    .sort((a,b)=>(a.isGeneral===b.isGeneral) ? a.name.localeCompare(b.name,'ar') : (a.isGeneral ? 1 : -1));
}
function paperSettingsCard(u, adminView){
  const cands = paperCandidates(u), cur = u.paperProxyIds||[];
  const sel = i => `<select id="paperProxy${i}" ${u.paperApproval ? '' : 'disabled'}>
      <option value="">${i===0 ? 'اختر المسجِّل' : 'مسجِّل إضافي (اختياري)'}</option>
      ${cands.map(x=>`<option value="${escH(x.id)}"${cur[i]===x.id?' selected':''}>${escH(x.name)} — ${escH((x.jobTitle&&x.jobTitle.trim()) || findRole(x.role).name)}${x.isGeneral ? ' · عام' : ''}</option>`).join('')}
    </select>`;
  return `<div class="card paper-card" id="paperCard">
    <h2 style="margin:0 0 4px;font-size:var(--fs-h3);">الاعتماد الورقي</h2>
    <p class="file-hint" style="margin:0 0 8px;">${adminView ? 'إن كان هذا الشخص لا يستخدم النظام' : 'إن كنت لا تستخدم النظام في الاعتماد'}: يوقّع على الطلب المطبوع، ويسجّل اعتماده أو رفضه في النظام أحد المسجِّلين بإرفاق الورقة الموقعة. حتى ثلاثة مسجِّلين من نفس الشركة أو من العامّين في المؤسسة.</p>
    <label class="check-line" style="display:flex;align-items:center;gap:8px;margin:0 0 8px;font-weight:700;color:var(--text);">
      <input id="paperOn" type="checkbox" style="width:auto;" ${u.paperApproval ? 'checked' : ''} data-on-change="paperToggleUi"> تفعيل الاعتماد الورقي
    </label>
    <div class="paper-proxies">
      <div><label>المسجِّل الأول</label>${sel(0)}</div>
      <div><label>المسجِّل الثاني</label>${sel(1)}</div>
      <div><label>المسجِّل الثالث</label>${sel(2)}</div>
    </div>
    ${adminView ? `<div class="actions-row no-bar"><button type="button" class="btn btn-primary btn-md" data-on-click="savePaperSettings" data-on-click-args="${qa([(''+u.id)])}">حفظ الاعتماد الورقي</button></div>` : '<p class="file-hint" style="margin:8px 0 0;">يُحفظ مع زر «حفظ» أسفل الصفحة.</p>'}
  </div>`;
}
// طلبات تنتظر الآن تسجيلاً ورقياً عن هذا المعتمِد
function paperPendingFor(uid){
  return state.requests.filter(r=>r.status==='pending_decision' && !r.isCancelled && !isUnderReview(r) && currentDecisionGroup(r).some(s=>s.approverId===uid));
}
// قبل إلغاء الاعتماد الورقي: تنبيه بما ينتظر، ثم إشعار للمسجِّلين في سجل كل طلب
async function paperConfirmOff(u){
  if(!u || !u.paperApproval) return true;
  const list = paperPendingFor(u.id); if(!list.length) return true;
  const ok = await askModal({title:'إلغاء الاعتماد الورقي', confirm:'إلغاء الاعتماد الورقي',
    text:`${state.user.id===u.id ? 'لديك' : 'لدى '+escH(u.name)} ${list.length} ${list.length===1 ? 'طلب' : 'طلبات'} بانتظار تسجيل ورقي. بعد الإلغاء ${list.length===1 ? 'يعود' : 'تعود'} للاعتماد من النظام مباشرة، ويُبلَّغ المسجِّلون بذلك.`});
  return !!ok;
}
async function paperNotifyOff(u, oldIds){
  const list = paperPendingFor(u.id); if(!list.length || !(oldIds||[]).length) return;
  for(const r of list){
    await pushHistory(r, {step:r.status, actor:state.user.name, userId:state.user.id, action:'إلغاء الاعتماد الورقي', note:'لـ '+u.name+' — يعتمد من النظام مباشرة|ids:'+oldIds.join(','), time:fmtDate()});
  }
}
// ===== إشعارات الجهاز (Web Push) =====
const QY_VAPID_PUBLIC = 'BIJc7ESKrmePhWm7SZ1LJw92LsF6jsQiO4jSTXME9vRQ9ZFDmvBcU9CreMlT6Mqjh4C5mPWxGm31nRy47Sdq89g';
function pushSupported(){ return ('serviceWorker' in navigator) && ('PushManager' in window) && ('Notification' in window); }
function pushIsIos(){ return /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform==='MacIntel' && navigator.maxTouchPoints>1); }
function pushIsStandalone(){ try{ return window.matchMedia('(display-mode: standalone)').matches || navigator.standalone===true; }catch(e){ return false; } }
function pushKeyBytes(b64){ const p='='.repeat((4-b64.length%4)%4), s=(b64+p).replace(/-/g,'+').replace(/_/g,'/'), r=atob(s), o=new Uint8Array(r.length); for(let i=0;i<r.length;i++) o[i]=r.charCodeAt(i); return o; }
function pushCard(){
  setTimeout(pushPaint, 40);
  return `<div class="card" id="pushCard">
    <h2 style="margin:0 0 4px;font-size:var(--fs-h3);">إشعارات الجهاز</h2>
    <p class="file-hint" style="margin:0 0 8px;">تصلك على هذا الجهاز إشعارات الطلبات التي تنتظر إجراءك أو تخص طلباتك، حتى والنظام مغلق. تُفعَّل لكل جهاز على حدة.</p>
    <div id="pushBox" class="file-hint">جارٍ الفحص…</div>
  </div>`;
}
async function pushPaint(){
  const box = document.getElementById('pushBox'); if(!box) return;
  const btn = (fn, label, cls) => `<button type="button" class="btn ${cls||'btn-primary'}" style="min-height:40px;" data-on-click="${fn}">${label}</button>`;
  if(state.impersonatingFromAdmin){ box.innerHTML = 'لا تُفعَّل الإشعارات أثناء التصفح كمستخدم آخر — يفعّلها صاحب الحساب من جهازه.'; return; }
  if(!pushSupported()){
    box.innerHTML = (pushIsIos() && !pushIsStandalone())
      ? 'على الآيفون: افتح النظام في Safari ثم اضغط «مشاركة» ← «إضافة إلى الشاشة الرئيسية»، وافتحه من الأيقونة، ثم فعّل الإشعارات من هنا.'
      : 'هذا المتصفح لا يدعم إشعارات الجهاز. جرّب Chrome أو Edge أو Safari حديثاً.';
    return;
  }
  if(Notification.permission==='denied'){ box.innerHTML = 'الإشعارات محظورة لهذا الموقع. افتح إعدادات المتصفح للموقع وغيّرها إلى «سماح»، ثم ارجع هنا.'; return; }
  let sub = null;
  try{ const reg = await navigator.serviceWorker.ready; sub = await reg.pushManager.getSubscription(); }catch(e){}
  let evOn = [];
  const isAdm = !!(sub && state.user && state.user.role==='admin');
  if(isAdm){ try{ const q = await db.from('push_subscriptions').select('admin_events').eq('endpoint', sub.endpoint).maybeSingle(); evOn = (q.data && q.data.admin_events) || []; }catch(e){} }
  const adminOpt = isAdm
    ? `<div style="margin:0 0 10px;padding:10px;border:1px solid var(--border,#d9dde3);border-radius:10px;">
        <div style="font-weight:800;margin-bottom:6px;color:var(--text);">إشعارات مدير النظام (على هذا الجهاز)</div>
        <label class="check-line" style="display:flex;align-items:center;gap:8px;margin:0 0 6px;font-weight:800;color:var(--text);"><input id="pushEvAll" type="checkbox" style="width:auto;" ${PUSH_EVENTS.every(e=>evOn.includes(e[0]))?'checked':''} data-on-change="pushEvAll"> كل شيء</label>
        ${PUSH_EVENTS.map(e=>`<label class="check-line" style="display:flex;align-items:center;gap:8px;margin:0 0 4px;color:var(--text);"><input type="checkbox" class="pushEv" value="${e[0]}" style="width:auto;" ${evOn.includes(e[0])?'checked':''} data-on-change="pushEvSave"> ${e[1]}</label>`).join('')}
      </div>` : '';
  box.innerHTML = sub
    ? `<div style="margin-bottom:8px;color:var(--green,#15803d);font-weight:700;">✅ مفعّلة على هذا الجهاز</div>${adminOpt}${btn('pushDisable','إيقاف الإشعارات على هذا الجهاز','btn-ghost')}`
    : `<div style="margin-bottom:8px;">غير مفعّلة على هذا الجهاز.</div>${btn('pushEnable','تفعيل الإشعارات على هذا الجهاز')}`;
}
async function pushEnable(){
  if(state.impersonatingFromAdmin || !pushSupported()) return;
  try{
    const perm = await Notification.requestPermission();
    if(perm!=='granted'){ showToast('لم يُسمح بالإشعارات','error'); pushPaint(); return; }
    const reg = await navigator.serviceWorker.ready;
    let sub = await reg.pushManager.getSubscription();
    if(!sub) sub = await reg.pushManager.subscribe({userVisibleOnly:true, applicationServerKey: pushKeyBytes(QY_VAPID_PUBLIC)});
    const j = sub.toJSON();
    const r = await db.rpc('qy_push_subscribe', {p_endpoint:j.endpoint, p_p256dh:(j.keys||{}).p256dh, p_auth:(j.keys||{}).auth, p_ua:navigator.userAgent});
    if(!(await dbCheck(r, 'تفعيل الإشعارات'))) return;
    try{ await reg.showNotification('تم تفعيل الإشعارات', {body:'ستصلك إشعارات الطلبات على هذا الجهاز', icon:'icons/icon-192.png'}); }catch(e){}
    showToast('فُعّلت الإشعارات على هذا الجهاز','success');
  }catch(e){ showToast('تعذّر تفعيل الإشعارات: '+(e&&e.message||e),'error'); }
  pushPaint();
}
const PUSH_EVENTS = [['new','طلب جديد'],['approve','كل اعتماد مقبول'],['reject','كل رفض'],['paid','تم صرف طلب'],['cancel','إلغاء طلب'],['overrun','تجاوز ميزانية'],['login_fail','محاولة دخول فاشلة'],['pwreset','طلب إعادة تعيين كلمة مرور'],['security','تنبيهات الأمان'],['userchange','تغيير صلاحية أو إيقاف مستخدم'],['structure','مشكلة في مسار طلب (الهيكل)'],['error','أخطاء النظام'],['note','ملحوظة جديدة في الشات'],['import_stale','تأخر رفع ملفات بوابة الدفع'],['late','نسخة من تذكيرات الطلبات المتأخرة'],['review','طلب قيد المراجعة (عند إنشائه وعند حذفه قبل الإرسال)'],['self','أبلغني حتى بما أفعله أنا']];
async function pushEvSave(){
  try{
    const reg = await navigator.serviceWorker.ready, sub = await reg.pushManager.getSubscription(); if(!sub) return;
    const on = [...document.querySelectorAll('.pushEv:checked')].map(x=>x.value);
    const all = document.getElementById('pushEvAll'); if(all) all.checked = (on.length===PUSH_EVENTS.length);
    const r = await db.rpc('qy_push_set_events', {p_endpoint:sub.endpoint, p_events:on});
    if(!(await dbCheck(r, 'حفظ خيارات الإشعارات'))) return;
    showToast('حُفظت خيارات الإشعارات','success');
  }catch(e){ showToast('تعذّر الحفظ: '+(e&&e.message||e),'error'); }
}
async function pushEvAll(){
  const on = !!(document.getElementById('pushEvAll')||{}).checked;
  document.querySelectorAll('.pushEv').forEach(x=>{ x.checked = on; });
  await pushEvSave();
}
async function pushDisable(){
  try{
    const reg = await navigator.serviceWorker.ready, sub = await reg.pushManager.getSubscription();
    if(sub){ const ep = sub.endpoint; await sub.unsubscribe(); await db.rpc('qy_push_unsubscribe', {p_endpoint:ep}); }
    showToast('أُوقفت الإشعارات على هذا الجهاز','success');
  }catch(e){ showToast('تعذّر الإيقاف: '+(e&&e.message||e),'error'); }
  pushPaint();
}
// فتح الطلب من رابط الإشعار (?req=…) أو من رسالة عامل الخدمة
function pushOpenReq(id){
  if(!id) return false;
  const r = (state.requests||[]).find(x=>String(x.id)===String(id));
  if(!state.user || !r) return false;
  try{ if(r.companyId!==state.currentCompanyId && typeof switchCompany==='function') switchCompany(r.companyId); }catch(e){}
  openRequest(r.id); return true;
}
(function pushBoot(){
  try{
    const q = new URLSearchParams(location.search).get('req'); let tries = 0;
    const clean = () => { try{ const u = new URL(location.href); u.searchParams.delete('req'); history.replaceState(null,'',u.pathname+u.search+u.hash); }catch(e){} };
    if(q){ const t = setInterval(()=>{ tries++; if(pushOpenReq(q)){ clearInterval(t); clean(); } else if(tries>60){ clearInterval(t); clean(); } }, 1000); }
    if('serviceWorker' in navigator) navigator.serviceWorker.addEventListener('message', e=>{ if(e.data && e.data.type==='qy-open') pushOpenReq(e.data.req); });
  }catch(e){}
})();
function paperToggleUi(){ const on = !!(document.getElementById('paperOn')||{}).checked; [0,1,2].forEach(i=>{ const s = document.getElementById('paperProxy'+i); if(s) s.disabled = !on; }); }
async function savePaperSettings(uid){
  const u = state.users.find(x=>x.id===uid); if(!u) return;
  const on = !!(document.getElementById('paperOn')||{}).checked;
  const ids = [...new Set([0,1,2].map(i=>(document.getElementById('paperProxy'+i)||{}).value||'').filter(Boolean))];
  if(on && !ids.length){ fieldErr(document.getElementById('paperProxy0'), 'اختر مسجِّلاً واحداً على الأقل'); return; }
  const oldIds = (u.paperProxyIds||[]).slice(), turningOff = u.paperApproval && !on;
  if(turningOff && !(await paperConfirmOff(u))) return;
  const r = await db.from('users').update({paper_approval:on, paper_proxy_ids: on ? ids : []}).eq('id', uid).select('id');
  if(!(await dbCheck(r, 'حفظ الاعتماد الورقي'))) return;
  if(!r.data || !r.data.length){ showToast('تعذّر الحفظ: لا صلاحية لتعديل هذا الحساب','error'); return; }
  if(turningOff) await paperNotifyOff(u, oldIds);
  u.paperApproval = on; u.paperProxyIds = on ? ids : [];
  qyLog('paper_settings', (on ? 'تفعيل' : 'إيقاف') + ' الاعتماد الورقي لـ ' + u.name, ids.map(id=>(userById(id)||{}).name||id).join('، '));
  showToast(on ? 'فُعّل الاعتماد الورقي' : 'أُوقف الاعتماد الورقي', 'success');
  render();
}
// المحاسب يؤكد إتمام الصرف فعلياً — الخطوة الأخيرة بالطلب، تأكيد بسيط بلا توقيع
// إسناد طلب «بند غير محدد» إلى بند حقيقي — يُسجَّل في سجل الطلب
async function assignBudgetItem(reqId){
  const req = state.requests.find(r=>r.id===reqId);
  const sel = document.getElementById('assignBudgetSel');
  if(!req || !sel) return;
  const itemId = sel.value;
  if(!itemId){ fieldErr(sel, 'اختر البند أولاً'); return; }
  const bi = (state.budgetItems||[]).find(b=>b.id===itemId);

  const r = await db.from('requests').update({budget_item_id: itemId}).eq('id', reqId);
  if(!(await dbCheck(r,'إسناد بند الميزانية'))) return;
  req.budgetItemId = itemId;
  await pushHistory(req, {step:req.status, actor: state.user.name, userId: state.user.id,
    action:'إسناد بند الميزانية', note:`أُسند إلى: ${bi?bi.name:itemId}`, time: fmtDate()});
  showToast('تم إسناد البند — صار الطلب مكتملاً','success');
  render();
}

async function markDisbursed(req){
  // الصمام يُغلق هنا: لا صرف قبل إسناد الطلب إلى بند ميزانية حقيقي
  if(isUnspecifiedBudget(req.budgetItemId) && !isCenterReq(req)){
    fieldErr(document.getElementById('assignBudgetSel'), 'لا يمكن إتمام الصرف: الطلب على «بند غير محدد». أسنده إلى بند من بطاقة الطلب أولاً');
    return false;
  }
  // الحركة تُسجَّل في الدفتر أولاً. فإن تعذّر تسجيلها لا يُعلَّم الطلب مصروفاً،
  // لئلا يخرج المال من الواقع ولا يظهر في الدفتر.
  if(!hasTransactionFor('request', req.id)){
    const benes = req.beneficiaries || [];
    const who = benes.length === 0 ? '' : (benes.length === 1 ? benes[0].name : `${benes.length} مستفيدين`);
    const posted = await postTransaction({
      companyId: req.companyId,
      centerId: req.centerId,
      direction: 'out',
      amount: req.totalAmount,
      budgetItemId: req.budgetItemId,
      beneficiary: who,
      description: `صرف الطلب ${req.number || ''} — ${req.reason||''}`.trim(),
      sourceType: 'request',
      sourceId: req.id
    });
    if(!posted) return;   // الرسالة ظهرت من postTransaction
  }
  const doneEntry = {step:req.status, actor: state.user.name, userId: state.user.id, action:'تم الصرف', note:'', time: fmtDate()};
  if(!(await setRequestStatus(req, 'completed'))){ render(); return; }
  await pushHistory(req, doneEntry);
  showToast('تم تأكيد الصرف وتسجيله في دفتر الحركات', 'success');
  render();
}

async function rebuildRequestPath(req){
  const creator = state.users.find(u=>u.id===req.createdById);
  if(!creator){ showToast('تعذر إيجاد صاحب الطلب', 'error'); return; }
  const {steps: newSteps, error: chainError} = buildDecisionChain(creator, req.companyId);
  if(chainError && req.requestType!=='custody'){   // مسار العهدة من صاحبها، يحكم عليه الخادم
    showToast('تعذّر إعادة البناء: '+chainError, 'error');
    return;
  }
  const rr = await db.rpc('qy_set_chain', {p_req: req.id, p_reset: false});
  if(!(await dbCheck(rr, 'إعادة بناء مسار الاعتماد'))) return;
  req.approvalSteps = (rr.data||[]).map(mapStepRow); noteSelfApproval(req);
  const stepRows = req.approvalSteps;
  const newStatus = statusForSteps(stepRows);
  if(newStatus !== req.status){
    await pushHistory(req, {step:req.status, actor: state.user.name, userId: state.user.id, action:'إعادة بناء مسار الاعتماد', note:'', time: fmtDate()});
    await setRequestStatus(req, newStatus);
  }
  showToast('تم إعادة بناء مسار الاعتماد حسب "من يعتمد طلبه" الحالي', 'success');
  render();
}
// ============================================================
// إعادة المسار والاعتماد — تُستخدم عندما اعتمد أحد أو وصل الطلب للذيل
// ============================================================
async function rebuildRequestPathAndReset(req){
  if(!confirm('سيتم إعادة بناء مسار الاعتماد وإلغاء جميع الاعتمادات السابقة.\nهل أنت متأكد؟')) return;

  const creator = state.users.find(u=>u.id===req.createdById);
  if(!creator){ showToast('تعذر إيجاد صاحب الطلب', 'error'); return; }
  const {steps: newSteps, error: chainError} = buildDecisionChain(creator, req.companyId);
  if(chainError){
    showToast('تعذّر إعادة البناء: '+chainError, 'error');
    return;
  }

  // جمع المعتمدين السابقين (من اعتمد فعلياً أو كان في الذيل)
  const prevApprovers = (req.approvalSteps||[])
    .filter(s=>s.actedAt || s.status==='approved')
    .map(s=>s.approverId)
    .filter((v,i,a)=>a.indexOf(v)===i);

  // الخادم يحذف المسار القديم ويبني الجديد معاً (ذرّياً)، ويلغي الاعتمادات السابقة
  const rr = await db.rpc('qy_set_chain', {p_req: req.id, p_reset: true});
  if(!(await dbCheck(rr, 'إعادة المسار والاعتماد'))) return;
  req.approvalSteps = (rr.data||[]).map(mapStepRow);
  const stepRows = req.approvalSteps;

  // إضافة سجل تاريخي
  await pushHistory(req, {step:req.status, actor: state.user.name, userId: state.user.id,
    action:'إعادة المسار والاعتماد',
    note:'تم إعادة بناء مسار الاعتماد وإلغاء الاعتمادات السابقة. المعتمدون السابقون: '+
      (prevApprovers.map(id=>{ const u=state.users.find(x=>x.id===id); return u?u.name:id; }).join('، ')||'—'),
    time: fmtDate()
  });

  // إضافة إشعار path_reset لكل معتمد سابق في تاريخ الطلب
  for(const approverId of prevApprovers){
    await pushHistory(req, {
      step:'path_reset_notify',
      actor: state.user.name,
      userId: state.user.id,
      action:'path_reset',
      note:'notif_target:'+approverId,
      time: fmtDate()
    });
  }

  // تحديث الحالة للـ pending_decision (أو للمحاسب إن كان المنشئ في أعلى السلسلة فاعتُمد بإنشائه)
  const newStatus = statusForSteps(stepRows);
  await setRequestStatus(req, newStatus);

  showToast('تم إعادة بناء المسار — '+(prevApprovers.length ? 'أُرسل إشعار للمعتمدين السابقين' : 'لم يكن هناك اعتمادات سابقة'), 'success');
  render();
}

async function submitBankTransfer(){
  const req = state.requests.find(r=>r.id===state.transferFormReqId);
  if(!req) return;
  const refInput = document.getElementById('bankTransferRefInput');
  const ref = refInput ? refInput.value.trim() : '';
  if(!ref){ showToast('الرجاء إدخال رقم/مرجع التحويل البنكي', 'error'); return; }
  const updateResult = await db.from('requests').update({bank_transfer_ref: ref, bank_transfer_at: new Date().toISOString()}).eq('id', req.id);
  if(!(await dbCheck(updateResult, 'تسجيل إثبات التحويل'))) return;
  req.bankTransferRef = ref; req.bankTransferAt = new Date().toISOString();
  state.transferFormReqId = null;
  const me = state.users.find(u=>u.id===state.user.id);
  const canManualSign = me && me.signatureMode==='manual';
  if(canManualSign){
    state.manualSignReqId = req.id;
    render();
    return;
  }
  await finalizeApprove(req, null);
}

/* ═══ المرفقات المتعددة (صور + PDF) في مجلد خاص — الجزء 7 ═══ */
const ATT_MAX_FILES = 10, ATT_MAX_BYTES = 10*1024*1024;
const ATT_LABELS = ['هوية','حساب بنكي','فاتورة','عقد','أخرى'];
const ATT_EXT = {'image/jpeg':'jpg','image/png':'png','image/webp':'webp','application/pdf':'pdf'};
const PDFJS_SRC = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
const PDFJS_WORKER = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
const ATT_MAX_PX = 1700;            // أقصى عرض/ارتفاع لصور المعاينة والطباعة
function attFmtSize(n){ n=Number(n)||0; return n>=1048576 ? (n/1048576).toFixed(1)+' MB' : Math.max(1,Math.round(n/1024))+' KB'; }
// نوع الملف الحقيقي من أول بايتات (لا نثق باسمه ولا بنوعه المُعلَن)
async function attSniff(file){
  const b = new Uint8Array(await file.slice(0,12).arrayBuffer());
  const s = (i,n)=>String.fromCharCode(...b.slice(i,i+n));
  if(b[0]===0xFF && b[1]===0xD8 && b[2]===0xFF) return 'image/jpeg';
  if(b[0]===0x89 && s(1,3)==='PNG') return 'image/png';
  if(s(0,4)==='RIFF' && s(8,4)==='WEBP') return 'image/webp';
  if(s(0,4)==='%PDF') return 'application/pdf';
  return null;
}
function attLoadScript(src){
  return new Promise((res,rej)=>{
    const s = document.createElement('script'); s.src = src; s.onload = ()=>res(); s.onerror = ()=>rej(new Error('تعذّر تحميل مكتبة قراءة PDF — تحقق من الاتصال'));
    document.head.appendChild(s);
  });
}
async function attPdfLib(){
  if(!window.pdfjsLib) await attLoadScript(PDFJS_SRC);
  window.pdfjsLib.GlobalWorkerOptions.workerSrc = PDFJS_WORKER;
  return window.pdfjsLib;
}
function attCanvasToJpeg(src, w, h){
  const k = Math.min(1, ATT_MAX_PX / Math.max(w, h));
  const cw = Math.max(1, Math.round(w*k)), ch = Math.max(1, Math.round(h*k));
  const cv = document.createElement('canvas'); cv.width = cw; cv.height = ch;
  const cx = cv.getContext('2d'); cx.fillStyle = '#fff'; cx.fillRect(0,0,cw,ch); cx.drawImage(src, 0, 0, cw, ch);
  return cv.toDataURL('image/jpeg', 0.88);
}
// صورة → رابط data مضغوط الأبعاد (لتعمل في المعاينة والطباعة)
function attImageToDataUrl(blob){
  return new Promise((res,rej)=>{
    const u = URL.createObjectURL(blob), im = new Image();
    im.onload = ()=>{ try{ res(attCanvasToJpeg(im, im.naturalWidth||1, im.naturalHeight||1)); }catch(e){ rej(e); } URL.revokeObjectURL(u); };
    im.onerror = ()=>{ URL.revokeObjectURL(u); rej(new Error('تعذّر قراءة الصورة')); };
    im.src = u;
  });
}
// PDF → قائمة صفحات (روابط data)، حتى 30 صفحة
async function attPdfToPages(buf){
  const lib = await attPdfLib();
  const doc = await lib.getDocument({data: buf, isEvalSupported:false}).promise;
  const pages = [], n = Math.min(doc.numPages, 30);
  for(let i=1;i<=n;i++){
    const pg = await doc.getPage(i), vp = pg.getViewport({scale: 1.6});
    const cv = document.createElement('canvas'); cv.width = Math.ceil(vp.width); cv.height = Math.ceil(vp.height);
    const cx = cv.getContext('2d'); cx.fillStyle = '#fff'; cx.fillRect(0,0,cv.width,cv.height);
    await pg.render({canvasContext: cx, viewport: vp}).promise;
    pages.push(attCanvasToJpeg(cv, cv.width, cv.height));
  }
  return pages;
}
async function attBlobToPages(blob, mime){
  return mime==='application/pdf' ? attPdfToPages(await blob.arrayBuffer()) : [await attImageToDataUrl(blob)];
}
async function attFetchRowBlob(row){
  const sg = await db.storage.from('attachments').createSignedUrl(row.path, 300);
  if(sg.error || !sg.data) throw new Error('تعذّر فتح المرفق: ' + ((sg.error&&sg.error.message)||''));
  const r = await fetch(sg.data.signedUrl);
  if(!r.ok) throw new Error('تعذّر تحميل المرفق');
  return r.blob();
}
async function attRowPages(row){
  state.attPagesCache = state.attPagesCache || {};
  if(state.attPagesCache[row.id]) return state.attPagesCache[row.id];
  const pages = await attBlobToPages(await attFetchRowBlob(row), row.mime);
  state.attPagesCache[row.id] = pages;
  return pages;
}
async function attLoadRows(masterId, reqId){
  const r = await db.from('qy_attachments').select('*').eq('master_id', masterId).order('created_at');
  if(r.error) throw new Error(r.error.message);
  const fixed = r.data.filter(x=>!x.request_id);
  state.attCounts = state.attCounts || {}; state.attCounts[masterId] = fixed.length;
  // الثابتة للمستفيد + المرتبطة بهذا الطلب فقط (مرفقات الطلبات الأخرى لا تظهر)
  return r.data.filter(x=>!x.request_id || (reqId && x.request_id===reqId));
}
async function attLoadCounts(){
  if(state._attCountsBusy || state.attCounts) return;
  state._attCountsBusy = true;
  try{
    const r = await db.from('qy_attachments').select('master_id,request_id');
    const m = {}; (r.data||[]).forEach(x=>{ if(!x.request_id) m[x.master_id] = (m[x.master_id]||0)+1; });
    state.attCounts = m;
    if(state.view==='newRequest' && !state.attModal){ syncDraftFromDOM(); render(); }
  }catch(e){ state.attCounts = {}; }
  state._attCountsBusy = false;
}
// يرفع ملفاً واحداً (تخزين ثم صف بيانات؛ إن فشل الصف يُحذف الملف)
async function attUploadOne(master, file, label, mime, reqId){
  const path = master.companyId + '/' + master.id + '/' + (crypto.randomUUID ? crypto.randomUUID() : (Date.now()+'-'+Math.random().toString(36).slice(2))) + '.' + ATT_EXT[mime];
  const up = await db.storage.from('attachments').upload(path, file, {contentType: mime, upsert:false});
  if(up.error) throw new Error(up.error.message);
  const row = {master_id: master.id, company_id: master.companyId, label, file_name: String(file.name||'ملف').slice(0,200), mime, size_bytes: file.size, path};
  if(reqId) row.request_id = reqId;
  const ins = await db.from('qy_attachments').insert(row).select().single();
  if(ins.error){ await db.storage.from('attachments').remove([path]); throw new Error(ins.error.message); }
  if(!reqId){ state.attCounts = state.attCounts || {}; state.attCounts[master.id] = (state.attCounts[master.id]||0) + 1; }
  return ins.data;
}
function attCurrentScope(){
  const sel = document.getElementById('attScopeSel'); return sel && sel.value==='req' ? 'req' : 'fixed';
}
function attCurrentLabel(){
  const sel = document.getElementById('attLabelSel'); const v = sel ? sel.value : 'هوية';
  if(v!=='أخرى') return v;
  const c = (document.getElementById('attLabelCustom')||{}).value||'';
  return c.trim().slice(0,60) || 'أخرى';
}
function attMasterOf(m){
  if(m.kind==='master') return m.master;
  const b = state.draft && state.draft.beneficiaries[m.idx];
  const name = b ? (b.name||'').trim() : '';
  return name ? (state.beneficiaries.find(x=>x.name===name && x.companyId===state.currentCompanyId && x.id) || null) : null;
}
async function openAttachmentsModal(kind, idx, masterName){
  if(kind==='draft'){ syncDraftFromDOM(); }
  state.attModal = {kind, idx, master: null, rows: [], loading: true, busy: false, preview: null, name: ''};
  const m = state.attModal;
  if(kind==='master'){ m.master = state.beneficiaries.find(x=>x.name===masterName && x.id) || null; m.name = masterName; }
  else { const b = state.draft.beneficiaries[idx]; m.name = (b.name||'').trim(); m.master = attMasterOf(m); }
  if(kind==='master') attRefresh(); else render();
  m.reqId = (kind==='draft' && state.editingReqId) ? state.editingReqId : null;
  try{ if(m.master) m.rows = await attLoadRows(m.master.id, m.reqId); }catch(e){ showToast('تعذّر تحميل المرفقات: ' + e.message, 'error'); }
  m.loading = false; attRefresh();
}
function closeAttachmentsModal(){
  const wasDraft = state.attModal && state.attModal.kind==='draft';
  if(state.attModal && state.attModal.kind==='master'){
    state.attModal = null; const r = document.getElementById('attModalRoot'); if(r) r.remove(); return;
  }
  state.attModal = null;
  if(wasDraft && state.view==='newRequest') syncDraftFromDOM();
  render();
}
function attRefresh(){
  const old = document.getElementById('attModalRoot'); if(old) old.remove();
  if(state.attModal){ const app = document.getElementById('app'); if(app) app.insertAdjacentHTML('beforeend', renderAttachmentsModal()); }
}
async function attPick(input){
  const m = state.attModal; if(!m) return;
  const files = Array.from(input.files||[]); input.value = '';
  if(!files.length) return;
  const label = attCurrentLabel();
  const scope = (m.kind==='draft') ? attCurrentScope() : 'fixed';
  const draftItem = (m.kind==='draft') ? state.draft.beneficiaries[m.idx] : null;
  if(draftItem && !m.master) draftItem._pend = draftItem._pend || [];
  m.busy = true; attRefresh();
  let ok = 0;
  for(const f of files){
    try{
      const have = (m.master ? m.rows.filter(r=>!r.request_id).length : 0) + (draftItem && draftItem._pend ? draftItem._pend.filter(q=>q.scope!=='req').length : 0);
      if(have >= ATT_MAX_FILES) throw new Error('الحد الأقصى ' + ATT_MAX_FILES + ' مرفقات لكل مستفيد');
      if(f.size > ATT_MAX_BYTES) throw new Error('حجم «' + f.name + '» يتجاوز 10 ميجابايت');
      if(f.size < 1) throw new Error('الملف «' + f.name + '» فارغ');
      const mime = await attSniff(f);
      if(!mime) throw new Error('«' + f.name + '»: النوع غير مقبول (المقبول: JPG وPNG وWEBP وPDF)');
      if(m.master && (scope==='fixed' || m.reqId)){ m.rows.push(await attUploadOne(m.master, f, label, mime, scope==='req' ? m.reqId : null)); }
      else { draftItem._pend = draftItem._pend || []; draftItem._pend.push({file: f, label, mime, scope}); }
      ok++;
    }catch(e){ showToast(e.message, 'error'); }
  }
  m.busy = false; attRefresh();
  if(ok) showToast((m.master && (scope==='fixed' || m.reqId)) ? ('تم رفع ' + ok + ' ملف') : ('أُضيف ' + ok + ' ملف — يُرفع عند إرسال الطلب'), 'success');
}
async function attPreview(key){
  const m = state.attModal; if(!m) return;
  let title = '', loader;
  if(key==='legacy-id'){ const mm=m.master; title='هوية (قديم)'; loader = async()=>[mm.idFileData]; }
  else if(key==='legacy-bank'){ const mm=m.master; title='حساب بنكي (قديم)'; loader = async()=>[mm.bankFileData]; }
  else if(key.startsWith('p')){ const it = state.draft.beneficiaries[m.idx]._pend[Number(key.slice(1))]; title = it.label + ' — ' + it.file.name; loader = ()=>attBlobToPages(it.file, it.mime); }
  else { const row = m.rows.find(r=>r.id===key); if(!row) return; title = row.label + ' — ' + row.file_name; loader = ()=>attRowPages(row); }
  m.preview = {title, pages: [], loading: true}; attRefresh();
  try{ m.preview.pages = await loader(); }catch(e){ showToast(e.message, 'error'); m.preview = null; }
  if(m.preview) m.preview.loading = false;
  attRefresh();
}
function attClosePreview(){ if(state.attModal){ state.attModal.preview = null; attRefresh(); } }
async function attDownload(key){
  const m = state.attModal; if(!m) return;
  try{
    let url, name;
    if(key==='legacy-id'){ url = m.master.idFileData; name = 'هوية'; }
    else if(key==='legacy-bank'){ url = m.master.bankFileData; name = 'حساب-بنكي'; }
    else if(key.startsWith('p')){ const it = state.draft.beneficiaries[m.idx]._pend[Number(key.slice(1))]; url = URL.createObjectURL(it.file); name = it.file.name; }
    else {
      const row = m.rows.find(r=>r.id===key); name = row.file_name;
      const sg = await db.storage.from('attachments').createSignedUrl(row.path, 120, {download: row.file_name});
      if(sg.error) throw new Error(sg.error.message);
      url = sg.data.signedUrl;
    }
    const a = document.createElement('a'); a.href = url; a.download = name; a.rel = 'noopener'; document.body.appendChild(a); a.click(); a.remove();
  }catch(e){ showToast('تعذّر التحميل: ' + e.message, 'error'); }
}
async function attDelete(key){
  const m = state.attModal; if(!m) return;
  if(key==='legacy-id' || key==='legacy-bank'){
    if(!confirm('حذف هذا المرفق القديم نهائياً؟')) return;
    const col = key==='legacy-id' ? 'id_file_data' : 'bank_file_data';
    m.busy = true; attRefresh();
    try{
      const d = await db.from('beneficiaries_master').update({[col]: null}).eq('id', m.master.id).select('id');
      if(d.error) throw new Error(d.error.message);
      if(!d.data || !d.data.length) throw new Error('لا تملك صلاحية حذف هذا المرفق');
      if(key==='legacy-id'){ m.master.idFileData = ''; m.master.idFileName = ''; } else { m.master.bankFileData = ''; m.master.bankFileName = ''; }
      qyLog('attachment_delete', 'حذف مرفق قديم: ' + key, 'master=' + m.master.id);
    }catch(e){ showToast('تعذّر الحذف: ' + e.message, 'error'); }
    m.busy = false; attRefresh(); return;
  }
  if(key.startsWith('p')){
    const arr = state.draft.beneficiaries[m.idx]._pend; arr.splice(Number(key.slice(1)), 1); attRefresh(); return;
  }
  const row = m.rows.find(r=>r.id===key); if(!row) return;
  if(!confirm('حذف المرفق «' + row.file_name + '» نهائياً؟')) return;
  m.busy = true; attRefresh();
  try{
    const d = await db.from('qy_attachments').delete().eq('id', row.id).select('id');
    if(d.error) throw new Error(d.error.message);
    if(!d.data || !d.data.length) throw new Error('لا تملك صلاحية حذف هذا المرفق');
    await db.storage.from('attachments').remove([row.path]);
    m.rows = m.rows.filter(r=>r.id!==row.id);
    state.attCounts[m.master.id] = m.rows.filter(r=>!r.request_id).length;
    if(state.attPagesCache) delete state.attPagesCache[row.id];
    qyLog('attachment_delete', 'حذف مرفق: ' + row.label, 'master=' + m.master.id);
  }catch(e){ showToast('تعذّر الحذف: ' + e.message, 'error'); }
  m.busy = false; attRefresh();
}
// بعد حفظ المستفيد (لأول مرة) نرفع ما اختاره المستخدم قبل الإرسال
let ATT_REQ_QUEUE = [];
// مرفقات «لهذا الطلب» تنتظر حتى يُنشأ الطلب ويُعرف رقمه الداخلي
async function attFlushReqQueue(reqId){
  const q = ATT_REQ_QUEUE; ATT_REQ_QUEUE = [];
  let ok = 0;
  for(const x of q){
    try{ await attUploadOne(x.master, x.p.file, x.p.label, x.p.mime, reqId); ok++; }
    catch(e){ showToast('تعذّر رفع «' + x.p.file.name + '»: ' + e.message, 'error'); }
  }
  if(ok) showToast('رُفع ' + ok + ' مرفق خاص بالطلب', 'success');
}
async function attFlushPending(draftB, master){
  const pend = draftB._pend || []; if(!pend.length || !master || !master.id) return;
  let ok = 0;
  for(const p of pend){
    if(p.scope==='req'){ ATT_REQ_QUEUE.push({master, p}); continue; }
    try{ await attUploadOne(master, p.file, p.label, p.mime); ok++; }
    catch(e){ showToast('تعذّر رفع «' + p.file.name + '»: ' + e.message, 'error'); }
  }
  draftB._pend = [];
  if(ok) showToast('رُفع ' + ok + ' مرفق للمستفيد ' + master.name, 'success');
}
function attButtonHtml(i, b){
  const name = (b.name||'').trim();
  const mst = name ? state.beneficiaries.find(x=>x.name===name && x.companyId===state.currentCompanyId && x.id) : null;
  const saved = mst ? ((state.attCounts||{})[mst.id]||0) + (mst.idFileData?1:0) + (mst.bankFileData?1:0) : 0;
  const pend = (b._pend||[]).length;
  const n = saved + pend;
  if(!state.attCounts && !state._attCountsBusy) setTimeout(attLoadCounts, 0);
  return `<button type="button" class="btn btn-ghost btn-sm" data-on-click="openAttachmentsModal" data-on-click-args="${qa(["draft", (i)])}">📎 مرفقات${n ? ' (' + n + ')' : ''}</button>
    ${pend ? `<span class="file-hint" style="margin-right:8px;">${pend} ملف بانتظار الرفع عند الإرسال</span>` : ''}`;
}
