    list += m.rows.map(r=>item(r.id, icon(r.mime), r.label + (r.request_id ? ' · لهذا الطلب' : ''), r.file_name, attFmtSize(r.size_bytes), true, false)).join('');
    list += pend.map((p,k)=>item('p'+k, icon(p.mime), p.label + (p.scope==='req' ? ' · لهذا الطلب' : ''), p.file.name, attFmtSize(p.file.size), true, false)).join('');
