function setupManualSignCanvas(){
  const canvas = document.getElementById('manualSignCanvas');
  if(!canvas) return;
  const me = state.users.find(u=>u.id===state.user.id);
  const ctx = canvas.getContext('2d');
  ctx.lineWidth = (me && me.signatureWidth) || 2.2;
  ctx.lineCap = 'round';
  ctx.strokeStyle = (me && me.signatureColor) || '#1B2733';
  let drawing=false, lastX=0, lastY=0;
  function pos(e){
    const rect = canvas.getBoundingClientRect();
    const cx = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left;
    const cy = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top;
    return {x: cx*(canvas.width/rect.width), y: cy*(canvas.height/rect.height)};
  }
  function start(e){ drawing=true; const p=pos(e); lastX=p.x; lastY=p.y; e.preventDefault(); }
  function move(e){ if(!drawing) return; const p=pos(e); ctx.beginPath(); ctx.moveTo(lastX,lastY); ctx.lineTo(p.x,p.y); ctx.stroke(); lastX=p.x; lastY=p.y; e.preventDefault(); }
  function end(){ drawing=false; }
  canvas.addEventListener('mousedown', start);
  canvas.addEventListener('mousemove', move);
  window.addEventListener('mouseup', end);
  canvas.addEventListener('touchstart', start, {passive:false});
  canvas.addEventListener('touchmove', move, {passive:false});
  canvas.addEventListener('touchend', end);
}

function clearManualSignCanvas(){
  const canvas = document.getElementById('manualSignCanvas');
  canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);
}

async function confirmManualSign(){
  const canvas = document.getElementById('manualSignCanvas');
  const dataUrl = canvas.toDataURL('image/png');
  const req = state.requests.find(r=>r.id===state.manualSignReqId);
  state.manualSignReqId = null;
  await finalizeApprove(req, dataUrl);
}

// حدّ المرفقات: صور وPDF فقط وبحجم لا يزيد عن 4 ميغابايت (يمنع تضخيم الجداول ورفع ملفات غريبة)
const UPLOAD_MAX_BYTES = 4*1024*1024;
function uploadProblem(file){
  if(!file) return '';
  if(!/^(image\/(png|jpe?g|webp|gif|svg\+xml)|application\/pdf)$/.test(file.type||'')) return 'نوع الملف غير مسموح — المسموح صور (PNG/JPG/WEBP/GIF) أو PDF';
  if(file.size > UPLOAD_MAX_BYTES) return 'حجم الملف أكبر من 4 ميغابايت — صغّر الصورة ثم أعد المحاولة';
  return '';
}
document.addEventListener('change', e=>{
  const t=e.target;
  if(!t || t.tagName!=='INPUT' || t.type!=='file') return;
  if(t.hasAttribute('data-csv')) return;   // ملفات CSV لاستيراد البوابة (تُقرأ في المتصفح ولا تُرفع كمرفق)
  for(const f of (t.files||[])){
    const msg=uploadProblem(f);
    if(msg){ t.value=''; e.stopImmediatePropagation(); showToast(msg,'error'); return; }
  }
}, true);
function readFileAsDataURL(file){
  { const msg=uploadProblem(file); if(msg){ showToast(msg,'error'); return Promise.reject(new Error(msg)); } }
  return new Promise((resolve, reject)=>{
    const r = new FileReader();
    r.onload = e=>resolve(e.target.result);
    r.onerror = reject;
    r.readAsDataURL(file);
  });
}

async function saveAccount(){
  const me = state.users.find(u=>u.id===state.user.id);
  const newName = document.getElementById('accName').value.trim();
  const newPass = document.getElementById('accPass').value.trim();
  const newEmail = document.getElementById('accEmail').value.trim();
  const newNameEn = document.getElementById('accNameEn').value.trim();
  const newIban = document.getElementById('accIban').value.trim();
  const newCivilId = document.getElementById('accCivilId').value.trim();
  const idInfoFile = (document.getElementById('accIdFile')||{files:[]}).files[0];
  const bankInfoFile = (document.getElementById('accBankFile')||{files:[]}).files[0];
  const signModeEl = document.getElementById('accSignatureMode');
  const signColorEl = document.getElementById('accSignColor');
  const signWidthEl = document.getElementById('accSignWidth');
  const idFile = document.getElementById('accSignFile').files[0];
  const bankFile = document.getElementById('accStampFile').files[0];
  const stampFile2 = document.getElementById('accStampFile2') ? document.getElementById('accStampFile2').files[0] : null;

  const updates = {};
  if(newName){ updates.name = newName; }
  // كلمة المرور لم تعد تُحفظ في الجدول — تُغيَّر في Supabase Auth أدناه
  updates.email = newEmail;
  updates.name_en = newNameEn;
  updates.iban = newIban;
  updates.national_id = newCivilId;
  if(idInfoFile){ updates.id_file_data = await readFileAsDataURL(idInfoFile); }
  if(bankInfoFile){ updates.bank_file_data = await readFileAsDataURL(bankInfoFile); }
  if(signModeEl){ updates.signature_mode = signModeEl.value; }
  if(signColorEl){ updates.signature_color = signColorEl.value; }
  if(signWidthEl){ updates.signature_width = parseFloat(signWidthEl.value); }
  if(idFile){ updates.signature_data = await readFileAsDataURL(idFile); }
  else if(state.pendingCanvasSignature){ updates.signature_data = state.pendingCanvasSignature; }
  if(bankFile){ updates.stamp_data = await readFileAsDataURL(bankFile); }
  if(stampFile2){ updates.stamp_data_2 = await readFileAsDataURL(stampFile2); }

  // الاعتماد الورقي يُحفظ مع بقية الحساب بزر «حفظ» نفسه
  const paperOnEl = document.getElementById('paperOn');
  if(paperOnEl){
    const pOn = !!paperOnEl.checked;
    const pIds = [...new Set([0,1,2].map(i=>(document.getElementById('paperProxy'+i)||{}).value||'').filter(Boolean))];
    if(pOn && !pIds.length){ const pc = document.getElementById('paperCard'); if(pc && pc.dataset.accsec) setAccountSec(+pc.dataset.accsec); fieldErr(document.getElementById('paperProxy0'), 'اختر مسجِّلاً واحداً على الأقل للاعتماد الورقي'); return; }
    updates.paper_approval = pOn; updates.paper_proxy_ids = pOn ? pIds : [];
    if(me.paperApproval && !pOn && !(await paperConfirmOff(me))) return;
  }
  const _paperOffIds = (paperOnEl && me.paperApproval && !updates.paper_approval) ? (me.paperProxyIds||[]).slice() : null;
  const updResult = await db.from('users').update(updates).eq('id', me.id).select('id');
  if(!(await dbCheck(updResult, 'حفظ بيانات الحساب'))) return;
  if(!updResult.data || !updResult.data.length){ showToast('لم يُحفظ شيء: لا صلاحية لتعديل هذا الحساب','error'); return; }
  if(_paperOffIds) await paperNotifyOff(me, _paperOffIds);
  if(paperOnEl){ me.paperApproval = updates.paper_approval; me.paperProxyIds = updates.paper_proxy_ids; }
  // مهلة إغلاق الدخول (عمود منفصل: إن لم يُشغَّل ملف SQL 7 بعد لا يفشل حفظ بقية البيانات)
  const idleEl = document.getElementById('accIdle');
  if(idleEl){
    let v = parseInt(idleEl.value, 10); if(!(v>0)) v = null;
    const cap = idleCapFor(state.user.role);
    if(v!==null && v<IDLE_MIN_MIN){ v = IDLE_MIN_MIN; showToast('الحد الأدنى لمهلة الإغلاق '+IDLE_MIN_MIN+' دقائق','error'); }
    if(v!==null && v>cap){ v = cap; showToast('أقصى مهلة مسموحة لدورك '+cap+' دقيقة، فضُبطت عليها','error'); }
    if((v||null) !== (state.myIdleMin||null)){
      const ir = await db.from('users').update({idle_minutes: v}).eq('id', me.id);
      if(ir.error) showToast('تعذّر حفظ مهلة الإغلاق — يلزم تشغيل ملف SQL 7 أولاً','error');
      else { state.myIdleMin = v; idleStay(); }
    }
  }

  // تغيير كلمة المرور يمرّ عبر Supabase Auth لا عبر الجدول
  if(newPass && state.impersonatingFromAdmin){ showToast('لا تُغيَّر كلمة المرور أثناء التصفح كمستخدم آخر — حُفظت بقية البيانات','error'); }
  else if(newPass){
    if(newPass.length < 6){ showToast('كلمة المرور يجب ألا تقل عن 6 خانات','error'); return; }
    const { error: pwErr } = await db.auth.updateUser({ password: newPass });
    if(pwErr){ showToast('تعذّر تغيير كلمة المرور: ' + (pwErr.message||''),'error'); return; }
  }

  if(updates.name){ me.name = updates.name; state.user.name = updates.name; }
  me.email = updates.email;
  me.nameEn = updates.name_en;
  me.iban = updates.iban;
  me.civilId = updates.national_id;
  if(updates.id_file_data) me.idFileData = updates.id_file_data;
  if(updates.bank_file_data) me.bankFileData = updates.bank_file_data;
  if(updates.signature_mode) me.signatureMode = updates.signature_mode;
  if(updates.signature_color) me.signatureColor = updates.signature_color;
  if(updates.signature_width) me.signatureWidth = updates.signature_width;
  if(updates.signature_data) me.signatureData = updates.signature_data;
  if(updates.stamp_data) me.stampData = updates.stamp_data;
  if(updates.stamp_data_2) me.stampData2 = updates.stamp_data_2;

  // سجل المستفيدين: إن كان اسمك مسجّلاً بآيبان آخر فلا يُستبدل إلا من المالية (بياناتك في حسابك حُفظت)
  const _nI = v => String(v||'').replace(/\s+/g,'').toUpperCase();
  const _m0 = state.beneficiaries.find(x=>x.name===me.name && x.companyId===state.currentCompanyId);
  const _blockMaster = !isFinanceUser() && _m0 && _m0.id && ((_m0.iban && _nI(_m0.iban)!==_nI(me.iban)) || (_m0.civilId && me.civilId && String(_m0.civilId).trim()!==me.civilId.trim()));
  if(_blockMaster) showToast('حُفظت بياناتك. اسمك مسجّل في سجل المستفيدين بآيبان آخر، وتعديله هناك للمالية.','success');
  if(me.nameEn && me.iban && !_blockMaster){
    let master = state.beneficiaries.find(x=>x.name===me.name);
    const payload = {name: me.name, name_en: me.nameEn, iban: me.iban, national_id: me.civilId||'', company_id: state.currentCompanyId};
    const mUp = await db.from('beneficiaries_master').upsert(payload, {onConflict:'company_id,name'}).select('id,company_id').maybeSingle();
    await dbCheck(mUp, 'حفظ بيانات المستفيد');
    const mId = mUp && mUp.data ? mUp.data.id : undefined;
    const mCo = mUp && mUp.data && mUp.data.company_id ? mUp.data.company_id : state.currentCompanyId;
    if(!master){
      state.beneficiaries.push({id: mId, name: me.name, nameEn: me.nameEn, iban: me.iban, civilId: me.civilId||'', idFileData: me.idFileData||'', bankFileData: me.bankFileData||'', companyId: mCo});
    } else {
      if(mId) master.id = mId; master.companyId = mCo;
      master.nameEn = me.nameEn; master.iban = me.iban;
      if(me.idFileData) master.idFileData = me.idFileData;
      if(me.bankFileData) master.bankFileData = me.bankFileData;
    }
  }

  if(state.returnTo){
    state.activeReqId = state.returnTo;
    state.returnTo = null;
    state.view = 'detail';
  } else {
    state.view = 'dashboard';
  }
  showToast('تم حفظ بياناتك', 'success');
  state.pendingCanvasSignature = null;
  render();
}

