async function confirmRejectModal(){
  const note = document.getElementById('modalRejectNote').value.trim();
  if(!note){ showToast('الرجاء كتابة سبب الرفض','error'); return; }
  const req = state.requests.find(r=>r.id===state.rejectModalReqId);
  state.rejectModalReqId = null;
  let _rejNote = note;
  if(req.status==='pending_decision'){ const _st2 = myDecisionStep(req, state.user.id); if(_st2 && _st2.approverId!==state.user.id) _rejNote = '(بالإنابة عن '+hoUserName(_st2.approverId)+') '+note; }
  const rgroup = req.status==='pending_decision' ? currentDecisionGroup(req) : [];
  const step = req.status==='pending_decision' ? (rgroup.find(s=>s.approverId===state.user.id) || myDecisionStep(req, state.user.id)) : (req.approvalSteps||[]).find(s=>s.roleLabel===req.status);
  if(req.status==='pending_decision' && !step){ showToast('لا توجد خطوة اعتماد بانتظارك في هذا الطلب. حدّث الصفحة.','error'); render(); return; }
  if(step){
    const rjR = await db.from('request_approval_steps').update({status:'rejected', acted_at:new Date().toISOString(), note}).eq('id', step.id).eq('status','pending').select('id');
    if(!(await dbCheck(rjR, 'رفض خطوتك'))){ render(); return; }
    if(!rjR.data || !rjR.data.length){ showToast('تعذّر الرفض: الخطوة لم تعد بانتظارك. حدّث الصفحة.','error'); render(); return; }
    step.status='rejected'; step.actedAt=new Date().toISOString();
    for(const o of rgroup){ if(o!==step && o.status==='pending'){ await db.from('request_approval_steps').update({status:'skipped', acted_at:new Date().toISOString()}).eq('id', o.id); o.status='skipped'; } }
  }
  const rejEntry = {step:req.status, actor: state.user.name, userId: state.user.id, action:'رفض الطلب', note:_rejNote, time: fmtDate()};
  if(!(await setRequestStatus(req, 'rejected'))){ render(); return; }
  await pushHistory(req, rejEntry);
  showToast('تم رفض الطلب', 'success');
  render();
}

