async function confirmDeletePassword(){
  const pass = document.getElementById('deleteConfirmPass').value;
  const me = state.users.find(u=>u.id===state.user.id);
  if(!pass){ showToast('أدخل كلمة المرور', 'error'); return; }
  // التحقق يتم في الخادم: إعادة مصادقة بنفس الحساب بدل مقارنة نص في المتصفح
  const { error: vErr } = await db.auth.signInWithPassword({
    email: loginIdToEmail(me.phone), password: pass
  });
  if(vErr){ qyLog('login_failed','فشل تأكيد كلمة المرور قبل حذف','', (me&&me.phone)||'');
    showToast('كلمة المرور غير صحيحة', 'error');
    return;
  }
  const {type, id} = state.pendingDelete;
  state.pendingDelete = null;
  if(type==='request') await executeDeleteRequest(id);
  else if(type==='cancel_request') await executeCancelRequest(id);
  else if(type==='center') await executeDeleteCenter(id);
  else if(type==='role') await executeDeleteCustomRole(id);
  else if(type==='user') await executeDeleteUser(id);
  else if(type==='company') await executeDeleteCompany(id);
  else if(type==='jobLevel') await performDeleteJobLevel(id);
}

