const STATUS_ORDER = {
  pending_decision: 1, pending_manager: 1, pending_senior: 1, pending_executive: 1,
  pending_transfer_request: 2, pending_accountant: 2,
  pending_transfer_approval: 3, pending_cfo: 3,
  pending_disbursement: 4, completed: 5, rejected: 6
};
// لون حالة الطلب: شريط على يمين الطلب في القوائم، ونقطة بجوار اسم الحالة في الفلتر
const REQ_CAT = {
  review:  {c:'#7c3aed', dot:'🟣', label:'قيد المراجعة'},
  decision:{c:'#d97706', dot:'🟠', label:'قيد القرار'},
  finance: {c:'#2563eb', dot:'🔵', label:'في يد المالية'},
  done:    {c:'#15803d', dot:'🟢', label:'تم الصرف'},
  rejected:{c:'#b91c1c', dot:'🔴', label:'مرفوض'},
  cancelled:{c:'#9ca3af', dot:'⚪', label:'ملغى'},
  handed:  {c:'#E8A317', dot:'🤝', label:'مسندة إليك'}
};
function reqCat(r){
  if(r.isCancelled) return 'cancelled';
  if(typeof isUnderReview==='function' && isUnderReview(r) && !['completed','rejected'].includes(r.status) && !TAIL_FLOW.includes(r.status)) return 'review';
  if(r.status==='completed') return 'done';
  if(r.status==='rejected') return 'rejected';
  if(TAIL_FLOW.includes(r.status) || ['pending_accountant','pending_cfo'].includes(r.status)) return 'finance';
  return 'decision';
}
// من أسند إليّ قراره في هذا الطلب: إسناد نشط يشمله، وقراره فيه لم يُتَّخذ بعد (لا يُعلَّم ما انتهى)
function handedFromNames(r){
  if(!state.user || r.isCancelled || ['completed','rejected'].includes(r.status)) return [];
  return delegatedFromIds(state.user.id, r.companyId, r.id)
    .filter(fid=>(r.approvalSteps||[]).some(s=>s.approverId===fid && s.status==='pending'))
    .map(fid=>hoUserName(fid));
}
// الشريط الملوّن على يمين بطاقة الطلب بلون حالته (المسنَد إليك تميّزه شارة اليدين 🤝)
function reqStripStyle(r){ return `border-right:6px solid ${REQ_CAT[reqCat(r)].c};`; }
// أزرار الفلتر: مربّع اللون والاسم والعدد، بحد أيمن بلون الحالة وحد أسفل وظل خفيف، وعرض واحد ثابت
const REQ_CAT_ICON = {review:'review', decision:'hour', finance:'bank', done:'done', rejected:'rej', cancelled:'ban', handed:'hand'};
function fbtn(k, label, n, on, act, blink, ico, boxC){
  const c = k ? REQ_CAT[k].c : (boxC || '');
  // الرمز بخط رفيع كرموز الشريط الجانبي، وبلون الحد الأيمن نفسه (لون الحالة)
  const mark = `<span class="fb-ic"${c ? ` style="color:${c};"` : ''}>${qi(k ? REQ_CAT_ICON[k] : (ico || 'all'))}</span>`;
  const tint = c ? (h=>{ const v=parseInt(h.slice(1),16); return `rgba(${v>>16&255},${v>>8&255},${v&255},.14)`; })(c) : '';
  const st = (c ? `border-right-color:${c};` : '') + (on && c ? `background:${tint};border-color:${c};` : '');
  const dis = !on && n===0;
  return `<button type="button" class="fb${k?'':' fb-neu'}${on?' on':''}${on && !k && c ? ' fb-tint' : ''}${blink?' fb-blink':''}" style="${st}" ${dis?'disabled':''} ${qon('click', act)} title="${escH(dis ? 'لا توجد طلبات بهذه الحالة' : on ? 'اضغط مرة أخرى لإلغاء هذا الاختيار' : 'اعرض '+label+' فقط')}">${mark}<span class="fb-l">${escH(label)}</span><span class="fb-n">${Number(n).toLocaleString('en')}</span></button>`;
}
// عرض واحد لكل أزرار الصف: يُقاس أطول زر بعدد من خمس خانات، ويُزاد 10٪
function fitFilterButtons(){
  const app = document.getElementById('app'); if(!app) return;
  const bs = [...app.querySelectorAll('.fb:not(.fb-sel)')]; if(!bs.length) return;
  app.style.setProperty('--fbw', 'auto');
  const saved = bs.map(b=>{ const n = b.querySelector('.fb-n'); const t = n ? n.textContent : ''; if(n) n.textContent = '99,999'; return t; });
  const w = Math.ceil(Math.max(...bs.map(b=>b.getBoundingClientRect().width)) * 1.1);
  bs.forEach((b,i)=>{ const n = b.querySelector('.fb-n'); if(n) n.textContent = saved[i]; });
  if(w>0) app.style.setProperty('--fbw', w+'px');
}
function dashAll(){ state.dashOwner = 'all'; state.dashStatusFilter = 'all'; render(); }
function dashToggleMine(){ state.dashOwner = (state.dashOwner==='mine') ? 'all' : 'mine'; state.dashStatusFilter = 'all'; render(); }   // كل زر يعمل وحده: اختياره يلغي غيره، وإطفاؤه يعيد «الكل»
function dashToggleCat(k){ state.dashStatusFilter = (state.dashStatusFilter===k) ? 'all' : k; state.dashOwner = 'all'; render(); }
function dashPickOwner(v){ state.dashOwner = v || 'all'; state.dashStatusFilter = 'all'; render(); }
function statusLegendHtml_unused(){
  return `<div class="status-legend no-print">${['review','decision','finance','done','rejected','cancelled','handed'].map(k=>`<span><i style="background:${REQ_CAT[k].c};"></i>${REQ_CAT[k].label}</span>`).join('')}</div>`;
}
function statusBadge(status, isCancelled, isOwnTurn, isBig, overdue){
  if(isCancelled) return `<span class="badge" style="background:#E3E0D6;color:#56554F;">ملغى</span>`;
  if(status==='completed') return `<span class="badge badge-paid">تم الصرف</span>`;
  if(status==='rejected') return `<span class="badge badge-rejected" title="مرفوض: يحتاج تعديلًا ثم إعادة إرسال" style="white-space:nowrap;">مرفوض</span>`;
  const role = STATUS_ROLE_MAP[status];
  if(!isOwnTurn && TAIL_FLOW.includes(status)){
    return `<span class="badge badge-pending${isBig ? ' badge-own-turn' : ''}" title="اكتمل اعتماد القرار — بانتظار ${role ? findRole(role).name : ''}">جارٍ الصرف</span>`;
  }
  const label = isOwnTurn ? (overdue ? '⏰ بانتظار قرارك' : 'بانتظار قرارك') : `بانتظار ${role ? findRole(role).name : ''}`;
  return `<span class="badge badge-pending${(isOwnTurn || isBig) ? ' badge-own-turn' : ''}${overdue ? ' badge-overdue' : ''}" ${overdue ? 'title="متأخر: تجاوز مهلة الاعتماد"' : ''}>${label}</span>`;
}

function getImageDims(dataUrl){
  return new Promise(resolve=>{
    const img = new Image();
    img.onload = ()=> resolve({w: img.naturalWidth||1, h: img.naturalHeight||1});
    img.onerror = ()=> resolve({w:1, h:1});
    img.src = dataUrl;
  });
}
// يفتح معاينة الطلب ثم يطلق مباشرة نافذة الطباعة/الحفظ كـPDF، لمن يريد الملف مباشرة بلا توقف عند المعاينة
async function downloadRequestPdf(reqId){
  await openPrintPreview(reqId, true);   // الطباعة تنتظر اكتمال المرفقات
  setTimeout(()=>window.print(), 150);
}
async function qyMeasureImages(list){
  state.attachmentDims = state.attachmentDims || {};
  const toMeasure = list.filter(src=>!state.attachmentDims[src]);
  if(toMeasure.length){
    const results = await Promise.all(toMeasure.map(getImageDims));
    toMeasure.forEach((src,idx)=>{ state.attachmentDims[src] = results[idx]; });
  }
}
async function openPrintPreview(reqId, wait){
  const req = state.requests.find(r=>r.id===reqId);
  const images = [];
  if(req){
    req.beneficiaries.forEach(b=>{
      const master = state.beneficiaries.find(x=>x.name===b.name);
      if(master){
        if(master.idFileData) images.push(master.idFileData);
        if(master.bankFileData) images.push(master.bankFileData);
      }
    });
    state.attPrint = state.attPrint || {};
    const loadNew = async ()=>{
      try{ state.attPrint[reqId] = await attCollectForRequest(req); }catch(e){ state.attPrint[reqId] = []; showToast('تعذّر تجهيز المرفقات الجديدة للطباعة','error'); }
      await qyMeasureImages(state.attPrint[reqId].map(x=>x.img));
    };
    if(wait){ await loadNew(); }
    else {
      // المعاينة تُفتح فوراً بما هو جاهز؛ المرفقات الجديدة تُحمَّل بالخلفية ثم تُضاف
      state.attPrint[reqId] = state.attPrint[reqId] || [];
      loadNew().then(()=>{ if(state.view==='printPreview' && state.activeReqId===reqId) render(); });
    }
    state.attPrint[reqId].forEach(x=>images.push(x.img));
  }
  await qyMeasureImages(images);
  state.activeReqId = reqId;
  state.view = 'printPreview';
  render();
}

const ROLE_TO_STEP = {dept_manager:'pending_manager', senior_manager:'pending_senior', executive_manager:'pending_executive', accountant:'pending_accountant', cfo:'pending_cfo'};

function generateQRSvg(text, sizePx){
  try{
    if(typeof qrcode==='undefined') return '';
    let qr = null;
    for(let tn=4; tn<=40 && !qr; tn+=2){
      try{
        const candidate = qrcode(tn, 'L');
        candidate.addData(text);
        candidate.make();
        qr = candidate;
      }catch(innerErr){ qr = null; }
    }
    if(!qr) return '';
    const count = qr.getModuleCount();
    const cellSize = sizePx / count;
    let rects = '';
    for(let r=0;r<count;r++){
      for(let c=0;c<count;c++){
        if(qr.isDark(r,c)){
          rects += `<rect x="${(c*cellSize).toFixed(2)}" y="${(r*cellSize).toFixed(2)}" width="${(cellSize+0.5).toFixed(2)}" height="${(cellSize+0.5).toFixed(2)}"/>`;
        }
      }
    }
    return `<svg viewBox="0 0 ${sizePx} ${sizePx}" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:100%;shape-rendering:crispEdges;"><rect width="100%" height="100%" fill="#fff"/><g fill="#111">${rects}</g></svg>`;
  }catch(e){
    console.error('تعذر توليد رمز QR', e);
    return '';
  }
}
function renderRequestQRCode(req, extraClass){
  try{
  // الرابط يُبنى من عنوان الموقع الحالي، فيفتح QR النسخة التجريبية صفحة التحقق التجريبية، والحقيقية للحقيقية
  const verifyUrl = location.origin + location.pathname + '?verify=' + encodeURIComponent(req.verifyCode || req.id);
  const svg = generateQRSvg(verifyUrl, 200);
  if(!svg) return '';
  return `
    <div class="request-qr-block${extraClass ? ' '+extraClass : ''}">
      <div class="request-qr-row">
        <a href="${verifyUrl}" target="_blank" rel="noopener" style="display:block;cursor:pointer;text-decoration:none;" title="انقر لفتح صفحة التحقق من السند">
          <div class="request-qr-img">${svg}</div>
        </a>
        ${req.verifyCode ? `<div class="request-qr-code" dir="ltr">${escH(req.verifyCode)}</div>` : ''}
      </div>
      <div class="request-qr-hint">اضغط للتحقق</div>
    </div>`;
  }catch(e){
    console.error('تعذر عرض رمز QR', e);
    return '';
  }
}
// آخر اعتماد نفّذه فعلياً مستخدم بهذا الدور — تُستخدم لصناديق مدير الإدارة/الأعلى/التنفيذي (مسار القرار متغيّر الطول،
// ولا يوجد اسم خطوة فريد لكل منهم بالمحرك الجديد، فلازم نطابق بالدور الفعلي بدلاً من اسم الخطوة)
function findApprovalEntryForRole(req, role){
  const matches = req.history.filter(h=>{
    if(h.action!=='اعتماد') return false;
    const u = state.users.find(x=>x.id===h.userId);
    return u && u.role===role;
  });
  return matches.length ? matches[matches.length-1] : null;
}
// لصندوقي المحاسب (طلب التحويل) والمدير المالي (اعتماد التحويل): نطابق باسم الخطوة الثابت نفسه لا بالدور،
// لأن المحاسب وقت يكون مفوَّضاً ينفّذ الخطوتين معاً بدوره الحقيقي (محاسب) على التوالي
function findApprovalEntryForBox(req, role){
  if(role==='accountant') return req.history.find(h=>h.step==='pending_transfer_request' && h.action==='اعتماد') || null;
  if(role==='cfo') return req.history.find(h=>h.step==='pending_transfer_approval' && h.action==='اعتماد') || null;
  return findApprovalEntryForRole(req, role);
}
function renderSignatureArea(req){
  if(useSeqSigs(req)) return renderSeqSignatures(req, 'final');
  const PX_TO_MM = 0.25;
  const boxesHtml = SIG_DESIGNER_ROLES.map(role=>{
    const approveEntry = findApprovalEntryForBox(req, role);
    if(!approveEntry) return '';
    const user = state.users.find(u=>u.id===approveEntry.userId);
    const roleTitle = (role==='cfo' && approveEntry.note==='بالتفويض عن المدير المالي') ? findRole(role).name+' (بالتفويض)' : findRole(role).name;
    const cfg = (state.sigLayoutConfigs && state.sigLayoutConfigs.final && state.sigLayoutConfigs.final[role] && Object.keys(state.sigLayoutConfigs.final[role]).length)
      ? state.sigLayoutConfigs.final[role] : defaultSigDesignerConfig(role, 'final');
    const sigImg = approveEntry.signatureOverride || (user && user.signatureData) || '';
    const stampImg = user && user.stampData ? user.stampData : '';

    let out = '';
    if(cfg.name && cfg.name.visible){
      out += `<div style="position:absolute;left:${cfg.name.x*PX_TO_MM}mm;top:${cfg.name.y*PX_TO_MM}mm;width:${cfg.name.w*PX_TO_MM}mm;height:${cfg.name.h*PX_TO_MM}mm;display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:${cfg.name.fontSize||14}px;" class="sign-name">${escH(approveEntry.actor)}</div>`;
    }
    if(cfg.title && cfg.title.visible){
      out += `<div style="position:absolute;left:${cfg.title.x*PX_TO_MM}mm;top:${cfg.title.y*PX_TO_MM}mm;width:${cfg.title.w*PX_TO_MM}mm;height:${cfg.title.h*PX_TO_MM}mm;display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:${cfg.title.fontSize||14}px;" class="sign-role-title">${escH(roleTitle)}</div>`;
    }
    if(cfg.date && cfg.date.visible){
      out += `<div style="position:absolute;left:${cfg.date.x*PX_TO_MM}mm;top:${cfg.date.y*PX_TO_MM}mm;width:${cfg.date.w*PX_TO_MM}mm;height:${cfg.date.h*PX_TO_MM}mm;display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:${cfg.date.fontSize||10}px;color:var(--muted);">${toWesternDigits(approveEntry.time)||''}</div>`;
    }
    if(cfg.signature && cfg.signature.visible && sigImg){
      out += `<div style="position:absolute;left:${cfg.signature.x*PX_TO_MM}mm;top:${cfg.signature.y*PX_TO_MM}mm;width:${cfg.signature.w*PX_TO_MM}mm;height:${cfg.signature.h*PX_TO_MM}mm;display:flex;align-items:center;justify-content:center;overflow:hidden;"><img src="${escH(sigImg)}" style="max-width:100%;max-height:100%;object-fit:contain;"></div>`;
    }
    if(cfg.stamp && cfg.stamp.visible && stampImg){
      out += `<div style="position:absolute;left:${cfg.stamp.x*PX_TO_MM}mm;top:${cfg.stamp.y*PX_TO_MM}mm;width:${cfg.stamp.w*PX_TO_MM}mm;height:${cfg.stamp.h*PX_TO_MM}mm;display:flex;align-items:center;justify-content:center;overflow:hidden;"><img src="${escH(stampImg)}" style="max-width:100%;max-height:100%;object-fit:contain;"></div>`;
    }
    return out;
  }).join('');
  if(!boxesHtml) return '';

  return `<div class="sign-final-block-v2">${boxesHtml}</div>`;
}

