const AMOUNT_TABLE_COLGROUP = `
  <colgroup>
    <col style="width:4%;"><col style="width:26%;"><col style="width:28%;">
    <col style="width:13%;"><col style="width:14%;"><col style="width:15%;">
  </colgroup>`;

function buildAmountTableHeader(benLabel){
  return `
    <table class="amount-table amount-table-head">
      ${AMOUNT_TABLE_COLGROUP}
      <thead><tr><th>#</th><th>${benLabel||'المستفيد'}</th><th>البيان / رقم الهوية / الآيبان</th><th>المبلغ</th><th>ملاحظات</th><th>الإجمالي</th></tr></thead>
    </table>`;
}

function buildBeneficiaryTable(b, i){
  const net = b.amount - (b.deduction||0) + (b.extra||0);
  const ibanClean = (b.iban||'').replace(/\s+/g,'');
  const rowCount = 1 + (b.deduction>0?1:0) + (b.extra>0?1:0);
  const altClass = (i%2===1) ? ' row-alt' : '';
  const extraRows = [];
  if(b.deduction>0){
    const isLast = !(b.extra>0);
    extraRows.push(`
    <tr class="sub-row${isLast?' sub-row-last':''}${altClass}">
      <td style="color:var(--doc-red);"><div class="amt-signed"><span class="amt-number" dir="ltr">-${fmtKWDHtml(b.deduction)}</span></div></td>
      <td class="cell-right" style="color:var(--doc-red);">خصم${b.deductionNote ? ' ' + escH(b.deductionNote) : ''}</td>
    </tr>`);
  }
  if(b.extra>0){
    extraRows.push(`
    <tr class="sub-row sub-row-last${altClass}">
      <td style="color:var(--green);"><div class="amt-signed"><span class="amt-number" dir="ltr">+${fmtKWDHtml(b.extra)}</span></div></td>
      <td class="cell-right" style="color:var(--green);">إضافي${b.extraNote ? ' ' + escH(b.extraNote) : ''}</td>
    </tr>`);
  }
  const mainBorder = rowCount>1 ? 'border-bottom:none;padding-bottom:0;' : '';
  const rowsHtml = `
    <tr class="${altClass.trim()}">
      <td class="num" rowspan="${rowCount}">${i+1}</td>
      <td rowspan="${rowCount}">
        <div class="cell-right">${escH(b.name)}</div>
        ${b.nameEn ? `<div class="cell-left">${escH(b.nameEn)}</div>` : ''}
      </td>
      <td rowspan="${rowCount}">
        <div class="cell-right">${escH(b.statement || '—')}</div>
        <div class="cell-left" style="font-size:10px;">${escH(b.civilId || '—')}</div>
        <div class="cell-left" style="font-size:10px;word-break:break-all;">${escH(ibanClean || '—')}</div>
      </td>
      <td style="${mainBorder}"><div class="amt-signed"><span class="amt-number" dir="ltr">${fmtKWDHtml(b.amount)}</span></div></td>
      <td class="cell-right" style="${mainBorder}">${escH(b.notes || '')}</td>
      <td rowspan="${rowCount}" style="font-weight:700;"><div class="amt-signed"><span class="amt-number" dir="ltr" style="width:70px;">${fmtKWDHtml(net)}</span></div></td>
    </tr>${extraRows.join('')}`;
  return `
    <table class="amount-table amount-table-bene" data-bene-index="${i}">
      ${AMOUNT_TABLE_COLGROUP}
      <tbody>${rowsHtml}</tbody>
    </table>`;
}

function buildBeneficiaryTables(beneficiaries, startIndex){
  return beneficiaries.map((b,idx)=> buildBeneficiaryTable(b, startIndex+idx)).join('');
}

function mmToPx(mm){
  const ref = document.createElement('div');
  ref.style.cssText = `position:absolute;visibility:hidden;height:${mm}mm;width:0;`;
  document.body.appendChild(ref);
  const px = ref.getBoundingClientRect().height;
  document.body.removeChild(ref);
  return px;
}

function measureAndPaginateBeneficiaries(req, headerHtml, footerHtml, signatureOverlayHtml){
  const LETTERHEAD_TOP_MM = 33.5;
  const LETTERHEAD_BOTTOM_MM = 70; // محجوزة لتفادي تداخل تدفق المحتوى مع طبقة التوقيعات العلوية (overlay) المثبّتة بأسفل الصفحة بارتفاع 70مم
  const PAGE_HEIGHT_MM = 297;
  const CONTENT_WIDTH_MM = 200;

  try{
    const maxContentPx = mmToPx(PAGE_HEIGHT_MM - LETTERHEAD_TOP_MM - LETTERHEAD_BOTTOM_MM);

    const measureDiv = document.createElement('div');
    measureDiv.className = 'print-measure';
    measureDiv.style.cssText = `position:absolute;visibility:hidden;top:-9999px;left:-9999px;width:${CONTENT_WIDTH_MM}mm;font-family:'Times New Roman', Times, serif;`;
    document.body.appendChild(measureDiv);

    measureDiv.innerHTML = headerHtml;
    const headerPx = measureDiv.getBoundingClientRect().height;

    measureDiv.innerHTML = footerHtml;
    const footerPx = measureDiv.getBoundingClientRect().height;

    const continuationLineHtml = '<p class="doc-body-text" style="margin-top:0;font-weight:700;">تابع جدول المستفيدين:</p>';
    measureDiv.innerHTML = continuationLineHtml;
    const continuationPx = measureDiv.getBoundingClientRect().height;

    measureDiv.innerHTML = buildAmountTableHeader();
    const theadPx = measureDiv.getBoundingClientRect().height;

    // كل مستفيد الآن جدول مستقل بحد ذاته، فقياس ارتفاعه مباشر وبسيط بدون تعقيد rowspan
    const groupHeights = req.beneficiaries.map((b,i)=>{
      measureDiv.innerHTML = buildBeneficiaryTable(b, i);
      return measureDiv.getBoundingClientRect().height;
    });

    document.body.removeChild(measureDiv);

    const chunks = [];
    let currentChunk = [];
    let used = headerPx + theadPx;
    req.beneficiaries.forEach((b,i)=>{
      const h = groupHeights[i] || 0;
      if(used + h > maxContentPx && currentChunk.length>0){
        chunks.push(currentChunk);
        currentChunk = [];
        used = continuationPx + theadPx;
      }
      currentChunk.push(b);
      used += h;
    });
    if(currentChunk.length>0 || chunks.length===0) chunks.push(currentChunk);

    if(used + footerPx > maxContentPx){
      const lastChunk = chunks[chunks.length-1];
      if(lastChunk && lastChunk.length>1){
        // اسحب آخر مستفيد من الصفحة الأخيرة ليرافق الإجمالي والتوقيعات بالصفحة الجديدة
        // (بدل ما تكون صفحة فاضية تماماً من أي مستفيد)
        const pulled = lastChunk.pop();
        chunks.push([pulled]);
      } else {
        chunks.push([]);
      }
    }
    return chunks;
  }catch(e){
    console.error('تعذر قياس تقسيم الصفحات، استخدام التقسيم الاحتياطي', e);
    const MAX_PER_PAGE = 10;
    const MAX_LAST_PAGE = 5;
    const fallback = [];
    for(let idx=0; idx<req.beneficiaries.length; idx+=MAX_PER_PAGE){
      fallback.push(req.beneficiaries.slice(idx, idx+MAX_PER_PAGE));
    }
    if(fallback.length===0) fallback.push([]);
    if(fallback[fallback.length-1].length > MAX_LAST_PAGE){
      fallback.push([]);
    }
    return fallback;
  }
}

function renderLetterPages(req){
  const docCompany = state.companies.find(c=>c.id===req.companyId);
  // ورقة «طلب صرف عهدة»: العنوان والنص باسم صاحبها وغرضها وموعد تسويتها، والجدول نفسه (بلا خصم ولا إضافي)
  const isCus = req.requestType==='custody';
  const kc = isCus ? custodyOf(req) : null;
  const cusHolder = isCus ? ((kc && (userById(kc.holderId)||{}).name) || ((req.beneficiaries||[])[0]||{}).name || '') : '';
  const cusDue = kc ? kc.dueCloseAt : '';
  const salutationText = req.salutationText || (docCompany ? docCompany.salutationText : 'الإخوة / الإدارة المالية');
  const referenceText = req.referenceText || (docCompany ? docCompany.referenceText : 'بالإشارة إلى الموضوع أعلاه');

  const header = `
    <div class="doc-date" dir="ltr">
      <div>${req.dateHijri||''}</div>
      <div>${dmyStr(req.dateGreg||'')}</div>
    </div>
    <div class="doc-salutation">
      <span>${salutationText}</span>
      <span class="mohtaramin">المحترمين</span>
    </div>
    <div style="display:flex;justify-content:space-between;align-items:baseline;">
      <p class="doc-greeting" style="margin:0;padding-right:0;">تحية طيبة وبعد،...</p>
      <span class="doc-red" style="font-size:14px;font-weight:600;text-decoration:underline;">رقم الطلب: ${req.number || '— قيد المراجعة —'}</span>
    </div>
    <div class="doc-subject-bar" style="margin-top:4px;">${isCus ? 'طلب صرف عهدة' : 'طلب صرف'} – <span>${escH(req.reason)}</span></div>
    <div style="margin-top:4px;font-size:13px;">بند الصرف: <b>${requestBudgetName(req) ? escH(requestBudgetName(req)) : 'غير محدد'}</b></div>
    ${isCus
      ? `<p class="doc-body-text" style="margin-top:4px;">بالإشارة إلى الموضوع أعلاه، يرجى التكرم بالموافقة على صرف عهدة مالية باسم <span class="doc-red">${escH(cusHolder)}</span> لغرض <span class="doc-red">${escH(req.detailedReason || req.reason)}</span>${cusDue ? `، على أن تُسوّى بالفواتير في موعد أقصاه <span class="doc-red">${fmtDateDMY(cusDue)}</span>` : ''}، وفق الجدول الآتي:</p>`
      : `<p class="doc-body-text" style="margin-top:4px;">بالإشارة إلى الموضوع أعلاه، ${referenceText} <span class="doc-red">${escH(req.detailedReason || req.reason)}</span> وفق الجدول الآتي:</p>`}`;

  const footer = `
    <div class="app-total-box">
      <span style="font-size:13px;font-weight:600;">${amountToArabicWords(req.totalAmount)}</span>
      <span>الإجمالي: ${fmtKWDHtml(req.totalAmount)} د.ك</span>
    </div>
    <p class="doc-closing">وتفضلوا بقبول فائق التحية والتقدير ،،،،،</p>`;
  const signatureOverlay = renderSignatureArea(req);

  const chunks = measureAndPaginateBeneficiaries(req, header, footer, signatureOverlay);

  let offset = 0;
  const pages = chunks.map((chunk, idx)=>{
    const tablesHtml = buildBeneficiaryTables(chunk, offset);
    offset += chunk.length;
    const isFirst = idx===0;
    const isLast = idx===chunks.length-1;
    const isEmptyFooterPage = chunk.length===0;
    if(isEmptyFooterPage){
      return `<div style="min-height:20mm;"></div>${footer}${signatureOverlay}`;
    }
    return `
      ${isFirst ? header : `<p class="doc-body-text" style="margin-top:0;font-weight:700;">تابع جدول المستفيدين:</p>`}
      ${buildAmountTableHeader(isCus ? 'صاحب العهدة' : '')}
      ${tablesHtml}
      ${isLast ? footer+signatureOverlay : `${renderMiniSignatureRow(req)}<p class="doc-body-text continuation-note">▼ تتمة تفاصيل الطلب بالصفحة التالية</p>`}`;
  });
  return pages;
}
function renderLetterBody(req){
  return renderLetterPages(req).join('');
}

function renderPrintPreview(app){
  const req = state.requests.find(r=>r.id===state.activeReqId);

  const reqCompany = state.companies.find(c=>c.id===req.companyId);
  let letterhead = (reqCompany && reqCompany.logoData) ? reqCompany.logoData : LETTERHEAD_IMG;
  if(req.origin==='center' && req.centerId){
    const lhUnit = effectiveLetterheadUnit(req.centerId);   // الوحدة أو أقرب وحدة أم لها ترويسة
    if(lhUnit) letterhead = lhUnit.letterheadData;
  }

  const attachmentImages = [];
  req.beneficiaries.forEach(b=>{
    const master = state.beneficiaries.find(x=>x.name===b.name);
    if(master){
      if(master.idFileData) attachmentImages.push({name:b.name, img:master.idFileData});
      if(master.bankFileData) attachmentImages.push({name:b.name, img:master.bankFileData});
    }
  });
  ((state.attPrint||{})[req.id]||[]).forEach(x=>attachmentImages.push(x));

  const letterPages = renderLetterPages(req);

  const USABLE_W_MM = 189.68, USABLE_H_MM = 276.68, TITLE_RESERVE_MM = 10;
  const PX_TO_MM = 25.4 / 96;
  const dims = state.attachmentDims || {};
  const items = attachmentImages.map(a=>{
    const d = dims[a.img] || {w:1,h:1};
    let wMM = d.w * PX_TO_MM, hMM = d.h * PX_TO_MM;
    if(wMM > USABLE_W_MM){ hMM = hMM * (USABLE_W_MM / wMM); wMM = USABLE_W_MM; }
    if(hMM > USABLE_H_MM){ wMM = wMM * (USABLE_H_MM / hMM); hMM = USABLE_H_MM; }
    const dispH = hMM + TITLE_RESERVE_MM;
    return {...a, wMM, hMM, dispH};
  });
  const attachmentChunks = [];
  let curChunk = [], curH = 0;
  items.forEach(item=>{
    if(curH + item.dispH > USABLE_H_MM && curChunk.length>0){
      attachmentChunks.push(curChunk); curChunk = []; curH = 0;
    }
    curChunk.push(item); curH += item.dispH;
  });
  if(curChunk.length) attachmentChunks.push(curChunk);

  const cancelledWatermark = req.isCancelled ? `<div class="print-watermark" style="top:18%">ملغى</div><div class="print-watermark" style="top:50%">ملغى</div><div class="print-watermark" style="top:82%">ملغى</div>` : '';

  const totalPages = letterPages.length + attachmentChunks.length;
  const footerSpec = printFooterSpec(req);
  const mainContentHtml = letterPages.map((pageHtml, idx)=>`
    <div class="doc-page with-letterhead" style="background-image:url('${escH(String(letterhead||'').replace(/['\\]/g,''))}')">
      ${cancelledWatermark}
      ${pageHtml}
      ${renderRequestQRCode(req)}
      ${footerHtml(footerSpec, idx+1, totalPages)}
    </div>`).join('');

  const attachmentPages = attachmentChunks.map((chunk,i)=>`
    <div class="doc-page attachment-page attachment-flow-page">
      ${chunk.map(a=>`
        <div class="attachment-flow-block">
          <div class="attachment-title">${/^ورقة (الاعتماد|الرفض) الورقي/.test(a.label||'') ? 'مرفقات '+((a.label||'').indexOf('الرفض')>-1?'الرفض':'الاعتماد')+' الورقي لـ '+escH(a.name)+' — '+escH((a.label||'').replace(/^[^—]*— /,'')) : 'مرفقات المستفيد: '+escH(a.name)+(a.label?' — '+escH(a.label):'')}</div>
          <img src="${escH(safeDataUrl(a.img))}" style="width:${a.wMM.toFixed(1)}mm;height:${a.hMM.toFixed(1)}mm;cursor:zoom-in;" data-on-click="openFilePreviewModal" data-on-click-args="${qa([qs(a.img), qs('مرفق '+a.name)])}">
        </div>
      `).join('')}
      ${footerHtml(footerSpec, i+1, attachmentChunks.length, 'مرفقات — ')}
    </div>`).join('');

  app.innerHTML = `
    <p class="sub no-print">هذه معاينة مطابقة تماماً للصفحات التي ستُطبع أو تُحفظ كملف PDF (${totalPages} صفحة). يمكن تحميل أي مرفق بالضغط عليه ثم زر "تحميل" بالنافذة اللي تفتح.</p>
    <div class="pv-zoom">
      <div class="doc-pages-wrap">
        ${mainContentHtml}
      </div>
      ${attachmentPages}
    </div>
  `;
}
// الورقة A4 كما هي (210 مم) مكبّرة أو مصغّرة بنسبتها لتطابق عرض صفحة الطلب (920) أو المساحة المتاحة إن ضاقت
const DOC_BOX_W = 920;
function fitPreviewZoom(){
  const z = document.querySelector('#app .pv-zoom'); if(!z) return;
  const app = document.getElementById('app'); const cs = getComputedStyle(app);
  const avail = app.clientWidth - (parseFloat(cs.paddingLeft)||0) - (parseFloat(cs.paddingRight)||0);
  const pageW = 210 * 96 / 25.4;
  const target = Math.max(260, Math.min(avail, DOC_BOX_W));
  z.style.zoom = (target / pageW).toFixed(4);
}

// ===== سجل التنقل: زر «رجوع» يعيد إلى الصفحة التي جئت منها فعلاً =====
function navSnap(){ return {view:state.view, activeReqId:state.activeReqId, adminSubTab:state.adminSubTab}; }
function navKey(x){ return x.view+'|'+((x.view==='detail'||x.view==='printPreview')?x.activeReqId:'')+'|'+(x.view==='admin'?x.adminSubTab:''); }
function navTrack(){
  const cur = navSnap(), prev = state._navPrev;
  if(prev && navKey(prev)!==navKey(cur)){
    if(prev.view==='admin' && cur.view!=='admin'){ state.editingUserId=null; state.editingCompanyId=null; state.editingCenterId=null; }   // صندوق التعديل لا يبقى مفتوحاً بعد مغادرة الإدارة
    if(!state._navPopping && prev.view!=='login' && cur.view!=='login'){
      prev.scrollY = window.scrollY;
      (state._navStack = state._navStack||[]).push(prev);
      if(state._navStack.length>30) state._navStack.shift();
      qyHistPush();
    }
  }
  state._navPopping = false;
  state._navPrev = cur;
}
function navBack(fallback){
  const st = state._navStack || [];
  const here = navKey(navSnap());
  let t = st.pop();
  while(t && (navKey(t)===here || t.view==='newRequest' || t.view==='login' || (t.view==='detail' && !state.requests.some(r=>r.id===t.activeReqId)))) t = st.pop();
  qyHistPopSilently();
  state._navPopping = true;
  if(t){ state.view=t.view; state.activeReqId=t.activeReqId; if(t.adminSubTab) state.adminSubTab=t.adminSubTab; }
  else state.view = fallback || 'dashboard';
  render();
  const y = t ? (t.scrollY||0) : 0;
  setTimeout(()=>window.scrollTo(0,y), 0);
}
function navCanGoBack(){
  if(state.view!=='dashboard') return true;
  return (state._navStack||[]).some(t=>navKey(t)!==navKey(navSnap()) && t.view!=='login');
}
function navFormDirty(){
  if(state.view!=='newRequest' && state.view!=='newCustody') return false;
  return Array.from(document.querySelectorAll('#app input:not([type=hidden]):not([type=checkbox]):not([type=radio]):not([type=date]):not([readonly]),#app textarea')).some(e=>String(e.value||'').trim()!=='');
}
function navBackSafe(){
  if(navCloseOverlay()) return true;
  if(!navCanGoBack()) { showToast('أنت في الصفحة الرئيسية','info'); return false; }
  if(navFormDirty() && !confirm('عندك بيانات مكتوبة في هذه الصفحة.\n\nهل تريد الرجوع وتجاهلها؟')) return false;
  navBack('dashboard');
  return true;
}
// نافذة مفتوحة (معاينة ملف، مرفقات، رفض…): زر الرجوع يغلقها أولاً بدل مغادرة الصفحة
function navCloseOverlay(){
  const keys=['filePreviewModal','cusDocs','attModal','rejectModalReqId','pendingDelete','suspendCheck','manualSignReqId','transferFormReqId'];
  const sh = document.querySelector('.mtab-sheet'); if(sh){ sh.remove(); return true; }
  if(state.navDrawer || document.body.classList.contains('nav-drawer-open')){ closeNavDrawer(); return true; }
  if(state.cusPathOpen && isPhone()){ cusPathToggle(); return true; }
  const k=keys.find(x=>state[x]);
  if(!k) return false;
  state[k]=null; render(); return true;
}
// زر الرجوع في الهاتف/المتصفح (والتطبيق المثبّت): سجل المتصفح يطابق سجل التنقل داخل النظام إدخالاً بإدخال.
// كل انتقال للأمام يضيف إدخالاً {qyDepth: عمق السجل}، وكل رجوع داخل النظام يسحب إدخالاً، فيبقى العدّان متطابقين:
// يرجع خطوة بعد خطوة لصفحات النظام، وعند الصفحة الرئيسية يبقى فيها (إدخال حارس واحد في القاع) بدل إغلاق التطبيق.
const qyHist = {armed:false, skip:0, fromPop:false};
function qyHistArm(){
  if(qyHist.armed) return; qyHist.armed = true;
  try{ history.replaceState({qyRoot:1},''); history.pushState({qyDepth:(state._navStack||[]).length},''); }catch(e){}
}
['pointerdown','keydown','touchstart'].forEach(ev=>document.addEventListener(ev,qyHistArm,{once:true,capture:true,passive:true}));
function qyHistPush(){ if(!qyHist.armed) return; try{ history.pushState({qyDepth:(state._navStack||[]).length},''); }catch(e){} }
function qyHistPopSilently(){ if(!qyHist.armed || qyHist.fromPop) return; const d = history.state && history.state.qyDepth; if(typeof d==='number' && d>0){ qyHist.skip++; try{ history.back(); }catch(e){ qyHist.skip--; } } }
window.addEventListener('popstate',ev=>{
  if(qyHist.skip>0){ qyHist.skip--; return; }
  if(!qyHist.armed || !state.user || state.view==='login') return;
  const st = ev.state || {};
  const len = (state._navStack||[]).length;
  if(st.qyRoot){   // ضغط رجوع وهو في الصفحة الرئيسية: يبقى فيها
    try{ history.pushState({qyDepth:len},''); }catch(e){}
    if(!navCloseOverlay() && state.view!=='dashboard'){ state.view='dashboard'; render(); }
    return;
  }
  const d = typeof st.qyDepth==='number' ? st.qyDepth : 0;
  if(d > len){ try{ history.go(len - d); }catch(e){} return; }   // إدخالات زائدة قديمة: نتخطّاها
  if(navCloseOverlay()){ try{ history.pushState({qyDepth:len},''); }catch(e){} return; }   // أُغلقت نافذة فقط: نعيد الإدخال
  if(navFormDirty() && !confirm('عندك بيانات مكتوبة في هذه الصفحة.\n\nهل تريد الرجوع وتجاهلها؟')){ try{ history.pushState({qyDepth:len},''); }catch(e){} return; }
  qyHist.fromPop = true;
  try{ while((state._navStack||[]).length > d && (state._navStack||[]).length>0){ const before=(state._navStack||[]).length; navBack('dashboard'); if((state._navStack||[]).length>=before) break; } } finally { qyHist.fromPop = false; }
});
// إعادة الرسم داخل الصفحة نفسها (اختيار، علامة، حفظ) لا تحرّك الصفحة — تبقى حيث كان المستخدم
(function(){ const o = window.scrollTo.bind(window); window._qyScrollTo = o; window.scrollTo = function(){ window._qyScrollAt = Date.now(); return o.apply(window, arguments); };
  const si = Element.prototype.scrollIntoView; Element.prototype.scrollIntoView = function(){ window._qyScrollAt = Date.now(); return si.apply(this, arguments); }; })();
function render(){
  window._qyInRender = true; queueMicrotask(()=>{ window._qyInRender = false; });
  const _sy = window.scrollY, _sk = [state.view, state.adminSubTab, state.activeReqId, state.activeCustodyId, state.cusDocs ? 1 : 0].join('|'), _same = state._sk===_sk; state._sk = _sk;
  { const pv = state.view+'|'+state.activeReqId+'|'+state.activeCustodyId; if(state._pv!==pv){
    // الدخول إلى صفحة الطلبات من صفحة أخرى: من عنده طلبات تنتظر قراره يرى «بانتظار قرارك» مختاراً أولاً
    const fromV = (state._pv||'').split('|')[0];
    if(state.view==='dashboard' && !['dashboard','detail','printPreview'].includes(fromV) && state.user && typeof getMyPendingRequests==='function' && getMyPendingRequests().length && (!state.dashStatusFilter || state.dashStatusFilter==='all') && (state.dashOwner||'all')==='all') state.dashStatusFilter = 'mypending';
    state._pv = pv; state.cusPathOpen = false; } }
  if(state.pendingEscalate && state.pendingEscalate.reqId!==state.activeReqId) state.pendingEscalate = null;
  if(state.user && !viewAllowed(state.view)) state.view = 'dashboard';
  if(state.view!=='ledger') state._inLedger = false;
  navTrack();
  state._viewStale = false;
  if(state.user) startReviewTicker();   // عدّاد نافذة المراجعة إن كان لي طلب لم يُرقَّم بعد
  renderBrand();
  renderTopbar();
  renderAppNav();
  renderDbBadge();
  const app = document.getElementById('app');
  document.body.classList.toggle('on-login', state.view==='login');
  app.classList.toggle('cxv', ['clients','catalog','centerBooks','centerBook','gwImport'].includes(state.view));
  if(state.view==='login') renderLogin(app);
  else if(state.view==='dashboard') { renderDashboard(app); cxStaffBanner(app); cxDashBanner(app); }
  else if(state.view==='newRequest') renderNewRequest(app);
  else if(state.view==='detail') renderDetail(app);
  else if(state.view==='account') renderAccount(app);
  else if(state.view==='admin') renderAdmin(app);
  else if(state.view==='analytics') renderAnalytics(app);
  else if(state.view==='newRequestChoice') renderNewRequestChoice(app);
  else if(state.view==='duplicateList') renderDuplicateList(app);
  else if(state.view==='printPreview'){ renderPrintPreview(app); }
  else if(state.view==='cancelledArchive') renderCancelledArchive(app);
  else if(state.view==='budgetReport') renderBudgetReportPage(app);
  else if(state.view==='ledger') renderLedger(app);
  else if(state.view==='revenues') renderRevenues(app);
  else if(state.view==='clients') renderClients(app);
  else if(state.view==='catalog') renderCatalog(app);
  else if(state.view==='centerBooks') renderCenterBooks(app);
  else if(state.view==='centerBook') renderCenterBook(app);
  else if(state.view==='gwImport') renderGwImport(app);
  else if(state.view==='recurring') renderRecurring(app);
  else if(state.view==='guide') renderGuide(app);
  else if(state.view==='sitemap') renderSiteMap(app);
  else if(state.view==='sigDesigner') renderSigDesigner(app);
  else if(state.view==='orgTree') renderOrgTree(app);
  else if(state.view==='jobLevels') renderJobLevels(app);
  else if(state.view==='barSettings') renderBarSettings(app);
  else if(state.view==='securityLog') renderSecurityLog(app);
  else if(state.view==='verifySettings') renderVerifySettings(app);
  else if(state.view==='handovers') renderHandovers(app);
  else if(state.view==='oldRequests') renderOldRequests(app);
  else if(state.view==='pathCheck') renderPathCheckPage(app);
  else if(state.view==='monitor') renderMonitor(app);
  else if(state.view==='custodyList') renderCustodyList(app);
  else if(state.view==='custody') renderCustodyPage(app);
  else if(state.view==='newCustody') renderNewCustody(app);

  // حقول الدور والشركة وسلسلة الاعتماد يغيّرها مدير النظام وحده (الخادم يمنع غيره) — تُقفل لغيره بدل أن يظهر له خطأ
  if(state.user && state.user.role!=='admin'){
    ['editUserRole','editUserCompany','editUserManager','editUserRequestApprover','editUserNextApprover','editUserLevel','editUserCenter','editUserGeneral','editUserDeadline','editUserEscMode','editUserEscUser'].forEach(id=>{
      const e = document.getElementById(id); if(e){ e.disabled = true; e.title = 'تغيير هذا الحقل لمدير النظام وحده'; }
    });
    document.querySelectorAll('[data-access-company],[data-ucm-company]').forEach(e=>{ e.disabled = true; });
  }

  if(state.rejectModalReqId){ app.insertAdjacentHTML('beforeend', renderRejectModal()); }
  if(state.pendingDelete){ app.insertAdjacentHTML('beforeend', renderDeleteConfirmModal()); }
  if(state.suspendCheck){ app.insertAdjacentHTML('beforeend', renderSuspendModal()); }
  if(state.manualSignReqId){ app.insertAdjacentHTML('beforeend', renderManualSignModal()); setupManualSignCanvas(); }
  if(state.transferFormReqId){ app.insertAdjacentHTML('beforeend', renderTransferFormModal()); }
  if(state.filePreviewModal){ app.insertAdjacentHTML('beforeend', renderFilePreviewModal()); }
  if(state.attModal){ app.insertAdjacentHTML('beforeend', renderAttachmentsModal()); }

  attachQuickAdds();
  syncPageTitle();
  applyPageWidth();
  { const ar = document.getElementById('qyamAssistant'); if(ar) ar.style.display = canSeeAssistant() ? '' : 'none'; }
  if(state._astView!==undefined && state._astView!==state.view) assistantAutoClose();
  state._astView = state.view;
  if(canSeeAssistant()) mountAssistant();
  injectGroupNav();
  applyPageSections();
  ensureBottomBar();
  renderMobileTabs();
  markDupTitle();
  pageTidy();
  decorateButtons();
  iconActs();
  qylEnhance(app);
  window._qyInRender = false; { const a = document.getElementById('app'); if(a){ _qyMO.takeRecords(); _qyMO.observe(a, {childList:true, subtree:true}); } }
  if(_same && _sy > 0){ const t0 = Date.now(); const keep = ()=>{ if((window._qyScrollAt||0) >= t0) return; if(Math.abs(window.scrollY - _sy) > 2) window._qyScrollTo(0, _sy); }; keep(); requestAnimationFrame(keep); setTimeout(keep, 60); }
  scrollActiveTabIntoView();
  fitFilterButtons();
  reapplyFieldErr();
  refreshNotifIndicators();
  navApplyPadding(); fitNavBleed(); requestAnimationFrame(()=>{ navApplyPadding(); fitNavBleed(); });
  maybeCheckDeadlines();
  maybeMigrateNames();
  ensureOrgUnit();
  if(state.view==='admin' && state.adminSubTab==='printSetup' && document.getElementById('pfPreview')) updateFooterPreview();
  if(state.view==='admin' && state.adminSubTab==='printSetup' && state.printSetupUnit && document.getElementById('cpPreview')) updateCenterPreview(state.printSetupUnit);
  if(state.view==='printPreview') fitPageFooters();
  renderBellPanel();
}

// ينسخ أزرار الصفوف الرئيسية للصفحة (الموسومة data-bar-actions) إلى الشريط السفلي العام، وتبقى الأصلية بمكانها
// يضمن وجود الشريط السفلي داخل #app (صفحة الهيكل تُرسم أحياناً بعد الانتظار أو تُعاد جزئياً فتمسح الشريط)
function ensureBottomBar(){
  const app = document.getElementById('app'); if(!app) return;
  // عند صفحة إنشاء/تعديل الطلب: أخفِ global-floating-bar وأظهر sticky-submit-bar فقط
  if(state.view==='newRequest'){
    const gfb = document.querySelector('.global-floating-bar');
    if(gfb) gfb.style.display='none';
    syncBottomBarMetrics();
    return;
  }
  // في باقي الصفحات: أظهر global-floating-bar وأخفِ sticky-submit-bar
  const gfb = document.querySelector('.global-floating-bar');
  if(gfb) gfb.style.display='';
  if(app.querySelector('.global-floating-bar')) { moveRowsToBottomBar(); syncBottomBarMetrics(); return; }
  const html = renderGlobalFloatingBar();
  if(html) app.insertAdjacentHTML('beforeend', html);
  moveRowsToBottomBar();
  syncBottomBarMetrics();
}
function moveRowsToBottomBar(){
  const target = document.querySelector('.global-floating-bar .gfb-actions');
  if(!target) return;
  // قاعدة عامة: كل صف أزرار رئيسي في الصفحة يدخل الشريط السفلي ولو لم يُوسَم، إلا ما كان في نافذة أو قائمة أو صندوق حساب
  document.querySelectorAll('#app .actions-row:not([data-bar-actions])').forEach(r=>{
    if(r.closest('.modal-box,.list-item,.calc-box,.no-bar,.modal-overlay')) return;
    if(!r.querySelector('.btn-primary')) return;
    r.setAttribute('data-bar-actions','');
  });
  document.querySelectorAll('#app [data-bar-actions]').forEach(row=>{
    if(row.closest('.modal-box') || (row.offsetParent===null && !row.classList.contains('bar-moved'))) return;
    const key = row.getAttribute('data-bar-key');
    if(key && state.barToggles && state.barToggles[key]===false) return; // هذا الزر مخفي من الشريط السفلي حسب إعداد الأدمن
    // نسطّح الأزرار: أي حاوية وسيطة (مثل زوج معاينة/تحميل) تُفكّك، فيدخل كل زر مباشرة بالصف الواحد
    const flat = [];
    Array.from(row.children).forEach(ch=>{
      if(ch.tagName==='BUTTON' || ch.tagName==='A') flat.push(ch);
      else { const inner = ch.querySelectorAll('button'); if(inner.length) inner.forEach(x=>flat.push(x)); else flat.push(ch); }
    });
    flat.forEach(btn=>{
      if(/^[→←\s]*رجوع\s*$/.test((btn.textContent||'').trim())) return;   // زر الرجوع ثابت في الشريط
      const copy = btn.cloneNode(true);
      copy.removeAttribute('id');
      // الشريط السفلي كله بالحجم الخامس (105×40): أزيل أي حجم آخر. الزر المزدوج يبقى سطره الأول فقط، ونصه الكامل في التلميح
      copy.className = copy.className.replace(/\bbtn-(lg2?|md2?|sm2?|xs2?)\b/g,'').trim() + ' btn-sm';
      if(copy.querySelector('.bl1')){
        const full = Array.from(copy.querySelectorAll('span')).map(x=>x.textContent.trim()).filter(Boolean).join(' ');
        const first = copy.querySelector('.bl1').textContent.trim();
        copy.textContent = first;
        if(!copy.getAttribute('title')) copy.setAttribute('title', full);
      }
      target.appendChild(copy);
    });
    if(flat.length) row.classList.add('bar-moved');   // زر واحد يكفي: يبقى في الشريط السفلي ويختفي تكراره في الصفحة
  });
}
// يضبط ارتفاع الشريط السفلي الفعلي: مسافة تمرير الحقول + الفاصل السفلي + زر الميزانية العائم
// ───────── عرض صندوق المحتوى ─────────
// صفحات البيانات تتسع بقدر ما يختاره المستخدم؛ وصفحة الطلب وإنشاؤه والمعاينة
// تبقى على 920 لأنها تحاكي ورقة A4، وتوسيعها يباعد حقولها بلا فائدة.
// العرض المختار يسري على كل الصفحات إلا ما يحاكي ورقة A4: معاينة الطباعة.
// وصفحة الدخول بطاقة موسّطة، لا شأن لها بعرض الصندوق.
const NARROW_VIEWS = ['printPreview','login'];
const PAGE_WIDTH_PRESETS = [1000, 1200, 1400, 1600];
const PAGE_WIDTH_DEFAULT = 1000;
function pageIsWide(){ return !NARROW_VIEWS.includes(state.view); }
function pageWidthKey(){ return 'qayam_page_width_' + (state.user ? state.user.id : 'anon'); }
function getPageWidth(){
  try{
    const v = localStorage.getItem(pageWidthKey());
    if(v!==null && v!==''){
      let n = Number(v);
      if(n===960){ n = 1000; try{ localStorage.setItem(pageWidthKey(),'1000'); }catch(e){} }  // 960 لم يعد من الخيارات
      if(!isNaN(n) && n>=0) return n;
    }
  }catch(e){}
  return PAGE_WIDTH_DEFAULT;
}
function setPageWidth(px){
  const n = Number(px);
  if(isNaN(n) || n<0) return;
  const v = n===0 ? 0 : Math.min(2400, Math.max(820, Math.round(n)));   // 0 = كامل الشاشة
  try{ localStorage.setItem(pageWidthKey(), String(v)); }catch(e){}
  render();
  showToast(v===0 ? 'عرض الصفحة: كامل الشاشة' : 'عرض الصفحة: ' + v + ' بكسل', 'success');
}
function effectiveBoxWidth(){
  if(!pageIsWide()) return 920;
  const w = getPageWidth();
  return w>0 ? w : 99999;
}
window.addEventListener('resize', ()=>{ clearTimeout(window._pwT); window._pwT=setTimeout(()=>{ try{ applyPageWidth(); }catch(e){} }, 120); });
function applyPageWidth(){
  const app = document.getElementById('app'); if(!app) return;
  // الصندوق يبدأ ملاصقاً للشريط الجانبي (بفجوة 16) ويمتدّ يساراً — لا موسّطاً في الفراغ.
  // التوسيط كان يترك مئات البكسلات بينه وبين الشريط كلما كان العرض أصغر من الشاشة.
  const mode = (document.getElementById('appNav')||{dataset:{}}).dataset.mode;
  const anchored = (mode==='open' || mode==='collapsed');
  app.style.marginRight = anchored ? '0' : '';
  app.style.marginLeft  = anchored ? 'auto' : '';
  // --page-box يتبعه الشريط السفلي وشريط الإرسال فتبدأ أزرارهما مع حافة الصندوق
  const setBox = v => document.documentElement.style.setProperty('--page-box', v);
  // صفحة الطلب ومعاينته: بجانب الشريط الجانبي كبقية الصفحات (نقطة بداية واحدة للعين)، بعرض الورقة الثابت
  // لا تتبع العرض الذي يختاره المستخدم: هما صورة الورقة المطبوعة، فتظهر بالحجم نفسه عند الجميع
  document.documentElement.style.setProperty('--page-shift', '0px');
  if(state.view==='detail' || state.view==='printPreview' || state.view==='custody'){
    const side = 0;
    app.style.maxWidth = (DOC_BOX_W + side) + 'px';
    setBox((DOC_BOX_W + side) + 'px');
    fitPreviewZoom();
    return;
  }
  fitPreviewZoom();
  if(!pageIsWide()){ app.style.maxWidth = ''; setBox('920px'); return; }   // قياس الورقة
  const w = getPageWidth();
  app.style.maxWidth = w>0 ? (w + 'px') : 'none';
  setBox(w>0 ? (w + 'px') : '100%');
}
// حسابي ← الأصوات: صوت الإشعارات (بدرجاته) وصوتا رسائل الخطأ والنجاح. يُحفظ فوراً في هذا الجهاز بلا زر حفظ
function soundsCardHtml(){
  const lv = notifLevel();
  const row = (label, ctl, test, hint)=>`<div class="snd-row"><div class="snd-lab"><b>${label}</b><div class="file-hint">${hint}</div></div>${ctl}<button type="button" class="btn btn-ghost btn-sm" data-on-click="${test[0]}" data-on-click-args="${qa(test[1])}" title="يُسمعك الصوت الآن">▶ تجربة</button></div>`;
  const sw = k=>`<label class="snd-sw"><input type="checkbox" style="width:auto;" ${toastSoundOn(k)?'checked':''} data-on-change="setToastSound" data-on-change-args="${qa([k, QA.c])}"> ${toastSoundOn(k)?'مُفعَّل':'متوقف'}</label>`;
  return `
    <div class="card flow">
      <h2 style="margin:0 0 4px;font-size:var(--fs-h3);">الأصوات</h2>
      <p class="file-hint" style="margin:0 0 8px;">تُحفظ فوراً في هذا الجهاز، بلا زر حفظ.</p>
      ${row('صوت الإشعارات', `<select style="--fw:180px;" data-on-change="setNotifLevel" data-on-change-args="${qa([QA.v])}">${[3,2,1,0].map(v=>`<option value="${v}" ${v===lv?'selected':''}>${NOTIF_LEVELS[v].ico} ${NOTIF_LEVELS[v].name}</option>`).join('')}</select>`, ['playNotifSound', []], 'عند وصول إشعار جديد في الجرس')}
      ${row('صوت رسائل الخطأ', sw('err'), ['playToastSound', ['err', true]], 'نغمة هابطة عند ظهور رسالة خطأ (حقل ناقص أو إجراء مرفوض)')}
      ${row('صوت رسائل النجاح', sw('ok'), ['playToastSound', ['ok', true]], 'نغمة صاعدة عند نجاح الحفظ أو الإرسال أو الاعتماد')}
    </div>`;
}
function setNotifLevel(v){
  _notifLevel = Math.max(0, Math.min(3, Number(v)||0));
  try{ localStorage.setItem('qayam_notif_vol', String(_notifLevel)); }catch(e){}
  if(_notifLevel>0) playNotifSound();
  try{ renderBellPanel(); }catch(e){}
}
function pageWidthFieldHtml(){
  const cur = getPageWidth();
  const btn = (v,label)=>`<button type="button" class="adm-sub${cur===v?' active':''}" style="border:1px solid var(--line);border-radius:6px;"
      data-on-click="setPageWidth" data-on-click-args="${qa([(v)])}">${escH(label)}</button>`;
  return `
    <div class="card">
      <h2>عرض صفحات البيانات</h2>
      <p class="file-hint">يخصّ الدفتر والتقارير ولوحة التحكم والهيكل. صفحة الطلب وإنشاؤه ومعاينة الطباعة تبقى على قياس الورقة.
        الاختيار يُحفظ لك على هذا الجهاز وحده، فلا يفرضه أحد على غيره.</p>
      <div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:10px 0 4px;">
        ${PAGE_WIDTH_PRESETS.map(v=>btn(v, v + ' بكسل')).join('')}
        ${btn(0, 'كامل الشاشة')}
      </div>
      <div class="row" style="max-width:320px;margin-top:6px;">
        <div><label>أو عرض من اختيارك (820 – 2400)</label>
          <input id="pageWidthInput" type="number" min="820" max="2400" step="20" value="${cur>0?cur:''}" placeholder="مثال: 1500"
                 data-on-keydown="#50">
        </div>
      </div>
      <div class="actions-row">
        <button class="btn btn-primary btn-sm btn-inline" data-on-click="#51">تطبيق</button>
      </div>
    </div>`;
}

// ───────── شريط التبويب السفلي للهاتف ─────────
// الشاشات المركّزة: إنشاء طلب ومعاينة الطباعة. فيهما أزرار خاصة تحتاج أسفل الشاشة كلّه،
// فيُخفى شريط التبويب ويعود شريط الإرسال وحده.
const M_FOCUS_VIEWS = ['newRequest','printPreview','login'];
// اسم زر الشريط السفلي على الهاتف: بلا أقواس، ويُقطع عند آخر كلمة كاملة (لا «…»)
function mShortLbl(t){
  t = String(t||'').replace(/\([^)]*\)/g,'').replace(/["«»]/g,'').replace(/\s+/g,' ').trim();
  if(t.length<=14) return t;
  const w = t.split(' '); let o = '';
  for(const x of w){ if((o ? o+' '+x : x).length>14) break; o = o ? o+' '+x : x; }
  return o || t.slice(0,14);
}
function renderMobileTabs(){
  const el = document.getElementById('mTab'); if(!el) return;
  document.body.classList.toggle('m-focus', M_FOCUS_VIEWS.includes(state.view));
  if(!state.user){ el.innerHTML=''; return; }
  const n = (typeof computeNotifications==='function' ? computeNotifications() : {badge:0}) || {badge:0};
  const badge = Number(n.badge)||0;
  const open = document.body.classList.contains('nav-drawer-open');
  // RTL: أول زرّ في الكود يظهر أقصى اليمين — فالترتيب البصري يمين←يسار كما هو مكتوب هنا
  // أزرار الصفحة العامة (المنسوخة إلى الشريط السفلي) تصير: زر رئيسي في الوسط، والباقي في «المزيد»
  const acts = Array.from(document.querySelectorAll('.global-floating-bar .gfb-actions > button, .global-floating-bar .gfb-actions > a'))
    .filter(b=>!/^[→←\s]*رجوع\s*$/.test((b.textContent||'').trim()));
  const isMain = b => /btn-(primary|approve)/.test(b.className) && !b.disabled;
  // الزر الرئيسي يبقى في الوسط حتى لو كان معطّلاً (يظهر باهتاً ويقول سببه عند الضغط) — لا يأخذ «إلغاء» مكانه
  // قرار مطلوب منك (اعتماد / اعتماد ورقي) يتقدّم على «معاينة الطلب» وغيرها في الوسط
  const main = acts.find(b=>/btn-approve/.test(b.className) && !b.disabled) || acts.find(isMain) || acts.find(b=>/btn-(primary|approve)/.test(b.className)) || acts.find(b=>!b.disabled) || null;
  state._mActs = acts; state._mMain = main ? acts.indexOf(main) : -1;
  const rest = acts.filter(b=>b!==main);
  const isAdminNav = state.user.role==='admin' && !state.impersonatingFromAdmin;
  const newItem = isAdminNav
      ? {key:'viewas', ico:'eye', label:'عرض كمستخدم', on:state.view==='admin' && state.adminSubTab==='impersonate' && !open, act:[["#14",[]]]}
      : {key:'new', ico:'plus', label:'جديد', on:['newRequest','newRequestChoice'].includes(state.view) && !open, act:[["#15",[]]]};
  const mainLbl = main ? ((main.getAttribute('title') && main.textContent.trim().length>14) ? main.textContent.trim() : main.textContent.trim()) : '';
  // الخانة الرابعة: «عرض العهدة» في طلب العهدة، وإلا «المزيد» أو «جديد/عرض كمستخدم» أو «حسابي»؛
  // والخامسة: «المسار» في صفحتي الطلب والعهدة، وإلا «حسابي» (الإشعارات انتقلت إلى الشريط العلوي)
  const cusBtn = rest.find(b=>b.getAttribute('data-on-click')==='openCustodyOfRequest');
  const rest2 = rest.filter(b=>b!==cusBtn);
  const accItem = {key:'account', ico:'account', label:'حسابي', on:state.view==='account' && !open, act:[["#10",[]]]};
  // لا يتكرر زر في الشريط: الخانات الفارغة تُملأ بالترتيب من (جديد/عرض كمستخدم ← حسابي ← العهد)
  const cusListItem = {key:'cuslist', ico:'case', label:'العهد', on:['custodyList','custody','newCustody'].includes(state.view) && !open, act:[["openCustodyList",[]]]};
  const slot3 = main ? null : newItem;
  const used = new Set(slot3 ? [slot3.key] : []);
  if(main && /جديد/.test(mainLbl)) used.add('new');
  const fillers = [newItem, accItem].concat((typeof viewAllowed!=='function' || viewAllowed('custodyList')) ? [cusListItem] : []);
  const nextFill = ()=>{ const f = fillers.find(x=>!used.has(x.key)) || accItem; used.add(f.key); return f; };
  let slot4;
  if(cusBtn && !rest2.length) slot4 = {key:'cus', ico:'case', label:'عرض العهدة', act:[["mTabCus",[]]]};
  else if(rest.length===1 && !rest[0].disabled){   // زر واحد إضافي: يظهر مباشرة بدل «المزيد»
    const t = (rest[0].textContent||'').trim(); const m = t.match(/^([^\p{L}\p{N}\s]+)\s*(.*)$/u);
    const lb1 = m ? m[2] : t; slot4 = {key:'one', ico:(m && m[1].replace(/[✓✔]/g,'').trim()) || btnIconFor(lb1) || '⋯', label:mShortLbl(lb1), act:[["mTabOne",[]]]};
  }
  else if(rest.length) slot4 = {key:'more', ico:'⋯', label:'المزيد', act:[["mTabMore",[]]], dot:0};
  else slot4 = nextFill();
  const hasPath = ['detail','custody'].includes(state.view) && !!document.querySelector('#app .req-wrap, #app .mcus, #app .doc');
  const slot5 = hasPath ? {key:'path', ico:'route', label:'المسار', on:!!state.cusPathOpen, act:[["cusPathToggle",[]]]} : nextFill();
  // RTL: أول زرّ في الكود يظهر أقصى اليمين
  const items = [
    {key:'menu',      ico:'menu',  label:'القائمة',  on:open,
     act: open ? [["closeNavDrawer",[]]] : [["openNavDrawer",[]]]},
    {key:'dashboard', ico:'clip', label:'الطلبات',  on:['dashboard','detail'].includes(state.view) && !open, dot:(typeof getMyPendingRequests==='function' ? getMyPendingRequests().length : 0),
     act:[["#13",[]]]},
    main ? (()=>{ const m = mainLbl.match(/^([^\p{L}\p{N}\s]+)\s*(.*)$/u); const ic = m ? m[1].replace(/[✓✔]/g,'').trim() : ''; const lb = (m ? m[2] : mainLbl); return {key:'pmain', ico: ic || (/^✓|^✔/.test(mainLbl) ? 'done' : (btnIconFor(lb) || 'plus')), label: mShortLbl(lb), main:true, off: !!(acts[state._mMain]||{}).disabled, act:[["mTabMain",[]]]}; })() : slot3,
    slot4,
    slot5,
  ];
  const pulse = !!state._pathPulse; state._pathPulse = false;
  // صفحة فيها أزرار: سطران — الأعلى أزرار الصفحة كلها بأسمائها (لا «المزيد»)، والأسفل أيقونات التنقّل بلا كلام
  if(acts.length){
    const clean = t => String(t||'').replace(/^[^\p{L}\p{N}]+/u,'').replace(/\s+/g,' ').trim();
    const kind = b => /btn-approve/.test(b.className) ? 'ok' : /btn-reject/.test(b.className) ? 'no' : /btn-(primary|warning)/.test(b.className) ? 'pri' : 'gh';
    const order = acts.map((b,i)=>i).sort((x,y)=>{ const r = b=>({ok:0,pri:1,gh:2,no:3})[kind(acts[b])]; return r(x)-r(y); });
    const cols = Math.min(3, acts.length);
    const nav = [
      {key:'menu', ico:'menu', label:'القائمة', on:open, act: open ? [["closeNavDrawer",[]]] : [["openNavDrawer",[]]]},
      {key:'dashboard', ico:'clip', label:'الطلبات', on:['dashboard','detail'].includes(state.view) && !open, dot:(typeof getMyPendingRequests==='function' ? getMyPendingRequests().length : 0), act:[["#13",[]]]},
      newItem, accItem
    ].concat(hasPath ? [{key:'path', ico:'route', label:'المسار', on:!!state.cusPathOpen, act:[["cusPathToggle",[]]]}] : ((typeof viewAllowed!=='function' || viewAllowed('custodyList')) ? [cusListItem] : []));
    el.innerHTML = `<div class="mtab-acts" style="--mta-cols:${cols};">${order.map(i=>{ const b = acts[i];
        return `<button type="button" class="mta mta-${kind(b)}${b.disabled ? ' mta-off' : ''}" ${qon('click', [["mTabAct",[i]]])} title="${escH(b.getAttribute('title')||clean(b.textContent))}">${escH(({'رفض لأسباب محاسبية':'رفض'})[clean(b.textContent)] || mShortLbl(clean(b.textContent)))}</button>`; }).join('')}</div>
      <div class="mtab-in mtab-icons">${nav.map(it=>`
        <button type="button" class="mtab-btn${it.on?' active':''}${it.key==='path' && pulse ? ' mtab-pulse':''}" data-k="${it.key}" ${qon('click', it.act)} aria-label="${escH(it.label)}" title="${escH(it.label)}">
          <span class="mtab-ico">${qiOr(it.ico)}</span>
          ${it.dot ? `<span class="mtab-dot">${it.dot>99?'99+':it.dot}</span>` : ''}
        </button>`).join('')}</div>`;
    document.body.style.setProperty('--mtab-h', (el.offsetHeight || 104) + 'px');
    return;
  }
  el.innerHTML = `<div class="mtab-in">${items.map(it=>`
    <button type="button" class="mtab-btn${it.on?' active':''}${it.main?' mtab-main':''}${it.off?' mtab-off':''}${it.key==='path' && pulse ? ' mtab-pulse':''}" data-k="${it.key}" ${qon('click', it.act)} aria-label="${escH(it.label)}">
      <span class="mtab-ico">${qiOr(it.ico)}</span><span>${escH(it.label)}</span>
      ${it.dot ? `<span class="mtab-dot">${it.dot>99?'99+':it.dot}</span>` : ''}
    </button>`).join('')}</div>`;
  document.body.style.setProperty('--mtab-h', (el.offsetHeight || 56) + 'px');
}
function mTabAct(i){ const b = (state._mActs||[])[i]; if(!b) return; if(b.disabled){ showToast(b.getAttribute('title') || 'هذا الزر غير متاح الآن', 'error'); return; } b.click(); }
// على الهاتف: عنوان الصفحة الكبير يُخفى إن كان يكرّر التبويب المختار
// ===== تهذيب عام للصفحات (10 نوفمبر): ⓘ للشروح، اسم الحقل بجانبه على الهاتف، الجداول، مؤشر التمرير =====
// الشرح الطويل يُطوى خلف ⓘ بجانب عنوانه؛ يُحفظ ما فتحه المستخدم حتى يعيد الضغط
const _tipOpen = new Set();
function infoTips(){
  const app = document.getElementById('app'); if(!app) return;
  app.querySelectorAll('p.sub, .file-hint, p.page-intro').forEach(el=>{
    if(el.dataset.tip || el.closest('.modal-overlay,.sec-note,.mtab-sheet,.doc-page,.print-only,.req-side,.mpath,.mcus-line,.snd-lab,.tcards,table')) return;
    if(el.querySelector('input,select,button,textarea,img')) return;
    const txt = (el.textContent||'').replace(/\s+/g,' ').trim();
    if(txt.length < 55) return;
    if(/color:\s*var\(--red\)|color:\s*#?b91c1c/i.test(el.getAttribute('style')||'')) return;   // تحذير أحمر يبقى ظاهراً
    let a = el.previousElementSibling;
    while(a && (a.hidden || a.classList.contains('tip-body'))) a = a.previousElementSibling;
    if(!a || !a.matches('h1,h2,h3,h4,label,summary,b,.lbl,.sec-title,.av-btns')){
      const p = el.parentElement;
      if(p && p.firstElementChild && p.firstElementChild!==el && p.firstElementChild.matches('h2,h3,h4,label,b')) a = p.firstElementChild;
      else return;
    }
    if(a.querySelector(':scope > .tip-btn')) return;
    const key = txt.slice(0, 60);
    el.dataset.tip = '1'; el.classList.add('tip-body'); el.hidden = !_tipOpen.has(key);
    const b = document.createElement('button'); b.type = 'button'; b.className = 'tip-btn no-print'; b.textContent = 'ⓘ';
    b.title = 'شرح'; b.setAttribute('aria-label','شرح');
    b.addEventListener('click', ev=>{ ev.preventDefault(); ev.stopPropagation();
      el.hidden = !el.hidden; if(el.hidden) _tipOpen.delete(key); else _tipOpen.add(key); b.classList.toggle('on', !el.hidden);
      if(!el.hidden) qyAutoBox(el, b, ()=>{ el.hidden = true; _tipOpen.delete(key); b.classList.remove('on'); }); });
    b.classList.toggle('on', !el.hidden);
    a.appendChild(b);
  });
}
// الهاتف: اسم الحقل بخط عريض على اليمين والحقل على يساره في سطر واحد
function pairFields(){
  if(!isPhone() || state.view==='login') return;
  const app = document.getElementById('app'); if(!app) return;
  const FIELD = 'input:not([type=checkbox]):not([type=radio]):not([type=file]):not([type=hidden]), select, textarea.grow-1, .sel-add, .field-with-btn, label.file-btn';
  app.querySelectorAll('label').forEach(l=>{
    if(l.closest('.lf,.modal-overlay,.mtab-sheet,table,.tcards,.cus-docs,.dash-filt,.snd-row,.sig-ed,.recipe,.sig-el,.perm-row')) return;
    if(l.querySelector('input,select,textarea')) return;          // مربع اختيار داخل اسمه
    let f = l.nextElementSibling;
    if(!f || !f.matches(FIELD)) return;
    const p = l.parentElement;
    if(f.type==='color' && p && p.parentElement && p.parentElement.querySelectorAll('input[type=color]').length>1) return;   // صف ألوان: ثلاث خانات متجاورة
    // الجزء بين قوسين في آخر الاسم يصغر حتى لا يطول الاسم ثلاثة أسطر
    if(l.childNodes.length===1 && l.firstChild.nodeType===3){ const m = l.textContent.match(/^(.{3,}?)\s*(\([^()]{6,}\))\s*$/); if(m){ l.textContent = m[1]+' '; const sm = document.createElement('small'); sm.className = 'lf-note'; sm.textContent = m[2]; l.appendChild(sm); } }
    if(p && p.children.length===2 && p.parentElement && p.parentElement.classList.contains('row')){ p.classList.add('lf'); return; }
    const w = document.createElement('div'); w.className = 'lf';
    l.before(w); w.appendChild(l); w.appendChild(f);
  });
  // عمود الأسماء في كل نموذج بعرض أطول اسم فيه فقط (حد أقصى 42%) — فلا يبعد الحقل عن اسمه، وتبقى الحقول متساوية
  const groups = new Map();
  app.querySelectorAll('.lf').forEach(f=>{ if(f.closest('.filt-bar')) return; const g = f.closest('.list-item, .modal') || app; if(!groups.has(g)) groups.set(g, []); groups.get(g).push(f); });
  groups.forEach((lfs, g)=>{
    const labs = lfs.map(f=>f.querySelector(':scope > label')).filter(Boolean);
    labs.forEach(l=>{ l.style.whiteSpace = 'nowrap'; l.style.width = 'max-content'; });
    let mx = 0; labs.forEach(l=>{ const c = l.cloneNode(true); c.querySelectorAll('.lf-note').forEach(x=>x.remove()); l.after(c); c.style.position = 'absolute'; c.style.visibility = 'hidden'; mx = Math.max(mx, c.getBoundingClientRect().width); c.remove(); });
    labs.forEach(l=>{ l.style.whiteSpace = ''; l.style.width = ''; });
    const cap = Math.round((lfs[0].clientWidth || g.clientWidth || 360) * 0.30);
    g.style.setProperty('--lfw', Math.max(48, Math.min(cap, Math.ceil(mx) + 2)) + 'px');
  });
  // زر يأتي بعد حقل مباشرة: تحت الحقل نفسه وبعرضه (لا ملتصقاً به ولا في الطرف الآخر)
  app.querySelectorAll('.lf').forEach(f=>{
    let n = f.nextElementSibling;
    if(!n && f.parentElement && f.parentElement.children.length===1) n = f.parentElement.nextElementSibling;
    if(!n || n.closest('.list-item') && n.closest('.list-item')!==f.closest('.list-item')) return;
    const kids = [...n.children].filter(k=>k.offsetParent || k.matches('.btn'));
    const isBtnBox = n.matches('.btn') || (kids.length && kids.length<=2 && kids.every(k=>k.matches('.btn')) && !n.matches('[data-bar-actions], .list-item, .lf'));
    if(isBtnBox && !n.classList.contains('bar-moved')) n.classList.add('under-lf');
  });
  // زر انكسر كلامه سطرين: يتّسع لكلامه في سطر واحد
  app.querySelectorAll('.btn').forEach(b=>{ if(b.closest('table.amount-table,.doc,.doc-page,.modal-overlay')) return; if(!b.offsetParent || b.classList.contains('btn-fit')) return; let two = b.offsetHeight > 46; if(!two){ const rg = document.createRange(); rg.selectNodeContents(b); const tops = new Set([...rg.getClientRects()].filter(r=>r.width>2).map(r=>Math.round(r.top/8))); two = tops.size>1 && (b.textContent||'').trim().length>6 && [...rg.getClientRects()].some(r=>r.height<24 && r.width>2) && b.getBoundingClientRect().height<50 && (()=>{ const rs=[...rg.getClientRects()].filter(r=>r.width>2 && r.height<26); const mn=Math.min(...rs.map(r=>r.top)), mx=Math.max(...rs.map(r=>r.top)); return mx-mn>10; })(); } if(two) b.classList.add('btn-fit'); });
}
// الجداول: لغير مدير النظام على الهاتف بطاقات (اسم العمود أمام كل قيمة)؛ لمدير النظام جدول بعمود أول ثابت ومؤشر تمرير
function adaptTables(){
  const app = document.getElementById('app'); if(!app) return;
  const cards = isPhone() && state.user && state.user.role!=='admin';
  app.querySelectorAll('table').forEach(t=>{
    if(t.closest('.doc,.doc-page,.note-box,.print-only,.modal-overlay,.sig-ed') || t.classList.contains('amount-table')) return;
    const hr = t.tHead && t.tHead.rows[0]; if(!hr) return;
    const heads = [...hr.cells].map(c=>(c.textContent||'').replace(/[▲▼↑↓]/g,'').replace(/\s+/g,' ').trim());
    if(heads.length < 3) return;
    if(cards){
      t.classList.add('tcards');
      [...t.tBodies].forEach(tb=>[...tb.rows].forEach(r=>{ let i=0; [...r.cells].forEach(c=>{ if(!c.dataset.l && heads[i]) c.dataset.l = heads[i]; i += c.colSpan||1; }); }));
    }
  });
}
function scrollHints(){
  const els = [...document.querySelectorAll('#app .adm-tabs2, #app table')].map(e=>e.tagName==='TABLE' ? e.parentElement : e).filter(Boolean);
  [...new Set(els)].forEach(sc=>{
    if(sc.closest('.doc,.doc-page,.modal-overlay') || sc.querySelector('table.tcards')) return;
    const cs = getComputedStyle(sc);
    if(!/(auto|scroll)/.test(cs.overflowX)) return;
    const upd = ()=>{
      const more = sc.scrollWidth > sc.clientWidth + 2;
      const end = Math.abs(sc.scrollLeft) + sc.clientWidth >= sc.scrollWidth - 2;
      sc.classList.toggle('xs-more', more && !end);
      sc.classList.toggle('xs-start', more && Math.abs(sc.scrollLeft) > 2);
    };
    if(!sc.dataset.xs){ sc.dataset.xs = '1'; sc.addEventListener('scroll', upd, {passive:true}); }
    sc.classList.add('xs');
    // الجداول: ظلّ بطول الجدول كله على الطرف الذي بقي فيه محتوى (لا على صف العناوين وحده)
    if(sc.querySelector(':scope > table')){
      const par = sc.parentElement;
      if(par && getComputedStyle(par).position==='static') par.style.position = 'relative';
      while(sc.nextElementSibling && sc.nextElementSibling.classList.contains('xs-shade')) sc.nextElementSibling.remove();
      ['l','r'].forEach(side=>{ const d = document.createElement('div'); d.className = 'xs-shade xs-shade-'+side+' no-print';
        d.style.top = sc.offsetTop+'px'; d.style.height = sc.clientHeight+'px';
        if(side==='l') d.style.left = sc.offsetLeft+'px'; else d.style.left = (sc.offsetLeft + sc.clientWidth - 26)+'px';
        sc.after(d); });
    }
    upd();
  });
}
// عنوان أول بطاقة يكرر اسم التبويب المفتوح: يُخفى
function hideDupH2(){
  const a = document.querySelector('#app .adm-t2.active'); if(!a) return;
  const t = s => (s||'').replace(/\(\d+\)/g,'').replace(/\s+/g,' ').trim();
  const at = t(a.textContent);
  document.querySelectorAll('#app .card h2, #app > h2').forEach(h=>{
    const own = t([...h.childNodes].filter(n=>n.nodeType===3 || (n.nodeType===1 && !n.classList.contains('tip-btn') && !n.classList.contains('sub'))).map(n=>n.textContent).join(''));
    if(own===at) h.classList.add('dup-h2');
  });
}
function hideEmptyTopBars(){
  document.querySelectorAll('#app .top-action-bar').forEach(t=>{
    const vis = [...t.querySelectorAll('button, a.btn')].some(b=>!b.closest('.bar-moved') && b.offsetParent!==null);
    t.classList.toggle('tab-empty', !vis);
  });
}
// الهاتف وسطح المكتب: أزرار الحذف والتعديل داخل البطاقات والجداول بشكل واحد في كل النظام — مربع برمز فقط، والاسم يظهر تلميحاً
function iconActs(){
  const app = document.getElementById('app'); if(!app) return;
  app.querySelectorAll('.btn').forEach(b=>{
    if(b.classList.contains('btn-ico') || b.closest('.modal-overlay,.mtab-sheet,.gfb-actions,[data-bar-actions]')) return;
    if(!b.closest('.list-item,table,.tcards,.cus-li,.rec-li,.cx-rep-g,.cat-acts')) return;
    const t = (b.textContent||'').replace(/\s+/g,' ').trim();
    const kind = /^حذف( نهائي| الصورة)?$/.test(t) ? 'del' : (t==='تعديل' ? 'edit' : '');
    if(!kind || !b.querySelector('svg')) return;
    b.classList.add('btn-ico', 'btn-ico-'+kind);
    b.setAttribute('aria-label', t);
    if(!b.title) b.title = t;
    const box = b.parentElement; if(box && [...box.children].filter(x=>x.matches('.btn')).every(x=>x.classList.contains('btn-ico'))) box.classList.add('ico-box');
  });
  // زر لا يكفي عرضه الثابت لكلامه: يتّسع لكلامه بدل أن يُقصّ (العرض الثابت يبقى حداً أدنى)
  document.querySelectorAll('#app .btn, .global-floating-bar .btn').forEach(b=>{
    if(b.classList.contains('btn-ico') || !b.offsetParent || b.closest('.list-item > div:last-child:has(> .btn-ico)')) return;
    if(b.scrollWidth > b.clientWidth + 1){ const w = b.getBoundingClientRect().width; b.style.minWidth = Math.round(w)+'px'; b.style.width = 'auto'; b.style.whiteSpace = 'nowrap'; }
  });
}
// سطح المكتب: صندوق الطلب تصميمه ثابت بعرض 880؛ إن ضاقت الصفحة (تكبير المتصفح أو نافذة صغيرة) يُصغَّر كله بنسبته بدل أن تنضغط أعمدته
// الشريط السفلي: إن اقتربت الأزرار من «الدعم الفني» يُختصر إلى رمز واتساب فقط (الأرقام تظهر عند الوقوف عليه)
function barFit(){
  const bar = document.querySelector('.global-floating-bar'); if(!bar) return;
  const c = bar.querySelector('.gfb-contact-fixed'), a = bar.querySelector('.gfb-actions'); if(!c || !a) return;
  bar.classList.remove('gfb-tight');
  const btns = [...a.children].filter(x=>x.offsetParent); if(!btns.length) return;
  const minL = Math.min(...btns.map(b=>b.getBoundingClientRect().left));
  if(minL < c.getBoundingClientRect().right + 10){ bar.classList.add('gfb-tight'); c.title = 'للدعم الفني: ' + [...c.querySelectorAll('.gfb-contact-numbers a')].map(x=>x.textContent.trim()).join(' · '); }
}
// سطح المكتب: المسار المفتوح صندوق بجوار صندوق الطلب مباشرة إن اتسعت الصفحة له، وإلا يطفو على يسار الشاشة
function placePathSide(){
  const side = document.querySelector('#app .req-wrap:not(.closed) > .req-side'); if(!side) return;
  side.classList.remove('beside'); side.style.left = '';
  if(isPhone()) return;
  const doc = side.parentElement.querySelector('.req-main > .doc') || side.parentElement.querySelector('.req-main');
  const L = doc.getBoundingClientRect().left;
  side.style.top = '';
  if(L >= 300 + 14 + 14){ side.classList.add('beside'); side.style.left = Math.round(L - 300 - 14)+'px'; const T = doc.getBoundingClientRect().top; if(T > 60 && T < innerHeight/2) side.style.top = Math.round(T)+'px'; }
}
window.addEventListener('resize', ()=>{ clearTimeout(window._bfT); window._bfT = setTimeout(()=>{ try{ barFit(); placePathSide(); }catch(e){} }, 160); });
const DOC_BASE_W = 880;
function fitDocZoom(){
  const d = document.querySelector('#app .req-main > .doc'); if(!d) return;
  d.style.zoom = ''; d.style.width = ''; d.style.maxWidth = '';
  if(isPhone()) return;
  const av = d.parentElement.clientWidth;
  if(av > 0 && av < DOC_BASE_W){ d.style.width = DOC_BASE_W+'px'; d.style.maxWidth = 'none'; d.style.zoom = (av / DOC_BASE_W).toFixed(4); }
}
window.addEventListener('resize', ()=>{ clearTimeout(window._dzT); window._dzT = setTimeout(()=>{ try{ fitDocZoom(); }catch(e){} }, 140); });
// حقل نص لا يكفيه سطر: يصير حقلاً يتمدد بأسطر بدل أن يُقصّ الكلام (هاتف وسطح مكتب)
function growTa(t){ t.style.height = 'auto'; t.style.height = Math.max(40, t.scrollHeight + 2) + 'px'; }
function growInput(inp, keepFocus){
  if(!inp || inp.tagName!=='INPUT' || inp.type!=='text' || inp.list || inp.dir==='ltr' || inp.closest('table,.modal-overlay,.tb-tools,.search-float,.filt-bar,.sel-add,.field-with-btn')) return null;
  if(inp.scrollWidth <= inp.clientWidth + 2) return null;
  const t = document.createElement('textarea');
  [...inp.attributes].forEach(a=>{ if(!['type','value','autocomplete','inputmode'].includes(a.name)) t.setAttribute(a.name, a.value); });
  t.classList.add('grow-ta'); t.rows = 1; t.value = inp.value;
  const st = keepFocus ? inp.selectionStart : null;
  inp.replaceWith(t); growTa(t);
  if(keepFocus){ t.focus(); try{ t.setSelectionRange(st, st); }catch(e){} }
  return t;
}
function growInputs(){ document.querySelectorAll('#app input[type=text]').forEach(i=>growInput(i,false)); document.querySelectorAll('#app textarea.grow-ta').forEach(growTa); }
document.addEventListener('input', e=>{ const t = e.target; if(!t) return; if(t.matches && t.matches('textarea.grow-ta')) growTa(t); else if(t.tagName==='INPUT') growInput(t, true); });
document.addEventListener('keydown', e=>{ if(e.key==='Enter' && e.target && e.target.matches && e.target.matches('textarea.grow-ta')) e.preventDefault(); });
// زر رفع ملف بشكل أزرار النظام بدل الشكل الافتراضي للمتصفح («Choose File»)
function fileButtons(){
  document.querySelectorAll('#app input[type=file]').forEach(inp=>{
    if(inp.closest('label') || inp.dataset.fb) return;   // ملف داخل زر جاهز (مثل «إضافة صورة»): لا يُلفّ بزر ثانٍ
    inp.dataset.fb = '1';
    const lb = document.createElement('label'); lb.className = 'btn btn-ghost btn-sm file-btn';
    const tx = document.createElement('span'); tx.textContent = inp.multiple ? 'اختيار ملفات' : 'اختيار ملف';
    lb.appendChild(tx); inp.before(lb); lb.appendChild(inp); inp.hidden = true;
    inp.addEventListener('change', ()=>{ const f = inp.files || []; if(f.length) tx.textContent = f.length>1 ? f.length+' ملفات' : (f[0].name.length>22 ? f[0].name.slice(0,20)+'…' : f[0].name); });
  });
}
// أجزاء تُرسم دون إعادة رسم الصفحة كلها (تبويب فرعي، نافذة داخل الصفحة): تأخذ نفس الترتيب تلقائياً
const _qyMO = new MutationObserver(()=>{ if(window._qyInRender) return; cancelAnimationFrame(window._qyMOt); window._qyMOt = requestAnimationFrame(tidyLite); });
function tidyLite(){
  const app = document.getElementById('app'); if(!app) return;
  _qyMO.disconnect();
  try{ infoTips(); fileButtons(); pairFields(); growInputs(); iconActs(); qylEnhance(app); }catch(e){ console.error('tidyLite', e); }
  _qyMO.takeRecords(); _qyMO.observe(app, {childList:true, subtree:true});
}
// شريط «تتصفح الآن كـ» على الهاتف: فوق أعلى شريط سفلي ظاهر، فلا يغطي أزراره
function impAboveBar(){
  const f = document.querySelector('.imp-float'); if(!f) return;
  if(!isPhone()){ f.style.bottom = ''; return; }
  let top = innerHeight;
  document.querySelectorAll('#mTab, .sticky-submit-bar, .global-floating-bar').forEach(e=>{ const cs = getComputedStyle(e); if(cs.display==='none' || cs.visibility==='hidden' || !/fixed|sticky/.test(cs.position)) return; const r = e.getBoundingClientRect(); if(r.height>0 && r.bottom>=innerHeight-2 && r.top<top) top = r.top; });
  f.style.bottom = Math.max(12, Math.round(innerHeight - top + 8)) + 'px';
}
window.addEventListener('resize', ()=>requestAnimationFrame(impAboveBar));
// صفحة الطلب الجديد تختلف بين الهاتف وسطح المكتب: عند عبور الحد يُعاد رسمها بعد حفظ ما كُتب
window.addEventListener('resize', ()=>{ if(state.view==='newRequest' && state.draft && state._nrDesk!==undefined && state._nrDesk===isPhone()){ try{ syncDraftFromDOM(); }catch(e){} render(); } });
function pageTidy(){ try{ requestAnimationFrame(impAboveBar); setTimeout(impAboveBar, 300); requestAnimationFrame(barFit); fitDocZoom(); placePathSide(); requestAnimationFrame(placePathSide); requestAnimationFrame(fitDocZoom); setTimeout(fitDocZoom, 250); hideEmptyTopBars(); hideDupH2(); infoTips(); fileButtons(); pairFields(); growInputs(); adaptTables(); requestAnimationFrame(scrollHints); }catch(e){ console.error('pageTidy', e); } }
function markDupTitle(){
  const h = document.querySelector('#app h1'); if(!h) return;
  const a = document.querySelector('#app .adm-t2.active');
  const t = s => (s||'').replace(/\s+/g,' ').trim();
  h.classList.toggle('m-dup-title', !!(a && (t(h.textContent)===t(a.textContent) || h.hasAttribute('data-m-hide'))) || h.hasAttribute('data-m-hide'));
}
function mTabCus(){ const b = (state._mActs||[]).find(x=>x.getAttribute('data-on-click')==='openCustodyOfRequest'); if(b) b.click(); }
function mTabOne(){ const b = (state._mActs||[]).find((x,i)=>i!==state._mMain); if(b) b.click(); }
function mTabMain(){ const b = (state._mActs||[])[state._mMain]; if(!b) return; if(b.disabled){ showToast(b.getAttribute('title') || 'هذا الزر غير متاح الآن', 'error'); return; } b.click(); }
function mTabMore(){
  const acts = (state._mActs||[]).filter((b,i)=>i!==state._mMain);
  const ov = document.createElement('div'); ov.className = 'mtab-sheet no-print';
  ov.innerHTML = `<div class="mtab-sheet-in"><h3>أزرار الصفحة</h3></div>`;
  const box = ov.firstElementChild;
  acts.forEach(b=>{
    const c = document.createElement('button'); c.type = 'button';
    c.className = (b.className||'').replace(/\bbtn-(lg2?|md2?|sm2?|xs2?)\b/g,'') + ' btn-md';
    c.textContent = (b.textContent||'').trim(); c.disabled = !!b.disabled;
    box.appendChild(c);
    if(b.disabled && b.getAttribute('title')){ const w = document.createElement('div'); w.className = 'why'; w.textContent = b.getAttribute('title'); box.appendChild(w); }
    c.addEventListener('click', ()=>{ ov.remove(); b.click(); });
  });
  const x = document.createElement('button'); x.type='button'; x.className='btn btn-ghost btn-md'; x.textContent='إغلاق'; box.appendChild(x);
  x.addEventListener('click', ()=>ov.remove()); ov.addEventListener('click', e=>{ if(e.target===ov) ov.remove(); });
  document.body.appendChild(ov);
}
function syncBottomBarMetrics(){
  const vis = el => el && getComputedStyle(el).display !== 'none';
  const bar = document.querySelector('.global-floating-bar') || document.querySelector('.sticky-submit-bar');
  const barH = vis(bar) ? Math.ceil(bar.getBoundingClientRect().height) : 0;
  const mt = document.getElementById('mTab');
  const mtH = vis(mt) ? Math.ceil(mt.getBoundingClientRect().height) : 0;
  const h = barH + mtH;
  document.documentElement.style.setProperty('--bar-h', h + 'px');
  document.querySelectorAll('.gfb-spacer').forEach(sp=>{ sp.style.height = (h + 10) + 'px'; });
  // الشاشات التي لا شريط عائم فيها تحتاج هامشاً أسفل المحتوى كي لا يختفي خلف شريط التبويب
  const app = document.getElementById('app');
  if(app) app.style.paddingBottom = mtH && !document.querySelector('.gfb-spacer') ? (mtH + 24) + 'px' : '';
}
// التبويب النشط يجب أن يُرى: شريط التبويبات يمرّر نفسه إليه بعد كل رسم
function scrollActiveTabIntoView(){
  document.querySelectorAll('.adm-tabs2').forEach(box=>{
    const a = box.querySelector('.adm-t2.active'); if(!a) return;
    const br = box.getBoundingClientRect(), ar = a.getBoundingClientRect();
    if(ar.right > br.right - 4)      box.scrollLeft += (ar.right - br.right) + 12;
    else if(ar.left < br.left + 4)   box.scrollLeft -= (br.left - ar.left) + 12;
  });
}
window.addEventListener('resize', syncBottomBarMetrics);
// عند الانتقال لحقل (Tab أو ضغط)، لا يبقى مخفياً خلف الشريط السفلي
document.addEventListener('focusin', function(e){
  const el = e.target;
  if(!el || !/^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName) || el.closest('.modal-box')) return;
  setTimeout(()=>{
    const bar = document.querySelector('.global-floating-bar') || document.querySelector('.sticky-submit-bar');
    if(!bar) return;
    const overlap = el.getBoundingClientRect().bottom - (bar.getBoundingClientRect().top - 12);
    if(overlap > 0) window.scrollBy({top: overlap, behavior:'auto'});
  }, 60);
});


// ===================== الدليل وخريطة الموقع (داخل النظام) =====================
function openGuide(anchor){
  state.guideAnchor = anchor || '';
  state.view = 'guide'; render(); window.scrollTo(0,0);
}
function renderGuide(app){
  const a = state.guideAnchor ? '#'+encodeURIComponent(state.guideAnchor) : '';
  app.innerHTML = `
    <h1>دليل المستخدم</h1>
    <p class="sub">شرح خطوة بخطوة لكل صفحات النظام. <a href="#" data-on-click="#52" style="color:var(--blue);text-decoration:underline;">🗺️ خريطة الموقع</a></p>
    <iframe title="دليل المستخدم" src="user-guide.html${a}" style="width:100%;height:calc(100vh - 270px);min-height:420px;border:1px solid var(--line);border-radius:12px;background:#fff;"></iframe>`;
}
function openSiteMap(){ state.view = 'sitemap'; render(); window.scrollTo(0,0); }

// كل صفحة: عنوان، شرح، شرط الظهور، كود الفتح، قسمها في الدليل، وأزرارها الرئيسية
function siteMapPages(){
  const u = state.user, role = u.role, isAdmin = role==='admin';
  const P = [];
  P.push({g:'الطلبات', ico:'📋', label:'طلباتي / الرئيسية', desc:'كل طلباتك وما ينتظر قرارك مع حالة كل طلب.', js:[["#12",[]]], guide:'track',
    btns:[['+ طلب صرف جديد','يبدأ طلب صرف جديداً'],['فلاتر الحالة والبحث','تضييق القائمة بحالة الطلب أو كلمة'],['فتح الطلب','يعرض مساره وسجله وأزرار قراره']]});
  P.push({g:'الطلبات', ico:'➕', label:'طلب صرف جديد', desc:'نموذج إنشاء طلب: العنوان والبند والمستفيدون والمرفقات.', js:[["openNewRequestChoice",[]]], guide:'new',
    btns:[['إرسال','يرسل الطلب بعد نافذة المراجعة'],['إلغاء','يتجاهل المسودة'],['+ خصم / + إضافي','يفتح صندوقاً عائماً للمبلغ وحسابه وسببه'],['تعديل (للمستفيد المسجّل)','يُظهر بياناته المحفوظة لتغييرها']]});
  if(canSeeRevenues()){
    P.push({g:'المالية', ico:'💰', label:'الإيرادات', desc:'ما دخل الصندوق على كل بند.', js:[["openRevenues",[0]]], guide:'rev',
      btns:[['حذف','يحذف سجل الإيراد (لمن يملك تحكماً كاملاً)']]});
    if(pageAtLeast('revenues','full')) P.push({g:'المالية', ico:'➕', label:'إيراد جديد', desc:'تسجيل إيراد على بند.', js:[["openRevenues",[1]]], guide:'rev', btns:[['تسجيل الإيراد','يحفظ الإيراد ويقيّده في الدفتر']]});
  }
  if(canSeeRecurring()) P.push({g:'المالية', ico:'🔁', label:'القيود الدورية', desc:'قوالب المصروفات والإيرادات المتكررة وكشف ترحيلها.', js:[["openRecurring",[0]]], guide:'rec',
    btns:[['ترحيل المحدد','يرحّل الاستحقاقات المحددة إلى الدفتر'],['تخطي','يلغي استحقاقاً واحداً'],['اعتماد / تعديل / إيقاف مؤقت / إنهاء','إدارة القالب'],['استعادة','يعيد استحقاقاً متخطّى إلى الكشف'],['حفظ وإرسال للاعتماد','في نموذج «قالب جديد»']]});
  if(canSeeMonitor()) P.push({g:'المالية', ico:'📡', label:'لوحة المتابعة', desc:'من ينتظر قراره ومنذ متى، وما في يد المالية، وآخر الحركات.', js:[["openMonitor",[]]], guide:'', btns:[['تحديث','يعيد تحميل الأرقام']]});
  if(pageLevel('ledger')!=='none' || isAdmin) P.push({g:'المالية', ico:'📒', label:'دفتر الحركات', desc:'سجل كل دخول وخروج مال، مع فرز وفلاتر.', js:[["openLedger",[]]], guide:'ledger',
    btns:[['استرداد','المال عاد فعلاً بعد خروجه'],['عكس','التسجيل نفسه خطأ'],['+ قيد يدوي','تسوية أو رصيد افتتاحي']]});
  if(pageLevel('analytics')!=='none' || isAdmin) P.push({g:'المالية', ico:'📊', label:'التحليلات المالية', desc:'رسوم وأرقام المصروف والمتاح.', js:[["openAnalytics",[]]], guide:'acct', btns:[]});
  if(!isAdmin) P.push({g:'حسابي', ico:'👤', label:'حسابي', desc:'بياناتك وتوقيعك وكلمة مرورك.', js:[["openAccount",[]]], guide:'start', btns:[['حفظ','يحفظ التعديلات']]});
  P.push({g:'مساعدة', ico:'📖', label:'دليل المستخدم', desc:'الشرح الكامل داخل النظام.', js:[["openGuide",[]]], guide:'', btns:[]});
  P.push({g:'مساعدة', ico:'🗺️', label:'خريطة الموقع', desc:'كل صفحات النظام المتاحة لك.', js:[["openSiteMap",[]]], guide:'', btns:[]});
  if(canSeeAssistant() && ASSISTANT_WEBHOOK) P.push({g:'مساعدة', ico:'💬', label:'مساعد النظام الذكي', desc:'اسأل عن أي خطوة، أو ابدأ رسالتك بكلمة «ملاحظة» لتصل لمدير النظام.', js:[["openAssistant",[]]], guide:'', btns:[]});
  if(isAdmin){
    ADMIN_NAV.forEach(gp=>gp.items.forEach(it=>{
      P.push({g:'لوحة التحكم — '+gp.cat, ico:'⚙️', label:it.label, desc:'', js:adminNavAction(it), guide:'admin', btns:[]});
    }));
  }
  return P;
}
function renderSiteMap(app){
  const pages = siteMapPages(), groups = {};
  pages.forEach(p=>{ (groups[p.g] = groups[p.g] || []).push(p); });
  app.innerHTML = `
    <h1>🗺️ خريطة الموقع</h1>
    <p class="sub">كل صفحة يمكنك فتحها، مع أزرارها الرئيسية. اضغط اسم الصفحة لفتحها، و«شرح» لقراءة قسمها في الدليل. وتتغير القائمة حسب صلاحياتك.</p>
    ${Object.keys(groups).map(g=>`
      <div class="card"><h2>${escH(g)}</h2>
        ${groups[g].map(p=>`
          <div class="list-item" style="cursor:default;flex-wrap:wrap;">
            <div class="li-main">
              <b><a href="#" style="color:var(--blue);text-decoration:underline;" ${qon('click', qhs([["#17",[]]], p.js))} title="يفتح صفحة «${escH(p.label)}»">${p.ico} ${escH(p.label)}</a></b>
              ${p.desc ? `<span class="sub">${escH(p.desc)}</span>` : ''}
              ${p.btns.length ? `<span style="font-size:var(--fs-label);">${p.btns.map(b=>`<span title="${escH(b[1])}" style="display:inline-block;background:var(--paper);border:1px solid var(--line);border-radius:8px;padding:1px 8px;margin:2px 0 2px 6px;">${escH(b[0])}</span> <small class="sub">${escH(b[1])}</small>`).join('<br>')}</span>` : ''}
            </div>
            ${p.guide ? `<div><button class="btn btn-ghost btn-xs" data-on-click="openGuide" data-on-click-args="${qa([(''+(p.guide))])}" title="يفتح قسم هذه الصفحة في الدليل">شرح</button></div>` : ''}
          </div>`).join('')}
      </div>`).join('')}`;
}

function qyBackBtn(){
  const can = navCanGoBack();
  return `<button type="button" class="btn btn-ghost btn-sm qy-back" data-on-click="navBackSafe" ${can?'title="يرجع إلى الصفحة السابقة"':'disabled title="أنت في الصفحة الرئيسية"'}>→ رجوع</button>`;
}
function renderGlobalFloatingBar(){
  if(state.view==='newRequest' || state.view==='login') return '';
  let buttons = '';
  if(state.view==='dashboard'){
    buttons = `<button class="btn btn-primary btn-lg" data-on-click="openNewRequestChoice">+ طلب صرف جديد</button>`;
  } else if(state.view==='detail'){
    const req = state.requests.find(r=>r.id===state.activeReqId);
    buttons = req ? `<button class="btn btn-primary btn-md" data-on-click="openPrintPreview" data-on-click-args="${qa([(''+(req.id))])}">معاينة الطلب</button>` : '';
  } else if(state.view==='printPreview'){
    buttons = `<button class="btn btn-primary btn-lg" data-on-click="#53">طباعة / تحميل PDF</button>`;
  }
  return renderGlobalFloatingBarInner(qyBackBtn() + buttons);
}
