function exportAnalyticsData(){
  const rows = state._analyticsRows || [], meta = state._analyticsMeta || {};
  return {title:'التقرير المالي حسب الجهة', period:[meta.selMonth && meta.selMonth!=='all' ? 'شهر '+meta.selMonth : '', meta.selYear ? 'سنة '+meta.selYear : ''].filter(Boolean).join(' · '),
    head:['الجهة','عدد الطلبات المصروفة','إجمالي المصروف (د.ك)'], body: rows.map(r=>[r.name, Number(r.count)||0, Number(r.total)||0]), numIdx:new Set([2])};
}
function exportAnalyticsCSV(){
  const rows = state._analyticsRows || [];
  const meta = state._analyticsMeta || {};
  let csv = '\uFEFF';
  csv += 'الجهة,عدد الطلبات المصروفة,إجمالي المصروف (د.ك)\n';
  rows.forEach(r=>{ csv += `${csvCell(r.name)},${r.count},${r.total}\n`; });
  const blob = new Blob([csv], {type:'text/csv;charset=utf-8;'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `تقرير-مالي-${meta.selYear||''}-${meta.selMonth||'all'}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast('تم تصدير التقرير', 'success');
}

function renderAnalytics(app){
  if(canSeeExec() && (state.analyticsTab||'exec')==='exec'){ renderExecTab(app); return; }
  const role = state.user.role;
  const me = state.users.find(u=>u.id===state.user.id);
  const scopedToOwnCenter = ['employee','dept_manager'].includes(role) && !!me.centerId;
  const myCenterId = scopedToOwnCenter ? me.centerId : null;

  const now = new Date();
  const selYear = state.analyticsYear || now.getFullYear();
  const selMonth = state.analyticsMonth || 'all';

  const years = new Set([now.getFullYear()]);
  state.requests.forEach(r=>{ if(r.createdAtRaw) years.add(new Date(r.createdAtRaw).getFullYear()); });
  const yearsList = Array.from(years).sort((a,b)=>b-a);

  const buckets = {};
  if(!scopedToOwnCenter){
    buckets['company'] = {name:'مصروفات الشركة المباشرة', total:0, count:0};
  }
  state.centers.forEach(c=>{
    if(scopedToOwnCenter && c.id!==myCenterId) return;
    buckets[c.id] = {name:c.name, total:0, count:0};
  });

  state.requests.forEach(r=>{
    if(r.status!=='completed') return;
    if(r.isCancelled) return;
    if(!r.createdAtRaw) return;
    const d = new Date(r.createdAtRaw);
    if(d.getFullYear()!==Number(selYear)) return;
    if(selMonth!=='all' && (d.getMonth()+1)!==Number(selMonth)) return;

    if(r.origin==='company'){
      if(scopedToOwnCenter) return;
      buckets['company'].total += r.totalAmount;
      buckets['company'].count += 1;
    } else {
      if(scopedToOwnCenter && r.centerId!==myCenterId) return;
      if(!buckets[r.centerId]) return;
      buckets[r.centerId].total += r.totalAmount;
      buckets[r.centerId].count += 1;
    }
  });

  const rows = Object.values(buckets);
  const grandTotal = rows.reduce((s,b)=>s+b.total,0);
  const grandCount = rows.reduce((s,b)=>s+b.count,0);

  const months = [
    {v:'all', n:'كل الشهور'},{v:1,n:'يناير'},{v:2,n:'فبراير'},{v:3,n:'مارس'},{v:4,n:'أبريل'},
    {v:5,n:'مايو'},{v:6,n:'يونيو'},{v:7,n:'يوليو'},{v:8,n:'أغسطس'},
    {v:9,n:'سبتمبر'},{v:10,n:'أكتوبر'},{v:11,n:'نوفمبر'},{v:12,n:'ديسمبر'}
  ];

  let budgetCardHtml = '';
  if(canSeeBudget()){
    const budgetCenters = state.centers.filter(c=>(!scopedToOwnCenter || c.id===myCenterId) && (c.monthlyBudget!=null || c.annualBudget!=null));
    if(budgetCenters.length){
      const yr = Number(selYear);
      const monthName = selMonth==='all' ? '' : (months.find(m=>String(m.v)===String(selMonth))||{}).n;
      const blocks = budgetCenters.map(c=>{
        const annualHtml = budgetBarHtml('الميزانية السنوية (' + yr + ')', c.annualBudget, centerConsumed(c.id, yr, null));
        const monthlyHtml = selMonth==='all'
          ? (c.monthlyBudget!=null ? '<div class="sub" style="font-size:var(--fs-hint);margin-bottom:10px;">الميزانية الشهرية: اختر شهراً من الأعلى لعرضها.</div>' : '')
          : budgetBarHtml('الميزانية الشهرية (' + monthName + ' ' + yr + ')', c.monthlyBudget, centerConsumed(c.id, yr, Number(selMonth)-1));
        return `<div style="padding:12px 0;border-top:1px solid var(--line);"><b style="display:block;margin-bottom:8px;">${escH(c.name)}</b>${monthlyHtml}${annualHtml}</div>`;
      }).join('');
      budgetCardHtml = `
        <div class="card" style="margin-top:20px;">
          <h2 style="margin:0 0 4px;font-size:var(--fs-h3);">الميزانية مقابل المصروف</h2>
          <p class="sub" style="margin:0 0 8px;font-size:var(--fs-hint);">تتلوّن الأشرطة بالكهرماني عند 80% من الميزانية وبالأحمر عند 100%. (الطلبات المصروفة وغير الملغاة فقط)</p>
          ${blocks}
        </div>`;
    }
  }

  app.innerHTML = wrapWithAdminSidebar(`
    <h1>التحليلات المالية</h1>
    ${analyticsTabsHtml('details')}
    <p class="sub">${scopedToOwnCenter ? 'إجمالي المصروف الفعلي لمركزك' : 'إجمالي المصروف الفعلي لكل المراكز والشركة'} (الطلبات المصروفة فقط)</p>
    <div class="filt-bar filt-narrow no-print">
      <div><label>السنة</label>
        <select id="analyticsYear" data-on-change="#54">
          ${yearsList.map(y=>`<option value="${y}" ${y==selYear?'selected':''}>${y}</option>`).join('')}
        </select>
      </div>
      <div><label>الشهر</label>
        <select id="analyticsMonth" data-on-change="#55">
          ${months.map(m=>`<option value="${m.v}" ${m.v==selMonth?'selected':''}>${m.n}</option>`).join('')}
        </select>
      </div>
      <div style="flex:0 0 auto;max-width:none;">
        ${qyExportBtn('exportAnalyticsData')}
      </div>
    </div>

    <div class="card" style="margin-top:20px;">
      <table class="amount-table">
        <thead><tr><th>الجهة</th><th>عدد الطلبات المصروفة</th><th>إجمالي المصروف (د.ك)</th></tr></thead>
        <tbody>
          ${rows.map(b=>`<tr><td>${escH(b.name)}</td><td>${b.count}</td><td class="num">${fmtKWDHtml(b.total)}</td></tr>`).join('')}
        </tbody>
      </table>
      <div class="amount-box" style="margin-top:14px;">
        <span class="amount-num">الإجمالي الكلي: ${fmtKWDHtml(grandTotal)} د.ك</span>
        <span class="amount-words">(${grandCount} طلب مصروف)</span>
      </div>
    </div>
    ${budgetCardHtml}
  `);
  state._analyticsRows = rows;
  state._analyticsMeta = {selYear, selMonth};
}

// ===================== إسناد المعاملات =====================
const HO_REASONS = {leave:'ترك العمل نهائياً', transfer:'نقل إلى شركة/جهة أخرى', vacation:'إجازة', absence:'غياب/مهمة'};
const HO_STATUS = {pending:'بانتظار موافقة المستلِم', accepted:'مقبول', rejected:'مرفوض', cancelled:'ملغى'};
function hoToday(){ const d=new Date(); return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'); }
function hoUserName(id){ const u=(state.users||[]).find(x=>x.id===id); return u ? u.name : '(غير معروف)'; }
function hoActive(h){ const t=hoToday(); return h.status==='accepted' && h.from_date<=t && (!h.to_date || h.to_date>=t); }
function hoCovers(h, reqId){ return h.scope_all || (h.request_ids||[]).includes(reqId); }
// المعتمِدون الذين أنوب عنهم في طلب معيّن
function delegatedFromIds(userId, companyId, reqId){
  return (state.handovers||[]).filter(h=>h.to_user_id===userId && h.company_id===companyId && hoActive(h) && hoCovers(h, reqId)).map(h=>h.from_user_id);
}
function qyIsApproverOn(r, userId){
  const dl = delegatedFromIds(userId, r.companyId, r.id);
  // والمسجِّل الورقي لمعتمِد في الطلب، أو من سجّل اعتماداً ورقياً فيه
  return (r.approvalSteps||[]).some(s=>s.approverId===userId || dl.includes(s.approverId) || s.recordedBy===userId
    || (()=>{ const u = userById(s.approverId); return !!(u && u.paperApproval && (u.paperProxyIds||[]).includes(userId)); })());
}
async function loadHandovers(){
  try{
    const r = await db.from('qy_handovers').select('*').order('created_at',{ascending:false});
    if(!r.error && r.data) state.handovers = r.data;
  }catch(e){}
}
function hoCompanyUsers(excludeIds){
  return companyUsers(state.currentCompanyId).filter(u=>!(excludeIds||[]).includes(u.id));
}
function hoStatusBadge(h){
  const cls = h.status==='accepted' ? 'badge-paid' : (h.status==='rejected' ? 'badge-rejected' : 'badge-pending');
  return `<span class="badge ${cls}">${HO_STATUS[h.status]||h.status}</span>${hoActive(h)?' <span class="file-hint">(نشط الآن)</span>':''}`;
}
function hoPeriod(h){
  return 'من ' + fmtDateDMY(h.from_date) + (h.to_date ? ' إلى ' + fmtDateDMY(h.to_date) : ' — مفتوح');
}
function hoScopeText(h){
  if(h.scope_all) return 'كل المعاملات المعلّقة والقادمة';
  const ids = h.request_ids||[];
  const nums = ids.map(id=>{ const r=(state.requests||[]).find(x=>x.id===id); return r ? (r.number||'قيد المراجعة') : id; });
  return 'طلبات محددة: ' + nums.join('، ');
}
function openHandovers(){ state.hoReject=null; state.hoForm=null; state.view='handovers'; render(); window.scrollTo(0,0); }
// الإسناد يظهر حسب صلاحية الصفحة، ودائماً لمن له إسناد قائم (وصله أو أرسله) حتى لا يضيع عليه قبوله
function canSeeHandovers(){
  if(!state.user) return false;
  if(pageLevel('handovers')!=='none') return true;
  const me = state.user.id;
  return (state.handovers||[]).some(h=>h.company_id===state.currentCompanyId && (h.to_user_id===me || h.from_user_id===me) && ['pending','accepted'].includes(h.status));
}
function hoMyPendingToMeCount(){
  if(!state.user) return 0;
  return (state.handovers||[]).filter(h=>h.company_id===state.currentCompanyId && h.to_user_id===state.user.id && h.status==='pending').length;
}
function hoCard(h, mode){
  const mine = h.to_user_id===state.user.id, fromMe = h.from_user_id===state.user.id;
  const isAdmin = state.user.role==='admin';
  let actions = '';
  if(h.status==='pending' && mine) actions += `<button class="btn btn-approve btn-sm" data-on-click="hoAccept" data-on-click-args="${qa([(''+(h.id))])}">قبول الإسناد</button><button class="btn btn-reject btn-sm" data-on-click="hoRejectOpen" data-on-click-args="${qa([(''+(h.id))])}">رفض</button>`;
  if((h.status==='pending'||h.status==='accepted') && (fromMe || isAdmin)) actions += `<button class="btn btn-ghost btn-sm" data-on-click="hoCancel" data-on-click-args="${qa([(''+(h.id))])}">إلغاء الإسناد</button>`;
  if(h.status==='rejected' && h.suggested_user_id && (fromMe||isAdmin)) actions += `<button class="btn btn-primary btn-sm" data-on-click="hoReassign" data-on-click-args="${qa([(''+(h.id))])}">إسناد إلى ${escH(hoUserName(h.suggested_user_id))} (مقترح الرافض)</button>`;
  const rejForm = (state.hoReject===h.id) ? `
    <div style="margin-top:10px;padding:10px;background:var(--paper);border-radius:8px;">
      <label>سبب الرفض (مطلوب)</label>
      <textarea id="hoRejReason" rows="2" placeholder="مثال: أنا في إجازة في الفترة نفسها"></textarea>
      <label style="margin-top:8px;">الشخص الذي ترى أنه الأنسب للإسناد (اختياري)</label>
      <select id="hoRejSuggest"><option value="">بدون اقتراح</option>
        ${hoCompanyUsers([state.user.id, h.from_user_id]).map(u=>`<option value="${escH(u.id)}">${escH(u.name)} — ${escH(findRole(u.role).name)}</option>`).join('')}</select>
      <div class="actions-row"><button class="btn btn-reject btn-sm" data-on-click="hoRejectConfirm" data-on-click-args="${qa([(''+(h.id))])}">تأكيد الرفض</button><button class="btn btn-ghost btn-sm" data-on-click="#56">تراجع</button></div>
    </div>` : '';
  const _hd = h.from_date || h.created_at || '';
  return `<div class="list-item" style="display:block;" data-qyl-i data-date="${escH(_hd ? qylIso(new Date(_hd)) : '')}" data-qyl-row='${escH(JSON.stringify([_hd ? fmtDateDMY(qylIso(new Date(_hd))) : '', hoUserName(h.from_user_id), hoUserName(h.to_user_id), HO_REASONS[h.reason]||h.reason, hoScopeText(h), h.status]))}'>
    <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;">
      <div><b>${escH(hoUserName(h.from_user_id))}</b> ← إلى → <b>${escH(hoUserName(h.to_user_id))}</b></div>
      <div>${hoStatusBadge(h)}</div>
    </div>
    <div class="sub" style="margin-top:4px;">${escH(HO_REASONS[h.reason]||h.reason)} · ${hoPeriod(h)} · ${escH(hoScopeText(h))}${h.needs_approval?'':' · <i>بدون اشتراط موافقة</i>'}</div>
    ${h.note ? `<div class="sub" style="margin-top:2px;">ملاحظة: ${escH(h.note)}</div>` : ''}
    ${h.status==='rejected' ? `<div class="note-box" style="margin-top:6px;"><b>سبب الرفض:</b> ${escH(h.reject_reason||'')}${h.suggested_user_id ? ' — <b>اقتراحه:</b> '+escH(hoUserName(h.suggested_user_id)) : ''}</div>` : ''}
    ${actions ? `<div class="actions-row" style="margin-top:8px;">${actions}</div>` : ''}
    ${rejForm}
  </div>`;
}
function renderHandovers(app){
  const me = state.user, isAdmin = me.role==='admin';
  const all = (state.handovers||[]).filter(h=>h.company_id===state.currentCompanyId);
  const toMePending = all.filter(h=>h.to_user_id===me.id && h.status==='pending');
  const toMeActive = all.filter(h=>h.to_user_id===me.id && hoActive(h));
  const mineAll = all.filter(h=>h.from_user_id===me.id);
  const others = isAdmin ? all.filter(h=>h.from_user_id!==me.id) : [];
  const f = state.hoForm;
  let form = '';
  if(f){
    // «نيابةً عن موظف»: الطلبات تُحسب للموظف المختار في الخانة نفسها، ولا شيء قبل اختياره
    const onBehalf = isAdmin && !!f.onBehalf;
    const fromId = onBehalf ? (f.fromId||'') : me.id;
    const fromName = fromId ? hoUserName(fromId) : '';
    const myReqs = !fromId ? [] : state.requests.filter(r=>r.companyId===state.currentCompanyId && !r.isCancelled && r.status!=='completed' && r.status!=='rejected' && (r.approvalSteps||[]).some(s=>s.approverId===fromId && s.status==='pending'));
    const chk = new Set(f.checked||[]);
    form = `<div class="card flow" style="margin-bottom:14px;">
      <h2 style="margin:0 0 6px;font-size:var(--fs-h3);">إسناد جديد</h2>
      ${onBehalf ? `<div><label>إسناد نيابةً عن <span style="color:var(--red);">*</span></label><select id="hoFrom" data-on-change="#57">
        <option value="">— اختر الموظف —</option>
        ${hoCompanyUsers([]).map(u=>`<option value="${escH(u.id)}" ${u.id===fromId?'selected':''}>${escH(u.name)} — ${escH(findRole(u.role).name)}</option>`).join('')}</select></div>` : ''}
      <div class="row">
        <div><label>المستلِم</label><select id="hoTo"><option value="">— اختر —</option>
          ${hoCompanyUsers([fromId]).map(u=>`<option value="${escH(u.id)}" ${f.toId===u.id?'selected':''}>${escH(u.name)} — ${escH(findRole(u.role).name)}</option>`).join('')}</select></div>
        <div><label>السبب</label><select id="hoReason">${Object.keys(HO_REASONS).map(k=>`<option value="${k}" ${f.reason===k?'selected':''}>${HO_REASONS[k]}</option>`).join('')}</select></div>
      </div>
      <div class="row">
        <div><label>من تاريخ</label><input id="hoFromDate" type="date" value="${f.fromDate||hoToday()}"></div>
        <div><label>إلى تاريخ (اتركه فارغاً للإسناد المفتوح)</label><input id="hoToDate" type="date" value="${f.toDate||''}"></div>
      </div>
      <div><label>النطاق</label>
        <label style="display:flex;gap:6px;align-items:center;"><input type="radio" name="hoScope" value="all" ${f.scope!=='some'?'checked':''} style="width:auto;" data-on-change="#58"> كل المعاملات المعلّقة والقادمة</label>
        <label style="display:flex;gap:6px;align-items:center;"><input type="radio" name="hoScope" value="some" ${f.scope==='some'?'checked':''} style="width:auto;" data-on-change="#59"> طلبات محددة فقط</label>
        ${f.scope==='some' ? (!fromId ? '<p class="file-hint">اختر الموظف أولاً لتظهر الطلبات التي تنتظر قراره.</p>' : myReqs.length ? myReqs.map(r=>`<label style="display:flex;gap:6px;align-items:center;margin-right:20px;"><input type="checkbox" class="hoReqChk" value="${escH(r.id)}" style="width:auto;" ${chk.has(r.id)?'checked':''}> ${escH(r.number||'قيد المراجعة')} — ${escH(r.reason)} — ${fmtKWDPlain(r.totalAmount)}</label>`).join('') : `<p class="file-hint">لا توجد طلبات تنتظر قرار ${escH(fromName)} الآن. الإسناد يخص الطلبات التي يعتمدها الشخص؛ ومن لا يعتمد طلبات (كالموظف) لا تظهر له طلبات هنا.</p>`) : ''}
      </div>
      <label style="display:flex;gap:6px;align-items:center;margin-top:8px;"><input id="hoNeedsApproval" type="checkbox" ${f.needsApproval===false?'':'checked'} style="width:auto;"> يتطلب موافقة المستلِم (إن أُلغي الخيار يسري الإسناد فوراً)</label>
      <div><label>ملاحظة (اختياري${isAdmin?'، واكتب السبب إن كان الإسناد طارئاً':''})</label><input id="hoNote" type="text" maxlength="200" value="${escH(f.note||'')}"></div>
      <div class="actions-row"><button class="btn btn-primary btn-md" data-on-click="hoCreate">إرسال الإسناد</button><button class="btn btn-ghost btn-md" data-on-click="#60">إلغاء</button></div>
    </div>`;
  }
  const sec = (title, arr, empty)=>`<h2 style="font-size:var(--fs-h3);margin:18px 0 6px;">${title}</h2>${arr.length ? `<div data-qyl="ho_${escH(title)}" data-qyl-title="الإسناد — ${escH(title)}" data-qyl-cols='${escH(JSON.stringify(['التاريخ','من','إلى','السبب','النطاق','الحالة']))}'>${arr.map(h=>hoCard(h)).join('')}</div>` : `<p class="sub">${empty}</p>`}`;
  app.innerHTML = `
    <h1 style="margin:0;">إسناد المعاملات</h1>
    <p class="sub">عند تركك العمل أو نقلك أو سفرك أو إجازتك: أسند معاملاتك المعلّقة لزميل يعتمدها بدلاً منك، ويظهر ذلك في سجل كل طلب («بالإنابة عن»).</p>
    <div class="actions-row"><button class="btn btn-primary btn-md" data-on-click="#62">+ إسناد جديد</button>
    ${isAdmin ? `<button class="btn btn-ghost btn-md" data-on-click="#61">+ إسناد نيابةً عن موظف</button>` : ''}</div>
    ${form}
    ${sec('طلبات إسناد بانتظار ردّك', toMePending, 'لا توجد طلبات إسناد بانتظارك.')}
    ${sec('إسنادات نشطة إليك حالياً', toMeActive, 'لا توجد إسنادات نشطة إليك.')}
    ${sec('إسنادات أنشأتها', mineAll, 'لم تُنشئ أي إسناد.')}
    ${isAdmin ? sec('كل إسنادات الشركة (لمدير النظام)', others, 'لا توجد إسنادات أخرى.') : ''}`;
}
// قيم النموذج قبل إعادة رسمه (تغيير النطاق أو الموظف) حتى لا تُمسح الحقول المختارة
function hoSyncForm(){
  const f = state.hoForm; if(!f) return;
  const val = id=>{ const e = document.getElementById(id); return e ? e.value : undefined; };
  ['toId:hoTo','reason:hoReason','fromDate:hoFromDate','toDate:hoToDate','note:hoNote'].forEach(x=>{ const [k,id] = x.split(':'); const v = val(id); if(v!==undefined) f[k] = v; });
  const na = document.getElementById('hoNeedsApproval'); if(na) f.needsApproval = na.checked;
  if(document.querySelector('.hoReqChk')) f.checked = [...document.querySelectorAll('.hoReqChk:checked')].map(x=>x.value);   // تبقى الاختيارات وإن أُخفيت القائمة مؤقتاً
}
async function hoCreate(){
  const me = state.user, isAdmin = me.role==='admin';
  const f = state.hoForm; if(!f) return;
  const fromId = (isAdmin && f.onBehalf) ? ((document.getElementById('hoFrom')||{}).value || '') : me.id;
  const toId = document.getElementById('hoTo').value;
  const reason = document.getElementById('hoReason').value;
  const fromDate = document.getElementById('hoFromDate').value || hoToday();
  const toDate = document.getElementById('hoToDate').value || null;
  const scopeSome = f.scope==='some';
  const ids = scopeSome ? [...document.querySelectorAll('.hoReqChk:checked')].map(x=>x.value) : null;
  const needs = document.getElementById('hoNeedsApproval').checked;
  const note = document.getElementById('hoNote').value.trim();
  if(!fromId){ fieldErr(document.getElementById('hoFrom'), 'اختر الموظف الذي يُسند عنه'); return; }
  if(!toId){ fieldErr(document.getElementById('hoTo'), 'اختر المستلِم'); return; }
  if(toId===fromId){ showToast('لا يصح الإسناد لنفسه','error'); return; }
  if(toDate && toDate<fromDate){ showToast('تاريخ النهاية قبل البداية','error'); return; }
  if(scopeSome && !ids.length){ showToast('اختر طلباً واحداً على الأقل أو غيّر النطاق إلى «الكل»','error'); return; }
  if(isAdmin && !needs && !note){ showToast('الإسناد الفوري بلا موافقة يحتاج ملاحظة بالسبب','error'); return; }
  const row = {company_id:state.currentCompanyId, from_user_id:fromId, to_user_id:toId, reason, scope_all:!scopeSome, request_ids:ids, from_date:fromDate, to_date:toDate, needs_approval:needs, note:note||null, created_by:me.id};
  const r = await db.from('qy_handovers').insert(row).select().single();
  if(!(await dbCheck(r,'إنشاء الإسناد'))) return;
  state.hoForm = null;
  await loadHandovers();
  qyLog('handover_create','إسناد من '+hoUserName(fromId)+' إلى '+hoUserName(toId),'');
  showToast(needs ? 'أُرسل الإسناد وبانتظار موافقة المستلِم' : 'سرى الإسناد فوراً','success');
  render();
}
async function hoSetStatus(id, patch, okMsg){
  const r = await db.from('qy_handovers').update(patch).eq('id', id).select('id');
  if(!(await dbCheck(r,'تحديث الإسناد'))) return false;
  if(!r.data || !r.data.length){ showToast('لم يُنفَّذ التحديث (صلاحية؟)','error'); return false; }
  await loadHandovers(); showToast(okMsg,'success'); render(); return true;
}
function hoAccept(id){ return hoSetStatus(id, {status:'accepted'}, 'قبلت الإسناد — صرت تعتمد بدلاً منه'); }
function hoRejectOpen(id){ state.hoReject = id; render(); }
async function hoRejectConfirm(id){
  const reason = (document.getElementById('hoRejReason').value||'').trim();
  const sug = document.getElementById('hoRejSuggest').value || null;
  if(!reason){ showToast('اكتب سبب الرفض','error'); return; }
  state.hoReject = null;
  await hoSetStatus(id, {status:'rejected', reject_reason:reason, suggested_user_id:sug}, 'تم الرفض وأُبلغ صاحب الإسناد');
}
async function hoCancel(id){
  if(!confirm('إلغاء هذا الإسناد؟ تعود المعاملات لصاحبها فوراً.')) return;
  await hoSetStatus(id, {status:'cancelled'}, 'أُلغي الإسناد');
}
async function hoReassign(id){
  const h = (state.handovers||[]).find(x=>x.id===id); if(!h || !h.suggested_user_id) return;
  const row = {company_id:h.company_id, from_user_id:h.from_user_id, to_user_id:h.suggested_user_id, reason:h.reason, scope_all:h.scope_all, request_ids:h.request_ids, from_date:h.from_date, to_date:h.to_date, needs_approval:true, note:'بعد رفض '+hoUserName(h.to_user_id)+' واقتراحه', created_by:state.user.id};
  const r = await db.from('qy_handovers').insert(row).select().single();
  if(!(await dbCheck(r,'إسناد إلى المقترح'))) return;
  await loadHandovers(); showToast('أُرسل الإسناد إلى '+hoUserName(h.suggested_user_id),'success'); render();
}

// ===================== إيقاف الحساب (ترك العمل) =====================
function suspendFindings(uid){
  const reqs = state.requests.filter(r=>!r.isCancelled && r.status==='pending_decision' && (r.approvalSteps||[]).some(s=>s.approverId===uid && s.status==='pending'));
  const subs = state.users.filter(u=>u.managerId===uid || u.requestApproverId===uid || u.nextApproverId===uid);
  const hoIn = (state.handovers||[]).filter(h=>h.to_user_id===uid && (h.status==='accepted'||h.status==='pending'));
  const hoOut = (state.handovers||[]).filter(h=>h.from_user_id===uid && hoActive(h));
  const own = state.requests.filter(r=>!r.isCancelled && r.createdById===uid && r.status!=='completed' && r.status!=='rejected');
  return {reqs, subs, hoIn, hoOut, own};
}
function openSuspendCheck(uid){ if(isOwnerUser((state.users||[]).find(x=>x.id===uid))){ showToast('حساب مالك النظام لا يُوقف','error'); return; } state.suspendCheck = uid; render(); }
function closeSuspendCheck(){ state.suspendCheck = null; render(); }
function renderSuspendModal(){
  const uid = state.suspendCheck; const u = state.users.find(x=>x.id===uid); if(!u) return '';
  if(u.isSuspended){
    return `<div class="modal-overlay no-print" data-on-click="#63"><div class="modal-box" style="max-width:min(94vw,520px);">
      <h2 style="margin-top:0;">إعادة تفعيل ${escH(u.name)}</h2>
      <p class="sub">أُوقف الحساب ${u.suspendedAt ? 'بتاريخ '+fmtDateDMY(u.suspendedAt) : ''}${u.suspendedNote ? ' — '+escH(u.suspendedNote) : ''}. عند إعادة التفعيل يستطيع الدخول بحسابه نفسه ويعود لقوائم الاختيار.</p>
      <div class="actions-row"><button class="btn btn-approve btn-md" data-on-click="suspendApply" data-on-click-args="${qa([(''+(u.id)), false])}">إعادة التفعيل</button><button class="btn btn-ghost btn-md" data-on-click="closeSuspendCheck">إغلاق</button></div></div></div>`;
  }
  const f = suspendFindings(uid);
  const list = (arr, fn)=> arr.length ? '<ul style="margin:4px 0 0;padding-right:18px;">'+arr.slice(0,8).map(fn).join('')+(arr.length>8?'<li>…والمزيد</li>':'')+'</ul>' : '';
  const warn = f.reqs.length || f.subs.length;
  return `<div class="modal-overlay no-print" data-on-click="#63"><div class="modal-box" style="max-width:min(94vw,620px);max-height:90vh;overflow:auto;">
    <h2 style="margin-top:0;">فحص قبل إيقاف ${escH(u.name)}</h2>
    <p class="sub">إيقاف الحساب يمنعه من الدخول فوراً ويُنهي جلساته، وتبقى سجلاته وأسماؤه في الطلبات القديمة. لا يُحذف شيء.</p>
    <div class="note-box" style="${f.reqs.length?'border-color:var(--amber);':''}"><b>طلبات بانتظار اعتماده (${f.reqs.length}):</b> ${f.reqs.length ? list(f.reqs, r=>`<li>${escH(r.number||'قيد المراجعة')} — ${escH(r.reason)}</li>`) : 'لا يوجد.'}</div>
    <div class="note-box" style="margin-top:8px;${f.subs.length?'border-color:var(--amber);':''}"><b>مرؤوسون يتبعونه في المسار (${f.subs.length}):</b> ${f.subs.length ? list(f.subs, x=>`<li>${escH(x.name)}</li>`) : 'لا يوجد.'}</div>
    <div class="note-box" style="margin-top:8px;"><b>طلبات أنشأها ولم تكتمل (${f.own.length}):</b> تبقى وتكمل مسارها.</div>
    <div class="note-box" style="margin-top:8px;"><b>إسناد قائم:</b> ${f.hoOut.length ? 'أسند معاملاته إلى '+f.hoOut.map(h=>escH(hoUserName(h.to_user_id))).join('، ') : 'لا يوجد إسناد نشط منه.'}${f.hoIn.length ? '<br>وهو مستلِم لإسنادات من غيره (ستتعطل).' : ''}</div>
    ${(f.reqs.length && !f.hoOut.length) ? `<p class="warn-box" style="margin-top:10px;border-color:var(--red);">⛔ لا يمكن الإيقاف قبل إسناد طلباته المعلقة (${f.reqs.length}). اضغط «إسناد معاملاته نيابةً عنه» أولاً.</p>` : ''}
    ${warn ? `<p class="warn-box" style="margin-top:10px;">⚠ قبل الإيقاف أسند معاملاته إلى زميل (زر «إسناد نيابةً عنه») وأعد تعيين مدير لمرؤوسيه، وإلا توقفت طلباتهم.</p>` : ''}
    <label style="margin-top:8px;">ملاحظة الإيقاف (اختياري)</label><input id="suspNote" type="text" maxlength="150" placeholder="مثال: ترك العمل 2026-10-31">
    <div class="actions-row">
      <button class="btn btn-reject btn-md" ${(f.reqs.length && !f.hoOut.length)?'disabled title="أسند طلباته المعلقة أولاً"':''} data-on-click="suspendApply" data-on-click-args="${qa([(''+(u.id)), true])}">إيقاف الحساب الآن</button>
      <button class="btn btn-ghost btn-md" data-on-click="#64" data-on-click-args="${qa([(''+(u.id))])}">إسناد معاملاته نيابةً عنه</button>
      <button class="btn btn-ghost btn-md" data-on-click="closeSuspendCheck">إغلاق</button>
    </div></div></div>`;
}
async function suspendApply(uid, suspend){
  if(state.user.role!=='admin'){ showToast('الإيقاف من صلاحية مدير النظام','error'); return; }
  if(uid===state.user.id){ showToast('لا يمكنك إيقاف حسابك','error'); return; }
  const note = suspend ? ((document.getElementById('suspNote')||{}).value||'').trim() : '';
  if(suspend){ const f0 = suspendFindings(uid); if(f0.reqs.length && !f0.hoOut.length){ showToast('لا يمكن إيقافه قبل إسناد طلباته المعلقة ('+f0.reqs.length+') — أسندها أولاً','error'); return; } }
  const r = await db.rpc('admin_set_suspended', {p_user_id: uid, p_suspended: suspend, p_note: note||null});
  if(!(await dbCheck(r, suspend ? 'إيقاف الحساب' : 'إعادة التفعيل'))) return;
  const u = state.users.find(x=>x.id===uid);
  if(u){ u.isSuspended = suspend; u.suspendedAt = suspend ? new Date().toISOString() : null; u.suspendedNote = note; }
  qyLog(suspend?'user_suspend':'user_reactivate', (suspend?'إيقاف ':'إعادة تفعيل ')+(u?u.name:uid), '');
  state.suspendCheck = null;
  showToast(suspend ? 'أُوقف الحساب' : 'أُعيد تفعيل الحساب','success'); render();
}

// ===================== نوافذ تُضاف إلى body مباشرة (لا تمر عبر render فلا تضيع حقول النماذج المفتوحة) =====================
function qyBodyModalClose(id){ document.querySelectorAll('[data-qy-bm="'+(id||'bm')+'"]').forEach(e=>e.remove()); }
function qyBodyModal(html, id){
  qyBodyModalClose(id);
  const d = document.createElement('div'); d.className = 'modal-overlay no-print'; d.setAttribute('data-qy-bm', id||'bm'); d.dir = 'rtl';
  d.innerHTML = html;
  d.addEventListener('click', e=>{ if(e.target===d) d.remove(); });
  document.body.appendChild(d); return d;
}

// ===================== مراجعة قبل الإرسال: ملخص + ملاحظات داخلية + خيار عدم الإظهار =====================
// الإعداد لكل شركة يضبطه مدير النظام؛ في «اختيارية» يحفظ كل مستخدم اختياره في حسابه على الخادم
function reviewMode(){ const c = state.companies.find(x=>x.id===state.currentCompanyId); return (c && c.reviewMode) || 'optional'; }
function reviewSkipped(){
  const m = reviewMode();
  if(m==='required') return false;
  if(m==='off') return true;
  const me = state.user && state.users.find(u=>u.id===state.user.id);
  return !!(me && me.skipReview);
}
async function setReviewSkipped(on){
  const me = state.user && state.users.find(u=>u.id===state.user.id); if(!me) return false;
  const r = await db.from('users').update({skip_review: !!on}).eq('id', me.id);
  if(!(await dbCheck(r, 'حفظ إعداد نافذة المراجعة'))) return false;
  me.skipReview = !!on; return true;
}
function reviewBeforeSend(o){
  return new Promise(resolve=>{
    const el = qyBodyModal(`<div class="modal-box" style="max-width:min(94vw,560px);max-height:90vh;overflow:auto;text-align:right;">
      <h2 style="margin-top:0;">مراجعة قبل الإرسال</h2>
      <div class="note-box">
        <div><b>المبلغ الإجمالي:</b> ${fmtKWDHtml(o.total)} د.ك</div>
        <div class="sub" style="margin-top:4px;">${escH(amountToArabicWords(o.total))}</div>
        <div style="margin-top:6px;"><b>عدد المستفيدين:</b> ${o.count} · <b>البند:</b> ${escH(o.item||'غير محدد')}</div>
      </div>
      ${o.diffs ? `<div class="warn-box" style="margin-top:8px;border-right:4px solid var(--amber);padding:8px 12px;border-radius:8px;">⚠ ${o.diffs} مستفيد بآيبان أو رقم مدني يختلف عن المسجّل: يُحفظ لهذا الطلب فقط، وكُتبت ملحوظة بذلك، ويصل تنبيه للمالية.</div>` : ''}
      <label style="margin-top:10px;">هل لديك ملاحظات على هذا الطلب؟ (اختياري — داخلية لا تُطبع)</label>
      <textarea id="rvNotes" rows="4">${escH(o.notes||'')}</textarea>
      ${reviewMode()==='optional'
        ? `<label style="display:flex;gap:6px;align-items:center;margin-top:8px;font-weight:600;"><input id="rvSkip" type="checkbox" style="width:auto;"> لا تُظهر هذه النافذة مرة أخرى (إرسال مباشر) — تعيدها من «حسابي»</label>`
        : `<div class="sub" style="margin-top:8px;color:var(--muted);">النافذة إلزامية في هذه الشركة</div>`}
      <div class="actions-row" style="margin-top:12px;">
        <button type="button" class="btn btn-primary btn-md" id="rvSend">إرسال</button>
        <button type="button" class="btn btn-ghost btn-md" id="rvCancel">رجوع للتعديل</button>
      </div></div>`, 'review');
    const done = v => { qyBodyModalClose('review'); resolve(v); };
    el.addEventListener('click', e=>{ if(e.target===el) resolve(null); });
    el.querySelector('#rvCancel').onclick = ()=>done(null);
    el.querySelector('#rvSend').onclick = ()=>{
      const sk = el.querySelector('#rvSkip');
      if(sk && sk.checked) setReviewSkipped(true);
      done({notes: el.querySelector('#rvNotes').value.trim()});
    };
  });
}

// ===================== فحص قبل نقل مستخدم من شركة =====================
function moveFindings(uid, removedIds){
  const inCo = r => removedIds.includes(r.companyId) && !r.isCancelled;
  const reqs = state.requests.filter(r=>inCo(r) && r.status==='pending_decision' && (r.approvalSteps||[]).some(s=>s.approverId===uid && s.status==='pending'));
  const own  = state.requests.filter(r=>inCo(r) && r.createdById===uid && r.status!=='completed' && r.status!=='rejected');
  const subs = state.users.filter(x=>x.id!==uid && removedIds.some(c=>userHasCompany(x,c)) && (x.managerId===uid || x.requestApproverId===uid || x.nextApproverId===uid));
  return {reqs, own, subs};
}
function showMoveCheck(u, removedIds, f){
  const list = (arr, fn)=> arr.length ? '<ul style="margin:4px 0 0;padding-right:18px;">'+arr.slice(0,8).map(fn).join('')+(arr.length>8?'<li>…والمزيد</li>':'')+'</ul>' : '';
  const coNames = removedIds.map(id=>(state.companies.find(c=>c.id===id)||{}).nameAr||id).join('، ');
  qyBodyModal(`<div class="modal-box" style="max-width:min(94vw,640px);max-height:90vh;overflow:auto;text-align:right;">
    <h2 style="margin-top:0;">تنبيه قبل نقل ${escH(u.name)} من: ${escH(coNames)}</h2>
    <p class="sub">هذا المستخدم له ارتباطات قائمة في الشركة التي سيخرج منها. نقله دون ترتيب يُعطّل المسار فلا تظهر الطلبات لأحد.</p>
    ${f.reqs.length ? `<div class="note-box" style="border-color:var(--amber);"><b>طلبات بانتظار اعتماده (${f.reqs.length}):</b>${list(f.reqs, r=>`<li>${escH(r.number||'قيد المراجعة')} — ${escH(r.reason)}</li>`)}</div>` : ''}
    ${f.own.length ? `<div class="note-box" style="margin-top:8px;"><b>طلبات أنشأها ولم تكتمل (${f.own.length}):</b> تكمل مسارها، وقد تعود إليه للتعديل. يبقى يراها ويعدّلها من لوحة طلباته (قسم «طلباتي في شركاتي الأخرى») بعد نقله.${list(f.own, r=>`<li>${escH(r.number||'قيد المراجعة')} — ${escH(r.reason)}</li>`)}</div>` : ''}
    ${f.subs.length ? `<div class="note-box" style="margin-top:8px;border-color:var(--amber);"><b>مرؤوسون يتبعونه (${f.subs.length}):</b>${list(f.subs, x=>`<li>${escH(x.name)}</li>`)}</div>` : ''}
    <div class="actions-row" style="margin-top:12px;">
      <button class="btn btn-primary btn-md" data-on-click="#65" data-on-click-args="${qa([(''+(u.id))])}">أسند معاملاته أولاً</button>
      <button class="btn btn-reject btn-md" data-on-click="#66">انقل على أي حال</button>
      <button class="btn btn-ghost btn-md" data-on-click="qyBodyModalClose" data-on-click-args="${qa(["move"])}">إلغاء</button>
    </div></div>`, 'move');
}

// ===================== فحص المسارات: المحفوظ في كل طلب مقابل مسار الشركة الآن =====================
function pathCheckRows(companyId){
  const nm = id => (state.users.find(u=>u.id===id)||{}).name || 'غير معروف';
  const TAILS = ['pending_transfer_request','pending_transfer_approval','pending_disbursement'];
  const skipped = r => TAILS.includes(r.status) && !(r.approvalSteps||[]).length && !(r.history||[]).some(h=>String(h.action||'').startsWith('اعتماد'));
  return state.requests.filter(r=>r.companyId===companyId && !r.isCancelled && (r.status==='pending_decision' || skipped(r))).map(r=>{
    const creator = state.users.find(u=>u.id===r.createdById);
    const saved = (r.approvalSteps||[]).slice().sort((a,b)=>a.sequenceOrder-b.sequenceOrder);
    const now = creator ? computeApprovalChainPreview(creator.id, companyId) : {chain:[], error:'صاحب الطلب غير موجود'};
    const nowIds = now.chain.map(u=>u.id);
    const pend = saved.filter(s=>s.status==='pending').map(s=>s.approverId);
    let st = 'ok', why = 'سليم';
    if(r.status!=='pending_decision'){
      if(now.error){ st='bad'; why = now.error; }
      else if(now.chain.length && !(creator && creator.directToTransfer)){ st='skip'; why='انتقل إلى المحاسب دون أن يمر بمعتمديه ('+now.chain.map(u=>u.name).join(' ← ')+') ولا اعتماد مسجّل'; }
      else { st='ok'; why='لا معتمدين لصاحب الطلب (مسار فارغ)'; }
    }
    else if(now.error){ st='bad'; why = now.error; }
    else {
      const badId = pend.find(id=>{ const a = state.users.find(u=>u.id===id); return !a || a.isSuspended || !userHasCompany(a, companyId); });
      if(badId){ const a = state.users.find(u=>u.id===badId); st='bad'; why = 'معتمِد الخطوة «'+nm(badId)+'» '+(!a?'غير موجود':a.isSuspended?'موقوف الحساب':'لم يعد مرتبطاً بشركة الطلب'); }
      else if(pend.length && pend.join('|') !== nowIds.slice(nowIds.length-pend.length).join('|')){ st='diff'; why='يختلف عن مسار الشركة الآن'; }
    }
    return {r, creator, saved, nowNames: now.chain.map(u=>u.name), st, why, nm};
  });
}
function openPathCheck(){
  if(!state._pcCo){
    const w = state.companies.find(c=>pathCheckRows(c.id).some(x=>x.st!=='ok'));
    state._pcCo = (w||{}).id || state.currentCompanyId;
  }
  state.view='pathCheck'; render(); window.scrollTo(0,0);
}
function pathBadgeHtml(st){
  return st==='skip' ? '<span style="color:#b42318;font-weight:700;">⤼ تخطّى القرار</span>' : st==='ok' ? '<span style="color:#15803d;font-weight:700;">✓ سليم</span>' : st==='diff' ? '<span style="color:#b45309;font-weight:700;">≠ مختلف</span>' : '<span style="color:#b42318;font-weight:700;">⛔ معطّل</span>';
}
function renderPathCheckPage(app){
  const co = state._pcCo || state.currentCompanyId;
  const rows = pathCheckRows(co);
  const bad = rows.filter(x=>x.st!=='ok');
  const cards = rows.length ? rows.map(x=>{
    const savedTxt = x.saved.map(s=>`${escH(x.nm(s.approverId))}${s.status==='approved'?' ✓':s.status==='pending'?' ⏳':''}`).join(' ← ') || '—';
    const bc = x.st==='ok' ? '#15803d' : x.st==='diff' ? '#b45309' : '#b42318';
    return `<div class="card" style="cursor:pointer;border-right:5px solid ${bc};margin-bottom:10px;" data-on-click="openRequest" data-on-click-args="${qa([(''+(x.r.id))])}">
      <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center;">
        <div><b>${escH(x.r.number||'قيد المراجعة')}</b> — ${escH(x.r.reason||'')}</div>
        <div>${pathBadgeHtml(x.st)}</div>
      </div>
      <div class="sub" style="margin:4px 0;">صاحب الطلب: ${escH(x.creator?x.creator.name:'—')} · المبلغ: ${fmtKWDHtml(x.r.totalAmount)} د.ك</div>
      <div style="font-size:var(--fs-label);margin-bottom:6px;">${escH(x.why)}</div>
      <div style="font-size:var(--fs-hint);"><b>المحفوظ في الطلب:</b> ${savedTxt}</div>
      <div style="font-size:var(--fs-hint);"><b>مسار الشركة الآن:</b> ${x.nowNames.length ? x.nowNames.map(escH).join(' ← ') : '—'}</div>
      <div class="actions-row pc-actions" style="margin-top:8px;" data-on-click="#67">
        <button class="btn btn-ghost btn-xs" data-on-click="openRequest" data-on-click-args="${qa([(''+(x.r.id))])}">فتح الطلب</button>
        ${x.st==='ok' ? '' : `<button class="btn btn-ghost btn-xs" data-on-click="pathCheckRebuild" data-on-click-args="${qa([(''+(x.r.id))])}">${x.st==='skip'?'إعادة إلى القرار':'إعادة بناء المسار'}</button>`}
      </div></div>`;
  }).join('') : '<div class="empty">لا توجد طلبات قيد القرار في هذه الشركة.</div>';
  app.innerHTML = `<h1>فحص المسارات</h1>
    <p class="sub">يقارن المسار المحفوظ في كل طلب قيد القرار بالمسار الذي كان سيُبنى لو أُنشئ الطلب اليوم. للقراءة فقط؛ لا يتغير شيء إلا بضغطك «إعادة بناء المسار». اضغط على أي بطاقة لفتح الطلب.</p>
    <label>الشركة</label>
    <select data-on-change="#68" style="max-width:360px;">${state.companies.map(c=>`<option value="${c.id}" ${c.id===co?'selected':''}>${escH(c.nameAr)}${pathCheckRows(c.id).some(x=>x.st!=='ok')?' ⚠':''}</option>`).join('')}</select>
    <p class="file-hint">${bad.length ? 'يحتاج مراجعة: '+bad.length+' من '+rows.length : 'كل المسارات سليمة'}</p>
    <div style="margin-top:8px;">${cards}</div>`;
}
async function pathCheckRebuild(reqId){
  const req = state.requests.find(r=>r.id===reqId); if(!req) return;
  await rebuildRequestPathAndReset(req);
  render();
}

