// المجموعة النشطة: تُستنتج من البند المفتوح؛ وإن لم يُعرف أي بند يبقى آخر اختيار
function activeAdminGroup(){
  for(const g of ADMIN_NAV){ if(g.items.some(it=>adminNavIsActive(it))) return g; }
  return ADMIN_NAV.find(g=>g.gkey===state.adminGroup) || ADMIN_NAV[0];
}
function openAdminGroup(gkey){
  const g = ADMIN_NAV.find(x=>x.gkey===gkey); if(!g) return;
  state.adminGroup = gkey;
  // لو البند المفتوح يتبع هذه المجموعة أصلاً، لا تنقل المستخدم
  if(g.items.some(it=>adminNavIsActive(it))){ render(); window.scrollTo(0,0); return; }
  qyRunJs(adminNavAction(g.items[0]));
}
function adminNavAction(item){
  if(item.kind==='view') return [["#18",[(''+(item.key))]]];
  if(item.kind==='tab') return [["#19",[(''+(item.key))]]];
  if(item.kind==='seclog') return [["#20",[(''+(item.key))]]];
  if(item.kind==='exec') return [["#21",[]]];
  if(item.kind==='sigFinal') return [["#22",[]]];
  if(item.kind==='sigMini') return [["#23",[]]];
  return '';
}
function adminSectionHeadHtml(){
  for(const g of ADMIN_NAV){ for(const it of g.items){ if(adminNavIsActive(it)) return `<div class="admin-section-head"><h2>${escH(it.head||it.label)}</h2><span class="admin-co-badge" title="الشركة الحالية — بدّلها من الأعلى">${escH((state.companies.find(c=>c.id===state.currentCompanyId)||{}).nameAr||'—')}</span></div>`; } }
  return '';
}
// رأس لوحة التحكم: صف عنوان + صف البنود العامة + صف تبويبات البند المفتوح
// ملاحظة RTL: العنصر الأول في الكود يظهر أقصى اليمين، وmargin-right:auto يدفع لليسار
function adminHeaderHtml(){
  const grp = activeAdminGroup();
  const coName = (state.companies.find(c=>c.id===state.currentCompanyId)||{}).nameAr || '—';
  const subTabs = grp.items.map(it=>
    `<button class="adm-t2${adminNavIsActive(it)?' active':''}" ${qon('click', adminNavAction(it))}>${escH(it.tab||it.label)}</button>`
  ).join('');
  // صفّان لا ثلاثة: اسم المجموعة هو العنوان، فلا حاجة لسطر «لوحة تحكم مدير النظام» فوقه —
  // المستخدم يعرف أنه في لوحة التحكم، ولا يعرف ثلث شاشة الهاتف المهدور فوق المحتوى.
  return `
    <div class="adm-head">
      <h1>${escH(grp.cat)}</h1>
      <span class="admin-co-badge" style="margin-right:auto;" title="الشركة الحالية — بدّلها من الأعلى">${escH(coName)}</span>
    </div>
    <div class="adm-nav2">
      <div class="adm-tabs2">${subTabs}</div>
      <div id="secTabs"></div>
    </div>`;
}
// ───────── الصفّ الفاتح: تبويبات أقسام الصفحة ─────────
// الأقسام تُقرأ من الصفحة نفسها لا من سجلّ يدوي: كل عنوان h2 في المستوى الأعلى
// يبدأ قسماً، وما بعده حتى العنوان التالي يتبعه. فأي قسم يُضاف للصفحة مستقبلاً
// يصير تبويباً من تلقاء نفسه، ولا يبقى سجلٌّ يتخلّف عن الشفرة.
const SECTIONED_PAGES = ['companies','centers','users','roles','budgetItems','branding','printSetup'];
// نماذج التعديل تعيش داخل قسم القائمة، فعناوينها لا تبدأ قسماً جديداً
const SEC_SKIP  = /^(تعديل|تحرير)/;
// أقسام الإنشاء تُؤخَّر إلى آخر الصفّ: الدخول للتعديل أكثر من الدخول للإنشاء
const SEC_IS_NEW = /^(إضافة|تسجيل|إنشاء)/;
const SEC_SHORT = [
  [/^إضافة شركة/,'شركة جديدة'],           [/^الشركات الحالية/,'الشركات'],
  [/^إضافة وحدة تنظيمية/,'وحدة جديدة'],    [/^وحدات الشركة/,'وحدات الشركة'],
  [/^أنواع الوحدات/,'أنواع الوحدات'],
  [/^إضافة مستخدم/,'مستخدم جديد'],         [/^مستخدمو الشركة/,'المستخدمون'],
  [/^إضافة دور/,'دور جديد'],               [/^الأدوار الوظيفية/,'الأدوار الوظيفية'],
  [/^الأدوار النظامية/,'الأدوار النظامية'],
  [/^إضافة بند/,'بند جديد'],               [/^بنود الميزانية/,'البنود'],
  [/^تسجيل إيراد/,'إيراد جديد'],           [/^الإيرادات المسجلة/,'الإيرادات'],
  [/^هوية النظام/,'هوية النظام'],          [/^هوية الشركة/,'هوية الشركة'],
  [/^ترويسة الشركة/,'ترويسة الشركة'],      [/^التذييل وترقيم/,'التذييل والترقيم'],
  [/^ترويسة وتذييل المراكز/,'ترويسة المراكز']
];
function shortSecLabel(t){
  for(const [re,lab] of SEC_SHORT){ if(re.test(t)) return lab; }
  return t.length > 24 ? t.slice(0,23)+'…' : t;
}
function setPageSec(key, i){
  state.pageSec = state.pageSec || {};
  state.pageSec[key] = i;
  render(); window.scrollTo(0,0);
}
function applyPageSections(){ applyPageSectionsInner(); fillSecNote(); }
function applyPageSectionsInner(){
  const host = document.getElementById('secTabs');
  if(host && host.closest('.adm-nav2[data-gn]')) return;      // خارج لوحة التحكم: الصف الثاني لسطر التعريف وحده
  if(host && !host.dataset.keep){
    const note = host.querySelector('.sec-note');
    if(note && note.dataset.moved){ const p = document.createElement('p'); p.className = 'sub page-intro'; while(note.firstChild) p.appendChild(note.firstChild); const nv = host.closest('.adm-nav2'); if(nv) nv.after(p); }
    host.innerHTML = '';
  }
  const app = document.getElementById('app'); if(!app) return;

  // صفحة بنت صفَّها الفاتح بنفسها (التحليلات، الهيكل، التقرير): انقله إلى داخل
  // الكتلة ليلتصق بالصفّ الداكن. ومن لا كتلة عنده يُبقيه مكانه بحدوده الخاصة.
  const own = app.querySelector('.adm-subs-solo');
  if(own){
    if(host){ own.classList.remove('adm-subs-solo'); host.appendChild(own); }
    return;
  }
  const key = (state.view==='admin') ? state.adminSubTab : null;
  if(!key || !SECTIONED_PAGES.includes(key)) return;

  const skip = el => el.id==='secTabs' || el.classList.contains('adm-head') ||
                     el.classList.contains('adm-tabs2') || el.classList.contains('gfb-spacer') || el.classList.contains('modal-overlay') ||
                     el.classList.contains('global-floating-bar');
  const secs = []; let cur = null;
  for(const el of Array.from(app.children)){
    if(skip(el)){ continue; }
    const h = (el.tagName==='H2') ? el : el.querySelector('h2');
    const txt = h ? h.textContent.trim() : '';
    if(h && txt && !SEC_SKIP.test(txt)){ cur = {title:txt, isNew:SEC_IS_NEW.test(txt), els:[el]}; secs.push(cur); }
    else if(cur){ cur.els.push(el); }
    // ما قبل أول قسم (لافتة طلبات إعادة التعيين مثلاً) يبقى ظاهراً دائماً
  }
  if(secs.length < 2) return;                       // قسم واحد: لا داعي لصفّ تبويبات
  const order = secs.map((s,i)=>({s,i}))
                    .sort((a,b)=> (a.s.isNew - b.s.isNew) || (a.i - b.i))
                    .map(x=>x.s);
  let idx = (state.pageSec && state.pageSec[key]) || 0;
  if(idx < 0 || idx >= order.length) idx = 0;
  order.forEach((s,i)=> s.els.forEach(el=>{ el.hidden = (i !== idx); }));
  if(host) host.innerHTML = `<div class="adm-subs">${order.map((s,i)=>
    `<button type="button" class="adm-sub${i===idx?' active':''}" data-on-click="setPageSec" data-on-click-args="${qa([(''+(key)), (i)])}">${escH(shortSecLabel(s.title))}</button>`
  ).join('')}</div>`;
}
function adminNavIsActive(item){
  if(item.kind==='tab') return state.view==='admin' && state.adminSubTab===item.key;
  if(item.kind==='view') return state.view===item.key;
  // اللوحة التنفيذية والتفاصيل المالية قسمان في صفحة واحدة، فكلاهما يُبقي الصفحة نشطة
  if(item.kind==='seclog') return state.view==='securityLog' && (state.secTab||'alerts')===item.key;
  if(item.kind==='exec') return state.view==='analytics';
  if(item.kind==='sigFinal') return state.view==='sigDesigner' && state.sigDesignerContext==='final';
  if(item.kind==='sigMini') return state.view==='sigDesigner' && state.sigDesignerContext==='mini';
  return false;
}
function buildAdminSidebar(){
  return `
    <input id="adminNavSearch" type="search" class="qy-search" placeholder="ابحث بالأقسام..." data-on-input="filterAdminNav" data-on-input-args="${qa([QA.v])}" style="margin-bottom:12px;">
    <div id="adminNavList">
      ${ADMIN_NAV.map(group=>`
        <div class="admin-nav-group" data-nav-group>
          <div class="admin-nav-cat">${escH(group.cat)}</div>
          ${group.items.map(item=>`
            <div class="admin-nav-item${adminNavIsActive(item) ? ' active':''}" data-nav-item data-nav-label="${escH(item.label)}" ${qon('click', adminNavAction(item))}>${escH(item.label)}</div>
          `).join('')}
        </div>
      `).join('')}
    </div>`;
}
// يلف أي صفحة مستقلة بنفس إطار الشريط الجانبي، فقط لمدير النظام (باقي الأدوار تشوف الصفحة بعرضها الكامل كالمعتاد)
function wrapWithAdminSidebar(contentHtml){
  if(!state.user || state.user.role!=='admin' || !inAdminArea()) return contentHtml;
  // التنقل صار بالشريط الجانبي العام؛ هنا عنوان موحّد + حذف رابط "رجوع" والعنوان الداخلي القديم
  let stripped = contentHtml.replace(/<span class="back-link[^"]*"[^>]*>→ رجوع<\/span>/g, '');
  stripped = stripped.replace(/<h1[^>]*>[\s\S]*?<\/h1>/, '');
  return `${adminHeaderHtml()}${stripped}`;
}
