function startLevelNameEdit(el,id){
  const cur = el.textContent;
  el.outerHTML = `<span style="display:inline-flex;gap:4px;"><input type="text" id="levelNameInput" value="${escH(cur)}" style="min-height:40px;padding:2px 8px;width:auto;min-width:140px;"><button type="button" class="btn btn-primary btn-xs" data-on-click="saveLevelName" data-on-click-args="${qa([(''+(id))])}">حفظ</button></span>`;
  const inp = document.getElementById('levelNameInput'); if(inp){ inp.focus(); inp.select(); }
}
async function saveLevelName(id){
  const val = (document.getElementById('levelNameInput').value||'').trim();
  if(!val) return;
  const result = await db.from('job_levels').update({name:val}).eq('id', id);
  if(!(await dbCheck(result, 'تعديل اسم المستوى'))) return;
  const l = state.jobLevels.find(x=>x.id===id); if(l) l.name = val;
  render();
}
async function seedDefaultLevels(){
  const companyId = state.jobLevelsCompanyId;
  const defaults = ['المدير العام','المدير التنفيذي','المدير المالي','مدير الإدارة / المركز','المحاسب','موظف'];
  const rows = defaults.map((name,i)=>({id:genId('lvl'), company_id:companyId, name, sort_order:i+1}));
  const result = await db.from('job_levels').insert(rows);
  if(!(await dbCheck(result, 'توليد السلّم الافتراضي'))) return;
  rows.forEach(r=> state.jobLevels.push({id:r.id, companyId:r.company_id, name:r.name, sortOrder:r.sort_order}));
  showToast('تم توليد السلّم الافتراضي', 'success');
  render();
}
async function addJobLevel(){
  const companyId = state.jobLevelsCompanyId;
  const levels = levelsForCompany(companyId);
  const sortOrder = levels.length ? Math.max.apply(null, levels.map(l=>l.sortOrder))+1 : 1;
  const row = {id:genId('lvl'), company_id:companyId, name:'مستوى جديد', sort_order:sortOrder};
  const result = await db.from('job_levels').insert(row);
  if(!(await dbCheck(result, 'إضافة مستوى'))) return;
  state.jobLevels.push({id:row.id, companyId:row.company_id, name:row.name, sortOrder:row.sort_order});
  render();
}
async function moveLevel(id, dir){
  const levels = levelsForCompany(state.jobLevelsCompanyId);
  const idx = levels.findIndex(l=>l.id===id);
  const swapIdx = idx+dir;
  if(idx<0 || swapIdx<0 || swapIdx>=levels.length) return;
  const a = levels[idx], b = levels[swapIdx];
  const oa = a.sortOrder, ob = b.sortOrder;
  const r1 = await db.from('job_levels').update({sort_order:ob}).eq('id', a.id);
  if(!(await dbCheck(r1, 'إعادة الترتيب'))) return;
  const r2 = await db.from('job_levels').update({sort_order:oa}).eq('id', b.id);
  if(!(await dbCheck(r2, 'إعادة الترتيب'))) return;
  a.sortOrder = ob; b.sortOrder = oa;
  render();
}
function deleteLevel(id){
  requestDeleteConfirm('حذف هذا المستوى من السلّم؟ المستخدمون المرتبطون به يرجعون للمستوى الافتراضي حسب دورهم.', 'jobLevel', id);
}
async function performDeleteJobLevel(id){
  const result = await db.from('job_levels').delete().eq('id', id);
  if(!(await dbCheck(result, 'حذف المستوى'))) return;
  state.jobLevels = state.jobLevels.filter(l=>l.id!==id);
  state.users.forEach(u=>{ if(u.levelId===id) u.levelId = null; });
  showToast('تم حذف المستوى', 'success');
  render();
}

