function onRoleDefaults(which){
  const roleEl = document.getElementById(which==='new' ? 'newUserRole' : 'editUserRole'); if(!roleEl) return;
  const cr = state.customRoles.find(x=>x.id===roleEl.value); if(!cr) return;
  const gen = document.getElementById(which==='new' ? 'newUserGeneral' : 'editUserGeneral');
  if(gen){ gen.checked = !!cr.generalDefault; if(which==='edit' && typeof toggleGeneralAccess==='function') toggleGeneralAccess(); }
  if(which==='edit'){
    const lvEl = document.getElementById('editUserLevel'); const u = state.users.find(x=>x.id===state.editingUserId);
    if(lvEl && u){ const lv = jobRoleLevel(cr.id, u.companyId); lvEl.value = lv ? lv.id : ''; }
  }
}

// ===================== الأدوار الوظيفية (دور واحد للمؤسسة كلها) =====================
function jobRoleUsersCount(id){ return state.users.filter(u=>u.role===id).length; }
// ── إعادة التحقق بكلمة المرور (للإجراءات الحساسة) ──
async function reauthModal(title, text, confirm){
  const a = await askModal({title, text, confirm: confirm||'تأكيد',
    fields:[{id:'pw', label:'أدخل كلمة مرور حسابك للتأكيد *', type:'password'}],
    validate:v=> v.pw ? null : 'أدخل كلمة المرور'});
  if(!a) return false;
  const me = (state.users||[]).find(u=>u.id===state.user.id);
  const { error } = await db.auth.signInWithPassword({ email: loginIdToEmail(me.phone), password: a.pw });
  if(error){ qyLog('login_failed','فشل تأكيد كلمة المرور قبل عملية حساسة','', (me&&me.phone)||''); showToast('كلمة المرور غير صحيحة','error'); return false; }
  return true;
}

// ── القيود الدورية: من ينشئ القوالب ──
function renderRecCreatorsPanel(){
  if(!state.user || state.user.role!=='admin') return '';
  const us = (state.users||[]).filter(u=>u.companyId===state.currentCompanyId && !['admin','accountant','cfo'].includes(u.role));
  const groups = {};
  us.forEach(u=>{ (groups[u.role] = groups[u.role] || []).push(u); });
  const body = Object.keys(groups).length ? roleOrderedKeys(Object.keys(groups)).map(r=>`
    <details class="gp-group" open><summary><b>${escH(roleGroupLabel(r))}</b> <span class="sub">(${groups[r].length})</span></summary>
      <div class="gp-body">${groups[r].map(u=>`<label><input type="checkbox" ${u.canManageRecurring?'checked':''} data-on-change="toggleRecurringPerm" data-on-change-args="${qa([(''+(u.id)), QA.c])}"> ${escH(u.name)}</label>`).join('')}</div>
    </details>`).join('') : '<div class="empty">لا يوجد مستخدمون آخرون في هذه الشركة</div>';
  return `<div class="card" style="margin-top:28px;"><h2>من يُنشئ قوالب القيود الدورية</h2>
    <p class="sub">المحاسب والمدير المالي ومدير النظام يُنشئون القوالب دائماً. هنا تمنح الصلاحية لموظفين آخرين. والاعتماد يبقى للمدير المالي أو مدير النظام.</p>${body}</div>`;
}

