async function saveRecNotify(){
  const roles = Array.from(document.querySelectorAll('.rnRole:checked')).map(x=>x.value);
  const ids = Array.from(document.querySelectorAll('.rnUser:checked')).map(x=>x.value);
  if(!roles.length && !ids.length){ showToast('اختر مستلماً واحداً على الأقل','error'); return; }
  const row = {company_id: state.currentCompanyId, approval_notify_roles: roles, approval_notify_user_ids: ids,
    updated_by: state.user.name, updated_at: new Date().toISOString()};
  const r = await db.from('recurring_settings').upsert(row, {onConflict:'company_id'});
  if(!(await dbCheck(r,'حفظ إشعارات الاعتماد'))) return;
  state.recurringSettings = (state.recurringSettings||[]).filter(x=>x.company_id!==row.company_id).concat([row]);
  showToast('حُفظت إعدادات إشعارات الاعتماد','success'); render();
}

// ── مديرو النظام ──
function renderAdminsPanel(){
  const admins = (state.users||[]).filter(u=>u.role==='admin');
  const nActive = admins.filter(u=>!u.isSuspended).length;
  const rows = admins.map(u=>{
    const me = u.id===state.user.id;
    const own = isOwnerUser(u);
    const why = own ? 'حساب مالك النظام — لا يُحذف' : me ? 'لا يمكنك حذف حسابك أنت' : (!u.isSuspended && nActive<=1) ? 'لا يمكن حذف آخر مدير نظام نشط' : '';
    const act = u.isSuspended
      ? `<button type="button" class="btn btn-ghost btn-sm" data-on-click="openSuspendCheck" data-on-click-args="${qa([(''+u.id)])}" title="الحساب موقوف — اضغط لإعادة تفعيله">إعادة التفعيل</button>`
      : `<button type="button" class="btn btn-reject btn-sm" ${why ? `disabled title="${escH(why)}"` : `title="حذف «${escH(u.name)}» — تُطلب كلمة مرورك، ومن له أثر في النظام يُوقف بدل حذفه"`} data-on-click="deleteAdminUser" data-on-click-args="${qa([(''+u.id)])}">حذف</button>`;
    return `<div class="list-item" style="cursor:default;"><div class="li-main">
      <b>${escH(u.name)}</b><span dir="ltr" style="text-align:right;">${escH(u.phone||'')}</span>
      ${own ? '<span class="sub" style="color:var(--blue);font-weight:800;">مالك النظام</span>' : ''}${me ? '<span class="sub">أنت</span>' : ''}${u.isSuspended ? '<span class="sub" style="color:#b45309;">موقوف</span>' : ''}</div><div>${act}</div></div>`;
  }).join('');
  return `
    <div class="card" style="margin-top:28px;"><h2>مديرو النظام (${admins.length})</h2>
      <p class="sub">مدير النظام يرى كل الشركات ولوحة التحكم كاملة. لا يمكن حذف آخر مدير نظام أو تخفيض صفته.</p>
      ${rows || '<div class="empty">لا يوجد</div>'}
    </div>
    <div class="card"><h2>إضافة مدير نظام جديد</h2>
      <p class="sub">هذه صلاحية كاملة، لذلك يُطلب منك إدخال كلمة مرور حسابك قبل الإنشاء.</p>
      <div class="row">
        <div style="--fw:280px;"><label>الاسم</label><input id="newAdminName" type="text" autocomplete="off" style="--fw:280px;"></div>
        <div style="--fw:280px;"><label>رقم الهاتف</label><input id="newAdminPhone" type="text" dir="ltr" autocomplete="off" style="--fw:280px;"></div>
        <div style="--fw:280px;"><label>كلمة المرور (6 خانات فأكثر)</label><input id="newAdminPass" type="password" autocomplete="new-password" style="--fw:280px;"></div>
      </div>
      <div class="actions-row" data-bar-actions><button class="btn btn-primary btn-md" data-on-click="createAdminUser" title="ينشئ حساب مدير نظام جديداً بعد تأكيد كلمة مرورك">إنشاء مدير نظام</button></div>
    </div>`;
}
async function createAdminUser(){
  const name = document.getElementById('newAdminName').value.trim();
  const phone = document.getElementById('newAdminPhone').value.trim();
  const pass = document.getElementById('newAdminPass').value.trim();
  if(!name || !phone || !pass){ showToast('الرجاء تعبئة جميع الحقول','error'); return; }
  if(pass.length < 6){ showToast('كلمة المرور يجب ألا تقل عن 6 خانات','error'); return; }
  if(state.users.some(u=>u.phone===phone)){ showToast('رقم الهاتف مستخدم من قبل','error'); return; }
  if(!(await reauthModal('تأكيد إنشاء مدير نظام','سيُنشأ حساب بصلاحية كاملة باسم «'+escH(name)+'».','إنشاء'))) return;
  const orgUnitRow = state.centers.find(c=>c.scope==='org');
  const { error } = await db.rpc('admin_create_user', {
    p_id:'u_'+Date.now(), p_phone:phone, p_password:pass, p_name:name, p_role:'admin',
    p_center_id: orgUnitRow ? orgUnitRow.id : null, p_manager_id:null,
    p_company_id:null, p_is_general:true, p_level_id:null
  });
  if(error){ showToast('تعذّر الإنشاء: '+(error.message||''),'error'); return; }
  await reloadUsers();
  showToast('أُنشئ مدير النظام','success'); render();
}

// ── صلاحيات الصفحات ──
function permAllRoles(){
  const fixed = ROLES.filter(r=>r.id!=='admin').map(r=>({id:r.id, name:findRole(r.id).name}));
  const custom = (state.customRoles||[]).map(r=>({id:r.id, name:r.name+' (وظيفي)'}));
  return fixed.concat(custom);
}
// الشركة التي تُضبط صلاحياتها (تُختار داخل الصفحة؛ الافتراضي الشركة الحالية)
function permCo(){ const c = state.permCo; return (c && state.companies.some(x=>x.id===c)) ? c : state.currentCompanyId; }
function permPickCo(id){
  if(Object.keys(state.permDraft||{}).length && !confirm('لديك تغييرات غير محفوظة لهذه الشركة. تجاهلها والانتقال؟')){ render(); return; }
  state.permCo = id; state.permDraft = {}; render();
}
function permDraftLevel(role, key){
  const d = state.permDraft || {};
  const k = role+'|'+key;
  return d[k] !== undefined ? d[k] : pageLevelFor(role, key, permCo());
}
function permSet(role, key, val){
  state.permDraft = state.permDraft || {};
  state.permDraft[role+'|'+key] = val;
  render();
}
function permPickRole(v){ state.permRole = v; render(); }
function permReset(){ state.permDraft = {}; render(); }
function renderPermissionsPanel(){
  const roles = permAllRoles(), co = permCo();
  const coName = (state.companies.find(c=>c.id===co)||{}).nameAr || '';
  const dirty = Object.keys(state.permDraft||{}).length > 0;
  // دور واحد في كل مرة: اختر الدور ثم اضبط صفحاته (بدل جدول عريض لا يتسع للشاشة)
  const pr = (state.permRole && roles.some(r=>r.id===state.permRole)) ? state.permRole : (roles[0]||{}).id;
  const nCustom = rid => PAGE_CATALOG.filter(p=>permDraftLevel(rid, p.key)!==pageDefaultLevel(rid, p.key)).length;
  const roleSel = `<select data-on-change="permPickRole" data-on-change-args="${qa([QA.v])}">${roles.map(r=>{ const n = nCustom(r.id); return `<option value="${escH(r.id)}" ${r.id===pr?'selected':''}>${escH(r.name)}${n ? ' · '+n+' مخصّص' : ''}</option>`; }).join('')}</select>`;
  const rowsHtml = PAGE_CATALOG.map(p=>{
    const cur = permDraftLevel(pr, p.key), def = pageDefaultLevel(pr, p.key);
    return `<div class="perm-row${cur!==def?' perm-custom':''}"><span class="perm-lbl" title="${escH(p.hint)}">${escH(p.label)}</span><select data-on-change="permSet" data-on-change-args="${qa([(''+pr), (''+(p.key)), QA.v])}" title="${escH(p.hint)}">${PAGE_LEVELS.map(([v,l])=>`<option value="${v}" ${cur===v?'selected':''}>${l}${v===def?' (افتراضي)':''}</option>`).join('')}</select></div>`;
  }).join('');
  return `
    <div class="card" style="margin-top:28px;"><h2>صلاحيات الصفحات — ${escH(coName)}</h2>
      <div class="row cx-item">
        <div style="--fw:320px;"><label>الشركة التي تضبط صلاحياتها</label>
          <select data-on-change="permPickCo" data-on-change-args="${qa([QA.v])}">${state.companies.map(c=>`<option value="${escH(c.id)}" ${c.id===co?'selected':''}>${escH(c.nameAr)}</option>`).join('')}</select></div>
        ${state.companies.length>1 ? `<div><button type="button" class="btn btn-ghost btn-md" data-on-click="copyPagePermsToAll" title="يجعل صلاحيات كل الشركات مثل صلاحيات هذه الشركة">نسخ هذه الصلاحيات لكل الشركات</button></div>` : ''}
      </div>
      <p class="sub">لكل دور في الشركة الحالية: هل يرى الصفحة، وماذا يفعل فيها. الخيار «افتراضي» هو الوضع المعمول به الآن. مدير النظام يرى كل شيء دائماً. لوحة التحكم لا تظهر لغير مدير النظام مهما كانت الصلاحية.</p>
      <p class="sub" style="font-size:var(--fs-hint);">ملاحظة: هذه الصلاحيات تتحكم في ظهور الصفحات والأزرار. أما البيانات المالية نفسها فتحميها قاعدة البيانات للأدوار المالية فقط، فمنح صفحة مالية لدور غير مالي لا يكشف له بيانات لا يملك حق قراءتها.</p>
      <div class="row" style="align-items:flex-end;margin:10px 0 6px;"><div style="--fw:320px;"><label>الدور</label>${roleSel}</div></div>
      <div class="perm-grid">${rowsHtml}</div>
      <p class="sub" style="font-size:var(--fs-hint);margin:8px 0 0;">الإطار البرتقالي = مختلف عن الافتراضي. تغييراتك على كل الأدوار تُحفظ معاً بزر «حفظ الصلاحيات».</p>
      <div id="permSaveBar" class="actions-row">
        <button class="btn btn-primary btn-md" data-perm-btn ${dirty?'':'disabled'} data-on-click="savePagePerms" title="يحفظ التغييرات بعد تأكيد كلمة مرورك">حفظ الصلاحيات</button>
        <button class="btn btn-ghost btn-md" data-perm-btn ${dirty?'':'disabled'} data-on-click="permReset" title="يتجاهل التغييرات غير المحفوظة">تراجع</button>
      </div>
    </div>`;
}
async function savePagePerms(){
  const d = state.permDraft || {}, keys = Object.keys(d);
  if(!keys.length){ showToast('لا تغييرات للحفظ'); return; }
  const co = permCo();
  const coName = (state.companies.find(c=>c.id===co)||{}).nameAr || '';
  if(!(await reauthModal('تأكيد حفظ الصلاحيات','ستتغير الصفحات التي يراها كل دور في «'+escH(coName)+'» فور الحفظ.','حفظ'))) return;
  const ups = [], dels = [];
  keys.forEach(k=>{
    const [role, page] = k.split('|'), lv = d[k];
    if(lv === pageDefaultLevel(role, page)) dels.push({role, page}); else ups.push({company_id:co, role, page_key:page, level:lv, updated_by:state.user.name, updated_at:new Date().toISOString()});
  });
  if(ups.length){
    const r = await db.from('page_permissions').upsert(ups, {onConflict:'company_id,role,page_key'});
    if(!(await dbCheck(r,'حفظ الصلاحيات'))) return;
  }
  for(const x of dels){
    const r = await db.from('page_permissions').delete().eq('company_id',co).eq('role',x.role).eq('page_key',x.page);
    if(!(await dbCheck(r,'حفظ الصلاحيات'))) return;
  }
  const p = await db.from('page_permissions').select('*');
  if(!p.error) state.pagePerms = p.data || [];
  state.permDraft = {};
  showToast('حُفظت صلاحيات الصفحات لـ «'+coName+'»','success'); render();
}
// ينسخ الصلاحيات الفعلية لهذه الشركة (بعد الحفظ) إلى كل الشركات الأخرى
async function copyPagePermsToAll(){
  if(Object.keys(state.permDraft||{}).length){ showToast('احفظ التغييرات أولاً ثم انسخها','error'); return; }
  const src = permCo(), srcName = (state.companies.find(c=>c.id===src)||{}).nameAr || '';
  const others = state.companies.filter(c=>c.id!==src);
  if(!others.length) return;
  if(!(await reauthModal('نسخ الصلاحيات لكل الشركات','ستصبح صلاحيات الصفحات في '+others.length+' شركة أخرى مثل «'+escH(srcName)+'» تماماً.','نسخ'))) return;
  for(const c of others){
    const ups = [], dels = [];
    permAllRoles().forEach(r=>PAGE_CATALOG.forEach(p=>{
      const lv = pageLevelFor(r.id, p.key, src);
      if(lv === pageDefaultLevel(r.id, p.key)) dels.push({role:r.id, page:p.key});
      else ups.push({company_id:c.id, role:r.id, page_key:p.key, level:lv, updated_by:state.user.name, updated_at:new Date().toISOString()});
    }));
    if(ups.length){ const r = await db.from('page_permissions').upsert(ups, {onConflict:'company_id,role,page_key'}); if(!(await dbCheck(r,'نسخ الصلاحيات'))) return; }
    for(const x of dels){ const r = await db.from('page_permissions').delete().eq('company_id',c.id).eq('role',x.role).eq('page_key',x.page); if(!(await dbCheck(r,'نسخ الصلاحيات'))) return; }
  }
  const p = await db.from('page_permissions').select('*');
  if(!p.error) state.pagePerms = p.data || [];
  showToast('نُسخت الصلاحيات إلى '+others.length+' شركة','success'); render();
}

function renderRolesPanel(){
  const lvOpts = (sel)=> allLevelNames().map(n=>`<option value="${escH(n)}" ${n===sel?'selected':''}>${escH(n)}</option>`).join('');
  const jobRows = state.customRoles.length ? state.customRoles.map(r=>{
    const n = jobRoleUsersCount(r.id);
    return `<div class="list-item jr-row" style="cursor:default;align-items:flex-end;gap:10px;flex-wrap:wrap;">
      <div style="flex:1 1 200px;"><label>اسم الدور</label><input id="jr_name_${r.id}" type="text" value="${escH(r.name)}" maxlength="60"></div>
      <div style="flex:0 1 210px;"><label>المستوى الافتراضي</label><select id="jr_lv_${r.id}">${lvOpts(r.defaultLevelName)}</select></div>
      <label style="flex:0 0 auto;display:flex;align-items:center;gap:6px;font-weight:600;margin:0 0 10px;"><input type="checkbox" id="jr_gen_${r.id}" ${r.generalDefault?'checked':''} style="width:auto;"> 🌐 عام افتراضياً</label>
      <span class="sub" style="margin:0 0 12px;">${n} مستخدم</span>
      <div style="display:flex;gap:8px;margin-bottom:6px;">
        <button type="button" class="btn btn-primary btn-xs" data-on-click="saveJobRole" data-on-click-args="${qa([(''+(r.id))])}">حفظ</button>
        <button type="button" class="btn btn-reject btn-xs" data-on-click="deleteCustomRole" data-on-click-args="${qa([(''+(r.id))])}" ${n?'disabled title="لا يُحذف دور يستخدمه مستخدمون"':''}>حذف</button>
      </div></div>`;
  }).join('') : '<div class="empty">لا توجد أدوار وظيفية بعد. أضف أولها من النموذج بالأسفل.</div>';
  const fixedRows = ROLES.map(r=>{
    const nm = findRole(r.id).name;
    const sys = {accountant:'يتصرف بالذيل التنفيذي (التحويل والصرف)', cfo:'يعتمد التحويل البنكي', admin:'إدارة النظام'}[r.id];
    return `<div class="list-item fr-row" style="cursor:default;align-items:flex-end;gap:10px;flex-wrap:wrap;">
      <div style="flex:1 1 200px;"><label>اسم الدور (الأصلي: ${escH(r.name)})</label><input id="fr_name_${r.id}" type="text" value="${escH(nm)}" maxlength="60" ${r.id==='admin'?'disabled':''}></div>
      <span class="sub" style="flex:1 1 220px;margin:0 0 12px;">${sys ? '🔒 صلاحية نظام: '+sys : 'دور إداري بالمسار (الصلاحية من مسار الاعتماد لا من الاسم)'} · ${jobRoleUsersCount(r.id)} مستخدم</span>
      ${r.id==='admin' ? '' : `<div style="margin-bottom:6px;"><button type="button" class="btn btn-ghost btn-xs" data-on-click="saveFixedRoleName" data-on-click-args="${qa([(''+(r.id))])}">حفظ الاسم</button></div>`}</div>`;
  }).join('');
  return `
    <div class="card" style="margin-top:28px;">
      <h2>إضافة دور وظيفي جديد</h2>
      <p class="file-hint">دور واحد لكل المؤسسة (مثل: منتج، مصور، مندوب، سائق، محرر، مدير قسم، مدير شركة). كل الأدوار الوظيفية ترفع طلبات صرف وتُعتمد حسب مسارها مثل «موظف». المستوى الافتراضي يُعبّأ تلقائياً عند اختيار الدور لمستخدم، وكذلك خانة «عام».</p>
      <div class="row">
        <div><label>اسم الدور</label><input id="newRoleName" type="text" maxlength="60" placeholder="مثال: مندوب"></div>
        <div><label>المستوى الافتراضي</label><select id="newRoleLevel">${lvOpts('موظف')}</select></div>
        <div style="flex:0 0 auto;align-self:flex-end;"><label style="display:flex;align-items:center;gap:6px;font-weight:600;margin:0 0 10px;"><input type="checkbox" id="newRoleGeneral" style="width:auto;"> 🌐 عام افتراضياً</label></div>
      </div>
      <div class="actions-row" data-bar-actions><button class="btn btn-primary btn-md" data-on-click="addJobRole">إضافة الدور</button></div>
    </div>
    <h2 style="margin-top:20px;">الأدوار الوظيفية (${state.customRoles.length})</h2>
    ${jobRows}
    <div class="card flow" style="margin-top:26px;">
      <h2 style="margin:0 0 4px;font-size:var(--fs-h3);">مهلة إغلاق الدخول التلقائي (السقف لكل دور)</h2>
      <p class="file-hint" style="margin:0 0 6px;">أطول مدة بلا نشاط يستطيع صاحب الدور أن يضبطها لنفسه من «حسابي ← الأمان» (من ${IDLE_MIN_MIN} إلى 1440 دقيقة). اترك الحقل فارغاً ليأخذ السقف الافتراضي أدناه. مثال: اجعل من يعتمد الصرف 30 دقيقة.</p>
      <div class="row">
        <div style="--fw:280px;"><label>السقف الافتراضي لكل الأدوار</label>
          <input id="idlecap_default" type="number" min="${IDLE_MIN_MIN}" max="1440" dir="ltr" value="${Number(idleCaps().default)||''}" placeholder="${IDLE_DEFAULT_CAP}"></div>
      </div>
      <div class="row">
        ${[...ROLES.map(r=>({id:r.id, name:findRole(r.id).name})), ...state.customRoles.map(r=>({id:r.id, name:r.name}))].map(r=>`
        <div style="--fw:280px;"><label>${escH(r.name)}</label>
          <input id="idlecap_${escH(r.id)}" data-idlecap="${escH(r.id)}" type="number" min="${IDLE_MIN_MIN}" max="1440" dir="ltr" value="${Number(idleCaps()[r.id])||''}" placeholder="الافتراضي"></div>`).join('')}
      </div>
      <div class="actions-row" data-bar-actions><button class="btn btn-primary btn-md" data-on-click="saveIdleCaps">حفظ المهل</button></div>
    </div>
    <h2 style="margin-top:26px;">الأدوار النظامية</h2>
    <p class="file-hint">يمكنك تعديل أسمائها (مثل «المدير العام»)، أما صلاحيات المحاسب والمدير المالي ومدير النظام فمرتبطة بمحرك الصرف ولا تُغيَّر هنا.</p>
    ${fixedRows}`;
}
async function addJobRole(){
  const name = (document.getElementById('newRoleName').value||'').trim();
  const lv = document.getElementById('newRoleLevel').value || 'موظف';
  const gen = document.getElementById('newRoleGeneral').checked;
  if(!name){ showToast('الرجاء إدخال اسم الدور','error'); return; }
  if(state.customRoles.some(r=>r.name===name) || ROLES.some(r=>findRole(r.id).name===name)){ showToast('يوجد دور بهذا الاسم','error'); return; }
  const role = {id:'role_'+Date.now(), companyId:null, name, description:'', defaultLevelName:lv, generalDefault:gen};
  const result = await db.from('custom_roles').insert({id:role.id, company_id:null, name, description:null, default_level_name:lv, general_default:gen});
  if(!(await dbCheck(result, 'إضافة الدور'))) return;
  state.customRoles.push(role);
  showToast('تمت إضافة الدور','success'); render();
}
async function saveJobRole(id){
  const r = state.customRoles.find(x=>x.id===id); if(!r) return;
  const name = (document.getElementById('jr_name_'+id).value||'').trim();
  const lv = document.getElementById('jr_lv_'+id).value || 'موظف';
  const gen = document.getElementById('jr_gen_'+id).checked;
  if(!name){ showToast('اسم الدور لا يكون فارغاً','error'); return; }
  if(state.customRoles.some(x=>x.id!==id && x.name===name)){ showToast('يوجد دور بهذا الاسم','error'); return; }
  const result = await db.from('custom_roles').update({name, default_level_name:lv, general_default:gen}).eq('id', id);
  if(!(await dbCheck(result, 'حفظ الدور'))) return;
  r.name = name; r.defaultLevelName = lv; r.generalDefault = gen;
  showToast('تم حفظ الدور','success'); render();
}
async function saveIdleCaps(){
  const caps = {};
  const d = document.getElementById('idlecap_default'); if(d && d.value.trim()) caps.default = parseInt(d.value,10);
  document.querySelectorAll('[data-idlecap]').forEach(el=>{ if(el.value.trim()) caps[el.dataset.idlecap] = parseInt(el.value,10); });
  for(const k of Object.keys(caps)){
    if(!(caps[k]>=IDLE_MIN_MIN && caps[k]<=1440)){ showToast('كل مهلة تكون بين '+IDLE_MIN_MIN+' و1440 دقيقة','error'); return; }
  }
  const r = await db.from('app_settings').upsert({key:'idle_caps', value:JSON.stringify(caps)});
  if(!(await dbCheck(r, 'حفظ مهل الإغلاق'))) return;
  state.appSettings = state.appSettings||{}; state.appSettings.idle_caps = JSON.stringify(caps);
  showToast('حُفظت مهل الإغلاق التلقائي','success'); render();
}
async function saveFixedRoleName(id){
  const name = (document.getElementById('fr_name_'+id).value||'').trim();
  if(!name){ showToast('الاسم لا يكون فارغاً','error'); return; }
  const ov = roleNameOverrides(); ov[id] = name;
  const result = await db.from('app_settings').upsert({key:'role_names', value:JSON.stringify(ov)});
  if(!(await dbCheck(result, 'حفظ اسم الدور'))) return;
  state.appSettings = state.appSettings||{}; state.appSettings.role_names = JSON.stringify(ov);
  showToast('تم حفظ اسم الدور','success'); render();
}
// ترحيل لمرة واحدة: «المدير الأعلى» ← «المدير العام» بسلالم المستويات المحفوظة
async function maybeMigrateNames(){
  if(!state.user || state.user.role!=='admin' || state._migDone) return;
  state._migDone = true;
  if(state.appSettings && state.appSettings.migr_gm==='1') return;
  const old = (state.jobLevels||[]).filter(l=>l.name==='المدير الأعلى');
  if(old.length){
    const r = await db.from('job_levels').update({name:'المدير العام'}).eq('name','المدير الأعلى');
    if(r && r.error) return;
    old.forEach(l=>l.name='المدير العام');
  }
  await db.from('app_settings').upsert({key:'migr_gm', value:'1'});
  state.appSettings = state.appSettings||{}; state.appSettings.migr_gm = '1';
}


// فلتر قائمة المدير المباشر: 'company'=الشركة الحالية | 'general'=العامّون+الشركة | 'all'=الكل
function mgrOptions(currentCompanyId, selectedId, excludeId, filterMode){
  filterMode = filterMode || 'company';
  let pool = state.users.filter(u=>u.role!=='admin' && u.id!==excludeId && !u.isSuspended);
  if(filterMode==='company') pool = pool.filter(u=>u.companyId===currentCompanyId && !u.isGeneral);
  else if(filterMode==='general') pool = pool.filter(u=>u.companyId===currentCompanyId || u.isGeneral);
  // 'all': كل المستخدمين
  // تأكد أن المدير المحدد ظاهر حتى لو خارج الفلتر
  if(selectedId && !pool.some(u=>u.id===selectedId)){
    const sel = state.users.find(u=>u.id===selectedId);
    if(sel) pool = [sel, ...pool];
  }
  pool.sort((a,b)=>userRank(a)-userRank(b) || String(a.name).localeCompare(String(b.name),'ar'));
  return pool.map(u=>`<option value="${u.id}" ${u.id===selectedId?'selected':''}>${escH(u.name)} — ${escH(findRole(u.role).name)}${u.isGeneral?' 🌐':''}</option>`).join('');
}
function mgrFilterBtns(inputId, company, general, all, current){
  const btn=(v,l)=>`<button type="button" class="seg-btn ${current===v?'on':''}" data-on-click="changeMgrFilter" data-on-click-args="${qa([(''+(inputId)), (''+(company)), (''+(general)), (''+(all||'')), (''+(v))])}" title="فلتر المدير">${l}</button>`;
  return `<div class="seg" style="margin-bottom:4px;">${btn('company','موظفو الشركة')}${btn('general','+ العامّون')}${btn('all','الكل')}</div>`;
}
function changeMgrFilter(selectId, companyId, excludeId, allId, mode){
  allId = allId || null;
  const sel = document.getElementById(selectId); if(!sel) return;
  const cur = sel.value;
  // اقرأ المدير المختار حالياً ثم أعد بناء القائمة
  const opts = mgrOptions(companyId, cur, excludeId, mode);
  sel.innerHTML = '<option value="">بدون مدير</option>' + opts;
  // احفظ الفلتر المختار كـ data-attr للزرّ
  const wrap = sel.closest('.row,.card,div');
  if(wrap){ const btns = wrap.querySelectorAll('.seg-btn'); btns.forEach(b=>{ let a = []; try{ a = JSON.parse(b.getAttribute('data-on-click-args')||'[]'); }catch(e){} b.classList.toggle('on', a[a.length-1]===mode); }); }
}

function toggleGeneralAccess(){
  const g = document.getElementById('editUserGeneral'); if(!g) return;
  document.querySelectorAll('[data-access-company]').forEach(c=>{
    if(g.checked){ c.checked = true; c.disabled = true; }
    else { c.disabled = false; c.checked = c.getAttribute('data-was-linked')==='1'; }   // عند إلغاء "عام" نرجع للروابط الفعلية السابقة
  });
}
// بعد فتح حساب مستخدم، النموذج قد يكون أسفل الصفحة بعيداً عن النظر.
// فالقفز إلى الأعلى يُخفيه ويُوهم أن شيئاً لم يحدث. ننزل إليه ونومض حوله.
function focusUserEdit(){
  requestAnimationFrame(()=>{
    const el = document.getElementById('userEditAnchor');
    if(!el) return;
    // النموذج أطول من الشاشة، فتوسيطه يدفع عنوانه فوق الحافة.
    // ننزل بحيث يقع رأسه تحت الشريط العلوي مباشرة.
    const y = el.getBoundingClientRect().top + window.scrollY - 90;
    window.scrollTo({top: Math.max(0, y), behavior:'smooth'});
    el.style.transition = 'box-shadow .35s';
    el.style.boxShadow = '0 0 0 4px rgba(37,99,235,.40)';
    setTimeout(()=>{ el.style.boxShadow = ''; }, 1800);
    // المؤشّر في خانة كلمة المرور — فهي الفعل الذي جاء من أجله
    const pw = document.getElementById('editUserPass');
    if(pw) setTimeout(()=>{ try{ pw.focus({preventScroll:true}); }catch(e){ pw.focus(); } }, 600);
  });
}

