async function saveUserEdit(){
  const u = state.users.find(x=>x.id===state.editingUserId);
  if(!u) return;
  const name = document.getElementById('editUserName').value.trim();
  const phone = document.getElementById('editUserPhone').value.trim();
  const pass = document.getElementById('editUserPass').value.trim();
  const role = document.getElementById('editUserRole').value;
  const centerId = document.getElementById('editUserCenter').value;
  const companyId = document.getElementById('editUserCompany').value;
  const managerSelect = document.getElementById('editUserManager');
  const managerId = managerSelect ? managerSelect.value : '';
  const jobTitleEl = document.getElementById('editUserJobTitle');
  const jobTitle = jobTitleEl ? jobTitleEl.value.trim() : (u.jobTitle||'');
  const levelEl = document.getElementById('editUserLevel');
  let levelId = levelEl ? levelEl.value : (u.levelId||'');
  // المستوى مطلوب ويجب أن يتبع الشركة المختارة: نقابله بالاسم عند تغيير الشركة، وإن لم يوجد نأخذ أدنى مستوى مع ملاحظة
  let levelNote = '';
  if(levelEl && levelsForCompany(companyId).length){
    const cur = state.jobLevels.find(l=>l.id===levelId);
    if(!cur || cur.companyId!==companyId){
      const same = cur ? state.jobLevels.find(l=>l.companyId===companyId && l.name===cur.name) : null;
      if(same) levelId = same.id;
      else {
        const low = defaultLevelFor(role, companyId) || lowestLevelFor(companyId);
        levelId = low.id;
        levelNote = (cur ? 'لا يوجد مستوى «'+cur.name+'» في الشركة الجديدة، ' : 'لم يُحدَّد مستوى، ')+'فعُيّن له المستوى «'+low.name+'»';
      }
    }
  }
  const reqApEl = document.getElementById('editUserRequestApprover');
  const reqVal = reqApEl ? reqApEl.value : (u.noRequestApprover ? 'none' : (u.requestApproverId||''));
  const noRequestApprover = reqVal==='none';
  const requestApproverId = noRequestApprover ? '' : reqVal;
  const nextApEl = document.getElementById('editUserNextApprover');
  const nextVal = nextApEl ? nextApEl.value : (u.noNextApprover ? 'none' : (u.nextApproverId||''));
  const noNextApprover = nextVal==='none';
  const nextApproverId = noNextApprover ? '' : nextVal;
  const generalEl = document.getElementById('editUserGeneral');
  const isGeneral = generalEl ? generalEl.checked : !!u.isGeneral;
  const directEl = document.getElementById('editUserDirect');
  const directToTransfer = directEl ? directEl.checked : !!u.directToTransfer;
  const dlEl = document.getElementById('editUserDeadline');
  const approvalDeadlineDays = dlEl ? (dlEl.value==='' ? null : Number(dlEl.value)) : u.approvalDeadlineDays;
  const escModeEl = document.getElementById('editUserEscMode');
  const escalateMode = escModeEl ? escModeEl.value : (u.escalateMode||'');
  const escUserEl = document.getElementById('editUserEscUser');
  const escalateUserId = escalateMode==='user' ? (escUserEl ? escUserEl.value : (u.escalateUserId||'')) : '';
  if(escalateMode==='user' && !escalateUserId){ showToast('اختر الشخص الذي تُحال إليه الخطوة عند انتهاء المهلة','error'); return; }
  const coChecks = [...document.querySelectorAll('[data-access-company]')];
  const linkedIds = coChecks.filter(c=>c.checked).map(c=>c.getAttribute('data-access-company'));
  if(!name || !phone){ showToast('الرجاء تعبئة الاسم ورقم الهاتف','error'); return; }
  if(state.users.some(x=>x.phone===phone && x.id!==u.id)){ showToast('رقم الهاتف مستخدم من قبل','error'); return; }
  // نقل المستخدم من شركة: تحذير إن كانت له معاملات أو مرؤوسون هناك (يتخطاه «انقل على أي حال»)
  { const moveOk = !!state._moveOk; state._moveOk = false;
    if(!moveOk && state.user.role==='admin'){
      const oldIds = state.companies.map(c=>c.id).filter(cid=>userHasCompany(u,cid));
      const keep = cid => isGeneral || cid===companyId || linkedIds.includes(cid);
      const removed = oldIds.filter(cid=>!keep(cid));
      if(removed.length){
        const f = moveFindings(u.id, removed);
        if(f.reqs.length || f.own.length || f.subs.length){ showMoveCheck(u, removed, f); return; }
      }
    }
  }
  // كلمة المرور اختيارية عند التعديل: تُترك فارغة لتبقى كما هي
  if(pass){
    if(pass.length < 6){ showToast('كلمة المرور يجب ألا تقل عن 6 خانات','error'); return; }
    const { error: pwErr } = await db.rpc('admin_set_password', { p_user_id: u.id, p_password: pass });
    if(pwErr){ showToast('تعذّر تغيير كلمة المرور: ' + (pwErr.message||''), 'error'); return; }
    await closeResetRequestsFor(u.id);   // طلب هذا المستخدم — إن وُجد — عولج بهذا
  }
  // رقم الدخول لا يُغيَّر بتحديث الجدول وحده: بريد المصادقة مشتقّ منه،
  // فلو تغيّر هنا فقط انقطع الربط وتعذّر الدخول بالرقم الجديد.
  // الدالة تحدّث الاثنين معاً وتُبقي الرقم القديم صالحاً.
  const phoneChanged = String(u.phone||'').trim() !== phone;
  if(phoneChanged){
    const { error: phErr } = await db.rpc('admin_set_login_phone', { p_user_id: u.id, p_phone: phone });
    if(phErr){
      const notDeployed = /admin_set_login_phone|PGRST202|does not exist|could not find/i.test(phErr.message||'');
      showToast(notDeployed
        ? 'تغيير رقم الدخول يحتاج تحديث قاعدة البيانات أولاً (ملف إصلاح-الدخول.sql)'
        : 'تعذّر تغيير رقم الدخول: ' + (phErr.message||''), 'error');
      return;
    }
    await loadLoginAliases();
  }
  const isAdminNow = state.user.role==='admin';
  const result = await db.from('users').update(isAdminNow ? {
    name, phone, role, center_id: centerId||null, manager_id: managerId||null, company_id: companyId||null,
    job_title: jobTitle||null, level_id: levelId||null, request_approver_id: requestApproverId||null, next_approver_id: nextApproverId||null,
    is_general: isGeneral, no_request_approver: noRequestApprover, no_next_approver: noNextApprover, direct_to_transfer: directToTransfer,
    approval_deadline_days: approvalDeadlineDays, escalate_mode: escalateMode||null, escalate_user_id: escalateUserId||null
  } : { name, phone, job_title: jobTitle||null }).eq('id', u.id);
  if(!(await dbCheck(result, 'تعديل المستخدم'))) return;
  u.name = name; u.phone = phone; u.role = role; u.centerId = centerId || null; u.managerId = managerId || null; u.companyId = companyId || null;
  u.jobTitle = jobTitle || ''; u.levelId = levelId || null; u.requestApproverId = requestApproverId || null; u.nextApproverId = nextApproverId || null;
  u.isGeneral = isGeneral; u.noRequestApprover = noRequestApprover; u.noNextApprover = noNextApprover; u.directToTransfer = directToTransfer;
  u.approvalDeadlineDays = approvalDeadlineDays; u.escalateMode = escalateMode; u.escalateUserId = escalateUserId||null;
  // ربط المستخدم بشركات إضافية (المستخدم العام لا يحتاج روابط: الخانة تشمل الشركات الحالية والمستقبلية)
  if(isAdminNow && (coChecks.length || generalEl)){
    const wanted = isGeneral ? [] : linkedIds.filter(id=>id!==u.companyId);
    const had = (state.userCompanyLinks||[]).filter(l=>l.userId===u.id).map(l=>l.companyId);
    const toAdd = wanted.filter(id=>!had.includes(id)), toRemove = had.filter(id=>!wanted.includes(id));
    for(const cid of toRemove){
      const rr = await db.from('user_companies').delete().eq('user_id', u.id).eq('company_id', cid);
      if(await dbCheck(rr, 'إزالة ربط الشركة')) state.userCompanyLinks = state.userCompanyLinks.filter(l=>!(l.userId===u.id && l.companyId===cid));
    }
    for(const cid of toAdd){
      const rr = await db.from('user_companies').insert({user_id:u.id, company_id:cid});
      if(await dbCheck(rr, 'ربط المستخدم بشركة')) state.userCompanyLinks.push({userId:u.id, companyId:cid});
    }
  }
  // المدير المباشر بالشركات الأخرى (للموظف المرتبط بأكثر من شركة)
  const ucmSelects = document.querySelectorAll('[data-ucm-company]');
  for(const sel of (isAdminNow ? ucmSelects : [])){
    const companyId2 = sel.getAttribute('data-ucm-company');
    const mgrVal = sel.value || null;
    const existing = (state.userCompanyManagers||[]).find(x=>x.userId===u.id && x.companyId===companyId2);
    if(existing && existing.managerId===mgrVal) continue;
    if(!existing && !mgrVal) continue;
    const r2 = await db.from('user_company_managers').upsert({user_id:u.id, company_id:companyId2, manager_id:mgrVal});
    if(!(await dbCheck(r2, 'تعديل المدير بشركة أخرى'))) continue;
    if(existing) existing.managerId = mgrVal;
    else state.userCompanyManagers.push({userId:u.id, companyId:companyId2, managerId:mgrVal});
  }
  state.editingUserId = null;
  showToast('تم حفظ تعديلات المستخدم' + (levelNote ? ' — ملاحظة: ' + levelNote : ''), levelNote ? 'info' : 'success');
  render();
}

const USER_USAGE_CHECKS = [['requests','created_by_id','طلبات'],['request_history','user_id','قرارات وسجل'],['request_approval_steps','approver_id','خطوات اعتماد'],['transactions','created_by_id','حركات مالية'],['qy_attachments','created_by','مرفقات'],['recurring_templates','created_by_id','قيود دورية']];
async function userUsage(id){
  const checks = USER_USAGE_CHECKS, used = [];
  for(const [t,c,l] of checks){
    if(t==='qy_attachments' && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(id))) continue;
    const r = await db.from(t).select('*',{count:'exact',head:true}).eq(c,id);
    if(r.error){ showToast('تعذّر فحص أثر المستخدم قبل الحذف: '+(r.error.message||''),'error'); return null; }
    if(r.count>0) used.push(l+' ('+r.count+')');
  }
  const h = await db.from('qy_handovers').select('*',{count:'exact',head:true}).or('from_user_id.eq.'+id+',to_user_id.eq.'+id+',created_by.eq.'+id);
  if(h.error){ showToast('تعذّر فحص الإسناد قبل الحذف: '+(h.error.message||''),'error'); return null; }
  if(h.count>0) used.push('إسناد ('+h.count+')');
  return used;
}
// حذف مدير نظام: ليس نفسك ولا آخر مدير نشط؛ بكلمة مرورك؛ ومن له أثر يُوقف بدل الحذف
async function deleteAdminUser(id){
  const u = state.users.find(x=>x.id===id); if(!u) return;
  if(isOwnerUser(u)){ showToast('حساب مالك النظام لا يُحذف','error'); return; }
  if(id===state.user.id){ showToast('لا يمكنك حذف حسابك أنت','error'); return; }
  const active = state.users.filter(x=>x.role==='admin' && !x.isSuspended && x.id!==id);
  if(!active.length){ showToast('لا يمكن حذف آخر مدير نظام نشط','error'); return; }
  const used = await userUsage(id); if(used===null) return;
  if(used.length){ showToast('«'+u.name+'» له أثر في النظام ('+used.join('، ')+')، فيُوقف حسابه بدل حذفه.','info'); openSuspendCheck(id); return; }
  requestDeleteConfirm(`حذف مدير النظام "${u.name}" نهائياً؟`, 'user', id);
}
async function deleteUser(id){
  const u = state.users.find(x=>x.id===id);
  if(isOwnerUser(u)){ showToast('حساب مالك النظام لا يُحذف','error'); return; }
  // الحذف النهائي لمن بلا أي أثر في أي شركة؛ وإلا فالإيقاف
  const checks = [['requests','created_by_id','طلبات'],['request_history','user_id','قرارات وسجل'],['request_approval_steps','approver_id','خطوات اعتماد'],['transactions','created_by_id','حركات مالية'],['qy_attachments','created_by','مرفقات'],['recurring_templates','created_by_id','قيود دورية']];
  const used = [];
  for(const [t,c,l] of checks){
    if(t==='qy_attachments' && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(id))) continue; // عمود uuid ومعرّفات المستخدمين نصّية
    const r = await db.from(t).select('*',{count:'exact',head:true}).eq(c,id);
    if(r.error){ showToast('تعذّر فحص أثر المستخدم قبل الحذف: '+(r.error.message||''),'error'); return; }
    if(r.count>0) used.push(l+' ('+r.count+')');
  }
  const h = await db.from('qy_handovers').select('*',{count:'exact',head:true}).or('from_user_id.eq.'+id+',to_user_id.eq.'+id+',created_by.eq.'+id);
  if(h.error){ showToast('تعذّر فحص الإسناد قبل الحذف: '+(h.error.message||''),'error'); return; }
  if(h.count>0) used.push('إسناد ('+h.count+')');
  if(used.length){
    showToast('لا يمكن حذف «'+(u?u.name:'')+'» لارتباطه بطلبات وسجلات ('+used.join('، ')+'). يمكنك إيقافه من صفحة التعديل.','error');
    return;
  }
  requestDeleteConfirm(`حذف المستخدم "${u?u.name:''}" نهائياً؟`, 'user', id);
}
async function executeDeleteUser(id){
  const delResult = await db.from('users').delete().eq('id', id);
  if(!(await dbCheck(delResult, 'حذف المستخدم'))) return;
  state.users = state.users.filter(u=>u.id!==id);
  showToast('تم حذف المستخدم', 'success');
  render();
}

